import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, getDoc, serverTimestamp, getDocs, addDoc, orderBy } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, GraduationCap, ArrowRight, BookOpen, Star, Camera, MapPin, Key, ChevronLeft, Info, ImageIcon, Users, Zap, ShieldCheck, MessageCircle, Play, Flame, RefreshCw, CheckCircle2, Quote, Activity, Award, LogIn, X, Send, CreditCard } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form' | 'success_notice' | 'password_recovery';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  // Chat Recovery States
  const [recoveryName, setRecoveryName] = useState('');
  const [recoveryEmail, setRecoveryEmail] = useState('');
  const [activeProtocol, setActiveProtocol] = useState<string | null>(null);
  const [ticketId, setTicketId] = useState<string | null>(null);
  const [chatMessage, setChatMessage] = useState('');
  const [messages, setMessages] = useState<any[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);
  const [generatedEmail, setGeneratedEmail] = useState('');
  const [realStats, setRealStats] = useState({ students: 0, classes: 0, rating: '0.0' });
  const [realFeedbacks, setRealFeedbacks] = useState<any[]>([]);

  const [enrollForm, setEnrollForm] = useState({
    nome: '', emailPessoal: '', password: '', cpf: '', nascimento: '', telefone: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubC = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setRealStats(prev => ({ ...prev, students: snap.size }));
    });
    const unsubF = onSnapshot(collection(db, 'feedbacks'), (snap) => {
      const data = snap.docs.map(d => d.data());
      setRealFeedbacks(data.slice(0, 3));
      if (data.length > 0) {
        const avg = data.reduce((acc, curr) => acc + (curr.rating || 0), 0) / data.length;
        setRealStats(prev => ({ ...prev, rating: avg.toFixed(1) }));
      }
    });
    return () => { unsubC(); unsubS(); unsubF(); };
  }, []);

  useEffect(() => {
    if (!ticketId) return;
    const unsub = onSnapshot(query(collection(db, `tickets/${ticketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setMessages(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsub();
  }, [ticketId]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Preencha todos os campos.');
      return;
    }
    setLoading(true);
    setError('');
    const emailLower = email.trim().toLowerCase();

    try {
      const userCredential = await signInWithEmailAndPassword(auth, emailLower, password);
      const userDoc = await getDoc(doc(db, 'users', userCredential.user.uid));

      if (userDoc.exists()) {
        const userData = userDoc.data();
        if (isAdminMode && userData.role === 'aluno') {
          await signOut(auth);
          setError('Acesso administrativo negado. Use uma conta de Gestor.');
          setLoading(false);
          return;
        }
      }
    } catch (err: any) {
      setError('Credenciais inválidas ou conta não sincronizada. Tente recuperar sua senha.');
      setLoading(false);
    }
  };

  const startRecoveryTicket = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const protocol = 'REC-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    const payload = {
      protocolo: protocol,
      user: recoveryName,
      email: recoveryEmail,
      type: 'Recuperação de Senha',
      status: 'Pendente',
      createdAt: serverTimestamp(),
      lastUpdate: serverTimestamp(),
      lastMessage: 'Solicitação de nova senha iniciada via interface de login.'
    };
    const docRef = await addDoc(collection(db, 'tickets'), payload);
    setTicketId(docRef.id);
    setActiveProtocol(protocol);
    setLoading(false);
  };

  const sendChatMessage = async () => {
    if (!chatMessage.trim() || !ticketId) return;
    await addDoc(collection(db, `tickets/${ticketId}/messages`), {
      text: chatMessage,
      sender: 'Aluno',
      timestamp: serverTimestamp()
    });
    setChatMessage('');
  };

  const generateAcademicEmail = async (fullName: string) => {
    const names = fullName.trim().toLowerCase().split(' ');
    const firstName = names[0];
    const lastName = names.length > 1 ? names[names.length - 1] : '';
    let baseEmail = `${firstName}@ead.com`;
    const q = query(collection(db, 'users'), where('email', '==', baseEmail));
    const snap = await getDocs(q);
    if (!snap.empty && lastName) {
      baseEmail = `${firstName}.${lastName}@ead.com`;
    }
    return baseEmail;
  };

  const handleFinalizeEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    setLoading(true);
    setError('');
    try {
      const academicoEmail = await generateAcademicEmail(enrollForm.nome);
      const userCredential = await createUserWithEmailAndPassword(auth, academicoEmail, enrollForm.password);
      const uid = userCredential.user.uid;
      const academicId = `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;
      const authHash = Math.random().toString(36).substring(2, 12).toUpperCase() + "-" + Date.now().toString().slice(-4);

      const payload = {
        uid,
        displayName: enrollForm.nome,
        nome: enrollForm.nome,
        email: academicoEmail,
        emailPessoal: enrollForm.emailPessoal.toLowerCase(),
        password: enrollForm.password, 
        cpf: enrollForm.cpf,
        nascimento: enrollForm.nascimento,
        telefone: enrollForm.telefone,
        photoURL: enrollForm.fotoUrl,
        endereco: enrollForm.endereco,
        role: 'aluno',
        // Audit: Para segurança e fluxo de secretaria, iniciamos como 'aguardando_validacao'
        status: 'aguardando_validacao',
        cursoInicial: selectedCourse.id,
        academicId,
        authHash,
        createdAt: serverTimestamp(),
        progress: 0,
        sincronizado: true
      };

      await setDoc(doc(db, 'users', uid), payload);
      setGeneratedEmail(academicoEmail);
      setViewMode('success_notice');
      setLoading(false);
    } catch (err: any) {
      console.error("Erro na matrícula:", err);
      setError('Falha na sincronização: ' + (err.code === 'auth/email-already-in-use' ? 'E-mail em uso.' : 'Verifique sua conexão ou dados.'));
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => setEnrollForm({...enrollForm, fotoUrl: ev.target?.result as string});
      reader.readAsDataURL(file);
    }
  };

  if (viewMode === 'password_recovery') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative">
        <div className="absolute inset-0 z-0 opacity-20">
          <img src="https://images.unsplash.com/photo-1454165833767-027ffea9e61b?auto=format&fit=crop&w=1920&q=80" className="w-full h-full object-cover" />
        </div>
        <div className="relative z-10 w-full max-w-4xl bg-white rounded-[3rem] shadow-2xl overflow-hidden flex flex-col md:flex-row h-[600px] animate-in zoom-in-95 duration-500">
           {!activeProtocol ? (
             <div className="flex-1 p-12 flex flex-col justify-center space-y-8">
                <button onClick={() => setViewMode('login')} className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-indigo-600 transition-all"><ChevronLeft size={16}/> Voltar ao Login</button>
                <div>
                   <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Recuperar Senha</h2>
                   <p className="text-xs text-slate-400 mt-2 font-medium italic">Inicie um atendimento com a Secretaria Master para validar sua identidade.</p>
                </div>
                <form onSubmit={startRecoveryTicket} className="space-y-4">
                   <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">Nome Completo</label><input required value={recoveryName} onChange={e => setRecoveryName(e.target.value)} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-sm font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">E-mail Cadastrado</label><input required type="email" value={recoveryEmail} onChange={e => setRecoveryEmail(e.target.value)} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-sm font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <button type="submit" disabled={loading} className="w-full py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] italic hover:bg-indigo-600 transition-all shadow-xl">
                      {loading ? <RefreshCw className="animate-spin mx-auto" size={20}/> : 'Abrir Protocolo de Atendimento'}
                   </button>
                </form>
             </div>
           ) : (
             <div className="flex-1 flex flex-col h-full">
                <header className="p-6 bg-slate-900 text-white flex justify-between items-center">
                   <div className="flex items-center gap-4">
                      <div className="p-2 bg-indigo-600 rounded-xl shadow-lg"><MessageCircle size={20}/></div>
                      <div>
                        <h3 className="text-sm font-black uppercase italic tracking-tighter">Secretaria Virtual</h3>
                        <p className="text-[8px] text-indigo-400 font-bold uppercase tracking-widest mt-1">Prot: {activeProtocol}</p>
                      </div>
                   </div>
                   <button onClick={() => setViewMode('login')} className="p-2 bg-white/10 hover:bg-rose-600 rounded-full transition-all"><X size={18}/></button>
                </header>
                <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50 shadow-inner">
                   {messages.map((m, i) => (
                     <div key={i} className={`flex flex-col ${m.sender === 'Aluno' ? 'items-end' : 'items-start'}`}>
                        <div className={`max-w-[80%] p-4 rounded-2xl text-xs font-medium italic ${m.sender === 'Aluno' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-900 rounded-tl-none shadow-sm'}`}>
                          {m.text}
                        </div>
                        <span className="text-[7px] font-bold text-slate-400 uppercase mt-1 px-1">{m.sender} • Agora</span>
                     </div>
                   ))}
                   <div ref={chatEndRef} />
                </div>
                <div className="p-6 border-t border-slate-100 bg-white flex gap-3">
                   <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendChatMessage()} placeholder="Digite aqui sua dúvida..." className="flex-1 bg-slate-50 border-none rounded-xl px-6 text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                   <button onClick={sendChatMessage} className="p-4 bg-slate-900 text-white rounded-xl shadow-xl hover:bg-indigo-600 transition-all"><Send size={18}/></button>
                </div>
             </div>
           )}
           <div className="hidden md:flex w-72 bg-slate-50 border-l border-slate-100 p-8 flex-col justify-center space-y-6">
              <div className="p-4 bg-white rounded-2xl shadow-sm border border-slate-100 text-center space-y-3">
                 <ShieldCheck size={32} className="mx-auto text-indigo-600"/>
                 <p className="text-[10px] font-black uppercase text-slate-900 italic leading-tight">Sua segurança é nossa prioridade</p>
                 <p className="text-[8px] text-slate-400 font-medium italic">A secretaria validará seus dados antes de qualquer alteração de credencial.</p>
              </div>
              <div className="p-4 bg-indigo-600 text-white rounded-2xl shadow-xl text-center space-y-2">
                 <h4 className="text-xs font-black uppercase italic tracking-tighter">Horário Administrativo</h4>
                 <p className="text-[8px] font-bold opacity-70 uppercase tracking-widest">Seg a Sex: 08h às 22h</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  if (viewMode === 'landing') {
    return (
      <div className="min-h-screen bg-white font-sans text-slate-900 overflow-x-hidden">
        <div className="relative min-h-screen flex flex-col">
          <div className="absolute inset-0 z-0">
            <img src="https://images.unsplash.com/photo-1519791883288-dc8bd696e667?auto=format&fit=crop&w=1920&q=80" className="w-full h-full object-cover brightness-[0.2]" alt="Background Sacred study" />
            <div className="absolute inset-0 bg-gradient-to-b from-indigo-900/30 via-transparent to-white"></div>
          </div>
          <header className="relative z-10 h-24 px-8 flex items-center justify-between max-w-7xl mx-auto w-full">
            <div className="flex items-center gap-3">
              <div className="bg-indigo-600 p-2.5 rounded-2xl text-white shadow-2xl"><BookOpen size={28} /></div>
              <div className="flex flex-col">
                <span className="font-black text-white text-2xl uppercase italic tracking-tighter leading-none">Escola Bíblica AD</span>
                <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest italic mt-1">LMS Teológico Sincronizado</span>
              </div>
            </div>
            <div className="hidden md:flex items-center gap-4">
              <button onClick={() => setViewMode('login')} className="px-8 py-3 bg-white/10 backdrop-blur-md text-white border border-white/20 rounded-full text-[11px] font-black uppercase italic hover:bg-white hover:text-slate-900 transition-all">Portal do Aluno</button>
              <a href="#cursos" className="px-8 py-3 bg-indigo-600 text-white rounded-full text-[11px] font-black uppercase italic shadow-2xl hover:bg-indigo-500 transition-all">Matricule-se Já</a>
            </div>
          </header>
          <main className="relative z-10 flex-1 flex flex-col items-center justify-center text-center px-6 py-20 max-w-5xl mx-auto">
            <div className="inline-flex items-center gap-2 px-6 py-2 bg-indigo-600/30 backdrop-blur-xl rounded-full border border-indigo-400/30 text-indigo-400 text-[11px] font-black uppercase tracking-[0.4em] mb-10">
              <Zap size={16} fill="currentColor" className="text-yellow-400" /> Fluxo de Ensino v4.2 Ativo
            </div>
            <h1 className="text-7xl md:text-9xl font-black text-white uppercase italic tracking-tighter leading-[0.82] mb-10 drop-shadow-2xl">Teologia <br/> <span className="text-indigo-500">Master</span></h1>
            <p className="text-slate-300 text-xl md:text-2xl font-medium italic max-w-3xl leading-relaxed mb-16 drop-shadow-lg">Capacitação avançada com certificação digital e suporte operacional em tempo real.</p>
            <div className="flex flex-col sm:flex-row gap-6 w-full max-w-lg">
              <a href="#cursos" className="flex-1 py-6 bg-indigo-600 text-white rounded-[2rem] text-xs font-black uppercase italic tracking-[0.3em] shadow-2xl hover:bg-indigo-700 transition-all flex items-center justify-center gap-3">Explorar Matriz <ArrowRight size={20}/></a>
            </div>
          </main>
        </div>
        <section id="cursos" className="py-32 px-6 max-w-7xl mx-auto space-y-16">
          <div className="text-center space-y-4">
            <h2 className="text-5xl font-black uppercase italic tracking-tighter">Matriz Acadêmica</h2>
            <p className="text-slate-400 text-sm font-bold uppercase tracking-[0.4em] italic">Vagas Reais e Sincronizadas</p>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12">
            {courses.map(course => (
              <div key={course.id} className="group bg-white border border-slate-200 rounded-[3rem] overflow-hidden hover:shadow-2xl hover:border-indigo-400 transition-all flex flex-col">
                <div className="h-72 overflow-hidden relative">
                   <img src={course.capaUrl || "https://images.unsplash.com/photo-1507434965515-61970f2bd7c6?auto=format&fit=crop&w=1920&q=80"} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                   <div className="absolute top-6 right-6 px-4 py-1.5 bg-white/90 backdrop-blur-md rounded-full text-[9px] font-black uppercase italic shadow-lg text-indigo-600 border border-indigo-100">{course.categoria}</div>
                </div>
                <div className="p-10 flex-1 flex flex-col">
                  <h3 className="text-2xl font-black uppercase italic text-slate-900 mb-6">{course.nome}</h3>
                  <button onClick={() => { setSelectedCourse(course); setViewMode('enroll_form'); }} className="mt-auto w-full py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all shadow-xl">Realizar Matrícula Master</button>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>
    );
  }

  if (viewMode === 'enroll_form') {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col">
        <header className="bg-white border-b border-slate-200 h-20 px-8 flex items-center justify-between shadow-sm shrink-0">
          <button onClick={() => setViewMode('landing')} className="flex items-center gap-2 text-[10px] font-black uppercase italic text-slate-400 hover:text-indigo-600 transition-all"><ChevronLeft size={18}/> Cancelar Fluxo</button>
          <div className="text-center"><h2 className="text-lg font-black uppercase italic tracking-tighter leading-none">Matrícula Sincronizada</h2><p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-1">Disciplina: {selectedCourse?.nome}</p></div>
          <div className="w-20"></div>
        </header>
        <div className="flex-1 overflow-y-auto bg-slate-50 py-12 px-6">
          <form onSubmit={handleFinalizeEnroll} className="max-w-4xl mx-auto bg-white rounded-[3rem] p-12 shadow-2xl space-y-12 border border-slate-100">
             <div className="grid grid-cols-1 lg:grid-cols-4 gap-12">
                <div className="lg:col-span-1 flex flex-col items-center gap-4">
                   <div onClick={() => fileInputRef.current?.click()} className="w-40 h-40 bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden rounded-3xl group hover:border-indigo-400 shadow-inner">
                      {enrollForm.fotoUrl ? <img src={enrollForm.fotoUrl} className="w-full h-full object-cover" /> : <div className="text-center opacity-30"><Camera size={32} className="mx-auto"/><span className="text-[8px] font-black uppercase mt-2 block">Upload Identidade</span></div>}
                   </div>
                   <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                </div>
                <div className="lg:col-span-3 grid grid-cols-1 md:grid-cols-2 gap-6 text-slate-900">
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Nome Completo</label><input required value={enrollForm.nome} onChange={e => setEnrollForm({...enrollForm, nome: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">WhatsApp / Tel</label><input required value={enrollForm.telefone} onChange={e => setEnrollForm({...enrollForm, telefone: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" placeholder="(00) 00000-0000" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">E-mail de Contato</label><input type="email" required value={enrollForm.emailPessoal} onChange={e => setEnrollForm({...enrollForm, emailPessoal: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Defina sua Senha</label><input type="password" required value={enrollForm.password} onChange={e => setEnrollForm({...enrollForm, password: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Documento CPF</label><input required value={enrollForm.cpf} onChange={e => setEnrollForm({...enrollForm, cpf: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Nascimento</label><input type="date" required value={enrollForm.nascimento} onChange={e => setEnrollForm({...enrollForm, nascimento: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                </div>
             </div>
             <div className="space-y-6 pt-6 border-t border-slate-100">
                <h4 className="text-[10px] font-black uppercase text-indigo-600 italic flex items-center gap-2 tracking-widest"><MapPin size={16}/> Localidade e Endereço</h4>
                <div className="grid grid-cols-1 md:grid-cols-6 gap-4 text-slate-900">
                   <div className="md:col-span-1 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">CEP</label><input required value={enrollForm.endereco.cep} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, cep: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner" placeholder="00000-000" /></div>
                   <div className="md:col-span-4 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">Logradouro / Rua</label><input required value={enrollForm.endereco.rua} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, rua: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner" /></div>
                   <div className="md:col-span-1 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">Nº</label><input required value={enrollForm.endereco.numero} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, numero: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner" placeholder="S/N" /></div>
