                <div className="relative py-4 flex items-center justify-center"><div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div><span className="relative px-6 bg-slate-50 text-[9px] font-black text-slate-300 uppercase italic">Ingresso Acadêmico</span></div>
                <button onClick={() => setViewMode('landing')} className="w-full py-6 bg-white border border-slate-200 text-slate-900 rounded-[2rem] text-[10px] font-black uppercase italic tracking-widest hover:bg-slate-100 hover:border-indigo-600 transition-all flex items-center justify-center gap-3">
