               <ShieldCheck size={14} className={isAdminMode ? 'text-indigo-600' : ''}/> {isAdminMode ? 'Sair da Governança Administrativa' : 'Acesso Restrito: Painel de Governança'}
             </button>
          </div>
       </div>
    </div>
