import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, MessageSquare, Search, Plus, X, FolderOpen, FileText, Download, UserCheck, ShieldAlert, FileSignature, Save, PenTool, UserX, Check, ArrowRightLeft, Fingerprint, Star, Send, Folder, Archive, CheckCircle2, ChevronRight, FileDown, Eye, Phone, CreditCard
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'assinatura';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  const [currentPath, setCurrentPath] = useState<string[]>([]);
  const [viewingStudent, setViewingStudent] = useState<any | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const pendingVal = students.filter(s => s.status === 'aguardando_validacao').length;
    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado').length,
      arquivados: tickets.filter(t => t.status === 'Arquivado').length,
      pendentesVal: pendingVal,
      totalGed: files.length
    };
  }, [tickets, students, files]);

  const handleSendMessage = async () => {
    if (!selectedTicketId || !chatMessage.trim()) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const filteredTickets = tickets.filter(t => {
    const matchSearch = t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase()) || t.user?.toLowerCase().includes(searchTerm.toLowerCase());
    if (activeTab === 'atendimento') return matchSearch && t.status === 'Pendente';
    if (activeTab === 'chat') {
       if (chatFilter === 'abertos') return matchSearch && t.status === 'Em Atendimento';
       if (chatFilter === 'finalizados') return matchSearch && t.status === 'Finalizado';
       if (chatFilter === 'arquivados') return matchSearch && t.status === 'Arquivado';
    }
    return matchSearch;
  });

  const renderOperational = () => {
    switch(opSubView) {
      case 'validacao':
        const pending = students.filter(s => s.status === 'aguardando_validacao');
        return (
          <div className="bg-white border border-slate-300 animate-in zoom-in-98 h-full flex flex-col">
             <div className="p-4 bg-slate-900 text-white flex justify-between items-center shrink-0">
                <h3 className="text-xs font-bold uppercase italic flex items-center gap-2"><UserCheck size={16}/> Auditoria de Novas Matrículas</h3>
                <button onClick={() => setOpSubView('main')}><X size={18}/></button>
             </div>
             <div className="flex-1 overflow-auto">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-50 border-b border-slate-300 text-[10px] font-bold uppercase sticky top-0">
                       <tr><th className="px-6 py-4">Matrícula / ID</th><th className="px-6 py-4">Aluno</th><th className="px-6 py-4">Curso Selecionado</th><th className="px-6 py-4 text-center">Gestão Direta</th></tr>
                    </thead>
                    <tbody className="text-xs">
                       {pending.length === 0 ? (
                         <tr><td colSpan={4} className="p-20 text-center text-slate-300 uppercase italic font-black text-xs">Fila de validação limpa.</td></tr>
                       ) : pending.map(s => (
                         <tr key={s.uid} className="border-b border-slate-200 hover:bg-indigo-50/20 transition-all group">
                            <td className="px-6 py-4 font-mono font-bold text-indigo-600">{s.academicId}</td>
                            <td className="px-6 py-4">
                               <p className="font-black uppercase text-slate-900 leading-none">{s.displayName}</p>
                               <p className="text-[9px] text-slate-400 font-bold mt-1 uppercase tracking-tight">{s.cpf} • {s.telefone}</p>
                            </td>
                            <td className="px-6 py-4 font-bold text-indigo-600 uppercase italic">{courses.find(c=>c.id===s.cursoInicial)?.nome}</td>
                            <td className="px-6 py-4 flex items-center justify-center gap-2">
                               <button onClick={() => setViewingStudent(s)} className="p-2 bg-slate-100 text-slate-400 hover:text-indigo-600 rounded-lg transition-all border border-slate-200"><Eye size={14}/></button>
                               <button onClick={async () => await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'})} className="px-6 py-2 bg-emerald-600 text-white text-[9px] font-black uppercase italic shadow-lg shadow-emerald-100 hover:bg-emerald-700">Aprovar Matrícula</button>
                               <button onClick={async () => { if(confirm('Remover matrícula irregular?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2 text-rose-300 hover:text-rose-600 border border-slate-100"><UserX size={16}/></button>
                            </td>
                         </tr>
                       ))}
                    </tbody>
                </table>
             </div>
             {viewingStudent && (
               <div className="fixed inset-0 z-[3000] bg-slate-900/80 backdrop-blur-md flex items-center justify-center p-6 animate-in zoom-in-95">
                  <div className="bg-white w-full max-w-xl rounded-[3rem] p-10 shadow-2xl relative">
                     <button onClick={() => setViewingStudent(null)} className="absolute top-8 right-8 p-2 bg-slate-50 rounded-full hover:bg-rose-50 hover:text-rose-600 transition-all"><X size={20}/></button>
                     <div className="flex items-center gap-4 mb-8">
                        <div className="w-16 h-16 bg-indigo-600 text-white rounded-2xl flex items-center justify-center text-2xl font-black italic shadow-xl">{(viewingStudent.displayName||'U').charAt(0)}</div>
                        <div>
                           <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{viewingStudent.displayName}</h2>
                           <p className="text-[9px] text-indigo-500 font-black uppercase tracking-widest mt-1">Status: Aguardando Auditoria</p>
                        </div>
                     </div>
                     <div className="grid grid-cols-2 gap-6 bg-slate-50 p-6 rounded-3xl border border-slate-100 shadow-inner">
                        <div className="space-y-1"><p className="text-[8px] font-black text-slate-400 uppercase">Documento CPF</p><p className="text-xs font-bold text-slate-800 flex items-center gap-2"><CreditCard size={12}/> {viewingStudent.cpf}</p></div>
                        <div className="space-y-1"><p className="text-[8px] font-black text-slate-400 uppercase">WhatsApp / Contato</p><p className="text-xs font-bold text-slate-800 flex items-center gap-2"><Phone size={12}/> {viewingStudent.telefone}</p></div>
                        <div className="space-y-1"><p className="text-[8px] font-black text-slate-400 uppercase">Login Acadêmico</p><p className="text-xs font-bold text-indigo-600 lowercase">{viewingStudent.email}</p></div>
                        <div className="space-y-1"><p className="text-[8px] font-black text-slate-400 uppercase">Endereço Declarado</p><p className="text-[10px] font-bold text-slate-800 leading-tight uppercase">{viewingStudent.endereco?.cidade}-{viewingStudent.endereco?.uf}</p></div>
                     </div>
                     <div className="mt-10 flex gap-4">
                        <button onClick={() => setViewingStudent(null)} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic">Fechar Dossiê</button>
                        <button onClick={async () => { await updateDoc(doc(db, 'users', viewingStudent.uid), {status: 'ativo'}); setViewingStudent(null); }} className="flex-2 py-4 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase italic shadow-2xl shadow-emerald-100">Efetivar Matrícula</button>
                     </div>
                  </div>
               </div>
             )}
          </div>
        );
      case 'assinatura':
        return (
          <div className="max-w-md mx-auto bg-white border border-slate-300 p-8 text-center space-y-6 rounded-[2rem] shadow-xl">
             <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto text-slate-400"><Fingerprint size={32}/></div>
             <h3 className="font-bold uppercase italic text-slate-900 tracking-tight">Assinatura do Secretário</h3>
