             </div>
             <button onClick={() => setIsSignModalOpen(true)} className="w-full py-4 bg-slate-900 text-white text-[10px] font-black uppercase italic tracking-widest shadow-2xl hover:bg-indigo-600 transition-all">Registrar Biometria Digital</button>
             <button onClick={() => setOpSubView('main')} className="text-[9px] text-slate-400 underline uppercase italic font-bold">Voltar ao operacional</button>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
             <button onClick={() => alert('Abrir Gerador de Declaração Acadêmica Master')} className="bg-white p-8 border border-slate-200 rounded-[2rem] flex flex-col items-center gap-4 hover:bg-indigo-600 group transition-all shadow-sm">
                <div className="text-slate-400 group-hover:text-white transition-colors"><FileText size={32}/></div>
                <span className="text-[9px] font-black uppercase text-slate-900 group-hover:text-white italic tracking-widest">Declaracão</span>
             </button>
             <button onClick={() => setOpSubView('validacao')} className="bg-white p-8 border border-slate-200 rounded-[2rem] flex flex-col items-center gap-4 hover:bg-indigo-600 group transition-all shadow-sm relative">
                <div className="text-slate-400 group-hover:text-white transition-colors"><UserCheck size={32}/></div>
                <span className="text-[9px] font-black uppercase text-slate-900 group-hover:text-white italic tracking-widest text-center">Auditoria Matrícula</span>
                {stats.pendentesVal > 0 && <span className="absolute top-4 right-4 bg-rose-600 text-white text-[9px] px-2 py-0.5 font-black rounded-full shadow-lg border border-white animate-bounce">{stats.pendentesVal}</span>}
