import React, { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, doc, getDoc, updateDoc, serverTimestamp, orderBy } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Course, User, Module, Lesson } from '../types';
import { BookOpen, PlayCircle, Award, ArrowLeft, GraduationCap, Zap, Bell, Menu, X, LogOut, Home, LifeBuoy, ScrollText, Smartphone, ShieldAlert, Star, Play, Settings, RefreshCw, UserCheck, Clock } from 'lucide-react';

interface StudentViewProps { user: User; }
type StudentSubView = 'dashboard' | 'classroom' | 'library' | 'certificates' | 'support';

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [enrolledCourse, setEnrolledCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [userData, setUserData] = useState<any>(null);

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      try {
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          const data = userDoc.data();
          setUserData(data);
          // Auditoria: Alunos administrativos usam 'cursoInicial', captados podem usar similar.
          const cId = data.cursoInicial || data.cursoId;

          if (cId) {
            const courseDoc = await getDoc(doc(db, 'cursos', cId));
            if (courseDoc.exists()) {
              setEnrolledCourse({ id: courseDoc.id, ...courseDoc.data() } as Course);
            }
          }
        }
      } catch (error) {
        console.error("Erro na auditoria de acesso do aluno:", error);
      }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  const handleStartLesson = () => {
    if (!enrolledCourse) return;
    onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', enrolledCourse.id)), snap => {
      const mods = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));
      setModules(mods);
      if (mods.length > 0 && mods[0].lessons?.length > 0) setActiveLesson(mods[0].lessons[0]);
      setActiveSubView('classroom');
    });
  };

  if (loading) return (
    <div className="h-screen bg-slate-950 flex flex-col items-center justify-center p-12 text-center gap-6">
       <RefreshCw size={48} className="text-indigo-600 animate-spin" />
       <div>
          <p className="font-black text-white uppercase italic text-[12px] tracking-[0.5em] leading-none">Auditando Vínculos Acadêmicos</p>
          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-4">Ecossistema Sincronizado EB-AD v4.0</p>
       </div>
    </div>
  );

  // Audit: Se o aluno ainda está aguardando validação pela secretaria
  if (userData?.status === 'aguardando_validacao') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 text-center">
         <div className="max-w-xl w-full bg-white rounded-[4rem] p-16 shadow-[0_100px_200px_rgba(0,0,0,0.8)] space-y-12 animate-in zoom-in-95">
            <div className="w-24 h-24 bg-amber-50 text-amber-600 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner animate-pulse"><UserCheck size={48}/></div>
            <div className="space-y-4">
              <h2 className="text-4xl font-black text-slate-900 uppercase italic tracking-tighter leading-[0.9]">Matrícula em <br/> <span className="text-indigo-600">Auditoria Digital</span></h2>
              <p className="text-slate-400 text-xs font-medium italic leading-relaxed">Sua conta foi sincronizada com sucesso, mas como medida de segurança, nossa secretaria está validando seus dados cadastrais (CPF e Pagamento).</p>
            </div>
            <div className="grid grid-cols-2 gap-4">
               <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 flex flex-col items-center justify-center gap-3">
                  <Clock size={24} className="text-indigo-600" />
                  <p className="text-[10px] font-black uppercase text-slate-900 italic">Prazo Estimado</p>
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Até 24h Úteis</p>
               </div>
               <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 flex flex-col items-center justify-center gap-3">
                  <ShieldAlert size={24} className="text-rose-600" />
                  <p className="text-[10px] font-black uppercase text-slate-900 italic">Segurança Ativa</p>
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Sincronização SSL</p>
               </div>
            </div>
            <div className="pt-6 border-t border-slate-50 flex flex-col gap-4">
               <button onClick={() => window.location.reload()} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] text-[11px] font-black uppercase italic tracking-[0.3em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-3 active:scale-95"><RefreshCw size={20}/> Verificar Atualização</button>
               <button onClick={() => auth.signOut()} className="text-[10px] font-black text-slate-400 uppercase italic tracking-widest hover:text-rose-600">Sair do Sistema</button>
            </div>
         </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex overflow-hidden font-sans">
      <aside className={`bg-slate-900 w-72 flex flex-col transition-all duration-300 z-50 ${isSidebarOpen ? 'ml-0' : '-ml-72'}`}>
         <div className="p-8 border-b border-white/5 flex items-center gap-3">
            <div className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-600/20"><GraduationCap size={24}/></div>
            <div><p className="font-black text-white uppercase italic text-lg leading-none">EB-EAD</p><p className="text-[8px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Portal do Aluno Sinc</p></div>
         </div>
         <nav className="flex-1 p-4 space-y-2 mt-4">
            {[
              { id: 'dashboard', label: 'Home Page', icon: <Home size={18}/> },
              { id: 'library', label: 'Biblioteca GED', icon: <BookOpen size={18}/> },
              { id: 'certificates', label: 'Meus Diplomas', icon: <Award size={18}/> },
              { id: 'support', label: 'Suporte & Ajuda', icon: <LifeBuoy size={18}/> }
            ].map(item => (
              <button key={item.id} onClick={() => setActiveSubView(item.id as any)} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${activeSubView === item.id ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}>{item.icon} {item.label}</button>
            ))}
         </nav>
         <div className="p-6 border-t border-white/5 bg-black/20">
            <div className="flex items-center gap-4 p-4 bg-white/5 rounded-2xl">
               <div className="w-10 h-10 rounded-xl overflow-hidden shadow-lg border border-white/10">
                  {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-indigo-600 flex items-center justify-center text-white font-black italic">{(user.displayName||'U').charAt(0)}</div>}
               </div>
               <div className="flex-1 overflow-hidden">
                  <p className="text-[9px] font-black text-white uppercase italic truncate">{(user.displayName||'Aluno').split(' ')[0]}</p>
                  <p className="text-[7px] font-bold text-indigo-400 uppercase mt-1 tracking-widest">MATRÍCULA ATIVA</p>
               </div>
               <button onClick={() => auth.signOut()} className="text-rose-500 hover:scale-125 transition-transform"><LogOut size={18}/></button>
            </div>
         </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
         <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-8 shadow-sm">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2.5 bg-slate-50 text-slate-400 rounded-xl hover:bg-indigo-600 hover:text-white transition-all"><Menu size={20}/></button>
            <div className="flex items-center gap-6">
               <div className="hidden sm:flex items-center gap-3 px-6 py-2 bg-indigo-50 text-indigo-600 rounded-full border border-indigo-100 shadow-inner"><Zap size={14} fill="currentColor"/><span className="text-[9px] font-black uppercase italic tracking-widest">Sincronização SSL Ativa</span></div>
               <button className="relative p-2.5 text-slate-300 hover:text-indigo-600 transition-all"><Bell size={20}/><div className="absolute top-2 right-2 w-2 h-2 bg-rose-500 rounded-full border-2 border-white"></div></button>
            </div>
