                 <button onClick={() => setActiveSubView('dashboard')} className="flex items-center gap-2 px-6 py-3 bg-white border border-slate-200 text-slate-400 rounded-xl text-[10px] font-black uppercase mx-auto hover:bg-slate-50"><ChevronRight size={14} className="rotate-180"/> Retornar</button>
