                            </td>
                            <td className="px-6 py-4 font-black text-indigo-600 uppercase italic text-[10px]">{courses.find(c=>c.id===s.cursoInicial)?.nome || 'CURSO NÃO IDENTIFICADO'}</td>
                            <td className="px-6 py-4 flex items-center justify-center gap-2">
                               <button onClick={() => setViewingStudent(s)} className="p-2 bg-slate-100 text-slate-400 hover:text-indigo-600 rounded-lg transition-all border border-slate-200"><Eye size={14}/></button>
                               <button onClick={async () => { if(confirm(`Efetivar a matrícula de ${s.displayName}?`)) await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'}); }} className="px-6 py-2.5 bg-emerald-600 text-white text-[9px] font-black uppercase italic shadow-lg hover:bg-emerald-700 transition-all">Aprovar Ingresso</button>
                               <button onClick={async () => { if(confirm('Remover matrícula irregular?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2 text-rose-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all"><UserX size={16}/></button>
                            </td>
                         </tr>
                       ))}
                    </tbody>
                </table>
             </div>
          </div>
        );
      case 'transferencia':
        return (
          <div className="max-w-2xl mx-auto bg-white border border-slate-300 p-10 space-y-10 rounded-[3rem] shadow-2xl animate-in zoom-in-95">
