             <div className="space-y-6">
                <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Selecionar Aluno Ativo</label><select value={transferenciaData.alunoUid} onChange={e => setTransferenciaData({...transferenciaData, alunoUid: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black uppercase outline-none shadow-inner focus:ring-1 focus:ring-indigo-600 shadow-slate-200"><option value="">Selecione o Aluno...</option>{students.filter(s=>s.status==='ativo').map(s=><option key={s.uid} value={s.uid}>{s.displayName} ({s.academicId})</option>)}</select></div>
                <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Nova Cadeira / Curso</label><select value={transferenciaData.novoCursoId} onChange={e => setTransferenciaData({...transferenciaData, novoCursoId: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black uppercase outline-none shadow-inner focus:ring-1 focus:ring-indigo-600 shadow-slate-200"><option value="">Selecione o Novo Curso...</option>{courses.map(c=><option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
             </div>
             <div className="flex gap-4 pt-6"><button onClick={() => setOpSubView('main')} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Cancelar</button><button onClick={async () => { if(!transferenciaData.alunoUid || !transferenciaData.novoCursoId) return; await updateDoc(doc(db, 'users', transferenciaData.alunoUid), { cursoInicial: transferenciaData.novoCursoId }); alert('Transferência de Matriz Concluída!'); setOpSubView('main'); }} className="flex-2 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic shadow-2xl hover:bg-indigo-600 transition-all tracking-[0.2em]">Executar Mudança</button></div>
