             </div>
             <div className="p-8 bg-slate-50 rounded-3xl border border-slate-100 space-y-8">
                <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Selecione o Aluno Beneficiário</label><select onChange={e => { const s = students.find(x=>x.uid===e.target.value); setViewingStudent(s); }} className="w-full p-4 bg-white border-none rounded-2xl text-[11px] font-black uppercase shadow-sm outline-none focus:ring-1 focus:ring-indigo-600"><option value="">Localizar Aluno...</option>{students.map(s=><option key={s.uid} value={s.uid}>{s.displayName} ({s.academicId})</option>)}</select></div>
                {viewingStudent && (
                  <div className="bg-white p-12 rounded-[2rem] border border-slate-200 shadow-2xl space-y-10 font-serif text-slate-900 relative" id="printable-decl">
