          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {courses.map(course => (
              <div key={course.id} className="group bg-white border border-slate-200 rounded-[2.5rem] overflow-hidden hover:shadow-2xl transition-all flex flex-col">
                <div className="h-60 overflow-hidden relative"><img src={course.capaUrl} className="w-full h-full object-cover transition-transform group-hover:scale-105" /><div className="absolute top-4 right-4 px-3 py-1 bg-white/90 rounded-full text-[8px] font-black uppercase text-indigo-600 italic">{course.categoria}</div></div>
                <div className="p-8 flex-1 flex flex-col items-center text-center">
                  <h3 className="text-xl font-black uppercase italic text-slate-900 mb-6">{course.nome}</h3>
                  <button onClick={() => { setSelectedCourse(course); setViewMode('enroll_form'); }} className="mt-auto w-full py-4 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all">Iniciar Matrícula Master</button>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>
    );
  }

  if (viewMode === 'enroll_form') {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col">
        <header className="bg-white border-b border-slate-200 h-20 px-4 md:px-8 flex items-center justify-between shadow-sm sticky top-0 z-10">
          <button onClick={() => setViewMode('landing')} className="flex items-center gap-2 text-[9px] font-black uppercase text-slate-400 hover:text-indigo-600"><ChevronLeft size={16}/> Cancelar</button>
          <div className="text-center hidden sm:block"><h2 className="text-sm font-black uppercase italic leading-none">Matrícula Sincronizada</h2><p className="text-[7px] font-bold text-slate-400 uppercase mt-1 italic">{selectedCourse?.nome}</p></div>
          <div className="w-20"></div>
        </header>
        <div className="flex-1 overflow-y-auto py-8 px-4">
          <form onSubmit={handleFinalizeEnroll} className="max-w-4xl mx-auto bg-white rounded-[2rem] md:rounded-[3rem] p-6 md:p-12 shadow-2xl space-y-10 border border-slate-100 text-slate-900">
             <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
