                   <p className="text-[8px] font-black uppercase text-slate-400">Selfie Identidade</p>
                </div>
                <div className="lg:col-span-3 grid grid-cols-1 md:grid-cols-2 gap-4">
                   <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">Nome Completo</label><input required value={enrollForm.nome} onChange={e => setEnrollForm({...enrollForm, nome: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-black shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">WhatsApp / Tel</label><input required value={enrollForm.telefone} onChange={e => setEnrollForm({...enrollForm, telefone: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-black shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" placeholder="(00) 00000-0000" /></div>
