                   <div className="col-span-2 md:col-span-3 space-y-1"><label className="text-[8px] font-black uppercase text-slate-400">Rua</label><input required value={enrollForm.endereco.rua} className="w-full p-3 bg-slate-50 border-none rounded-xl text-xs font-black shadow-inner" /></div>
                   <div className="col-span-1 space-y-1"><label className="text-[8px] font-black uppercase text-slate-400">Nº</label><input required value={enrollForm.endereco.numero} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, numero: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-xs font-black shadow-inner" /></div>
                   <div className="col-span-2 space-y-1"><label className="text-[8px] font-black uppercase text-slate-400">Bairro</label><input required value={enrollForm.endereco.bairro} className="w-full p-3 bg-slate-50 border-none rounded-xl text-xs font-black shadow-inner" /></div>
                   <div className="col-span-1 md:col-span-2 space-y-1"><label className="text-[8px] font-black uppercase text-slate-400">Cidade</label><input required value={enrollForm.endereco.cidade} className="w-full p-3 bg-slate-50 border-none rounded-xl text-xs font-black shadow-inner" /></div>
