             {error && <div className="p-4 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-2xl flex items-center gap-2 animate-bounce"><Info size={14}/> {error}</div>}
             <button type="submit" disabled={loading} className="w-full py-6 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-[0.3em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-3">
                {loading ? <RefreshCw className="animate-spin" size={20}/> : <><CreditCard size={20}/> Finalizar Matrícula Master</>}
             </button>
          </form>
        </div>
      </div>
    );
  }

  if (viewMode === 'success_notice') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6">
         <div className="max-w-md w-full bg-white rounded-[3rem] p-10 md:p-12 text-center space-y-10 animate-in zoom-in-95">
            <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><CheckCircle2 size={48}/></div>
            <div className="space-y-3"><h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Matrícula Efetuada!</h2><p className="text-slate-400 text-xs font-medium italic">Seus dados foram sincronizados via Master Cloud. Aguarde validação para liberar a sala de aula.</p></div>
            <div className="p-8 bg-indigo-50 rounded-[2.5rem] border border-indigo-100 space-y-4"><p className="text-[9px] font-black uppercase text-indigo-400 tracking-widest">Seu Login Acadêmico Permanente</p><p className="text-sm font-black text-indigo-600 italic select-all underline">{generatedEmail}</p></div>
            <button onClick={() => setViewMode('login')} className="w-full py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all shadow-xl">Entrar no Portal</button>
         </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative">
       <div className="absolute inset-0 z-0 opacity-20"><img src="https://images.unsplash.com/photo-1501290830387-99bc439ca623?auto=format&fit=crop&w=1920&q=80" className="w-full h-full object-cover" /></div>
       <div className="relative z-10 w-full max-w-5xl bg-white rounded-[2rem] md:rounded-[4rem] shadow-2xl overflow-hidden flex flex-col lg:flex-row animate-in zoom-in-95">
