             <div className="space-y-3"><h3 className="text-4xl font-black uppercase italic tracking-tighter leading-none">Portal <span className="text-indigo-600">Master</span></h3><p className="text-slate-400 text-xs font-medium italic">Acesse sua trilha acadêmica sincronizada.</p></div>
             {error && <div className="p-4 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-2xl border border-rose-100 flex items-center gap-2"><Info size={16}/> {error}</div>}
