                <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4">Senha</label><input type="password" required value={password} onChange={e => setPassword(e.target.value)} className="w-full p-5 bg-slate-50 border-none rounded-[2rem] text-sm font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                <button type="submit" disabled={loading} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] text-[10px] font-black uppercase italic tracking-[0.4em] shadow-xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-3">
                   {loading ? <RefreshCw className="animate-spin" size={24}/> : <><LogIn size={20}/> Ingressar na Sala</>}
