                        <h2 className="text-2xl font-black uppercase italic tracking-tighter leading-none">Escola Bíblica AD</h2>
                        <p className="text-[10px] font-bold uppercase tracking-[0.4em] italic text-slate-400">Certificação Acadêmica Permanente</p>
                     </div>
                     <div className="space-y-6 text-sm leading-relaxed text-justify px-4">
