                        <p>O referido aluno cumpre regularmente a carga horária e diretrizes pedagógicas estabelecidas pelo conselho acadêmico para o ciclo letivo vigente.</p>
                        <p className="pt-8">Por ser verdade, firmamos the presente.</p>
                     </div>
                     <div className="flex flex-col items-center gap-2 pt-16">
                        <div className="w-48 h-12 border-b border-slate-900 flex flex-col items-center justify-center">
                           {secSignature && <img src={secSignature} className="max-h-12 grayscale" />}
                        </div>
                        <p className="text-[10px] font-black uppercase italic">Secretaria Master EB-AD</p>
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{new Date().toLocaleDateString('pt-BR', {day:'2-digit', month:'long', year:'numeric'})}</p>
                     </div>
                     <div className="absolute top-10 right-10 opacity-10"><ShieldCheck size={80}/></div>
                  </div>
                )}
             </div>
             {viewingStudent && (
               <div className="flex gap-4"><button onClick={() => window.print()} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic flex items-center justify-center gap-3 shadow-2xl hover:bg-indigo-600 transition-all"><Printer size={18}/> Imprimir Documento Validado</button></div>
             )}
          </div>
        );
      case 'assinatura':
        return (
          <div className="max-w-md mx-auto bg-white border border-slate-300 p-8 text-center space-y-6 rounded-[2rem] shadow-xl">
