import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, updateProfile } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, serverTimestamp, getDocs } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, GraduationCap, ArrowRight, BookOpen, Camera, MapPin, ChevronLeft, Info, RefreshCw, CheckCircle2, LogIn, CreditCard } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form' | 'success_notice';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);
  const [generatedEmail, setGeneratedEmail] = useState('');

  const [enrollForm, setEnrollForm] = useState({
    nome: '', emailPessoal: '', password: '', cpf: '', nascimento: '', telefone: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsub = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), snap => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsub();
  }, []);

  const handleCepSearch = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    setEnrollForm(prev => ({ ...prev, endereco: { ...prev.endereco, cep: cleanCep } }));
    if (cleanCep.length === 8) {
      try {
        const res = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await res.json();
        if (!data.erro) {
          setEnrollForm(prev => ({
            ...prev,
            endereco: { ...prev.endereco, rua: data.logradouro, bairro: data.bairro, cidade: data.localidade, uf: data.uf }
          }));
        }
      } catch (e) { console.error("Erro ViaCEP", e); }
    }
  };

  const generateAcademicEmail = async (fullName: string) => {
    const names = fullName.trim().toLowerCase().split(' ');
    const first = names[0];
    const last = names.length > 1 ? names[names.length - 1] : '';
    let base = `${first}${last ? '.' + last : ''}@ead.com`;
    const snap = await getDocs(query(collection(db, 'users'), where('email', '==', base)));
    if (!snap.empty) base = `${first}.${last}${Math.floor(Math.random() * 99)}@ead.com`;
    return base;
  };

  const handleFinalizeEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    setLoading(true);
    setError('');
    try {
      const academicoEmail = await generateAcademicEmail(enrollForm.nome);
      const userCredential = await createUserWithEmailAndPassword(auth, academicoEmail, enrollForm.password);

      // Sincronização de Perfil de Identidade para evitar o erro do "U"
      await updateProfile(userCredential.user, {
        displayName: enrollForm.nome,
        photoURL: enrollForm.fotoUrl || null
      });

      const uid = userCredential.user.uid;
      const academicId = `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      const payload = {
        uid,
        displayName: enrollForm.nome,
        nome: enrollForm.nome,
        email: academicoEmail,
        emailPessoal: enrollForm.emailPessoal.toLowerCase(),
        password: enrollForm.password, 
        cpf: enrollForm.cpf,
        nascimento: enrollForm.nascimento,
        telefone: enrollForm.telefone,
        photoURL: enrollForm.fotoUrl,
        endereco: enrollForm.endereco,
        role: 'aluno',
        status: 'aguardando_validacao',
        cursoInicial: selectedCourse.id,
        academicId,
        createdAt: serverTimestamp(),
        progress: 0,
        sincronizado: true
      };

      await setDoc(doc(db, 'users', uid), payload);
      setGeneratedEmail(academicoEmail);
      setViewMode('success_notice');
    } catch (err: any) {
      setError('Falha na sincronização Master: ' + err.message);
    } finally { setLoading(false); }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => setEnrollForm({...enrollForm, fotoUrl: ev.target?.result as string});
      reader.readAsDataURL(file);
    }
  };

  if (viewMode === 'landing') {
    return (
      <div className="min-h-screen bg-white font-sans text-slate-900 overflow-x-hidden">
        <div className="relative min-h-screen flex flex-col">
          <div className="absolute inset-0 z-0"><img src="https://images.unsplash.com/photo-1519791883288-dc8bd696e667?auto=format&fit=crop&w=1920&q=80" className="w-full h-full object-cover brightness-[0.2]" /><div className="absolute inset-0 bg-gradient-to-b from-indigo-900/30 via-transparent to-white"></div></div>
          <header className="relative z-10 h-24 px-4 md:px-8 flex items-center justify-between max-w-7xl mx-auto w-full">
            <div className="flex items-center gap-3">
              <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-2xl"><BookOpen size={24} /></div>
              <div className="flex flex-col"><span className="font-black text-white text-xl uppercase italic tracking-tighter leading-none">EB-AD</span><span className="text-[8px] font-bold text-indigo-400 uppercase tracking-widest mt-1">LMS Master</span></div>
            </div>
            <div className="flex items-center gap-2 md:gap-4">
              <button onClick={() => setViewMode('login')} className="px-5 py-2.5 bg-white/10 backdrop-blur-md text-white border border-white/20 rounded-full text-[10px] font-black uppercase italic transition-all hover:bg-white hover:text-slate-900">Login</button>
              <a href="#cursos" className="px-5 py-2.5 bg-indigo-600 text-white rounded-full text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-500 transition-all">Matrícula</a>
            </div>
          </header>
          <main className="relative z-10 flex-1 flex flex-col items-center justify-center text-center px-6 py-20 max-w-5xl mx-auto">
             <div className="inline-flex items-center gap-2 px-6 py-2 bg-indigo-600/30 backdrop-blur-xl rounded-full border border-indigo-400/30 text-indigo-400 text-[10px] font-black uppercase tracking-[0.3em] mb-8">Fluxo de Ensino Sincronizado</div>
             <h1 className="text-5xl md:text-8xl lg:text-9xl font-black text-white uppercase italic tracking-tighter leading-[0.82] mb-8 drop-shadow-2xl">Teologia <br/> <span className="text-indigo-500">Master</span></h1>
             <p className="text-slate-300 text-lg md:text-2xl font-medium italic max-w-2xl mb-12">Capacitação teológica de alta performance com certificação digital e suporte Master.</p>
             <a href="#cursos" className="w-full max-w-xs py-6 bg-indigo-600 text-white rounded-[2rem] text-[10px] font-black uppercase italic tracking-[0.3em] shadow-2xl hover:bg-indigo-700 transition-all flex items-center justify-center gap-3">Explorar Cursos <ArrowRight size={18}/></a>
