                     <div className="mt-10 flex gap-4">
                        <button onClick={() => handleNotifyWhatsApp(viewingStudent)} className="flex-1 py-4 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest flex items-center justify-center gap-2 hover:bg-emerald-700 shadow-lg shadow-emerald-100"><MessageCircle size={16}/> Notificar Aluno</button>
                        <button onClick={async () => { await updateDoc(doc(db, 'users', viewingStudent.uid), {status: 'ativo'}); setViewingStudent(null); }} className="flex-1 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 shadow-2xl">Aprovar Matrícula</button>
                     </div>
                  </div>
               </div>
             )}
          </div>
        );
      case 'transferencia':
        return (
          <div className="max-w-2xl mx-auto bg-white border border-slate-300 p-10 space-y-10 rounded-[3rem] shadow-2xl animate-in zoom-in-95">
             <div className="flex items-center gap-4"><div className="p-4 bg-indigo-600 text-white rounded-2xl shadow-xl"><ArrowRightLeft size={32}/></div><div><h3 className="text-2xl font-black uppercase italic text-slate-900 tracking-tighter">Transferência Master</h3><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest italic mt-1">Alteração de Matriz Acadêmica</p></div></div>
             <div className="space-y-6">
                <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Selecionar Aluno Ativo</label><select value={transferenciaData.alunoUid} onChange={e => setTransferenciaData({...transferenciaData, alunoUid: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black uppercase outline-none shadow-inner focus:ring-1 focus:ring-indigo-600 shadow-slate-200"><option value="">Selecione o Aluno...</option>{students.filter(s=>s.status==='ativo').map(s=><option key={s.uid} value={s.uid}>{s.displayName} ({s.academicId})</option>)}</select></div>
                <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Nova Cadeira / Curso</label><select value={transferenciaData.novoCursoId} onChange={e => setTransferenciaData({...transferenciaData, novoCursoId: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-[11px] font-black uppercase outline-none shadow-inner focus:ring-1 focus:ring-indigo-600 shadow-slate-200"><option value="">Selecione o Novo Curso...</option>{courses.map(c=><option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
             </div>
             <div className="flex gap-4 pt-6"><button onClick={() => setOpSubView('main')} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Cancelar</button><button onClick={async () => { if(!transferenciaData.alunoUid || !transferenciaData.novoCursoId) return; await updateDoc(doc(db, 'users', transferenciaData.alunoUid), { cursoInicial: transferenciaData.novoCursoId }); alert('Transferência de Matriz Concluída!'); setOpSubView('main'); }} className="flex-2 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic shadow-2xl hover:bg-indigo-600 transition-all tracking-[0.2em]">Executar Mudança</button></div>
          </div>
        );
      case 'declaracao':
        return (
          <div className="max-w-4xl mx-auto bg-white border border-slate-300 p-8 rounded-[3rem] shadow-2xl space-y-10 animate-in zoom-in-95 overflow-hidden">
             <div className="flex items-center justify-between border-b border-slate-100 pb-6">
                <div className="flex items-center gap-4"><FileText size={32} className="text-indigo-600"/><h3 className="text-xl font-black uppercase italic text-slate-900 tracking-tighter">Emissão de Declaração Acadêmica</h3></div>
                <button onClick={() => setOpSubView('main')} className="p-3 bg-slate-50 rounded-full hover:bg-rose-50 text-slate-400 transition-all"><X size={20}/></button>
             </div>
             <div className="p-8 bg-slate-50 rounded-3xl border border-slate-100 space-y-8">
                <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Selecione o Aluno Beneficiário</label><select onChange={e => { const s = students.find(x=>x.uid===e.target.value); setViewingStudent(s); }} className="w-full p-4 bg-white border-none rounded-2xl text-[11px] font-black uppercase shadow-sm outline-none focus:ring-1 focus:ring-indigo-600"><option value="">Localizar Aluno...</option>{students.map(s=><option key={s.uid} value={s.uid}>{s.displayName} ({s.academicId})</option>)}</select></div>
                {viewingStudent && (
                  <div className="bg-white p-12 rounded-[2rem] border border-slate-200 shadow-2xl space-y-10 font-serif text-slate-900 relative" id="printable-decl">
                     <div className="text-center space-y-4 border-b pb-8">
                        <div className="flex justify-center mb-2"><BookOpen size={40} className="text-slate-900"/></div>
                        <h2 className="text-2xl font-black uppercase italic tracking-tighter leading-none">Escola Bíblica AD</h2>
                        <p className="text-[10px] font-bold uppercase tracking-[0.4em] italic text-slate-400">Certificação Acadêmica Permanente</p>
                     </div>
                     <div className="space-y-6 text-sm leading-relaxed text-justify px-4">
                        <h4 className="text-center font-bold uppercase underline mb-8">DECLARAÇÃO DE MATRÍCULA ATIVA</h4>
                        <p>Declaramos para os devidos fins de direito que o(a) Sr(a). <strong>{viewingStudent.displayName}</strong>, inscrito sob o CPF <strong>{viewingStudent.cpf}</strong> e Matrícula Acadêmica <strong>{viewingStudent.academicId}</strong>, encontra-se devidamente matriculado(a) e com vínculo ATIVO no curso de <strong>{courses.find(c=>c.id===viewingStudent.cursoInicial)?.nome || 'Matriz Geral'}</strong> desta instituição de ensino teológico.</p>
                        <p>O referido aluno cumpre regularmente a carga horária e diretrizes pedagógicas estabelecidas pelo conselho acadêmico para o ciclo letivo vigente.</p>
                        <p className="pt-8">Por ser verdade, firmamos a presente.</p>
                     </div>
                     <div className="flex flex-col items-center gap-2 pt-16">
                        <div className="w-48 h-12 border-b border-slate-900 flex flex-col items-center justify-center">
                           {secSignature && <img src={secSignature} className="max-h-12 grayscale" />}
                        </div>
                        <p className="text-[10px] font-black uppercase italic">Secretaria Master EB-AD</p>
                        <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{new Date().toLocaleDateString('pt-BR', {day:'2-digit', month:'long', year:'numeric'})}</p>
                     </div>
                     <div className="absolute top-10 right-10 opacity-10"><ShieldCheck size={80}/></div>
                  </div>
                )}
             </div>
             {viewingStudent && (
               <div className="flex gap-4"><button onClick={() => window.print()} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic flex items-center justify-center gap-3 shadow-2xl hover:bg-indigo-600 transition-all"><Printer size={18}/> Imprimir Documento Validado</button></div>
             )}
          </div>
        );
      case 'assinatura':
        return (
          <div className="max-w-md mx-auto bg-white border border-slate-300 p-8 text-center space-y-6 rounded-[2rem] shadow-xl">
             <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto text-slate-400"><Fingerprint size={32}/></div>
             <h3 className="font-bold uppercase italic text-slate-900 tracking-tight">Assinatura do Secretário</h3>
             <div className="p-4 border-2 border-dashed border-slate-100 bg-slate-50 min-h-[100px] flex items-center justify-center rounded-2xl shadow-inner">
                {secSignature ? <img src={secSignature} className="max-h-20 grayscale" /> : <p className="text-[10px] text-slate-300 uppercase italic">Assinatura não coletada</p>}
             </div>
             <button onClick={() => setIsSignModalOpen(true)} className="w-full py-4 bg-slate-900 text-white text-[10px] font-black uppercase italic tracking-widest shadow-2xl hover:bg-indigo-600 transition-all">Registrar Biometria Digital</button>
             <button onClick={() => setOpSubView('main')} className="text-[9px] text-slate-400 underline uppercase italic font-bold">Voltar ao operacional</button>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
             <button onClick={() => setOpSubView('declaracao')} className="bg-white p-8 border border-slate-200 rounded-[2rem] flex flex-col items-center gap-4 hover:bg-indigo-600 group transition-all shadow-sm">
                <div className="text-slate-400 group-hover:text-white transition-colors"><FileText size={32}/></div>
                <span className="text-[9px] font-black uppercase text-slate-900 group-hover:text-white italic tracking-widest">Declaracão</span>
             </button>
             <button onClick={() => setOpSubView('validacao')} className="bg-white p-8 border border-slate-200 rounded-[2rem] flex flex-col items-center gap-4 hover:bg-indigo-600 group transition-all shadow-sm relative">
                <div className="text-slate-400 group-hover:text-white transition-colors"><UserCheck size={32}/></div>
                <span className="text-[9px] font-black uppercase text-slate-900 group-hover:text-white italic tracking-widest text-center">Auditoria Matrícula</span>
                {stats.pendentesVal > 0 && <span className="absolute top-4 right-4 bg-rose-600 text-white text-[9px] px-2 py-0.5 font-black rounded-full shadow-lg border border-white animate-bounce">{stats.pendentesVal}</span>}
             </button>
             <button onClick={() => setOpSubView('transferencia')} className="bg-white p-8 border border-slate-200 rounded-[2rem] flex flex-col items-center gap-4 hover:bg-indigo-600 group transition-all shadow-sm">
                <div className="text-slate-400 group-hover:text-white transition-colors"><ArrowRightLeft size={32}/></div>
                <span className="text-[9px] font-black uppercase text-slate-900 group-hover:text-white italic tracking-widest text-center">Transferências</span>
             </button>
             <button onClick={() => setOpSubView('assinatura')} className="bg-white p-8 border border-slate-200 rounded-[2rem] flex flex-col items-center gap-4 hover:bg-indigo-600 group transition-all shadow-sm">
                <div className="text-slate-400 group-hover:text-white transition-colors"><Fingerprint size={32}/></div>
                <span className="text-[9px] font-black uppercase text-slate-900 group-hover:text-white italic tracking-widest">Assinatura Sec.</span>
             </button>
          </div>
        );
    }
  };

  const renderChatButtons = (ticket: any) => {
    const isFinalizado = ticket.status === 'Finalizado';
    const isArquivado = ticket.status === 'Arquivado';
    const isEmAtendimento = ticket.status === 'Em Atendimento';

    return (
      <div className="flex gap-2">
         {isEmAtendimento && (
           <button onClick={async () => { await updateDoc(doc(db, 'tickets', ticket.id), {status: 'Finalizado'}); setSelectedTicketId(null); }} className="px-5 py-2.5 bg-white border border-slate-200 text-[9px] font-black uppercase italic rounded-xl hover:bg-rose-50 hover:text-rose-600 transition-all">Encerrar Chat</button>
         )}
         {isFinalizado && (
           <button onClick={async () => await updateDoc(doc(db, 'tickets', ticket.id), {status: 'Em Atendimento'})} className="px-5 py-2.5 bg-emerald-50 text-emerald-600 border border-emerald-100 text-[9px] font-black uppercase italic rounded-xl hover:bg-emerald-600 hover:text-white transition-all">Reabrir Atendimento</button>
         )}
         {isArquivado && (
           <button onClick={async () => await updateDoc(doc(db, 'tickets', ticket.id), {status: 'Finalizado'})} className="px-5 py-2.5 bg-indigo-50 text-indigo-600 border border-indigo-100 text-[9px] font-black uppercase italic rounded-xl hover:bg-indigo-600 hover:text-white transition-all">Desarquivar Chat</button>
         )}
         {!isArquivado && (
           <button onClick={async () => { await updateDoc(doc(db, 'tickets', ticket.id), {status: 'Arquivado'}); setSelectedTicketId(null); }} className="px-5 py-2.5 bg-slate-900 text-white text-[9px] font-black uppercase italic rounded-xl shadow-xl hover:bg-indigo-600 transition-all flex items-center gap-2"><Archive size={14}/> Arquivar</button>
         )}
      </div>
    );
  };

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-10 print:bg-white print:p-0">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-6 text-white gap-4 rounded-[2rem] shadow-2xl print:hidden">
        <div>
           <h1 className="text-2xl font-black uppercase italic tracking-tighter leading-none">Secretaria Virtual Master</h1>
           <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-1.5 italic">Gabinete Operacional Central EB-AD</p>
        </div>
        <div className="flex bg-slate-800 p-1.5 rounded-2xl shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); setSelectedTicketId(null); }} className={`px-5 py-2.5 text-[10px] font-black uppercase italic transition-all rounded-xl whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-xl' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 print:hidden">
         <div className="bg-white border-l-4 border-l-amber-500 p-5 md:p-6 rounded-3xl border border-slate-200 shadow-sm"><p className="text-[9px] font-black text-slate-400 uppercase italic tracking-widest">Pendentes</p><p className="text-2xl md:text-3xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.abertos}</p></div>
         <div className="bg-white border-l-4 border-l-indigo-500 p-5 md:p-6 rounded-3xl border border-slate-200 shadow-sm"><p className="text-[9px] font-black text-slate-400 uppercase italic tracking-widest">Ativos</p><p className="text-2xl md:text-3xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.finalizados}</p></div>
         <div className="bg-white border-l-4 border-l-rose-500 p-5 md:p-6 rounded-3xl border border-slate-200 shadow-sm relative overflow-hidden">
            <p className="text-[9px] font-black text-slate-400 uppercase italic tracking-widest">Auditoria</p>
            <p className="text-2xl md:text-3xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.pendentesVal}</p>
            {stats.pendentesVal > 0 && <div className="absolute top-0 right-0 w-10 h-10 bg-rose-50 rounded-bl-[2rem] flex items-center justify-center text-rose-500 animate-pulse"><UserCheck size={16}/></div>}
         </div>
         <div className="bg-white border-l-4 border-l-emerald-500 p-5 md:p-6 rounded-3xl border border-slate-200 shadow-sm"><p className="text-[9px] font-black text-slate-400 uppercase italic tracking-widest">GED Master</p><p className="text-2xl md:text-3xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.totalGed}</p></div>
      </div>

      <main className="flex-1 min-h-[500px] overflow-hidden flex flex-col">
         {activeTab === 'operacional' && (
            <div className="flex-1 overflow-y-auto custom-scrollbar p-1">
              {renderOperational()}
            </div>
         )}

         {activeTab === 'atendimento' && (
           <div className="bg-white border border-slate-200 rounded-[2.5rem] overflow-hidden h-full flex flex-col shadow-sm">
              <div className="p-6 bg-slate-50/50 border-b border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4">
                 <h3 className="font-black text-[10px] uppercase italic tracking-widest flex items-center gap-3 text-slate-800"><TicketIcon size={16} className="text-indigo-600"/> Protocolos Administrativos Master</h3>
                 <div className="relative w-full md:w-72"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16}/><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Filtrar Aluno ou Protocolo..." className="w-full pl-12 pr-6 py-3 bg-white border border-slate-200 rounded-2xl text-[10px] font-black outline-none focus:ring-1 focus:ring-indigo-600 shadow-inner" /></div>
              </div>
              <div className="flex-1 overflow-auto custom-scrollbar">
                 <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-50 border-b border-slate-100 text-[9px] font-black uppercase italic text-slate-400 sticky top-0 z-10">
                       <tr><th className="px-8 py-5">Protocolo Master</th><th className="px-8 py-5">Solicitante</th><th className="px-8 py-5">Status</th><th className="px-8 py-5 text-center">Gestão</th></tr>
                    </thead>
                    <tbody className="text-xs">
                       {tickets.filter(t => t.status === 'Pendente' && (t.protocolo?.includes(searchTerm) || t.user?.includes(searchTerm))).length === 0 ? (
                         <tr><td colSpan={4} className="p-32 text-center text-slate-300 uppercase italic font-black text-sm tracking-[0.4em]">Fila Deserta.</td></tr>
                       ) : tickets.filter(t => t.status === 'Pendente' && (t.protocolo?.includes(searchTerm) || t.user?.includes(searchTerm))).map(t => (
                         <tr key={t.id} className="border-b border-slate-50 hover:bg-indigo-50/10 transition-all group">
                            <td className="px-8 py-4 font-mono font-black text-indigo-600 text-sm tracking-tighter">{t.protocolo}</td>
                            <td className="px-8 py-4 font-black uppercase text-slate-900 italic">{t.user}</td>
                            <td className="px-8 py-4"><span className="px-4 py-1.5 bg-amber-50 text-amber-600 text-[8px] font-black uppercase italic rounded-full border border-amber-100">{t.status}</span></td>
                            <td className="px-8 py-4 text-center"><button onClick={async () => { await updateDoc(doc(db, 'tickets', t.id), {status: 'Em Atendimento'}); setSelectedTicketId(t.id); setActiveTab('chat'); setChatFilter('abertos'); }} className="bg-slate-900 text-white px-6 py-2.5 rounded-xl text-[9px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all shadow-lg active:scale-95">Assumir Atendimento</button></td>
                         </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
         )}

         {activeTab === 'chat' && (
           <div className="grid grid-cols-12 gap-4 h-[650px] bg-slate-100 p-4 rounded-[3rem] border border-slate-200 shadow-inner overflow-hidden">
              <div className="col-span-4 bg-white rounded-[2.5rem] border border-slate-200 flex flex-col overflow-hidden shadow-sm">
                 <div className="flex border-b border-slate-100 bg-slate-50/50 overflow-x-auto">
                    {['abertos', 'finalizados', 'arquivados'].map((f:any) => (
                      <button key={f} onClick={() => { setChatFilter(f); setSelectedTicketId(null); }} className={`flex-1 py-4 px-2 text-[9px] font-black uppercase italic tracking-widest transition-all whitespace-nowrap ${chatFilter === f ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:bg-slate-50'}`}>{f}</button>
                    ))}
                 </div>
                 <div className="flex-1 overflow-y-auto custom-scrollbar">
                    {tickets.filter(t => {
                      if (chatFilter === 'abertos') return t.status === 'Em Atendimento';
                      if (chatFilter === 'finalizados') return t.status === 'Finalizado';
                      return t.status === 'Arquivado';
                    }).length === 0 ? (
                      <div className="p-10 text-center opacity-20"><MessageSquare size={40} className="mx-auto mb-3" /><p className="text-[10px] font-black uppercase italic">Vazio</p></div>
                    ) : tickets.filter(t => {
                      if (chatFilter === 'abertos') return t.status === 'Em Atendimento';
                      if (chatFilter === 'finalizados') return t.status === 'Finalizado';
                      return t.status === 'Arquivado';
                    }).map(t => (
                      <div key={t.id} onClick={() => setSelectedTicketId(t.id)} className={`p-6 border-b border-slate-50 cursor-pointer transition-all ${selectedTicketId === t.id ? 'bg-indigo-50 border-r-8 border-r-indigo-600 shadow-inner' : 'hover:bg-slate-50/50'}`}>
                         <p className="text-sm font-black uppercase italic text-slate-900 tracking-tight leading-none">{t.user}</p>
                         <p className="text-[9px] text-indigo-600 font-mono font-bold mt-2 tracking-tighter">PROT: {t.protocolo}</p>
                         <p className="text-[10px] text-slate-400 mt-2 italic truncate font-medium">"{t.lastMessage || 'Aguardando...'}"</p>
                      </div>
                    ))}
                 </div>
              </div>
              <div className="col-span-8 bg-white rounded-[2.5rem] border border-slate-200 flex flex-col relative overflow-hidden shadow-sm">
                 {selectedTicketId ? (
                   <>
                     <div className="p-6 bg-slate-50/50 border-b border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4">
                        <div className="flex items-center gap-4">
                           <div className="w-12 h-12 bg-indigo-600 text-white rounded-2xl flex items-center justify-center font-black italic shadow-xl text-xl">{(tickets.find(t=>t.id===selectedTicketId)?.user||'U').charAt(0)}</div>
                           <div>
                              <h4 className="text-base font-black uppercase italic text-slate-900 tracking-tighter leading-none">{tickets.find(t=>t.id===selectedTicketId)?.user}</h4>
                              <p className="text-[9px] text-slate-400 font-mono font-bold mt-1 tracking-widest uppercase">Protocolo: {tickets.find(t=>t.id===selectedTicketId)?.protocolo}</p>
                           </div>
                        </div>
                        {renderChatButtons(tickets.find(t=>t.id===selectedTicketId))}
                     </div>
                     <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-slate-50/30 custom-scrollbar">
                        {chatHistory.map((m, i) => (
                          <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'} animate-in slide-in-from-bottom-2`}>
                             <div className={`max-w-[70%] p-5 shadow-sm border ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white border-slate-900 rounded-[2rem] rounded-tr-none' : 'bg-white border-slate-100 text-slate-900 rounded-[2rem] rounded-tl-none shadow-indigo-100/20'}`}>
                                 <p className="text-[12px] font-medium leading-relaxed italic">"{m.text}"</p>
                             </div>
                             <span className="text-[8px] font-black text-slate-300 uppercase mt-2 px-4 tracking-[0.2em]">{m.sender} • Agora</span>
                          </div>
                        ))}
                        <div ref={chatEndRef} />
                     </div>
                     <div className="p-8 border-t border-slate-100 bg-white flex gap-3">
                        <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="DIGITAR RESPOSTA MASTER..." className="flex-1 bg-slate-50 border-none rounded-2xl px-6 py-4.5 text-xs font-black italic shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                        <button onClick={() => {}} className="bg-slate-900 text-white px-10 py-4 rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all shadow-2xl flex items-center gap-2"><Send size={18}/> Enviar</button>
                     </div>
                   </>
                 ) : (
                   <div className="flex-1 flex flex-col items-center justify-center opacity-10 text-center gap-4">
                      <MessageSquare size={120}/>
                      <p className="text-xl font-black uppercase italic tracking-[0.8em]">Selecione um Ticket</p>
                   </div>
                 )}
              </div>
           </div>
         )}
      </main>

      {isSignModalOpen && <SignaturePad title="Certificação Operacional" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert('Assinatura Registrada!'); }} />}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { collection, query, where, onSnapshot, deleteDoc, serverTimestamp, doc, setDoc, updateDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { createUserWithEmailAndPassword, updateProfile } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { db, auth } from '../firebase';
import { User, Course } from '../types';
import { Search, UserPlus, X, Save, UserCog, Trash2, Edit3, Camera, Eye, MapPin, RefreshCw, ShieldCheck, CreditCard, Phone, Calendar } from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<any>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    nome: '', emailPessoal: '', emailAcademico: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', senhaNova: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  useEffect(() => {
    // Alunos Ativos no painel são apenas quem já passou pela secretaria ou foi cadastrado manualmente
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno'), where('status', '==', 'ativo')), s => {
      setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() } as Course))));
    return () => { unsubS(); unsubC(); };
  }, []);

  const handleCepSearch = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    setFormData(prev => ({ ...prev, endereco: { ...prev.endereco, cep: cleanCep } }));
    if (cleanCep.length === 8) {
      try {
        const res = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await res.json();
        if (!data.erro) {
          setFormData(prev => ({
            ...prev,
            endereco: { ...prev.endereco, rua: data.logradouro, bairro: data.bairro, cidade: data.localidade, uf: data.uf }
          }));
        }
      } catch (e) { console.error("CEP error", e); }
    }
  };

  const filtered = useMemo(() => students.filter(s => {
    const name = (s.displayName || (s as any).nome || '').toLowerCase();
    return name.includes(searchTerm.toLowerCase()) || s.email?.toLowerCase().includes(searchTerm.toLowerCase());
  }), [students, searchTerm]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    try {
      let finalUid = selectedStudent?.uid;
      const academicId = selectedStudent?.academicId || `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      if (!selectedStudent) {
        const userCred = await createUserWithEmailAndPassword(auth, formData.emailAcademico, formData.senhaNova || '123456');
        finalUid = userCred.user.uid;
        await updateProfile(userCred.user, { displayName: formData.nome, photoURL: formData.fotoUrl });
      }

      const payload: any = {
        uid: finalUid,
        displayName: formData.nome,
        nome: formData.nome,
        email: formData.emailAcademico.toLowerCase().trim(),
        emailPessoal: formData.emailPessoal.toLowerCase().trim(),
        telefone: formData.telefone,
        cpf: formData.cpf,
        nascimento: formData.nascimento,
        photoURL: formData.fotoUrl || '',
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        role: 'aluno',
        status: formData.status,
        academicId,
        updatedAt: serverTimestamp(),
        createdAt: selectedStudent?.createdAt || serverTimestamp()
      };

      await setDoc(doc(db, 'users', finalUid), payload, { merge: true });
      setIsRegisterModalOpen(false);
      setSelectedStudent(null);
      alert("Sincronização Master Concluída!");
    } catch (err: any) {
      alert("Erro na operação: " + err.message);
    } finally { setActionLoading(false); }
  };

  const openEdit = (s: any) => {
    setSelectedStudent(s);
    setFormData({
      nome: s.displayName || s.nome || '',
      emailPessoal: s.emailPessoal || '',
      emailAcademico: s.email || '',
      telefone: s.telefone || '',
      cursoId: s.cursoInicial || '',
      status: s.status || 'ativo',
      cpf: s.cpf || '',
      nascimento: s.nascimento || '',
      fotoUrl: s.photoURL || '',
      senhaNova: '',
      endereco: s.endereco || { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
    });
    setIsRegisterModalOpen(true);
  };

  if (loading) return <div className="p-10 font-mono text-[10px] tracking-widest uppercase text-slate-400 text-center animate-pulse">Auditando Fluxo Institucional...</div>;

  return (
    <div className="space-y-4 animate-in fade-in duration-300">
      {isRegisterModalOpen && (
        <div className="fixed inset-0 z-[5000] bg-white flex flex-col animate-in slide-in-from-bottom duration-500 overflow-y-auto">
          <header className="bg-slate-900 text-white px-8 py-6 flex justify-between items-center shrink-0">
            <div className="flex items-center gap-4">
              <div className="p-3 bg-indigo-600 rounded-2xl shadow-xl"><UserCog size={24}/></div>
              <div><h2 className="text-xl font-black uppercase italic tracking-tighter leading-none">{selectedStudent ? 'Dossiê do Aluno' : 'Matrícula Master'}</h2><p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Sincronização Cloud Firestore</p></div>
            </div>
            <button onClick={() => setIsRegisterModalOpen(false)} className="p-3 hover:bg-rose-600 rounded-full transition-all"><X size={24}/></button>
          </header>

          <form onSubmit={handleSave} className="max-w-5xl mx-auto py-12 px-6 space-y-12 pb-40">
             <section className="space-y-8">
                <h3 className="text-xs font-black uppercase border-l-4 border-indigo-600 pl-4 text-slate-900 italic tracking-[0.2em]">01. Qualificação Discente</h3>
                <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
                   <div className="lg:col-span-1 flex flex-col items-center gap-4">
                      <div onClick={() => fileInputRef.current?.click()} className="w-44 h-44 bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden rounded-[2.5rem] shadow-inner group hover:border-indigo-400 transition-all">
                        {formData.fotoUrl ? <img src={formData.fotoUrl} className="w-full h-full object-cover" /> : <Camera size={32} className="text-slate-300 group-hover:text-indigo-600"/>}
                      </div>
                      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={e => { const r = new FileReader(); r.onload = (v) => setFormData({...formData, fotoUrl: v.target?.result as string}); r.readAsDataURL(e.target.files![0]); }} />
                   </div>
                   <div className="lg:col-span-3 grid grid-cols-1 md:grid-cols-2 gap-5">
                      <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Nome Completo</label><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-black shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                      <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">WhatsApp</label><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-black shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                      <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">CPF</label><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-black shadow-inner" /></div>
                      <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Nascimento</label><input type="date" required value={formData.nascimento} onChange={e => setFormData({...formData, nascimento: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-black shadow-inner" /></div>
                   </div>
                </div>
             </section>

             <section className="space-y-8">
                <h3 className="text-xs font-black uppercase border-l-4 border-indigo-600 pl-4 text-slate-900 italic tracking-[0.2em]">02. Endereço e Localidade</h3>
                <div className="grid grid-cols-1 md:grid-cols-6 gap-4">
                   <div className="md:col-span-1 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">CEP</label><input required value={formData.endereco.cep} onChange={e => handleCepSearch(e.target.value)} className="w-full p-3 bg-slate-50 border-none rounded-xl text-xs font-black shadow-inner" placeholder="00000-000" /></div>
                   <div className="md:col-span-4 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Rua / Logradouro</label><input required value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-xs font-black shadow-inner" /></div>
                   <div className="md:col-span-1 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Nº</label><input required value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-xs font-black shadow-inner" /></div>
                   <div className="md:col-span-2 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Bairro</label><input required value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-xs font-black shadow-inner" /></div>
                   <div className="md:col-span-3 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Cidade</label><input required value={formData.endereco.cidade} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cidade: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-xs font-black shadow-inner" /></div>
                   <div className="md:col-span-1 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">UF</label><input required value={formData.endereco.uf} onChange={e => setFormData({...formData, endereco: {...formData.endereco, uf: e.target.value.toUpperCase()}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-xs font-black shadow-inner text-center" maxLength={2} /></div>
                </div>
             </section>

             <section className="space-y-8">
                <h3 className="text-xs font-black uppercase border-l-4 border-indigo-600 pl-4 text-slate-900 italic tracking-[0.2em]">03. Parâmetros Acadêmicos</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-indigo-600 ml-4 italic">Login Acadêmico (E-mail @ead.com)</label><input type="email" required value={formData.emailAcademico} onChange={e => setFormData({...formData, emailAcademico: e.target.value})} className="w-full p-4 bg-indigo-50/30 border-none rounded-2xl text-xs font-black shadow-inner" /></div>
                   <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Cadeira / Curso Alocado</label><select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-black uppercase shadow-inner outline-none"><option value="">Selecionar Disciplina...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                </div>
             </section>

             <div className="flex gap-4 pt-10 border-t border-slate-100">
                <button type="button" onClick={() => setIsRegisterModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Fechar Prontuário</button>
                <button type="submit" disabled={actionLoading} className="flex-2 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-[0.3em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-4">
                  {actionLoading ? <RefreshCw className="animate-spin" size={20}/> : <><ShieldCheck size={20}/> Atualizar Sincronização Cloud</>}
                </button>
             </div>
          </form>
        </div>
      )}

      {!isRegisterModalOpen && (
        <div className="space-y-4">
           <header className="bg-white p-6 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
              <div><h1 className="text-xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Alunos Ativos</h1><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1.5 italic">Gestão de Alunos com Auditoria Completa</p></div>
              <button onClick={() => { setSelectedStudent(null); setFormData({nome:'', emailPessoal:'', emailAcademico:'', telefone:'', cursoId:'', status:'ativo', cpf:'', nascimento:'', fotoUrl:'', senhaNova:'', endereco:{cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''}}); setIsRegisterModalOpen(true); }} className="bg-slate-900 text-white px-8 py-3 rounded-xl text-[10px] font-black uppercase italic hover:bg-indigo-600 transition-all flex items-center gap-3 shadow-lg active:scale-95"><UserPlus size={18}/> Nova Matrícula Secretaria</button>
           </header>

           <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
              <div className="p-4 border-b border-slate-50 bg-slate-50/30">
                 <div className="relative w-full"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16}/><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar por nome ou e-mail..." className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600 shadow-inner" /></div>
              </div>
              <div className="overflow-x-auto">
                 <table className="w-full text-left">
                    <thead className="bg-slate-50 text-[9px] font-black uppercase italic text-slate-400 border-b border-slate-100">
                       <tr><th className="px-6 py-4 text-center">Identificação</th><th className="px-6 py-4">Dossiê Acadêmico</th><th className="px-6 py-4">Login Master</th><th className="px-6 py-4 text-center">Status</th><th className="px-6 py-4 text-center">Gestão</th></tr>
                    </thead>
                    <tbody className="text-xs">
                       {filtered.length === 0 ? (
                         <tr><td colSpan={5} className="p-20 text-center text-slate-300 font-black uppercase italic text-xs tracking-widest">Nenhum aluno ativo localizado no banco.</td></tr>
                       ) : filtered.map(s => (
                         <tr key={s.uid} className="border-b border-slate-50 hover:bg-indigo-50/10 transition-all group">
                            <td className="px-6 py-4 text-center font-mono font-bold text-indigo-600">{(s as any).academicId || '---'}</td>
                            <td className="px-6 py-4 flex items-center gap-3">
                               <div className="w-9 h-9 rounded-xl bg-slate-100 overflow-hidden border border-white shadow-sm shrink-0">
                                  {s.photoURL ? <img src={s.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center font-black italic text-slate-300">{(s.displayName||'U').charAt(0)}</div>}
                               </div>
                               <p className="font-black uppercase text-slate-900 italic">{(s as any).nome || s.displayName}</p>
                            </td>
                            <td className="px-6 py-4 font-bold text-slate-400">{s.email}</td>
                            <td className="px-6 py-4 text-center"><span className="px-4 py-1.5 bg-emerald-50 text-emerald-600 border border-emerald-100 rounded-full text-[8px] font-black uppercase italic">ATIVO</span></td>
                            <td className="px-6 py-4 text-center flex justify-center gap-1.5">
                               <button onClick={() => openEdit(s)} className="p-2.5 bg-slate-50 text-slate-300 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all" title="Ver Prontuário"><Eye size={16}/></button>
                               <button onClick={async () => { if(confirm('Remover aluno permanentemente?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2.5 bg-slate-50 text-slate-100 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all"><Trash2 size={16}/></button>
                            </td>
                         </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default StudentsView;

import React, { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, doc, getDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Course, User, Module, Lesson } from '../types';
import { BookOpen, PlayCircle, Award, GraduationCap, Zap, Bell, Menu, X, LogOut, Home, LifeBuoy, ScrollText, ShieldAlert, Play, RefreshCw, UserCheck, Clock, ChevronRight } from 'lucide-react';

interface StudentViewProps { user: User; }
type StudentSubView = 'dashboard' | 'classroom' | 'library' | 'certificates' | 'support';

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [enrolledCourse, setEnrolledCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [loading, setLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [userData, setUserData] = useState<any>(null);

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      try {
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          const data = userDoc.data();
          setUserData(data);
          const cId = data.cursoInicial || data.cursoId;
          if (cId) {
            const courseDoc = await getDoc(doc(db, 'cursos', cId));
            if (courseDoc.exists()) {
              setEnrolledCourse({ id: courseDoc.id, ...courseDoc.data() } as Course);
            }
          }
        }
      } catch (error) { console.error("Erro perfil discente", error); }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  const handleStartLesson = () => {
    if (!enrolledCourse) return;
    onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', enrolledCourse.id)), snap => {
      const mods = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));
      setModules(mods);
      setActiveSubView('classroom');
    });
  };

  if (loading) return (
    <div className="h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-center gap-6">
       <RefreshCw size={48} className="text-indigo-600 animate-spin" />
       <p className="font-black text-white uppercase italic text-xs tracking-[0.5em]">Sincronizando Identidade Master...</p>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 flex overflow-hidden font-sans relative">
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-slate-900/60 z-[60] lg:hidden backdrop-blur-sm"></div>}

      <aside className={`fixed lg:static inset-y-0 left-0 bg-slate-900 w-72 flex flex-col transition-transform duration-300 z-[70] ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
         <div className="p-6 md:p-8 border-b border-white/5 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg"><GraduationCap size={24}/></div>
              <div><p className="font-black text-white uppercase italic text-lg leading-none">EB-EAD</p><p className="text-[8px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Sala de Aula</p></div>
            </div>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden p-2 text-white/50 hover:text-white"><X size={20}/></button>
         </div>
         <nav className="flex-1 p-4 space-y-2 mt-4 overflow-y-auto">
            {[
              { id: 'dashboard', label: 'Home Page', icon: <Home size={18}/> },
              { id: 'library', label: 'Biblioteca', icon: <BookOpen size={18}/> },
              { id: 'certificates', label: 'Diplomas', icon: <Award size={18}/> },
              { id: 'support', label: 'Suporte', icon: <LifeBuoy size={18}/> }
            ].map(item => (
              <button key={item.id} onClick={() => { setActiveSubView(item.id as any); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${activeSubView === item.id ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}>{item.icon} {item.label}</button>
            ))}
         </nav>
         <div className="p-6 border-t border-white/5 bg-black/20">
            <div className="flex items-center gap-4 p-4 bg-white/5 rounded-2xl">
               <div className="w-10 h-10 rounded-xl overflow-hidden bg-indigo-600 flex items-center justify-center text-white font-black italic shadow-lg">
                  {userData?.photoURL ? <img src={userData.photoURL} className="w-full h-full object-cover" /> : (userData?.displayName||'U').charAt(0)}
               </div>
               <div className="flex-1 overflow-hidden">
                  <p className="text-[9px] font-black text-white uppercase italic truncate">{userData?.nome || userData?.displayName || 'Aluno'}</p>
                  <p className="text-[7px] font-bold text-indigo-400 uppercase mt-1 tracking-widest">MATRÍCULA {userData?.status === 'ativo' ? 'ATIVA' : 'EM ANÁLISE'}</p>
               </div>
               <button onClick={() => auth.signOut()} className="text-rose-500 p-1 hover:scale-110 transition-transform"><LogOut size={18}/></button>
            </div>
         </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
         <header className="h-16 md:h-20 bg-white border-b border-slate-100 flex items-center justify-between px-4 md:px-8 shadow-sm shrink-0">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2.5 bg-slate-50 text-slate-400 rounded-xl hover:bg-indigo-600 hover:text-white transition-all lg:hidden"><Menu size={20}/></button>
            <div className="flex items-center gap-3 md:gap-6">
               <div className="hidden sm:flex items-center gap-2 px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full border border-indigo-100"><Zap size={12} fill="currentColor"/><span className="text-[8px] font-black uppercase tracking-widest">Master Cloud Sync</span></div>
