                    </thead>
                    <tbody className="text-xs">
                       {pending.length === 0 ? (
                         <tr><td colSpan={4} className="p-32 text-center text-slate-300 uppercase italic font-black text-sm tracking-widest">Fila de Auditoria Limpa.</td></tr>
