                                     <p className="text-[9px] text-slate-400 font-bold mt-1.5 uppercase tracking-tighter italic">CPF: {s.cpf || 'PENDENTE'} • TEL: {s.telefone || 'PENDENTE'}</p>
                                  </div>
                               </div>
                            </td>
                            <td className="px-6 py-4 font-black text-indigo-600 uppercase italic text-[10px]">{courses.find(c=>c.id===s.cursoInicial)?.nome || 'CURSO NÃO IDENTIFICADO'}</td>
