                               <button onClick={() => handleNotifyWhatsApp(s)} className="p-2 bg-emerald-50 text-emerald-600 hover:bg-emerald-600 hover:text-white rounded-lg transition-all border border-emerald-100 shadow-sm" title="Notificar via WhatsApp"><MessageCircle size={14}/></button>
                            </td>
                         </tr>
                       ))}
                    </tbody>
                </table>
             </div>

             {viewingStudent && (
               <div className="fixed inset-0 z-[5000] bg-slate-950/80 backdrop-blur-md flex items-center justify-center p-6 animate-in zoom-in-95">
