                      return t.status === 'Arquivado';
                    }).length === 0 ? (
                      <div className="p-10 text-center opacity-20"><MessageSquare size={40} className="mx-auto mb-3" /><p className="text-[10px] font-black uppercase italic">Vazio</p></div>
                    ) : tickets.filter(t => {
                      if (chatFilter === 'abertos') return t.status === 'Em Atendimento';
                      if (chatFilter === 'finalizados') return t.status === 'Finalizado';
