                   <div className="space-y-1.5"><label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic tracking-widest">E-mail Pessoal (Alternativo)</label><input type="email" required value={formData.emailPessoal} onChange={e => setFormData({...formData, emailPessoal: e.target.value})} className="w-full p-5 bg-slate-50 border-none rounded-2xl text-xs font-black shadow-inner" /></div>
