                    <thead className="bg-slate-50 text-[10px] font-black uppercase italic text-slate-400 border-b border-slate-100 tracking-widest">
                       <tr><th className="px-10 py-6 text-center">Identificação</th><th className="px-10 py-6">Dossiê Acadêmico</th><th className="px-10 py-6">Login Master</th><th className="px-10 py-6 text-center">Status</th><th className="px-10 py-6 text-center">Gestão</th></tr>
                    </thead>
                    <tbody className="text-xs">
                       {filtered.length === 0 ? (
                         <tr><td colSpan={5} className="p-32 text-center text-slate-300 font-black uppercase italic text-sm tracking-[0.5em]">Nenhum Aluno Ativo Localizado no Servidor.</td></tr>
