                    }).length === 0 ? (
                      <div className="p-20 text-center opacity-20 flex flex-col items-center gap-4"><MessageSquare size={60}/><p className="text-[10px] font-black uppercase tracking-widest italic leading-none">Vazio</p></div>
                    ) : tickets.filter(t => {
                      if (chatFilter === 'abertos') return t.status === 'Em Atendimento';
                      if (chatFilter === 'finalizados') return t.status === 'Finalizado';
                      return t.status === 'Arquivado';
                    }).map(t => (
                      <div key={t.id} onClick={() => setSelectedTicketId(t.id)} className={`p-8 border-b border-slate-50 cursor-pointer transition-all ${selectedTicketId === t.id ? 'bg-indigo-50 border-r-8 border-r-indigo-600 shadow-inner' : 'hover:bg-slate-50/50'}`}>
