                         <p className="text-[10px] text-indigo-600 font-mono font-bold mt-2.5 tracking-tighter">PROTOCOLO: {t.protocolo}</p>
                         <p className="text-[11px] text-slate-400 mt-3 italic truncate font-medium">"{t.lastMessage || 'Aguardando interação...'}"</p>
                      </div>
                    ))}
                 </div>
              </div>
              <div className="col-span-8 bg-white rounded-[3rem] border border-slate-200 flex flex-col relative overflow-hidden shadow-2xl">
                 {selectedTicketId ? (
