                     <div className="p-8 bg-slate-50/50 border-b border-slate-100 flex flex-col md:flex-row justify-between items-center gap-6">
                        <div className="flex items-center gap-5">
                           <div className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center font-black italic shadow-2xl text-2xl border-2 border-white/20">{(tickets.find(t=>t.id===selectedTicketId)?.user||'U').charAt(0)}</div>
                           <div>
                              <h4 className="text-xl font-black uppercase italic text-slate-900 tracking-tighter leading-none">{tickets.find(t=>t.id===selectedTicketId)?.user}</h4>
                              <p className="text-[10px] text-slate-400 font-mono font-bold mt-1.5 tracking-[0.2em] uppercase leading-none">ID Master: {tickets.find(t=>t.id===selectedTicketId)?.protocolo}</p>
                           </div>
                        </div>
                        {renderChatButtons(tickets.find(t=>t.id===selectedTicketId))}
                     </div>
                     <div className="flex-1 overflow-y-auto p-10 space-y-8 bg-slate-50/30 custom-scrollbar">
                        {chatHistory.map((m, i) => (
                          <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'} animate-in slide-in-from-bottom-2`}>
                             <div className={`max-w-[75%] p-6 shadow-xl border ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white border-slate-900 rounded-[2.5rem] rounded-tr-none' : 'bg-white border-slate-100 text-slate-900 rounded-[2.5rem] rounded-tl-none shadow-indigo-100/10'}`}>
                                 <p className="text-[13px] font-medium leading-relaxed italic">"{m.text}"</p>
                             </div>
                             <span className="text-[9px] font-black text-slate-300 uppercase mt-2.5 px-6 tracking-[0.3em]">{m.sender} • Sincronizado</span>
                          </div>
                        ))}
                        <div ref={chatEndRef} />
                     </div>
                     <div className="p-10 border-t border-slate-100 bg-white shadow-[0_-20px_50px_rgba(0,0,0,0.02)]">
                        <div className="relative flex items-center gap-4">
                           <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="DIGITAR RESPOSTA INSTITUCIONAL..." className="flex-1 bg-slate-50 border-none rounded-[2rem] px-8 py-5 text-xs font-black italic shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 transition-all" />
                           <button onClick={handleSendMessage} className="bg-slate-900 text-white px-12 py-5 rounded-[2rem] text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all shadow-2xl active:scale-95 flex items-center gap-3"><Send size={20}/> Enviar</button>
                        </div>
                     </div>
                   </>
                 ) : (
                   <div className="flex-1 flex flex-col items-center justify-center opacity-10 text-center gap-6">
                      <MessageSquare size={150} className="text-slate-400"/>
                      <p className="text-2xl font-black uppercase italic tracking-[1em] text-slate-900">Selecione Protocolo</p>
                   </div>
                 )}
              </div>
           </div>
         )}
      </main>

      {isSignModalOpen && <SignaturePad title="Validação Digital da Secretaria" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert('Assinatura Operacional Registrada com Sucesso!'); }} />}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { collection, query, where, onSnapshot, deleteDoc, serverTimestamp, doc, setDoc, updateDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { createUserWithEmailAndPassword, updateProfile } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { db, auth } from '../firebase';
import { User, Course } from '../types';
import { 
  Search, UserPlus, X, Save, UserCog, Trash2, Edit3, Camera, Eye, 
  MapPin, RefreshCw, ShieldCheck, CreditCard, Phone, Download, 
  FileSpreadsheet, Mail, Lock, CheckCircle2, AlertCircle, Ban
} from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<any>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Estado do formulário unificado (Mesma estrutura do LoginView)
  const [formData, setFormData] = useState({
    nome: '', 
    emailPessoal: '', 
    emailAcademico: '', 
    telefone: '', 
    cursoId: '', 
    status: 'ativo', 
    cpf: '', 
    nascimento: '', 
    fotoUrl: '', 
    password: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  useEffect(() => {
    // Busca todos os alunos (ativos, pendentes, bloqueados)
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => {
      setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() } as Course))));
    return () => { unsubS(); unsubC(); };
  }, []);

  const handleCepSearch = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    setFormData(prev => ({ ...prev, endereco: { ...prev.endereco, cep: cleanCep } }));
    if (cleanCep.length === 8) {
      try {
        const res = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await res.json();
        if (!data.erro) {
          setFormData(prev => ({
            ...prev,
            endereco: { 
              ...prev.endereco, 
              rua: data.logradouro, 
              bairro: data.bairro, 
              cidade: data.localidade, 
              uf: data.uf 
            }
          }));
        }
      } catch (e) { console.error("CEP error", e); }
    }
  };

  const generateAcademicEmail = async (fullName: string) => {
    const names = fullName.trim().toLowerCase().split(' ');
    const first = names[0];
    const last = names.length > 1 ? names[names.length - 1] : '';
    return `${first}.${last}@ead.com`; // Simplificado para edição manual se necessário
  };

  const filtered = useMemo(() => students.filter(s => {
    const term = searchTerm.toLowerCase();
    const name = (s.displayName || (s as any).nome || '').toLowerCase();
    const email = (s.email || '').toLowerCase();
    const id = ((s as any).academicId || '').toLowerCase();
    return name.includes(term) || email.includes(term) || id.includes(term);
  }), [students, searchTerm]);

  const handleExportExcel = () => {
    const headers = "Nome,Matricula,Email Login,Email Pessoal,CPF,Telefone,Status,Curso,Cidade/UF\n";
    const rows = students.map(s => {
      const curso = courses.find(c => c.id === (s as any).cursoInicial)?.nome || 'N/A';
      const end = (s as any).endereco;
      return `"${s.displayName}","${(s as any).academicId || ''}","${s.email}","${(s as any).emailPessoal || ''}","${(s as any).cpf || ''}","${(s as any).telefone || ''}","${(s as any).status}","${curso}","${end?.cidade || ''}/${end?.uf || ''}"`;
    }).join("\n");

    const blob = new Blob(["\uFEFF" + headers + rows], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `Alunos_EB_EAD_${new Date().toLocaleDateString()}.csv`;
    link.click();
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    try {
      let finalUid = selectedStudent?.uid;
      // Gera ID Acadêmico se não existir
      const academicId = selectedStudent?.academicId || `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      // Nota: Criar usuário no Auth via Client SDK loga o admin fora. 
      // Em produção, usaríamos Firebase Admin SDK. Aqui, criamos o documento Firestore
      // e assumimos que a conta Auth será criada separadamente ou via fluxo de "primeiro acesso".
      // Se for edição, apenas atualizamos o doc.

      if (!selectedStudent) {
        // Simulação de criação de UID para Firestore (Auth seria tratado separadamente)
        finalUid = `user_${Date.now()}`; 
      }

      const payload: any = {
        displayName: formData.nome,
        nome: formData.nome,
        email: formData.emailAcademico.toLowerCase().trim(),
        emailPessoal: formData.emailPessoal.toLowerCase().trim(),
        telefone: formData.telefone,
        cpf: formData.cpf,
        nascimento: formData.nascimento,
        photoURL: formData.fotoUrl || '',
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        role: 'aluno',
        status: formData.status,
        academicId,
        updatedAt: serverTimestamp()
      };

      if (!selectedStudent) {
        payload.createdAt = serverTimestamp();
        payload.uid = finalUid;
        // Salvar senha no documento apenas para referência do suporte (Prática de risco, mas solicitada para "recuperar senha")
        // O ideal é nunca salvar senha em texto plano.
        payload.passwordHint = formData.password; 
        await setDoc(doc(db, 'users', finalUid), payload);
      } else {
        await updateDoc(doc(db, 'users', finalUid), payload);
      }

      setIsRegisterModalOpen(false);
      setSelectedStudent(null);
      alert("Operação realizada com sucesso! O aluno foi sincronizado na base.");
    } catch (err: any) {
      alert("Erro na operação: " + err.message);
    } finally { setActionLoading(false); }
  };

  const openEdit = (s: any) => {
    setSelectedStudent(s);
    setFormData({
      nome: s.displayName || s.nome || '',
      emailPessoal: s.emailPessoal || '',
      emailAcademico: s.email || '',
      telefone: s.telefone || '',
      cursoId: s.cursoInicial || '',
      status: s.status || 'ativo',
      cpf: s.cpf || '',
      nascimento: s.nascimento || '',
      fotoUrl: s.photoURL || '',
      password: s.passwordHint || '', // Recupera dica de senha se existir
      endereco: s.endereco || { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
    });
    setIsRegisterModalOpen(true);
  };

  const openNew = () => {
    setSelectedStudent(null);
    setFormData({
      nome: '', emailPessoal: '', emailAcademico: '', telefone: '', cursoId: '', 
      status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', password: '',
      endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
    });
    setIsRegisterModalOpen(true);
  };

  if (loading) return <div className="p-20 text-center flex flex-col items-center gap-6"><RefreshCw className="animate-spin text-indigo-600" size={40}/><p className="font-black text-slate-400 uppercase italic text-xs tracking-[0.5em]">Carregando Base de Alunos...</p></div>;

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      {/* HEADER DA GESTÃO */}
      <header className="bg-white p-8 rounded-[2.5rem] border border-slate-200 flex flex-col md:flex-row justify-between items-center shadow-xl shadow-slate-200/50 gap-6">
        <div>
           <h1 className="text-3xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Gestão de Alunos</h1>
           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-2 italic leading-none">Administração Acadêmica Central</p>
        </div>
        <div className="flex gap-3">
           <button onClick={handleExportExcel} className="bg-emerald-50 text-emerald-600 px-6 py-4 rounded-2xl text-[10px] font-black uppercase italic hover:bg-emerald-100 transition-all flex items-center gap-2 border border-emerald-100"><FileSpreadsheet size={18}/> Exportar Excel</button>
           <button onClick={openNew} className="bg-slate-900 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase italic hover:bg-indigo-600 transition-all flex items-center gap-2 shadow-2xl active:scale-95 shadow-indigo-100"><UserPlus size={18}/> Nova Matrícula</button>
        </div>
      </header>

      {/* TABELA DE ALUNOS */}
      <div className="bg-white rounded-[3rem] border border-slate-200 overflow-hidden shadow-2xl shadow-slate-200/30">
        <div className="p-6 border-b border-slate-50 bg-slate-50/30 flex flex-col md:flex-row gap-4 items-center">
           <div className="relative flex-1 w-full"><Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={20}/><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Buscar por Nome, Matrícula ou E-mail..." className="w-full pl-16 pr-6 py-4.5 bg-white border border-slate-200 rounded-2xl text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600 shadow-inner" /></div>
        </div>
        <div className="overflow-x-auto custom-scrollbar">
           <table className="w-full text-left border-collapse">
              <thead className="bg-slate-50 text-[10px] font-black uppercase italic text-slate-400 border-b border-slate-100 tracking-widest">
                 <tr>
                    <th className="px-8 py-6">Identificação</th>
                    <th className="px-8 py-6 text-center">Matrícula</th>
                    <th className="px-8 py-6">Dados de Acesso</th>
                    <th className="px-8 py-6 text-center">Status</th>
                    <th className="px-8 py-6 text-center">Gestão</th>
                 </tr>
              </thead>
              <tbody className="text-xs">
                 {filtered.length === 0 ? (
                   <tr><td colSpan={5} className="p-32 text-center text-slate-300 font-black uppercase italic text-sm tracking-[0.5em]">Nenhum Aluno Encontrado.</td></tr>
                 ) : filtered.map(s => (
                   <tr key={s.uid} className="border-b border-slate-50 hover:bg-indigo-50/10 transition-all group">
                      <td className="px-8 py-5">
                         <div className="flex items-center gap-4">
                            <div className="w-12 h-12 rounded-[1rem] bg-slate-100 overflow-hidden border-2 border-white shadow-md shrink-0">
                               {s.photoURL ? <img src={s.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center font-black italic text-slate-300 text-lg">{(s.displayName||'U').charAt(0)}</div>}
                            </div>
                            <div>
                               <p className="font-black uppercase text-slate-900 italic tracking-tight text-xs leading-none">{s.displayName}</p>
                               <p className="text-[9px] font-bold text-slate-400 uppercase mt-1.5 tracking-tighter italic flex items-center gap-1"><Mail size={10}/> {s.email}</p>
                            </div>
                         </div>
                      </td>
                      <td className="px-8 py-5 text-center font-mono font-black text-indigo-600 text-xs tracking-tighter">{(s as any).academicId || '---'}</td>
                      <td className="px-8 py-5">
                         <div className="space-y-1">
                            <p className="text-[10px] font-bold text-slate-600">Login: <span className="text-indigo-600">{s.email}</span></p>
                            <p className="text-[9px] text-slate-400 italic">Pessoal: {(s as any).emailPessoal || '---'}</p>
                         </div>
                      </td>
                      <td className="px-8 py-5 text-center">
                         <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase italic border flex items-center justify-center gap-1 w-fit mx-auto ${
                           (s as any).status === 'ativo' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 
                           (s as any).status === 'bloqueado' ? 'bg-rose-50 text-rose-600 border-rose-100' : 
                           'bg-amber-50 text-amber-600 border-amber-100'
                         }`}>
                           {(s as any).status === 'ativo' ? <CheckCircle2 size={10}/> : (s as any).status === 'bloqueado' ? <Ban size={10}/> : <AlertCircle size={10}/>}
                           {(s as any).status || 'PENDENTE'}
                         </span>
                      </td>
                      <td className="px-8 py-5 text-center">
                         <div className="flex justify-center gap-2">
                            <button onClick={() => { setSelectedStudent(s); setIsViewModalOpen(true); }} className="p-2.5 bg-slate-50 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-xl transition-all border border-transparent hover:border-slate-100 shadow-sm" title="Ver Prontuário"><Eye size={16}/></button>
                            <button onClick={() => openEdit(s)} className="p-2.5 bg-slate-50 text-slate-400 hover:text-amber-600 hover:bg-white rounded-xl transition-all border border-transparent hover:border-slate-100 shadow-sm" title="Editar"><Edit3 size={16}/></button>
                            <button onClick={async () => { if(confirm('ATENÇÃO: Excluir este aluno removerá todo o histórico escolar. Confirmar?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2.5 bg-slate-50 text-slate-400 hover:text-rose-600 hover:bg-white rounded-xl transition-all border border-transparent hover:border-slate-100 shadow-sm" title="Excluir"><Trash2 size={16}/></button>
                         </div>
                      </td>
                   </tr>
                 ))}
              </tbody>
           </table>
        </div>
      </div>

