              <div className="p-3 bg-indigo-600 rounded-2xl shadow-[0_15px_30px_rgba(79,70,229,0.3)] border border-indigo-400/30"><UserCog size={24}/></div>
              <div><h2 className="text-xl font-black uppercase italic tracking-tighter leading-none">{selectedStudent ? 'Editar Matrícula' : 'Nova Matrícula Institucional'}</h2><p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mt-1 italic">Sincronização Master</p></div>
