                   <div className="md:col-span-1 space-y-1.5"><label className="text-[9px] font-black uppercase text-indigo-600 ml-2 italic">CEP</label><input required value={formData.endereco.cep} onChange={e => handleCepSearch(e.target.value)} className="w-full p-3 bg-white border-none rounded-xl text-xs font-black shadow-sm" placeholder="00000-000" /></div>
                   <div className="md:col-span-4 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2 italic">Logradouro</label><input required value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="w-full p-3 bg-white border-none rounded-xl text-xs font-black shadow-sm" /></div>
                   <div className="md:col-span-1 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2 italic">Nº</label><input required value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="w-full p-3 bg-white border-none rounded-xl text-xs font-black shadow-sm" /></div>
                   <div className="md:col-span-2 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2 italic">Bairro</label><input required value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="w-full p-3 bg-white border-none rounded-xl text-xs font-black shadow-sm" /></div>
                   <div className="md:col-span-3 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2 italic">Cidade</label><input required value={formData.endereco.cidade} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cidade: e.target.value}})} className="w-full p-3 bg-white border-none rounded-xl text-xs font-black shadow-sm" /></div>
                   <div className="md:col-span-1 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2 italic">UF</label><input required value={formData.endereco.uf} onChange={e => setFormData({...formData, endereco: {...formData.endereco, uf: e.target.value.toUpperCase()}})} className="w-full p-3 bg-white border-none rounded-xl text-xs font-black shadow-sm text-center" maxLength={2} /></div>
