                   </div>
                   <div className="space-y-1.5">
                      <label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic tracking-widest">Curso Matriculado</label>
                      <select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-black uppercase shadow-inner outline-none focus:ring-1 focus:ring-indigo-600">
                         <option value="">Selecionar...</option>
                         {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                      </select>
                   </div>
                   <div className="space-y-1.5">
                      <label className="text-[10px] font-black uppercase text-indigo-600 ml-4 italic tracking-widest">Login Acadêmico (E-mail)</label>
                      <input type="email" required value={formData.emailAcademico} onChange={e => setFormData({...formData, emailAcademico: e.target.value})} className="w-full p-4 bg-indigo-50 border-2 border-indigo-100 rounded-2xl text-xs font-black shadow-sm" />
                   </div>
                   <div className="space-y-1.5">
                      <label className="text-[10px] font-black uppercase text-rose-500 ml-4 italic tracking-widest">Definir Senha de Acesso</label>
                      <div className="relative">
                         <input type="text" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-mono font-black shadow-inner" placeholder={selectedStudent ? "Deixe vazio para manter" : "Mínimo 6 caracteres"} />
                         <Lock size={16} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300"/>
                      </div>
                   </div>
                   <div className="space-y-1.5">
                      <label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic tracking-widest">Status da Matrícula</label>
                      <select value={formData.status} onChange={e => setFormData({...formData, status: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-black uppercase shadow-inner">
                         <option value="ativo">Ativo</option>
                         <option value="pendente">Pendente</option>
                         <option value="bloqueado">Bloqueado</option>
                         <option value="concluido">Concluído</option>
                         <option value="aguardando_validacao">Aguardando Validação</option>
                      </select>
                   </div>
                </div>
             </section>

             <div className="flex flex-col sm:flex-row gap-4 pt-8 border-t border-slate-100">
                <button type="button" onClick={() => setIsRegisterModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-[1.5rem] text-[10px] font-black uppercase italic tracking-widest hover:bg-slate-200 transition-all">Cancelar</button>
                <button type="submit" disabled={actionLoading} className="flex-[2] py-5 bg-slate-900 text-white rounded-[1.5rem] text-[10px] font-black uppercase italic tracking-[0.4em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-3 active:scale-95 shadow-indigo-100">
                  {actionLoading ? <RefreshCw className="animate-spin" size={20}/> : <><ShieldCheck size={20}/> {selectedStudent ? 'Atualizar Prontuário' : 'Efetivar Matrícula'}</>}
                </button>
             </div>
          </form>
        </div>
      )}

      {/* MODAL DE VISUALIZAÇÃO (PRONTUÁRIO) */}
      {isViewModalOpen && selectedStudent && (
        <div className="fixed inset-0 z-[5000] bg-slate-950/80 backdrop-blur-md flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 shadow-2xl relative border border-white/20">
