                    {selectedStudent.photoURL ? <img src={selectedStudent.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center font-black text-4xl text-slate-300">{(selectedStudent.displayName||'U').charAt(0)}</div>}
                 </div>
                 <div>
                    <h2 className="text-2xl font-black uppercase italic text-slate-900 leading-none">{selectedStudent.displayName}</h2>
                    <p className="text-[10px] font-bold text-indigo-600 uppercase tracking-[0.4em] mt-2">Matrícula: {selectedStudent.academicId}</p>
                 </div>
                 <div className="grid grid-cols-2 gap-4 w-full bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                    <div className="text-left space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase">CPF</p><p className="text-xs font-bold text-slate-800">{selectedStudent.cpf}</p></div>
                    <div className="text-left space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase">Nascimento</p><p className="text-xs font-bold text-slate-800">{selectedStudent.nascimento}</p></div>
                    <div className="text-left space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase">E-mail Pessoal</p><p className="text-xs font-bold text-slate-800">{selectedStudent.emailPessoal}</p></div>
                    <div className="text-left space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase">Telefone</p><p className="text-xs font-bold text-slate-800">{selectedStudent.telefone}</p></div>
                    <div className="col-span-2 text-left space-y-1 border-t border-slate-200 pt-2"><p className="text-[9px] font-black text-slate-400 uppercase">Endereço</p><p className="text-xs font-bold text-slate-800">{selectedStudent.endereco?.rua}, {selectedStudent.endereco?.numero} - {selectedStudent.endereco?.bairro}, {selectedStudent.endereco?.cidade}/{selectedStudent.endereco?.uf}</p></div>
                 </div>
                 <div className="w-full p-4 bg-indigo-50 border border-indigo-100 rounded-2xl flex justify-between items-center">
                    <span className="text-[10px] font-black text-indigo-600 uppercase italic">Acesso ao Portal</span>
                    <span className="text-xs font-bold text-slate-900">{selectedStudent.email}</span>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default StudentsView;

import React, { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, doc, getDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { updatePassword } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { auth, db } from '../firebase';
import { Course, User, Module, Lesson } from '../types';
import { BookOpen, PlayCircle, Award, GraduationCap, Zap, Bell, Menu, X, LogOut, Home, LifeBuoy, ScrollText, ShieldAlert, Play, RefreshCw, UserCheck, Clock, ChevronRight, Star, UserCircle, MapPin, Mail, Phone, Lock, Save } from 'lucide-react';

interface StudentViewProps { user: User; }
type StudentSubView = 'dashboard' | 'classroom' | 'library' | 'certificates' | 'support' | 'profile';

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [enrolledCourse, setEnrolledCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [loading, setLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [userData, setUserData] = useState<any>(null);

  // Profile Password State
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passMessage, setPassMessage] = useState('');

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      try {
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          const data = userDoc.data();
          setUserData(data);
          const cId = data.cursoInicial || data.cursoId;
          if (cId) {
            const courseDoc = await getDoc(doc(db, 'cursos', cId));
            if (courseDoc.exists()) {
              setEnrolledCourse({ id: courseDoc.id, ...courseDoc.data() } as Course);
            }
          }
        }
      } catch (error) { console.error("Erro sincronização aluno", error); }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  const handleStartLesson = () => {
    if (!enrolledCourse) return;
    onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', enrolledCourse.id)), snap => {
      const mods = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));
      setModules(mods);
      setActiveSubView('classroom');
    });
  };

  const handleChangePassword = async () => {
    if (newPassword !== confirmPassword) {
      setPassMessage('As senhas não coincidem.');
      return;
    }
    if (newPassword.length < 6) {
      setPassMessage('A senha deve ter no mínimo 6 caracteres.');
      return;
    }
    try {
      if (auth.currentUser) {
        await updatePassword(auth.currentUser, newPassword);
        setPassMessage('Senha atualizada com sucesso!');
        setNewPassword('');
        setConfirmPassword('');
      }
    } catch (e: any) {
      setPassMessage('Erro ao atualizar: ' + e.message);
    }
  };

  if (loading) return (
    <div className="h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-center gap-6">
       <RefreshCw size={48} className="text-indigo-600 animate-spin" />
       <p className="font-black text-white uppercase italic text-xs tracking-[0.5em]">Recuperando Identidade Digital...</p>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 flex overflow-hidden font-sans relative">
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-slate-900/60 z-[60] lg:hidden backdrop-blur-sm"></div>}

      <aside className={`fixed lg:static inset-y-0 left-0 bg-slate-900 w-72 flex flex-col transition-transform duration-300 z-[70] ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
         <div className="p-6 md:p-8 border-b border-white/5 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg"><GraduationCap size={24}/></div>
              <div><p className="font-black text-white uppercase italic text-lg leading-none">EB-EAD</p><p className="text-[8px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Portal do Aluno</p></div>
            </div>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden p-2 text-white/50 hover:text-white"><X size={20}/></button>
         </div>
         <nav className="flex-1 p-4 space-y-2 mt-4 overflow-y-auto">
            {[
              { id: 'dashboard', label: 'Home Page', icon: <Home size={18}/> },
              { id: 'library', label: 'Biblioteca', icon: <BookOpen size={18}/> },
              { id: 'certificates', label: 'Diplomas', icon: <Award size={18}/> },
              { id: 'profile', label: 'Meu Perfil', icon: <UserCircle size={18}/> },
              { id: 'support', label: 'Suporte VIP', icon: <LifeBuoy size={18}/> }
            ].map(item => (
              <button key={item.id} onClick={() => { setActiveSubView(item.id as any); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${activeSubView === item.id ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}>{item.icon} {item.label}</button>
            ))}
         </nav>
         <div className="p-6 border-t border-white/5 bg-black/20">
            <div className="flex items-center gap-4 p-4 bg-white/5 rounded-2xl border border-white/5 shadow-inner">
               <div className="w-12 h-12 rounded-xl overflow-hidden bg-indigo-600 flex items-center justify-center text-white font-black italic shadow-2xl border-2 border-white/10 shrink-0">
                  {userData?.photoURL || user.photoURL ? <img src={userData?.photoURL || user.photoURL} className="w-full h-full object-cover" /> : (userData?.displayName || user.displayName || 'U').charAt(0)}
               </div>
               <div className="flex-1 overflow-hidden">
                  <p className="text-[10px] font-black text-white uppercase italic truncate">{userData?.nome || userData?.displayName || user.displayName || 'Discente'}</p>
                  <p className="text-[7px] font-black text-indigo-400 uppercase mt-1 tracking-widest leading-none">Status: {userData?.status === 'ativo' ? 'Ativo' : 'Auditoria'}</p>
               </div>
               <button onClick={() => auth.signOut()} className="text-rose-500 p-2 hover:bg-rose-500/10 rounded-lg transition-all"><LogOut size={18}/></button>
            </div>
         </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
         <header className="h-16 md:h-20 bg-white border-b border-slate-100 flex items-center justify-between px-4 md:px-8 shadow-sm shrink-0">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2.5 bg-slate-50 text-slate-400 rounded-xl hover:bg-indigo-600 hover:text-white transition-all lg:hidden"><Menu size={20}/></button>
            <div className="flex items-center gap-3 md:gap-6">
               <div className="hidden sm:flex items-center gap-2 px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full border border-indigo-100 shadow-inner"><Zap size={12} fill="currentColor"/><span className="text-[8px] font-black uppercase tracking-widest italic">Sincronização Master Ativa</span></div>
               <button className="relative p-2.5 text-slate-300 hover:text-indigo-600 transition-all"><Bell size={20}/><div className="absolute top-2 right-2 w-1.5 h-1.5 bg-rose-500 rounded-full border-2 border-white"></div></button>
            </div>
         </header>

         {userData?.status === 'aguardando_validacao' && (
            <div className="bg-amber-600 text-white px-8 py-3.5 flex flex-col md:flex-row items-center justify-between animate-in slide-in-from-top duration-500 gap-4 shadow-xl z-10">
               <div className="flex items-center gap-4 text-center md:text-left">
                  <div className="p-2 bg-white/20 rounded-lg animate-pulse"><ShieldAlert size={18}/></div>
                  <div>
                    <p className="text-[10px] font-black uppercase tracking-widest italic leading-none">Matrícula em Auditoria Operacional</p>
                    <p className="text-[9px] font-bold opacity-80 mt-1 uppercase">Seus dados estão sendo validados. A geração de diplomas será liberada em até 24h.</p>
                  </div>
               </div>
               <button onClick={() => window.location.reload()} className="flex items-center gap-2 px-6 py-2 bg-white text-amber-600 rounded-full text-[9px] font-black uppercase italic shadow-lg active:scale-95 transition-all"><RefreshCw size={12}/> Forçar Verificação</button>
            </div>
         )}

         <main className="flex-1 overflow-y-auto p-6 md:p-12 bg-slate-50 custom-scrollbar">
            {activeSubView === 'dashboard' && (
              <div className="max-w-6xl mx-auto space-y-12 animate-in fade-in duration-1000">
                 <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
                    <div className="text-center md:text-left space-y-4">
                       <h1 className="text-5xl md:text-7xl lg:text-8xl font-black text-slate-900 uppercase italic tracking-tighter leading-[0.8] drop-shadow-sm">Evolução <br/> <span className="text-indigo-600">Acadêmica</span></h1>
                       <p className="text-slate-400 text-[10px] md:text-xs font-bold uppercase tracking-[0.5em] italic">Sincronizado via IA Master EB-AD</p>
                    </div>
                    <div className="flex items-center justify-center gap-4 md:gap-6 bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-xl shadow-indigo-100/20">
                       <div className="text-center px-4 md:px-8 border-r border-slate-100"><p className="text-3xl font-black text-slate-900 leading-none">0</p><p className="text-[7px] font-black uppercase text-slate-400 mt-2 tracking-widest italic">Aulas</p></div>
                       <div className="text-center px-4 md:px-8 border-r border-slate-100"><p className="text-3xl font-black text-slate-900 leading-none">0%</p><p className="text-[7px] font-black uppercase text-slate-400 mt-2 tracking-widest italic">Progresso</p></div>
                       <div className="text-center px-4 md:px-8"><p className="text-3xl font-black text-indigo-600 leading-none">---</p><p className="text-[7px] font-black uppercase text-slate-400 mt-2 tracking-widest italic">Média</p></div>
                    </div>
                 </div>

                 {enrolledCourse ? (
