import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, addDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, Clock, MessageSquare, Search, X, FileText, UserCheck, ShieldAlert, UserX, Check, ArrowRightLeft, Fingerprint, Send, Archive, ChevronRight, Eye, Phone, CreditCard, Printer, RefreshCw, BookOpen, ShieldCheck, MessageCircle, AlertTriangle
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'assinatura';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  const [viewingStudent, setViewingStudent] = useState<any | null>(null);
  const [transferenciaData, setTransferenciaData] = useState({ alunoUid: '', novoCursoId: '' });

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => {
      setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() })));
    });
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  // Sync chat messages with Firestore
  useEffect(() => {
    if (!selectedTicketId) {
      setChatHistory([]);
      return;
    }
    const q = query(collection(db, 'tickets', selectedTicketId, 'messages'), orderBy('createdAt', 'asc'));
    const unsubMessages = onSnapshot(q, (snap) => {
      setChatHistory(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsubMessages();
  }, [selectedTicketId]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  const getMissingFields = (s: any) => {
    const missing = [];
    if (!s.cpf) missing.push("CPF");
    if (!s.photoURL) missing.push("Foto");
    if (!s.endereco?.cep) missing.push("Endereço");
    if (!s.nascimento) missing.push("Nascimento");
    if (!s.telefone) missing.push("WhatsApp");
    if (!s.termsAccepted) missing.push("Contrato");
    return missing;
  };

  const stats = useMemo(() => {
    // Logic update: Include students who are pending OR have missing fields
    const pendingVal = students.filter(s => 
      s.status === 'aguardando_validacao' || 
      s.status === 'pendente' || 
      getMissingFields(s).length > 0
    ).length;

    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado').length,
      arquivados: tickets.filter(t => t.status === 'Arquivado').length,
      pendentesVal: pendingVal,
      totalGed: files.length
    };
  }, [tickets, students, files]);

  const handleNotifyWhatsApp = (s: any) => {
    const missing = getMissingFields(s);
    const phone = s.telefone?.replace(/\D/g, '');
    const message = `Olá ${s.displayName}, aqui é da Secretaria Master EB-AD. Para liberar seu acesso completo e emissão de diplomas, precisamos regularizar: ${missing.join(', ')}. Por favor, acesse o portal e atualize seu perfil.`;
    window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`, '_blank');
  };

  const handleSendMessage = async () => {
    if (!chatMessage.trim() || !selectedTicketId) return;
    const messageData = { text: chatMessage, sender: 'Secretaria', senderId: user.uid, createdAt: serverTimestamp() };
    try {
      await addDoc(collection(db, 'tickets', selectedTicketId, 'messages'), messageData);
      await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, updatedAt: serverTimestamp() });
      setChatMessage('');
    } catch (error) { console.error("Erro msg", error); }
  };

  const renderOperational = () => {
    switch(opSubView) {
      case 'validacao':
        // Strict Audit Logic: Show anyone pending OR missing data
        const pending = students.filter(s => 
          s.status === 'aguardando_validacao' || 
          s.status === 'pendente' ||
          getMissingFields(s).length > 0
        );

        return (
          <div className="bg-white border border-slate-300 animate-in zoom-in-98 h-full flex flex-col rounded-xl overflow-hidden shadow-xl">
             <div className="p-4 bg-slate-900 text-white flex justify-between items-center shrink-0">
                <div className="flex items-center gap-3">
                   <div className="p-1.5 bg-indigo-600 rounded-lg shadow-lg"><UserCheck size={16}/></div>
                   <h3 className="text-xs font-black uppercase italic tracking-widest">Auditoria Digital</h3>
                </div>
                <button onClick={() => setOpSubView('main')} className="p-1.5 hover:bg-white/10 rounded-lg transition-all"><X size={16}/></button>
             </div>
             <div className="flex-1 overflow-auto custom-scrollbar">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-50 border-b border-slate-200 text-[9px] font-black uppercase italic tracking-widest sticky top-0 z-10 text-slate-400">
                       <tr><th className="px-6 py-3">ID</th><th className="px-6 py-3">Discente</th><th className="px-6 py-3">Status</th><th className="px-6 py-3 text-center">Ação</th></tr>
                    </thead>
                    <tbody className="text-xs">
                       {pending.length === 0 ? (
                         <tr><td colSpan={4} className="p-20 text-center text-slate-300 uppercase italic font-black text-xs tracking-widest">Nenhuma pendência encontrada.</td></tr>
                       ) : pending.map(s => {
                         const missing = getMissingFields(s);
                         return (
                         <tr key={s.uid} className="border-b border-slate-100 hover:bg-indigo-50/20 transition-all group">
                            <td className="px-6 py-3 font-mono font-black text-indigo-600 text-xs">{s.academicId}</td>
                            <td className="px-6 py-3">
                               <div className="flex items-center gap-3">
                                  <div className="w-8 h-8 rounded-lg bg-slate-100 overflow-hidden shadow-sm shrink-0 border border-slate-200">
                                     {s.photoURL ? <img src={s.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center font-black italic text-slate-300 text-xs">{(s.displayName||'U').charAt(0)}</div>}
                                  </div>
                                  <div>
                                     <p className="font-black uppercase text-slate-900 leading-none italic text-xs">{s.displayName}</p>
                                     <p className="text-[9px] text-slate-400 font-bold mt-0.5 uppercase italic">Pendências: {missing.length > 0 ? <span className="text-rose-500">{missing.join(', ')}</span> : 'Aguardando Validação'}</p>
                                  </div>
