                               <button onClick={() => setViewingStudent(s)} className="p-2 bg-slate-100 text-slate-400 hover:text-indigo-600 rounded-lg transition-all border border-slate-200 shadow-sm"><Eye size={14}/></button>
                               <button 
                                 onClick={async () => { 
                                   if(confirm(`ATENÇÃO: Existem ${missing.length} campos pendentes. Deseja validar ${s.displayName} mesmo assim?`)) {
                                     await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'}); 
                                   }
