         )}
      </main>

      {isSignModalOpen && <SignaturePad title="Validação Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert('Assinatura salva!'); }} />}
    </div>
  );
};

