export default StudentView;

import React, { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, doc, getDoc, updateDoc, serverTimestamp } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { updatePassword } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { auth, db } from '../firebase';
import { Course, User, Module, Lesson } from '../types';
import { BookOpen, PlayCircle, Award, GraduationCap, Zap, Bell, Menu, X, LogOut, Home, LifeBuoy, ScrollText, ShieldAlert, Play, RefreshCw, UserCheck, Clock, ChevronRight, Star, UserCircle, MapPin, Mail, Phone, Lock, Save, FileText, Check, PenTool, CheckCircle2 } from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface StudentViewProps { user: User; }
type StudentSubView = 'dashboard' | 'classroom' | 'library' | 'certificates' | 'support' | 'profile';

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [enrolledCourse, setEnrolledCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [loading, setLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [userData, setUserData] = useState<any>(null);

  // Profile Password State
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passMessage, setPassMessage] = useState('');

  // Contract State
  const [showTermsModal, setShowTermsModal] = useState(false);
  const [termsAgreed, setTermsAgreed] = useState({ contract: false, terms: false, privacy: false });
  const [studentSignature, setStudentSignature] = useState<string | null>(null);
  const [showSigPad, setShowSigPad] = useState(false);

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      try {
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          const data = userDoc.data();
          setUserData(data);

          // Check for terms acceptance only if active
          if (data.status === 'ativo' && !data.termsAccepted) {
            setShowTermsModal(true);
          }

          const cId = data.cursoInicial || data.cursoId;
          if (cId) {
            const courseDoc = await getDoc(doc(db, 'cursos', cId));
            if (courseDoc.exists()) {
              setEnrolledCourse({ id: courseDoc.id, ...courseDoc.data() } as Course);
            }
          }
        }
      } catch (error) { console.error("Erro sincronização aluno", error); }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  const handleStartLesson = () => {
    if (!enrolledCourse) return;
    onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', enrolledCourse.id)), snap => {
      const mods = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));
      setModules(mods);
      setActiveSubView('classroom');
    });
  };

  const handleChangePassword = async () => {
    if (newPassword !== confirmPassword) { setPassMessage('As senhas não coincidem.'); return; }
    if (newPassword.length < 6) { setPassMessage('A senha deve ter no mínimo 6 caracteres.'); return; }
    try {
      if (auth.currentUser) {
        await updatePassword(auth.currentUser, newPassword);
        setPassMessage('Senha atualizada com sucesso!');
        setNewPassword(''); setConfirmPassword('');
      }
    } catch (e: any) { setPassMessage('Erro ao atualizar: ' + e.message); }
  };

  const handleAcceptTerms = async () => {
    if (!termsAgreed.contract || !termsAgreed.terms || !termsAgreed.privacy || !studentSignature) {
      alert("Por favor, aceite todos os termos e assine o contrato.");
      return;
    }
    try {
      await updateDoc(doc(db, 'users', user.uid), {
        termsAccepted: true,
        termsAcceptedAt: serverTimestamp(),
        signatureUrl: studentSignature
      });
      setShowTermsModal(false);
      window.location.reload(); 
    } catch (e) {
      console.error("Error accepting terms", e);
    }
  };

  if (loading) return (
    <div className="h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-center gap-6">
       <RefreshCw size={48} className="text-indigo-600 animate-spin" />
       <p className="font-black text-white uppercase italic text-xs tracking-[0.5em]">Carregando Portal...</p>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 flex overflow-hidden font-sans relative">
      {/* CONTRACT MODAL */}
      {showTermsModal && (
        <div className="fixed inset-0 z-[9000] bg-slate-950/95 backdrop-blur-xl flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-2xl h-[85vh] rounded-2xl flex flex-col shadow-2xl overflow-hidden animate-in zoom-in-95">
            <header className="p-6 border-b border-slate-100 bg-slate-50">
              <h2 className="text-xl font-black uppercase italic text-slate-900 tracking-tighter">Contrato de Prestação de Serviços</h2>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Assinatura Obrigatória para Acesso</p>
            </header>
            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-8">
              <div className="space-y-4">
                <h3 className="font-bold text-slate-900 text-sm uppercase flex items-center gap-2"><FileText size={16} className="text-indigo-600"/> 1. Termos de Uso</h3>
                <div className="h-32 bg-slate-50 p-4 rounded-xl border border-slate-200 text-[10px] text-slate-500 overflow-y-auto leading-relaxed text-justify">
                  <p>Ao utilizar a plataforma Escola Bíblica EAD, você concorda com os termos de serviço educacional. O conteúdo é de uso exclusivo e intransferível. A reprodução parcial ou total é proibida. O aluno compromete-se a manter a ética e o decoro no ambiente virtual. A instituição reserva-se o direito de atualizar o conteúdo programático conforme necessidade pedagógica.</p>
                </div>
                <label className="flex items-center gap-3 cursor-pointer p-3 rounded-lg hover:bg-slate-50 transition-colors border border-transparent hover:border-slate-100">
                  <input type="checkbox" checked={termsAgreed.terms} onChange={e => setTermsAgreed({...termsAgreed, terms: e.target.checked})} className="w-5 h-5 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500" />
                  <span className="text-xs font-bold text-slate-700">Li e aceito os Termos de Uso da Plataforma</span>
                </label>
              </div>

              <div className="space-y-4">
                <h3 className="font-bold text-slate-900 text-sm uppercase flex items-center gap-2"><ShieldAlert size={16} className="text-indigo-600"/> 2. Política de Privacidade</h3>
                <div className="h-32 bg-slate-50 p-4 rounded-xl border border-slate-200 text-[10px] text-slate-500 overflow-y-auto leading-relaxed text-justify">
                  <p>Coletamos dados pessoais para fins acadêmicos e administrativos conforme a LGPD. Seus dados (Nome, CPF, Endereço, Foto) são utilizados para emissão de certificados e validação de matrícula. Não compartilhamos dados com terceiros sem consentimento, exceto por obrigação legal. Você tem direito a solicitar a exclusão ou alteração de seus dados a qualquer momento via secretaria.</p>
                </div>
                <label className="flex items-center gap-3 cursor-pointer p-3 rounded-lg hover:bg-slate-50 transition-colors border border-transparent hover:border-slate-100">
                  <input type="checkbox" checked={termsAgreed.privacy} onChange={e => setTermsAgreed({...termsAgreed, privacy: e.target.checked})} className="w-5 h-5 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500" />
                  <span className="text-xs font-bold text-slate-700">Li e concordo com a Política de Privacidade e Tratamento de Dados</span>
                </label>
              </div>

              <div className="space-y-4">
