// --- SECURE VIDEO PLAYER COMPONENT ---
interface SecureVideoPlayerProps {
  videoUrl: string;
  onComplete: () => void;
  title: string;
}

const SecureVideoPlayer: React.FC<SecureVideoPlayerProps> = ({ videoUrl, onComplete, title }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState(100);
  const [isMuted, setIsMuted] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  // We use a ref to store the YouTube player instance if we were using the full API, 
  // but for a lightweight strict implementation without external script loading issues in this environment,
  // we will use the iframe API postMessage method or standard embedding.

  // Extract Video ID
  const getVideoId = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };
  const videoId = getVideoId(videoUrl);

  // Initial load
  useEffect(() => {
    // Reset state on new video
    setIsPlaying(false);
  }, [videoId]);

  // Simulated "End of Video" detection
  // Since we can't easily use the full YT API object in this specific react-lite setup without external script loaders,
  // we will use a time-based approximation or assume the user watches it if they don't navigate away.
  // HOWEVER, the prompt asks for strict completion.
  // We will simulate the "Check for completion" by requiring the video to be "played" for a certain duration or
  // ideally, we load the YT Iframe API. Let's try to load the API dynamically for 'onStateChange'.

  useEffect(() => {
    if (!window.YT) {
      const tag = document.createElement('script');
      tag.src = "https://www.youtube.com/iframe_api";
      const firstScriptTag = document.getElementsByTagName('script')[0];
      firstScriptTag.parentNode?.insertBefore(tag, firstScriptTag);
    }

    let player: any;

    window.onYouTubeIframeAPIReady = () => {
      loadPlayer();
    };

    const loadPlayer = () => {
      if (videoId && window.YT && window.YT.Player) {
        player = new window.YT.Player(`youtube-player-${videoId}`, {
          height: '100%',
          width: '100%',
          videoId: videoId,
          playerVars: {
            controls: 0, // No controls
            disablekb: 1, // Disable keyboard
            fs: 0, // We handle fullscreen
            modestbranding: 1,
            rel: 0,
            showinfo: 0,
            iv_load_policy: 3
          },
          events: {
            'onStateChange': onPlayerStateChange
          }
        });
      }
    };

    if (window.YT && window.YT.Player) {
      loadPlayer();
    }

    function onPlayerStateChange(event: any) {
      if (event.data == window.YT.PlayerState.PLAYING) {
        setIsPlaying(true);
      }
      if (event.data == window.YT.PlayerState.PAUSED) {
        setIsPlaying(false);
      }
      if (event.data == window.YT.PlayerState.ENDED) {
        setIsPlaying(false);
        onComplete(); // Trigger completion
      }
    }

    return () => {
      if (player && player.destroy) player.destroy();
    };
  }, [videoId]);

  // Custom Controls Handlers - Messaging the iframe directly is tricky without the object.
  // If the API loaded successfully above, we could use `player.playVideo()`.
  // Fallback: The standard iframe `postMessage` method.

  const sendCommand = (func: string, args: any[] = []) => {
    if (!iframeRef.current) return;
    iframeRef.current.contentWindow?.postMessage(JSON.stringify({
      'event': 'command',
      'func': func,
      'args': args
    }), '*');
  };

  const togglePlay = () => {
    if (isPlaying) {
      sendCommand('pauseVideo');
      setIsPlaying(false);
    } else {
      sendCommand('playVideo');
      setIsPlaying(true);
    }
  };

  const toggleMute = () => {
    if (isMuted) {
      sendCommand('unMute');
      setIsMuted(false);
    } else {
      sendCommand('mute');
      setIsMuted(true);
    }
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  return (
    <div ref={containerRef} className="relative w-full aspect-video bg-black rounded-3xl overflow-hidden group shadow-2xl border border-slate-900">
      {/* Interaction Shield - Prevents clicking title/Youtube logo */}
      <div className="absolute inset-0 z-10 pointer-events-none" />

      {/* YouTube Iframe */}
      <div className="w-full h-full pointer-events-none"> {/* Disable pointer events on iframe to force custom controls */}
        <iframe 
          ref={iframeRef}
          id={`youtube-player-${videoId}`}
          className="w-full h-full"
          src={`https://www.youtube.com/embed/${videoId}?enablejsapi=1&controls=0&modestbranding=1&rel=0&showinfo=0&iv_load_policy=3&disablekb=1`}
          allow="autoplay; encrypted-media"
          title={title}
        />
      </div>

      {/* Custom Control Bar */}
      <div className="absolute bottom-0 left-0 right-0 h-20 bg-gradient-to-t from-black/90 to-transparent z-20 flex items-end p-6 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
        <div className="w-full flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">
              {isPlaying ? <Pause size={24} fill="currentColor" /> : <PlayIcon size={24} fill="currentColor" />}
            </button>

            <div className="flex items-center gap-2 group/vol">
              <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">
                {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} />}
              </button>
              {/* Fake Volume Slider Visual */}
              <div className="w-0 overflow-hidden group-hover/vol:w-20 transition-all duration-300">
                 <div className="h-1 bg-white/30 rounded-full w-full relative">
                    <div className="h-1 bg-indigo-500 w-3/4 absolute top-0 left-0 rounded-full"></div>
                 </div>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-4">
             {/* Fake Quality Gear */}
             <button className="text-white/70 hover:text-white transition-colors" title="Quality Settings (Auto)">
                <Settings size={20} />
             </button>

             <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors">
                {isFullscreen ? <Minimize size={20} /> : <Maximize size={20} />}
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// --- QUIZ INTERFACE COMPONENT ---
interface QuizPlayerProps {
  exam: Exam;
  onPass: (score: number) => void;
}

const QuizPlayer: React.FC<QuizPlayerProps> = ({ exam, onPass }) => {
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [submitted, setSubmitted] = useState(false);
  const [score, setScore] = useState(0);
  const [passed, setPassed] = useState(false);

  const handleSubmit = () => {
    let correctCount = 0;
    exam.questions.forEach((q, idx) => {
      // Logic relies on Question ID or Index. 
      // Assuming exam.questions are ordered and answers key is question index for simplicity here,
      // or using question ID if available. Let's use Index to be safe if IDs are missing.
      const selected = answers[q.id];
      if (selected === q.correctOption) correctCount++;
    });

    const finalScore = (correctCount / exam.questions.length) * 100;
    setScore(finalScore);
    setSubmitted(true);

    if (finalScore >= (exam.passingGrade || 70)) {
      setPassed(true);
      onPass(finalScore);
    }
  };

  if (submitted) {
    return (
      <div className="flex flex-col items-center justify-center p-12 bg-white rounded-[3rem] border border-slate-200 shadow-xl text-center space-y-6 animate-in zoom-in-95">
        <div className={`w-24 h-24 rounded-full flex items-center justify-center shadow-inner ${passed ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
          {passed ? <Award size={48}/> : <AlertCircle size={48}/>}
        </div>
        <div>
          <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{passed ? 'Aprovado!' : 'Tente Novamente'}</h2>
          <p className="text-slate-500 font-bold mt-2">Sua nota: <span className={passed ? 'text-emerald-600' : 'text-rose-600'}>{score.toFixed(0)}%</span></p>
          <p className="text-[10px] text-slate-400 uppercase tracking-widest mt-1 italic">Mínimo necessário: {exam.passingGrade}%</p>
        </div>
        {passed ? (
          <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 max-w-sm">
            <p className="text-xs text-slate-600 font-medium">Parabéns! Você desbloqueou o próximo módulo da sua jornada acadêmica.</p>
          </div>
        ) : (
          <button 
            onClick={() => { setSubmitted(false); setAnswers({}); }} 
            className="px-8 py-3 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-600 transition-all shadow-lg"
          >
            Refazer Avaliação
          </button>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in max-w-3xl mx-auto pb-20">
      <div className="text-center space-y-2">
        <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">{exam.title}</h2>
        <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-indigo-50 text-indigo-700 rounded-full text-[9px] font-black uppercase tracking-widest border border-indigo-100">
          <Award size={12}/> Avaliação Oficial • Corte: {exam.passingGrade}%
        </div>
      </div>

      <div className="space-y-6">
        {exam.questions.map((q, i) => (
          <div key={q.id} className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
            <div className="flex gap-4 mb-6">
              <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-xs italic shrink-0">{i + 1}</span>
              <p className="text-sm font-bold text-slate-800 leading-relaxed">{q.text}</p>
            </div>
            <div className="space-y-3 pl-12">
              {q.options.map((opt, optIdx) => (
                <label key={optIdx} className={`flex items-center gap-4 p-4 rounded-xl border cursor-pointer transition-all ${answers[q.id] === optIdx ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-slate-50 border-slate-100 text-slate-600 hover:bg-slate-100'}`}>
                  <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${answers[q.id] === optIdx ? 'border-white' : 'border-slate-300'}`}>
                    {answers[q.id] === optIdx && <div className="w-2.5 h-2.5 bg-white rounded-full" />}
                  </div>
                  <input 
                    type="radio" 
                    name={q.id} 
                    className="hidden" 
                    checked={answers[q.id] === optIdx} 
                    onChange={() => setAnswers({...answers, [q.id]: optIdx})}
                  />
                  <span className="text-xs font-bold uppercase tracking-wide">{opt}</span>
                </label>
              ))}
            </div>
          </div>
        ))}
      </div>

      <div className="flex justify-end">
        <button 
          onClick={handleSubmit} 
          disabled={Object.keys(answers).length < exam.questions.length}
          className="px-10 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] shadow-xl hover:bg-emerald-600 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center gap-3"
        >
          <CheckCircle2 size={18}/> Enviar Respostas
        </button>
      </div>
    </div>
  );
};

