  isCompleted: boolean;
  index: number;
}

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');

  // Courses State
  const [enrolledCourses, setEnrolledCourses] = useState<Course[]>([]);
  const [selectedClassroomCourse, setSelectedClassroomCourse] = useState<Course | null>(null);
  const [loading, setLoading] = useState(true);

  // Timeline State
  const [timeline, setTimeline] = useState<TimelineItem[]>([]);
  const [activeTimelineIndex, setActiveTimelineIndex] = useState(0);
  const [studentProgress, setStudentProgress] = useState<Record<string, any>>({});

  // Sidebar & Modals
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showTermsModal, setShowTermsModal] = useState(false);

  // User Data State (Editable)
  const [userData, setUserData] = useState<any>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState<any>({});
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Profile Password State
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passMessage, setPassMessage] = useState('');

  // Contract State
  const [termsAgreed, setTermsAgreed] = useState({ contract: false, terms: false, privacy: false });
  const [studentSignature, setStudentSignature] = useState<string | null>(null);
  const [showSigPad, setShowSigPad] = useState(false);

  // Agenda & Notifications
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [showNotificationsDropdown, setShowNotificationsDropdown] = useState(false);

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      try {
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          const data = userDoc.data();
          setUserData(data);
          setEditForm(data);
          setStudentProgress(data.progress || {});

          if (data.status === 'ativo' && !data.termsAccepted) {
            setShowTermsModal(true);
          }

          let courseIds = data.matriculas || [];
          if (courseIds.length === 0 && (data.cursoInicial || data.cursoId)) {
             courseIds = [data.cursoInicial || data.cursoId];
          }

          if (courseIds.length > 0) {
             const q = query(collection(db, 'cursos'), where('__name__', 'in', courseIds.slice(0, 10)));
             const querySnapshot = await getDocs(q);
             const loadedCourses = querySnapshot.docs.map(d => ({ id: d.id, ...d.data() } as Course));
             setEnrolledCourses(loadedCourses);

             const agendaQuery = query(
                collection(db, 'scheduledClasses'), 
                where('courseId', 'in', courseIds.slice(0, 10)),
                where('date', '>=', new Date())
             );

             const unsubAgenda = onSnapshot(agendaQuery, (snap) => {
                const classes = snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass));
                setScheduledClasses(classes.sort((a,b) => {
                   const dateA = a.date?.seconds ? new Date(a.date.seconds * 1000) : new Date(a.date);
                   const dateB = b.date?.seconds ? new Date(b.date.seconds * 1000) : new Date(b.date);
                   return dateA.getTime() - dateB.getTime();
                }));
             });
          }
        }
      } catch (error) { console.error("Erro sincronização aluno", error); }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  // Build the Linear Timeline when a course is selected
  useEffect(() => {
    if (!selectedClassroomCourse || !userData) return;

    const buildTimeline = async () => {
      // Fetch Modules
      const modQ = query(collection(db, 'modulos'), where('courseId', '==', selectedClassroomCourse.id));
      const modSnap = await getDocs(modQ);
      const modules = modSnap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));

      // Fetch Exams
      const examQ = query(collection(db, 'exams'), where('courseId', '==', selectedClassroomCourse.id));
      const examSnap = await getDocs(examQ);
      const exams = examSnap.docs.map(d => ({ id: d.id, ...d.data() } as Exam));

      const rawTimeline: TimelineItem[] = [];
      let globalIndex = 0;

      modules.forEach(mod => {
        // Add Lessons
        mod.lessons?.forEach(lesson => {
          rawTimeline.push({
            id: lesson.id,
            type: 'lesson',
            title: lesson.title,
            moduleId: mod.id,
            moduleTitle: mod.title,
            data: lesson,
            isLocked: true, // Calc later
            isCompleted: false, // Calc later
            index: globalIndex++
          });
        });

        // Add Exams for this module
        exams.filter(e => e.moduleId === mod.id).forEach(exam => {
          rawTimeline.push({
            id: exam.id,
            type: 'exam',
            title: exam.title,
            moduleId: mod.id,
            moduleTitle: mod.title,
            data: exam,
            isLocked: true,
            isCompleted: false,
            index: globalIndex++
          });
        });
      });

      // Calculate Locking Logic based on user progress
      const courseProgress = studentProgress[selectedClassroomCourse.id] || {};

      const processedTimeline = rawTimeline.map((item, idx) => {
        const itemProgress = courseProgress[item.id] || {};
        const isCompleted = itemProgress.completed === true;

        // Locked if previous item is not completed
        // Item 0 is always unlocked.
        let isLocked = false;
        if (idx > 0) {
          const prevItem = rawTimeline[idx - 1];
          const prevProgress = courseProgress[prevItem.id] || {};
          if (!prevProgress.completed) {
            isLocked = true;
          }
        }

        return { ...item, isLocked, isCompleted };
      });

      setTimeline(processedTimeline);

      // Auto-select first unlocked but incomplete item, or last item
      const firstActive = processedTimeline.find(t => !t.isLocked && !t.isCompleted) || processedTimeline[processedTimeline.length - 1];
      if (firstActive) setActiveTimelineIndex(firstActive.index);
    };

    buildTimeline();
  }, [selectedClassroomCourse, studentProgress]); // Re-run when progress updates

  const markItemComplete = async (itemId: string, score?: number) => {
    if (!selectedClassroomCourse) return;

    // Optimistic Update
    const newProgress = {
      ...studentProgress,
      [selectedClassroomCourse.id]: {
        ...(studentProgress[selectedClassroomCourse.id] || {}),
        [itemId]: { completed: true, score }
      }
    };
    setStudentProgress(newProgress); // Triggers timeline rebuild

    // Firestore Update
    await updateDoc(doc(db, 'users', user.uid), {
      [`progress.${selectedClassroomCourse.id}.${itemId}`]: { completed: true, score }
    });
  };

  const activeItem = timeline[activeTimelineIndex];

  // Rest of the component logic (Notifications, Profile, etc.) similar to before...
  // Effect to update Notifications based on Agenda
  useEffect(() => {
     const newNotifs = [];
     newNotifs.push({
        id: 'sys-welcome',
        title: 'Bem-vindo ao Portal Master',
        desc: 'Sua área do aluno está pronta.',
        type: 'system',
        time: 'Agora'
     });
     scheduledClasses.forEach(c => {
        const cDate = c.date?.seconds ? new Date(c.date.seconds * 1000) : new Date(c.date);
        const courseName = enrolledCourses.find(ec => ec.id === c.courseId)?.nome || 'Curso';
        newNotifs.push({
           id: c.id,
           title: 'Aula Ao Vivo Agendada',
           desc: `${c.title} - ${courseName}`,
           type: 'live',
           time: cDate.toLocaleDateString() + ' ' + cDate.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})
        });
     });
     setNotifications(newNotifs);
  }, [scheduledClasses, enrolledCourses]);

  const handleChangePassword = async () => {
    if (newPassword !== confirmPassword) { setPassMessage('As senhas não coincidem.'); return; }
    if (newPassword.length < 6) { setPassMessage('A senha deve ter no mínimo 6 caracteres.'); return; }
    try {
      if (auth.currentUser) {
        await updatePassword(auth.currentUser, newPassword);
        setPassMessage('Senha atualizada com sucesso!');
        setNewPassword(''); setConfirmPassword('');
      }
    } catch (e: any) { setPassMessage('Erro ao atualizar: ' + e.message); }
  };

  const compressImage = (base64: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_WIDTH = 800;
        const scale = MAX_WIDTH / img.width;
        canvas.width = MAX_WIDTH;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.7));
      };
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const compressed = await compressImage(reader.result as string);
        setEditForm({ ...editForm, photoURL: compressed });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateProfile = async () => {
    try {
      if (!editForm.nome || !editForm.cpf || !editForm.telefone) {
        alert("Preencha os campos obrigatórios (Nome, CPF, Telefone).");
        return;
      }
      await updateDoc(doc(db, 'users', user.uid), {
        ...editForm,
        updatedAt: serverTimestamp()
      });
      setUserData(editForm);
      alert("Dados atualizados com sucesso!");
    } catch (e: any) {
      alert("Erro ao salvar: " + e.message);
    }
  };

  const handleAcceptTerms = async () => {
    if (!termsAgreed.contract || !termsAgreed.terms || !termsAgreed.privacy || !studentSignature) {
      alert("Por favor, aceite todos os termos e assine o contrato.");
      return;
    }
    try {
      await updateDoc(doc(db, 'users', user.uid), {
        termsAccepted: true,
        termsAcceptedAt: serverTimestamp(),
        signatureUrl: studentSignature
      });
      setShowTermsModal(false);
      window.location.reload(); 
    } catch (e) { console.error("Error accepting terms", e); }
  };

  if (loading) return (
    <div className="h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-center gap-6">
       <RefreshCw size={48} className="text-indigo-600 animate-spin" />
       <p className="font-black text-white uppercase italic text-xs tracking-[0.5em]">Carregando Portal...</p>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 flex overflow-hidden font-sans relative">
      {/* SIDEBAR & HEADER (Keep existing logic, updating main content area) */}

      {/* ... (Sidebar & Header code remains same as previous version until Main Content) ... */}
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-slate-900/60 z-[60] lg:hidden backdrop-blur-sm"></div>}

      <aside className={`fixed lg:static inset-y-0 left-0 bg-slate-900 w-72 flex flex-col transition-transform duration-300 z-[70] ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
         <div className="p-6 border-b border-white/5 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-indigo-600 text-white rounded-lg shadow-lg"><GraduationCap size={20}/></div>
              <div><p className="font-black text-white uppercase italic text-base leading-none">EB-EAD</p><p className="text-[8px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Portal do Aluno</p></div>
            </div>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden p-2 text-white/50 hover:text-white"><X size={20}/></button>
         </div>
         <nav className="flex-1 p-4 space-y-1 mt-2 overflow-y-auto">
            {[
              { id: 'dashboard', label: 'Home Page', icon: <Home size={16}/> },
              { id: 'library', label: 'Meus Cursos', icon: <BookOpen size={16}/> },
              { id: 'certificates', label: 'Galeria de Diplomas', icon: <Award size={16}/> },
              { id: 'profile', label: 'Meu Perfil', icon: <UserCircle size={16}/> },
              { id: 'support', label: 'Suporte VIP', icon: <LifeBuoy size={16}/> }
            ].map(item => (
              <button 
                key={item.id} 
                onClick={() => { setActiveSubView(item.id as any); setIsSidebarOpen(false); setSelectedClassroomCourse(null); }} 
                disabled={userData?.status !== 'ativo' && item.id !== 'profile'}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  activeSubView === item.id 
                    ? 'bg-indigo-600 text-white shadow-lg' 
                    : 'text-slate-500 hover:text-white hover:bg-white/5 disabled:opacity-50 disabled:cursor-not-allowed'
                }`}
              >
                {item.icon} {item.label}
              </button>
            ))}
         </nav>
         <div className="p-6 border-t border-white/5 bg-black/20">
            <div className="flex items-center gap-3 p-3 bg-white/5 rounded-xl border border-white/5 shadow-inner">
               <div className="w-10 h-10 rounded-lg overflow-hidden bg-indigo-600 flex items-center justify-center text-white font-black italic shadow-lg border border-white/10 shrink-0">
                  {userData?.photoURL || user.photoURL ? <img src={userData?.photoURL || user.photoURL} className="w-full h-full object-cover" /> : (userData?.displayName || user.displayName || 'U').charAt(0)}
               </div>
               <div className="flex-1 overflow-hidden">
                  <p className="text-[10px] font-black text-white uppercase italic truncate">{userData?.nome || userData?.displayName || user.displayName || 'Discente'}</p>
                  <p className="text-[7px] font-bold text-indigo-400 uppercase mt-0.5 tracking-widest leading-none">{userData?.status === 'ativo' ? 'Ativo' : 'Auditoria'}</p>
               </div>
               <button onClick={() => auth.signOut()} className="text-rose-500 p-2 hover:bg-rose-500/10 rounded-lg transition-all"><LogOut size={16}/></button>
            </div>
         </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
         {/* HEADER */}
         <header className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-6 shadow-sm shrink-0 z-50 relative">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-slate-50 text-slate-400 rounded-lg hover:bg-indigo-600 hover:text-white transition-all lg:hidden"><Menu size={18}/></button>
            <div className="flex items-center gap-4 ml-auto">
               <div className="hidden sm:flex items-center gap-2 px-3 py-1 bg-indigo-50 text-indigo-600 rounded-full border border-indigo-100 shadow-sm"><Zap size={10} fill="currentColor"/><span className="text-[8px] font-black uppercase tracking-widest italic">Sincronização Ativa</span></div>
               <div className="relative">
                 <button onClick={() => setShowNotificationsDropdown(!showNotificationsDropdown)} className={`relative p-2 transition-all rounded-lg ${notifications.length > 0 ? 'text-indigo-600 bg-indigo-50' : 'text-slate-300 hover:text-indigo-600'}`}>
                    <Bell size={18}/>
                    {notifications.length > 0 && <div className="absolute top-2 right-2 w-1.5 h-1.5 bg-rose-500 rounded-full border-2 border-white animate-pulse"></div>}
                 </button>
                 {showNotificationsDropdown && (
                   <div className="absolute top-12 right-0 w-80 bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden animate-in slide-in-from-top-2">
                      <div className="p-4 bg-slate-50 border-b border-slate-100"><h4 className="text-[10px] font-black uppercase text-indigo-600 tracking-widest italic">Central de Avisos</h4></div>
                      <div className="max-h-64 overflow-y-auto custom-scrollbar">
                         {notifications.length === 0 ? (
                           <p className="p-6 text-center text-[10px] text-slate-400 italic">Nenhuma notificação.</p>
                         ) : notifications.map((n, i) => (
                           <div key={i} className="p-4 border-b border-slate-50 hover:bg-indigo-50 transition-colors flex gap-3">
                              <div className={`p-2 rounded-lg h-fit ${n.type === 'live' ? 'bg-rose-50 text-rose-600' : 'bg-indigo-50 text-indigo-600'}`}>
                                 {n.type === 'live' ? <Video size={14}/> : <Bell size={14}/>}
                              </div>
                              <div>
                                 <p className="text-[10px] font-black uppercase text-slate-800 leading-tight">{n.title}</p>
                                 <p className="text-[10px] text-slate-500 mt-1 italic leading-tight">{n.desc}</p>
                                 <p className="text-[8px] text-slate-400 mt-2 font-mono">{n.time}</p>
                              </div>
                           </div>
                         ))}
                      </div>
                   </div>
                 )}
               </div>
            </div>
         </header>

         {/* MAIN CONTENT SWAP */}
         <main className="flex-1 overflow-y-auto p-6 md:p-8 bg-slate-50 custom-scrollbar">
            {activeSubView === 'classroom' && selectedClassroomCourse && activeItem ? (
              <div className="h-full flex flex-col md:flex-row gap-6 animate-in zoom-in-95">
                 <div className="flex-1 flex flex-col h-full overflow-hidden">
                    <div className="flex items-center justify-between mb-4">
                       <div>
                          <h2 className="text-xl font-black uppercase italic text-slate-900 tracking-tighter leading-none">{activeItem.title}</h2>
                          <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">Módulo: {activeItem.moduleTitle}</p>
                       </div>
                       <button onClick={() => { setActiveSubView('dashboard'); setSelectedClassroomCourse(null); }} className="px-6 py-2.5 bg-slate-200 text-slate-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-500 hover:text-white transition-all shadow-sm">Sair da Sala</button>
                    </div>

                    <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-xl overflow-hidden relative">
                       {activeItem.type === 'lesson' ? (
                         <div className="h-full flex flex-col">
                            <div className="w-full bg-black aspect-video flex-shrink-0">
                               <SecureVideoPlayer 
                                 videoUrl={activeItem.data.videoUrl} 
                                 title={activeItem.title}
                                 onComplete={() => markItemComplete(activeItem.id)}
                               />
                            </div>
                            <div className="flex-1 p-8 overflow-y-auto custom-scrollbar">
                               <h3 className="text-sm font-black uppercase text-indigo-600 tracking-widest mb-4 border-b border-slate-100 pb-2">Material de Apoio & Descrição</h3>
                               <p className="text-sm text-slate-600 leading-relaxed font-medium italic mb-6">{activeItem.data.description || 'Sem descrição.'}</p>
                               {activeItem.data.materialUrl && (
                                 <a href={activeItem.data.materialUrl} target="_blank" className="inline-flex items-center gap-3 px-6 py-4 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold text-slate-700 hover:bg-indigo-50 hover:text-indigo-600 hover:border-indigo-200 transition-all shadow-sm">
                                    <FileText size={18}/> Baixar Material Complementar
                                 </a>
                               )}
                            </div>
                         </div>
                       ) : activeItem.type === 'exam' ? (
                         <div className="h-full overflow-y-auto custom-scrollbar p-8">
                            <QuizPlayer 
                              exam={activeItem.data}
                              onPass={(score) => markItemComplete(activeItem.id, score)}
                            />
                         </div>
                       ) : (
                         <div className="h-full flex items-center justify-center text-slate-300">Item desconhecido</div>
                       )}
                    </div>
                 </div>

                 {/* TIMELINE SIDEBAR */}
                 <div className="w-full md:w-80 bg-white rounded-[2rem] border border-slate-200 shadow-lg overflow-hidden flex flex-col h-full">
                    <div className="p-6 bg-slate-50 border-b border-slate-100 shrink-0">
                       <h3 className="text-xs font-black uppercase italic text-slate-800 tracking-widest flex items-center gap-2"><BookOpen size={14} className="text-indigo-600"/> Cronograma</h3>
                    </div>
                    <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
                       {timeline.map((item, idx) => (
                         <div 
                           key={item.id} 
                           onClick={() => !item.isLocked && setActiveTimelineIndex(idx)}
                           className={`p-4 rounded-2xl border transition-all relative overflow-hidden group ${
                             activeTimelineIndex === idx 
                               ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg scale-[1.02]' 
                               : item.isLocked 
                                 ? 'bg-slate-50 border-slate-100 opacity-60 cursor-not-allowed grayscale' 
                                 : 'bg-white border-slate-100 hover:border-indigo-200 cursor-pointer'
                           }`}
                         >
                            <div className="flex justify-between items-start mb-2">
                               <span className={`text-[8px] font-black uppercase tracking-widest px-2 py-1 rounded-md ${activeTimelineIndex === idx ? 'bg-white/20' : 'bg-slate-100 text-slate-500'}`}>
                                 {item.type === 'lesson' ? 'Aula' : 'Exame'}
                               </span>
                               {item.isCompleted ? (
                                 <CheckCircle2 size={16} className={activeTimelineIndex === idx ? 'text-white' : 'text-emerald-500'} />
                               ) : item.isLocked ? (
                                 <Lock size={14} className="text-slate-400" />
                               ) : (
                                 <PlayCircle size={14} className={activeTimelineIndex === idx ? 'text-white' : 'text-indigo-400'} />
                               )}
                            </div>
                            <p className={`text-[10px] font-bold leading-tight ${activeTimelineIndex === idx ? 'text-white' : 'text-slate-700'}`}>{item.title}</p>

                            {/* Connector Line Logic (Visual only) */}
                            {idx < timeline.length - 1 && (
                              <div className={`absolute bottom-0 left-1/2 w-px h-2 ${item.isCompleted ? 'bg-emerald-200' : 'bg-slate-100'}`}></div>
                            )}
                         </div>
                       ))}
                    </div>
                 </div>
              </div>
            ) : activeSubView === 'classroom' && !selectedClassroomCourse ? (
               <div className="h-full flex items-center justify-center"><p>Selecione um curso para começar.</p></div>
            ) : (
              // Re-render Dashboard/Library/Etc logic here (Collapsing existing logic into unified view render)
              <>
              {(activeSubView === 'dashboard' || activeSubView === 'library') && (
                <div className="max-w-7xl mx-auto space-y-8 animate-in fade-in duration-700">
                   <div className="flex flex-col md:flex-row gap-8">
                      <div className="flex-1 space-y-8">
                         <div className="space-y-2">
                            <h1 className="text-4xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Meus Cursos</h1>
                            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.4em] italic">Jornada Acadêmica</p>
                         </div>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {enrolledCourses.map(course => (
                              <div key={course.id} className="bg-white rounded-3xl border border-slate-200 shadow-lg overflow-hidden flex flex-col group hover:border-indigo-300 transition-all">
                                 <div className="h-40 overflow-hidden relative">
                                    <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                                    <div className="absolute top-4 right-4 px-3 py-1 bg-white/90 backdrop-blur rounded-full text-[8px] font-black uppercase tracking-widest text-indigo-600 shadow-sm">{course.categoria}</div>
                                 </div>
                                 <div className="p-6 flex flex-col flex-1 space-y-4">
                                    <div>
                                       <h3 className="text-lg font-black text-slate-900 uppercase italic tracking-tighter leading-tight">{course.nome}</h3>
                                       <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wide mt-1">Prof. {course.professorResponsavel}</p>
                                    </div>
                                    <button 
                                      onClick={() => enterClassroom(course)} 
                                      className="w-full mt-auto py-3 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase italic tracking-[0.2em] shadow-lg hover:bg-indigo-600 transition-all flex items-center justify-center gap-2 active:scale-95"
                                    >
                                       <PlayCircle size={14}/> Ingressar na Sala
                                    </button>
                                 </div>
                              </div>
                            ))}
                         </div>
                      </div>
