// Global declaration for YouTube Iframe API
declare global {
  interface Window {
    YT: any;
    onYouTubeIframeAPIReady: () => void;
  }
}

// --- SECURE VIDEO PLAYER COMPONENT ---
interface SecureVideoPlayerProps {
  videoUrl: string;
  onComplete: () => void;
  title: string;
}

const SecureVideoPlayer: React.FC<SecureVideoPlayerProps> = ({ videoUrl, onComplete, title }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState(100);
  const [isMuted, setIsMuted] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const iframeRef = useRef<HTMLIFrameElement>(null);
  // We use a ref to store the YouTube player instance if we were using the full API, 
  // but for a lightweight strict implementation without external script loading issues in this environment,
  // we will use the iframe API postMessage method or standard embedding.

  // Extract Video ID
  const getVideoId = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };
  const videoId = getVideoId(videoUrl);

  // Initial load
  useEffect(() => {
    // Reset state on new video
    setIsPlaying(false);
  }, [videoId]);

  // Simulated "End of Video" detection
  // Since we can't easily use the full YT API object in this specific react-lite setup without external script loaders,
  // we will use a time-based approximation or assume the user watches it if they don't navigate away.
  // HOWEVER, the prompt asks for strict completion.
  // We will simulate the "Check for completion" by requiring the video to be "played" for a certain duration or
  // ideally, we load the YT Iframe API. Let's try to load the API dynamically for 'onStateChange'.

  useEffect(() => {
    if (!window.YT) {
      const tag = document.createElement('script');
      tag.src = "https://www.youtube.com/iframe_api";
      const firstScriptTag = document.getElementsByTagName('script')[0];
      firstScriptTag.parentNode?.insertBefore(tag, firstScriptTag);
    }

    let player: any;

    window.onYouTubeIframeAPIReady = () => {
      loadPlayer();
    };

    const loadPlayer = () => {
      if (videoId && window.YT && window.YT.Player) {
        player = new window.YT.Player(`youtube-player-${videoId}`, {
          height: '100%',
          width: '100%',
          videoId: videoId,
          playerVars: {
            controls: 0, // No controls
            disablekb: 1, // Disable keyboard
            fs: 0, // We handle fullscreen
            modestbranding: 1,
            rel: 0,
            showinfo: 0,
            iv_load_policy: 3
          },
          events: {
            'onStateChange': onPlayerStateChange
          }
        });
      }
    };

    if (window.YT && window.YT.Player) {
      loadPlayer();
    }

    function onPlayerStateChange(event: any) {
      if (event.data == window.YT.PlayerState.PLAYING) {
        setIsPlaying(true);
      }
      if (event.data == window.YT.PlayerState.PAUSED) {
        setIsPlaying(false);
      }
      if (event.data == window.YT.PlayerState.ENDED) {
        setIsPlaying(false);
        onComplete(); // Trigger completion
      }
    }

    return () => {
      if (player && player.destroy) player.destroy();
    };
  }, [videoId]);

  // Custom Controls Handlers - Messaging the iframe directly is tricky without the object.
  // If the API loaded successfully above, we could use `player.playVideo()`.
  // Fallback: The standard iframe `postMessage` method.

  const sendCommand = (func: string, args: any[] = []) => {
    if (!iframeRef.current) return;
    iframeRef.current.contentWindow?.postMessage(JSON.stringify({
      'event': 'command',
      'func': func,
      'args': args
    }), '*');
  };

  const togglePlay = () => {
    if (isPlaying) {
      sendCommand('pauseVideo');
      setIsPlaying(false);
    } else {
      sendCommand('playVideo');
      setIsPlaying(true);
    }
  };

  const toggleMute = () => {
    if (isMuted) {
      sendCommand('unMute');
      setIsMuted(false);
    } else {
      sendCommand('mute');
      setIsMuted(true);
    }
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  return (
    <div ref={containerRef} className="relative w-full aspect-video bg-black rounded-3xl overflow-hidden group shadow-2xl border border-slate-900">
      {/* Interaction Shield - Prevents clicking title/Youtube logo */}
      <div className="absolute inset-0 z-10 pointer-events-none" />

      {/* YouTube Iframe */}
      <div className="w-full h-full pointer-events-none"> {/* Disable pointer events on iframe to force custom controls */}
        <iframe 
          ref={iframeRef}
          id={`youtube-player-${videoId}`}
          className="w-full h-full"
          src={`https://www.youtube.com/embed/${videoId}?enablejsapi=1&controls=0&modestbranding=1&rel=0&showinfo=0&iv_load_policy=3&disablekb=1`}
          allow="autoplay; encrypted-media"
          title={title}
        />
      </div>

      {/* Custom Control Bar */}
      <div className="absolute bottom-0 left-0 right-0 h-20 bg-gradient-to-t from-black/90 to-transparent z-20 flex items-end p-6 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
        <div className="w-full flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={togglePlay} className="text-white hover:text-indigo-400 transition-colors">
              {isPlaying ? <Pause size={24} fill="currentColor" /> : <PlayIcon size={24} fill="currentColor" />}
            </button>

            <div className="flex items-center gap-2 group/vol">
              <button onClick={toggleMute} className="text-white hover:text-indigo-400 transition-colors">
                {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} />}
              </button>
              {/* Fake Volume Slider Visual */}
              <div className="w-0 overflow-hidden group-hover/vol:w-20 transition-all duration-300">
                 <div className="h-1 bg-white/30 rounded-full w-full relative">
                    <div className="h-1 bg-indigo-500 w-3/4 absolute top-0 left-0 rounded-full"></div>
                 </div>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-4">
             {/* Fake Quality Gear */}
             <button className="text-white/70 hover:text-white transition-colors" title="Quality Settings (Auto)">
                <Settings size={20} />
             </button>

             <button onClick={toggleFullscreen} className="text-white hover:text-indigo-400 transition-colors">
                {isFullscreen ? <Minimize size={20} /> : <Maximize size={20} />}
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// --- QUIZ INTERFACE COMPONENT ---
interface QuizPlayerProps {
  exam: Exam;
  onPass: (score: number) => void;
}

const QuizPlayer: React.FC<QuizPlayerProps> = ({ exam, onPass }) => {
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [submitted, setSubmitted] = useState(false);
  const [score, setScore] = useState(0);
  const [passed, setPassed] = useState(false);

  const handleSubmit = () => {
    let correctCount = 0;
    exam.questions.forEach((q, idx) => {
      // Logic relies on Question ID or Index. 
      // Assuming exam.questions are ordered and answers key is question index for simplicity here,
      // or using question ID if available. Let's use Index to be safe if IDs are missing.
      const selected = answers[q.id];
      if (selected === q.correctOption) correctCount++;
    });

    const finalScore = (correctCount / exam.questions.length) * 100;
    setScore(finalScore);
    setSubmitted(true);

    if (finalScore >= (exam.passingGrade || 70)) {
      setPassed(true);
      onPass(finalScore);
    }
  };

  if (submitted) {
    return (
      <div className="flex flex-col items-center justify-center p-12 bg-white rounded-[3rem] border border-slate-200 shadow-xl text-center space-y-6 animate-in zoom-in-95">
        <div className={`w-24 h-24 rounded-full flex items-center justify-center shadow-inner ${passed ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
          {passed ? <Award size={48}/> : <AlertCircle size={48}/>}
        </div>
        <div>
          <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{passed ? 'Aprovado!' : 'Tente Novamente'}</h2>
          <p className="text-slate-500 font-bold mt-2">Sua nota: <span className={passed ? 'text-emerald-600' : 'text-rose-600'}>{score.toFixed(0)}%</span></p>
          <p className="text-[10px] text-slate-400 uppercase tracking-widest mt-1 italic">Mínimo necessário: {exam.passingGrade}%</p>
        </div>
        {passed ? (
          <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 max-w-sm">
            <p className="text-xs text-slate-600 font-medium">Parabéns! Você desbloqueou o próximo módulo da sua jornada acadêmica.</p>
          </div>
        ) : (
          <button 
            onClick={() => { setSubmitted(false); setAnswers({}); }} 
            className="px-8 py-3 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-600 transition-all shadow-lg"
          >
            Refazer Avaliação
          </button>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in max-w-3xl mx-auto pb-20">
      <div className="text-center space-y-2">
        <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">{exam.title}</h2>
        <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-indigo-50 text-indigo-700 rounded-full text-[9px] font-black uppercase tracking-widest border border-indigo-100">
          <Award size={12}/> Avaliação Oficial • Corte: {exam.passingGrade}%
        </div>
      </div>

      <div className="space-y-6">
        {exam.questions.map((q, i) => (
          <div key={q.id} className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
            <div className="flex gap-4 mb-6">
              <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-xs italic shrink-0">{i + 1}</span>
              <p className="text-sm font-bold text-slate-800 leading-relaxed">{q.text}</p>
            </div>
            <div className="space-y-3 pl-12">
              {q.options.map((opt, optIdx) => (
                <label key={optIdx} className={`flex items-center gap-4 p-4 rounded-xl border cursor-pointer transition-all ${answers[q.id] === optIdx ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-slate-50 border-slate-100 text-slate-600 hover:bg-slate-100'}`}>
                  <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center shrink-0 ${answers[q.id] === optIdx ? 'border-white' : 'border-slate-300'}`}>
                    {answers[q.id] === optIdx && <div className="w-2.5 h-2.5 bg-white rounded-full" />}
                  </div>
                  <input 
                    type="radio" 
                    name={q.id} 
                    className="hidden" 
                    checked={answers[q.id] === optIdx} 
                    onChange={() => setAnswers({...answers, [q.id]: optIdx})}
                  />
                  <span className="text-xs font-bold uppercase tracking-wide">{opt}</span>
                </label>
              ))}
            </div>
          </div>
        ))}
      </div>

      <div className="flex justify-end">
        <button 
          onClick={handleSubmit} 
          disabled={Object.keys(answers).length < exam.questions.length}
          className="px-10 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] shadow-xl hover:bg-emerald-600 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center gap-3"
        >
          <CheckCircle2 size={18}/> Enviar Respostas
        </button>
      </div>
    </div>
  );
};

// --- MAIN STUDENT VIEW ---

interface StudentViewProps { user: User; }
type StudentSubView = 'dashboard' | 'classroom' | 'library' | 'certificates' | 'support' | 'profile';

// Types for the Linear Timeline
type TimelineItemType = 'lesson' | 'exam' | 'material';
interface TimelineItem {
  id: string; // Unique ID
  type: TimelineItemType;
  title: string;
  moduleId: string;
  moduleTitle: string;
  data: Lesson | Exam | any; // Specific data
  isLocked: boolean;
  isCompleted: boolean;
  index: number;
}

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');

  // Courses State
  const [enrolledCourses, setEnrolledCourses] = useState<Course[]>([]);
  const [selectedClassroomCourse, setSelectedClassroomCourse] = useState<Course | null>(null);
  const [loading, setLoading] = useState(true);

  // Timeline State
  const [timeline, setTimeline] = useState<TimelineItem[]>([]);
  const [activeTimelineIndex, setActiveTimelineIndex] = useState(0);
  const [studentProgress, setStudentProgress] = useState<Record<string, any>>({});

  // Sidebar & Modals
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showTermsModal, setShowTermsModal] = useState(false);

  // User Data State (Editable)
  const [userData, setUserData] = useState<any>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState<any>({});
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Profile Password State
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passMessage, setPassMessage] = useState('');

  // Contract State
  const [termsAgreed, setTermsAgreed] = useState({ contract: false, terms: false, privacy: false });
  const [studentSignature, setStudentSignature] = useState<string | null>(null);
  const [showSigPad, setShowSigPad] = useState(false);

  // Agenda & Notifications
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [showNotificationsDropdown, setShowNotificationsDropdown] = useState(false);

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      try {
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          const data = userDoc.data();
          setUserData(data);
          setEditForm(data);
          setStudentProgress(data.progress || {});

          if (data.status === 'ativo' && !data.termsAccepted) {
            setShowTermsModal(true);
          }

          let courseIds = data.matriculas || [];
          if (courseIds.length === 0 && (data.cursoInicial || data.cursoId)) {
             courseIds = [data.cursoInicial || data.cursoId];
          }

          if (courseIds.length > 0) {
             const q = query(collection(db, 'cursos'), where('__name__', 'in', courseIds.slice(0, 10)));
             const querySnapshot = await getDocs(q);
             const loadedCourses = querySnapshot.docs.map(d => ({ id: d.id, ...d.data() } as Course));
             setEnrolledCourses(loadedCourses);

             const agendaQuery = query(
                collection(db, 'scheduledClasses'), 
                where('courseId', 'in', courseIds.slice(0, 10)),
                where('date', '>=', new Date())
             );

             const unsubAgenda = onSnapshot(agendaQuery, (snap) => {
                const classes = snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass));
                setScheduledClasses(classes.sort((a,b) => {
                   const dateA = a.date?.seconds ? new Date(a.date.seconds * 1000) : new Date(a.date);
                   const dateB = b.date?.seconds ? new Date(b.date.seconds * 1000) : new Date(b.date);
                   return dateA.getTime() - dateB.getTime();
                }));
             });
          }
        }
      } catch (error) { console.error("Erro sincronização aluno", error); }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  // Build the Linear Timeline when a course is selected
  useEffect(() => {
    if (!selectedClassroomCourse || !userData) return;

    const buildTimeline = async () => {
      // Fetch Modules
      const modQ = query(collection(db, 'modulos'), where('courseId', '==', selectedClassroomCourse.id));
      const modSnap = await getDocs(modQ);
      const modules = modSnap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));

      // Fetch Exams
      const examQ = query(collection(db, 'exams'), where('courseId', '==', selectedClassroomCourse.id));
      const examSnap = await getDocs(examQ);
      const exams = examSnap.docs.map(d => ({ id: d.id, ...d.data() } as Exam));

      const rawTimeline: TimelineItem[] = [];
      let globalIndex = 0;

      modules.forEach(mod => {
        // Add Lessons
        mod.lessons?.forEach(lesson => {
          rawTimeline.push({
            id: lesson.id,
            type: 'lesson',
            title: lesson.title,
            moduleId: mod.id,
            moduleTitle: mod.title,
            data: lesson,
            isLocked: true, // Calc later
            isCompleted: false, // Calc later
            index: globalIndex++
          });
        });

        // Add Exams for this module
        exams.filter(e => e.moduleId === mod.id).forEach(exam => {
          rawTimeline.push({
            id: exam.id,
            type: 'exam',
            title: exam.title,
            moduleId: mod.id,
            moduleTitle: mod.title,
            data: exam,
            isLocked: true,
            isCompleted: false,
            index: globalIndex++
          });
        });
      });

      // Calculate Locking Logic based on user progress
      const courseProgress = studentProgress[selectedClassroomCourse.id] || {};

      const processedTimeline = rawTimeline.map((item, idx) => {
        const itemProgress = courseProgress[item.id] || {};
        const isCompleted = itemProgress.completed === true;

        // Locked if previous item is not completed
        // Item 0 is always unlocked.
        let isLocked = false;
        if (idx > 0) {
          const prevItem = rawTimeline[idx - 1];
          const prevProgress = courseProgress[prevItem.id] || {};
          if (!prevProgress.completed) {
            isLocked = true;
          }
        }

        return { ...item, isLocked, isCompleted };
      });

      setTimeline(processedTimeline);

      // Auto-select first unlocked but incomplete item, or last item
      const firstActive = processedTimeline.find(t => !t.isLocked && !t.isCompleted) || processedTimeline[processedTimeline.length - 1];
      if (firstActive) setActiveTimelineIndex(firstActive.index);
    };

    buildTimeline();
  }, [selectedClassroomCourse, studentProgress]); // Re-run when progress updates

  const markItemComplete = async (itemId: string, score?: number) => {
    if (!selectedClassroomCourse) return;

    // Optimistic Update
    const newProgress = {
      ...studentProgress,
      [selectedClassroomCourse.id]: {
        ...(studentProgress[selectedClassroomCourse.id] || {}),
        [itemId]: { completed: true, score }
      }
    };
    setStudentProgress(newProgress); // Triggers timeline rebuild

    // Firestore Update
    await updateDoc(doc(db, 'users', user.uid), {
      [`progress.${selectedClassroomCourse.id}.${itemId}`]: { completed: true, score }
    });
  };

  const enterClassroom = (course: Course) => {
    setSelectedClassroomCourse(course);
    setActiveSubView('classroom');
  };

  const activeItem = timeline[activeTimelineIndex];

  // Effect to update Notifications based on Agenda
  useEffect(() => {
     const newNotifs = [];
     newNotifs.push({
        id: 'sys-welcome',
        title: 'Bem-vindo ao Portal Master',
        desc: 'Sua área do aluno está pronta.',
        type: 'system',
        time: 'Agora'
     });
     scheduledClasses.forEach(c => {
        const cDate = c.date?.seconds ? new Date(c.date.seconds * 1000) : new Date(c.date);
        const courseName = enrolledCourses.find(ec => ec.id === c.courseId)?.nome || 'Curso';
        newNotifs.push({
           id: c.id,
           title: 'Aula Ao Vivo Agendada',
           desc: `${c.title} - ${courseName}`,
           type: 'live',
           time: cDate.toLocaleDateString() + ' ' + cDate.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})
        });
     });
     setNotifications(newNotifs);
  }, [scheduledClasses, enrolledCourses]);

  const handleChangePassword = async () => {
    if (newPassword !== confirmPassword) { setPassMessage('As senhas não coincidem.'); return; }
    if (newPassword.length < 6) { setPassMessage('A senha deve ter no mínimo 6 caracteres.'); return; }
    try {
      if (auth.currentUser) {
        await updatePassword(auth.currentUser, newPassword);
        setPassMessage('Senha atualizada com sucesso!');
        setNewPassword(''); setConfirmPassword('');
      }
    } catch (e: any) { setPassMessage('Erro ao atualizar: ' + e.message); }
  };

  const compressImage = (base64: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_WIDTH = 800;
        const scale = MAX_WIDTH / img.width;
        canvas.width = MAX_WIDTH;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.7));
      };
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const compressed = await compressImage(reader.result as string);
        setEditForm({ ...editForm, photoURL: compressed });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateProfile = async () => {
    try {
      if (!editForm.nome || !editForm.cpf || !editForm.telefone) {
        alert("Preencha os campos obrigatórios (Nome, CPF, Telefone).");
        return;
      }
      await updateDoc(doc(db, 'users', user.uid), {
        ...editForm,
        updatedAt: serverTimestamp()
      });
      setUserData(editForm);
      alert("Dados atualizados com sucesso!");
    } catch (e: any) {
      alert("Erro ao salvar: " + e.message);
    }
  };

  const handleAcceptTerms = async () => {
    if (!termsAgreed.contract || !termsAgreed.terms || !termsAgreed.privacy || !studentSignature) {
      alert("Por favor, aceite todos os termos e assine o contrato.");
      return;
    }
    try {
      await updateDoc(doc(db, 'users', user.uid), {
        termsAccepted: true,
        termsAcceptedAt: serverTimestamp(),
        signatureUrl: studentSignature
      });
      setShowTermsModal(false);
      window.location.reload(); 
    } catch (e) { console.error("Error accepting terms", e); }
  };

  if (loading) return (
    <div className="h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-center gap-6">
       <RefreshCw size={48} className="text-indigo-600 animate-spin" />
       <p className="font-black text-white uppercase italic text-xs tracking-[0.5em]">Carregando Portal...</p>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 flex overflow-hidden font-sans relative">
      {/* SIDEBAR & HEADER */}
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-slate-900/60 z-[60] lg:hidden backdrop-blur-sm"></div>}

      <aside className={`fixed lg:static inset-y-0 left-0 bg-slate-900 w-72 flex flex-col transition-transform duration-300 z-[70] ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
         <div className="p-6 border-b border-white/5 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-indigo-600 text-white rounded-lg shadow-lg"><GraduationCap size={20}/></div>
              <div><p className="font-black text-white uppercase italic text-base leading-none">EB-EAD</p><p className="text-[8px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Portal do Aluno</p></div>
            </div>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden p-2 text-white/50 hover:text-white"><X size={20}/></button>
         </div>
         <nav className="flex-1 p-4 space-y-1 mt-2 overflow-y-auto">
            {[
              { id: 'dashboard', label: 'Home Page', icon: <Home size={16}/> },
              { id: 'library', label: 'Meus Cursos', icon: <BookOpen size={16}/> },
              { id: 'certificates', label: 'Galeria de Diplomas', icon: <Award size={16}/> },
              { id: 'profile', label: 'Meu Perfil', icon: <UserCircle size={16}/> },
              { id: 'support', label: 'Suporte VIP', icon: <LifeBuoy size={16}/> }
            ].map(item => (
              <button 
                key={item.id} 
                onClick={() => { setActiveSubView(item.id as any); setIsSidebarOpen(false); setSelectedClassroomCourse(null); }} 
                disabled={userData?.status !== 'ativo' && item.id !== 'profile'}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  activeSubView === item.id 
                    ? 'bg-indigo-600 text-white shadow-lg' 
                    : 'text-slate-500 hover:text-white hover:bg-white/5 disabled:opacity-50 disabled:cursor-not-allowed'
                }`}
              >
                {item.icon} {item.label}
              </button>
            ))}
         </nav>
         <div className="p-6 border-t border-white/5 bg-black/20">
            <div className="flex items-center gap-3 p-3 bg-white/5 rounded-xl border border-white/5 shadow-inner">
               <div className="w-10 h-10 rounded-lg overflow-hidden bg-indigo-600 flex items-center justify-center text-white font-black italic shadow-lg border border-white/10 shrink-0">
                  {userData?.photoURL || user.photoURL ? <img src={userData?.photoURL || user.photoURL} className="w-full h-full object-cover" /> : (userData?.displayName || user.displayName || 'U').charAt(0)}
               </div>
               <div className="flex-1 overflow-hidden">
                  <p className="text-[10px] font-black text-white uppercase italic truncate">{userData?.nome || userData?.displayName || user.displayName || 'Discente'}</p>
                  <p className="text-[7px] font-bold text-indigo-400 uppercase mt-0.5 tracking-widest leading-none">{userData?.status === 'ativo' ? 'Ativo' : 'Auditoria'}</p>
               </div>
               <button onClick={() => auth.signOut()} className="text-rose-500 p-2 hover:bg-rose-500/10 rounded-lg transition-all"><LogOut size={16}/></button>
            </div>
         </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
         {/* HEADER */}
