import React, { useState, useEffect, useRef, useMemo } from 'react';
import { collection, query, where, onSnapshot, doc, getDoc, updateDoc, serverTimestamp, getDocs, addDoc, orderBy } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { updatePassword } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { auth, db } from '../firebase';
import { Course, User, Module, Lesson, ScheduledClass, Exam, Question } from '../types';
import { 
  BookOpen, PlayCircle, Award, GraduationCap, Zap, Bell, Menu, X, LogOut, 
  Home, LifeBuoy, ShieldAlert, Play, RefreshCw, UserCheck, 
  ChevronRight, Star, UserCircle, MapPin, Mail, Phone, Lock, Save, 
  FileText, Check, PenTool, CheckCircle2, Camera, Calendar, Video, 
  Maximize, Minimize, Settings, Volume2, VolumeX, AlertCircle, Play as PlayIcon, Pause,
  MessageSquare, HelpCircle, Send, ChevronDown, Clock, Search, BarChart3
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

// Global declaration for YouTube Iframe API
declare global {
  interface Window {
    YT: any;
    onYouTubeIframeAPIReady: () => void;
  }
}

// --- SECURE VIDEO PLAYER COMPONENT ---
interface SecureVideoPlayerProps {
  videoUrl: string;
  onComplete: () => void;
  title: string;
}

const SecureVideoPlayer: React.FC<SecureVideoPlayerProps> = ({ videoUrl, onComplete, title }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [volume, setVolume] = useState(100);
  const [isMuted, setIsMuted] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const iframeRef = useRef<HTMLIFrameElement>(null);

  // Extract Video ID
  const getVideoId = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };
  const videoId = getVideoId(videoUrl);

  // Send Command to YouTube Iframe
  const sendCommand = (func: string, args: any[] = []) => {
    if (!iframeRef.current) return;
    iframeRef.current.contentWindow?.postMessage(JSON.stringify({
      'event': 'command',
      'func': func,
      'args': args
    }), '*');
  };

  useEffect(() => {
    setIsPlaying(false);
  }, [videoId]);

  // YouTube API Integration for State Tracking
  useEffect(() => {
    if (!window.YT) {
      const tag = document.createElement('script');
      tag.src = "https://www.youtube.com/iframe_api";
      const firstScriptTag = document.getElementsByTagName('script')[0];
      firstScriptTag.parentNode?.insertBefore(tag, firstScriptTag);
    }

    let player: any;
    window.onYouTubeIframeAPIReady = () => { loadPlayer(); };

    const loadPlayer = () => {
      if (videoId && window.YT && window.YT.Player) {
        player = new window.YT.Player(`youtube-player-${videoId}`, {
          height: '100%',
          width: '100%',
          videoId: videoId,
          playerVars: {
            controls: 0, 
            disablekb: 1, 
            fs: 0, 
            modestbranding: 1,
            rel: 0,
            showinfo: 0,
            iv_load_policy: 3,
            autohide: 1
          },
          events: {
            'onStateChange': onPlayerStateChange,
            'onReady': (event: any) => {
               // Sync volume on load
               event.target.setVolume(volume);
            }
          }
        });
      }
    };

    if (window.YT && window.YT.Player) loadPlayer();

    function onPlayerStateChange(event: any) {
      if (event.data == window.YT.PlayerState.PLAYING) setIsPlaying(true);
      if (event.data == window.YT.PlayerState.PAUSED) setIsPlaying(false);
      if (event.data == window.YT.PlayerState.ENDED) {
        setIsPlaying(false);
        onComplete();
      }
    }

    return () => { if (player && player.destroy) player.destroy(); };
  }, [videoId]);

  const togglePlay = () => {
    if (isPlaying) {
      sendCommand('pauseVideo');
      setIsPlaying(false);
    } else {
      sendCommand('playVideo');
      setIsPlaying(true);
    }
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newVol = parseInt(e.target.value);
    setVolume(newVol);
    if (newVol > 0 && isMuted) setIsMuted(false);
    sendCommand('setVolume', [newVol]);
    if (newVol === 0) sendCommand('mute');
    else sendCommand('unMute');
  };

  const toggleMute = () => {
    if (isMuted) {
      sendCommand('unMute');
      sendCommand('setVolume', [volume]);
      setIsMuted(false);
    } else {
      sendCommand('mute');
      setIsMuted(true);
    }
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  return (
    <div ref={containerRef} className="relative w-full aspect-video bg-black rounded-3xl overflow-hidden group shadow-2xl border border-slate-900 select-none">
      {/* Click Shield for Play/Pause */}
      <div className="absolute inset-0 z-10 cursor-pointer" onClick={togglePlay}>
         {!isPlaying && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-[2px] transition-all">
               <div className="w-20 h-20 bg-white/20 rounded-full flex items-center justify-center backdrop-blur-md border border-white/30 shadow-2xl scale-100 hover:scale-110 transition-transform">
                  <PlayIcon size={40} className="text-white fill-white ml-1" />
               </div>
            </div>
         )}
      </div>

      {/* YouTube Iframe - Pointer Events None to force custom controls */}
      <div className="w-full h-full pointer-events-none relative z-0"> 
        <iframe 
          ref={iframeRef}
          id={`youtube-player-${videoId}`}
          className="w-full h-full"
          src={`https://www.youtube.com/embed/${videoId}?enablejsapi=1&controls=0&modestbranding=1&rel=0&showinfo=0&iv_load_policy=3&disablekb=1&playsinline=1`}
          allow="autoplay; encrypted-media"
          title={title}
        />
      </div>

      {/* Custom Control Bar */}
      <div className="absolute bottom-0 left-0 right-0 h-24 bg-gradient-to-t from-black/90 via-black/60 to-transparent z-20 flex items-end p-6 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
        <div className="w-full flex items-center justify-between pointer-events-auto">
          <div className="flex items-center gap-6">
            <button onClick={(e) => { e.stopPropagation(); togglePlay(); }} className="text-white hover:text-indigo-400 transition-colors">
              {isPlaying ? <Pause size={28} fill="currentColor" /> : <PlayIcon size={28} fill="currentColor" />}
            </button>

            <div className="flex items-center gap-3 group/vol">
              <button onClick={(e) => { e.stopPropagation(); toggleMute(); }} className="text-white hover:text-indigo-400 transition-colors">
                {isMuted || volume === 0 ? <VolumeX size={24} /> : <Volume2 size={24} />}
              </button>
              <input 
                type="range" 
                min="0" 
                max="100" 
                value={isMuted ? 0 : volume} 
                onChange={handleVolumeChange}
                onClick={(e) => e.stopPropagation()}
                className="w-24 h-1.5 bg-white/30 rounded-lg appearance-none cursor-pointer hover:bg-white/50 accent-indigo-500"
              />
            </div>
          </div>

          <div className="flex items-center gap-4">
             {/* Visual Quality Gear (Functionality limited by YT Embed API restrictions) */}
             <button className="text-white/70 hover:text-white transition-colors group/set relative" title="Quality: Auto (HD)">
                <Settings size={24} />
                <span className="absolute bottom-8 left-1/2 -translate-x-1/2 bg-black/80 text-white text-[9px] px-2 py-1 rounded opacity-0 group-hover/set:opacity-100 transition-opacity whitespace-nowrap">Auto HD</span>
             </button>

             <button onClick={(e) => { e.stopPropagation(); toggleFullscreen(); }} className="text-white hover:text-indigo-400 transition-colors">
                {isFullscreen ? <Minimize size={24} /> : <Maximize size={24} />}
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// --- QUIZ COMPONENT ---
interface QuizPlayerProps { exam: Exam; onPass: (score: number) => void; }
const QuizPlayer: React.FC<QuizPlayerProps> = ({ exam, onPass }) => {
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [submitted, setSubmitted] = useState(false);
  const [score, setScore] = useState(0);
  const [passed, setPassed] = useState(false);

  const handleSubmit = () => {
    let correctCount = 0;
    exam.questions.forEach((q) => {
      if (answers[q.id] === q.correctOption) correctCount++;
    });
    const finalScore = (correctCount / exam.questions.length) * 100;
    setScore(finalScore);
    setSubmitted(true);
    if (finalScore >= (exam.passingGrade || 70)) {
      setPassed(true);
      onPass(finalScore);
    }
  };

  if (submitted) {
    return (
      <div className="flex flex-col items-center justify-center p-12 bg-white rounded-[3rem] border border-slate-200 shadow-xl text-center space-y-6 animate-in zoom-in-95">
        <div className={`w-24 h-24 rounded-full flex items-center justify-center shadow-inner ${passed ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
          {passed ? <Award size={48}/> : <AlertCircle size={48}/>}
        </div>
        <div>
          <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{passed ? 'Aprovado!' : 'Tente Novamente'}</h2>
          <p className="text-slate-500 font-bold mt-2">Sua nota: <span className={passed ? 'text-emerald-600' : 'text-rose-600'}>{score.toFixed(0)}%</span></p>
          <p className="text-[10px] text-slate-400 uppercase tracking-widest mt-1 italic">Mínimo necessário: {exam.passingGrade}%</p>
        </div>
        {!passed && (
          <button onClick={() => { setSubmitted(false); setAnswers({}); }} className="px-8 py-3 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-600 transition-all shadow-lg">Refazer Avaliação</button>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-8 pb-20">
      <div className="text-center space-y-2">
        <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">{exam.title}</h2>
        <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-indigo-50 text-indigo-700 rounded-full text-[9px] font-black uppercase tracking-widest border border-indigo-100"><Award size={12}/> Mínimo: {exam.passingGrade}%</div>
      </div>
      <div className="space-y-6">
        {exam.questions.map((q, i) => (
          <div key={q.id} className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm">
            <div className="flex gap-4 mb-6">
              <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-xs italic shrink-0">{i + 1}</span>
              <p className="text-sm font-bold text-slate-800 leading-relaxed">{q.text}</p>
            </div>
            <div className="space-y-3 pl-12">
              {q.options.map((opt, optIdx) => (
                <label key={optIdx} className={`flex items-center gap-4 p-4 rounded-xl border cursor-pointer transition-all ${answers[q.id] === optIdx ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-slate-50 border-slate-100 text-slate-600 hover:bg-slate-100'}`}>
                  <input type="radio" name={q.id} className="hidden" checked={answers[q.id] === optIdx} onChange={() => setAnswers({...answers, [q.id]: optIdx})} />
                  <span className="text-xs font-bold uppercase tracking-wide">{opt}</span>
                </label>
              ))}
            </div>
          </div>
        ))}
      </div>
      <div className="flex justify-end"><button onClick={handleSubmit} disabled={Object.keys(answers).length < exam.questions.length} className="px-10 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] shadow-xl hover:bg-emerald-600 disabled:opacity-50 disabled:cursor-not-allowed transition-all">Enviar Respostas</button></div>
    </div>
  );
};

