        )}
      </div>

      {isNewTicketModal && (
        <div className="fixed inset-0 z-[6000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
           <div className="bg-white w-full max-w-lg rounded-[2.5rem] p-8 shadow-2xl animate-in zoom-in-95">
              <h3 className="text-xl font-black text-slate-900 uppercase italic mb-6">Nova Solicitação</h3>
              <textarea value={newTicketSubject} onChange={e => setNewTicketSubject(e.target.value)} className="w-full h-32 bg-slate-50 border border-slate-100 rounded-2xl p-4 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-600 resize-none mb-6" placeholder="Descreva seu problema ou solicitação detalhadamente..." />
