        </div>
      )}
    </div>
  );
};

// --- MAIN VIEW ---
const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [enrolledCourses, setEnrolledCourses] = useState<Course[]>([]);
  const [selectedClassroomCourse, setSelectedClassroomCourse] = useState<Course | null>(null);
  const [timelineModules, setTimelineModules] = useState<{module: Module, items: TimelineItem[]}[]>([]);
  const [activeTimelineItem, setActiveTimelineItem] = useState<TimelineItem | null>(null);
  const [studentProgress, setStudentProgress] = useState<Record<string, any>>({});
  const [loading, setLoading] = useState(true);

  // Profile & System
  const [userData, setUserData] = useState<any>(null);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showTermsModal, setShowTermsModal] = useState(false);
  const [termsAgreed, setTermsAgreed] = useState({ contract: false, terms: false, privacy: false });
  const [studentSignature, setStudentSignature] = useState<string | null>(null);
  const [showNotificationsDropdown, setShowNotificationsDropdown] = useState(false);
  const [editForm, setEditForm] = useState<any>({});
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passMessage, setPassMessage] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const enterClassroom = (course: Course) => {
    setSelectedClassroomCourse(course);
    setActiveSubView('classroom');
  };

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      try {
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          const data = userDoc.data();
          setUserData(data);
          setEditForm(data);
          setStudentProgress(data.progress || {});

          if (data.status === 'ativo' && !data.termsAccepted) setShowTermsModal(true);

          let courseIds = data.matriculas || [];
          if (courseIds.length === 0 && (data.cursoInicial || data.cursoId)) courseIds = [data.cursoInicial || data.cursoId];

          if (courseIds.length > 0) {
             const q = query(collection(db, 'cursos'), where('__name__', 'in', courseIds.slice(0, 10)));
             const querySnapshot = await getDocs(q);
             const loadedCourses = querySnapshot.docs.map(d => ({ id: d.id, ...d.data() } as Course));
             setEnrolledCourses(loadedCourses);

             const agendaQuery = query(collection(db, 'scheduledClasses'), where('courseId', 'in', courseIds.slice(0, 10)), where('date', '>=', new Date()));
             onSnapshot(agendaQuery, (snap) => {
                const classes = snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass));
                setScheduledClasses(classes.sort((a,b) => {
                   const dateA = a.date?.seconds ? new Date(a.date.seconds * 1000) : new Date(a.date);
                   const dateB = b.date?.seconds ? new Date(b.date.seconds * 1000) : new Date(b.date);
                   return dateA.getTime() - dateB.getTime();
                }));
             });
          }
        }
      } catch (error) { console.error("Sync Error", error); }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  // HIERARCHICAL TIMELINE BUILDER
  useEffect(() => {
    if (!selectedClassroomCourse || !userData) return;

    const buildTimeline = async () => {
      // 1. Get Modules sorted by Order
      const modQ = query(collection(db, 'modulos'), where('courseId', '==', selectedClassroomCourse.id));
      const modSnap = await getDocs(modQ);
      const modules = modSnap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));

      // 2. Get Exams
      const examQ = query(collection(db, 'exams'), where('courseId', '==', selectedClassroomCourse.id));
      const examSnap = await getDocs(examQ);
      const exams = examSnap.docs.map(d => ({ id: d.id, ...d.data() } as Exam));

      const structuredTimeline: {module: Module, items: TimelineItem[]}[] = [];
      let globalIndex = 0;
      let previousCompleted = true; // First item is always unlocked

      modules.forEach(mod => {
        const moduleItems: TimelineItem[] = [];

        // Sort lessons by order
        const lessons = (mod.lessons || []).sort((a,b) => (a.order||0)-(b.order||0));

        lessons.forEach(lesson => {
          const itemProgress = studentProgress[selectedClassroomCourse.id]?.[lesson.id] || {};
          const isCompleted = itemProgress.completed === true;
          const isLocked = !previousCompleted;

          moduleItems.push({
            id: lesson.id,
            type: 'lesson',
            title: lesson.title,
            moduleId: mod.id,
            moduleTitle: mod.title,
            data: lesson,
            isLocked,
            isCompleted,
            index: globalIndex++
          });
          previousCompleted = isCompleted;
        });

        exams.filter(e => e.moduleId === mod.id).forEach(exam => {
          const itemProgress = studentProgress[selectedClassroomCourse.id]?.[exam.id] || {};
          const isCompleted = itemProgress.completed === true;
          const isLocked = !previousCompleted;

          moduleItems.push({
            id: exam.id,
            type: 'exam',
            title: exam.title,
            moduleId: mod.id,
            moduleTitle: mod.title,
            data: exam,
            isLocked,
            isCompleted,
            index: globalIndex++
          });
          previousCompleted = isCompleted;
        });

        if (moduleItems.length > 0) {
          structuredTimeline.push({ module: mod, items: moduleItems });
        }
      });

      setTimelineModules(structuredTimeline);

      // Auto-select first unlocked incomplete item, or continue where left off
      if (!activeTimelineItem) {
        let firstActive: TimelineItem | null = null;
        for (const group of structuredTimeline) {
          for (const item of group.items) {
            if (!item.isLocked && !item.isCompleted) {
              firstActive = item;
              break;
            }
          }
          if (firstActive) break;
        }
        if (firstActive) setActiveTimelineItem(firstActive);
        else if (structuredTimeline.length > 0 && structuredTimeline[0].items.length > 0) setActiveTimelineItem(structuredTimeline[0].items[0]);
      }
    };

    buildTimeline();
  }, [selectedClassroomCourse, studentProgress]);

  const markItemComplete = async (itemId: string, score?: number) => {
    if (!selectedClassroomCourse) return;
    const newProgress = {
      ...studentProgress,
      [selectedClassroomCourse.id]: {
        ...(studentProgress[selectedClassroomCourse.id] || {}),
        [itemId]: { completed: true, score }
      }
    };
    setStudentProgress(newProgress);
    await updateDoc(doc(db, 'users', user.uid), {
      [`progress.${selectedClassroomCourse.id}.${itemId}`]: { completed: true, score }
    });
  };

  const handleUpdateProfile = async () => {
    try {
      await updateDoc(doc(db, 'users', user.uid), { ...editForm, updatedAt: serverTimestamp() });
      setUserData(editForm);
      alert("Perfil atualizado!");
    } catch (e: any) { alert("Erro: " + e.message); }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const img = new Image();
        img.src = reader.result as string;
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const scale = 800 / img.width;
          canvas.width = 800;
          canvas.height = img.height * scale;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
          setEditForm({ ...editForm, photoURL: canvas.toDataURL('image/jpeg', 0.7) });
        };
      };
      reader.readAsDataURL(file);
    }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-slate-50"><RefreshCw className="animate-spin text-indigo-600"/></div>;

  return (
