                            </div>

                            {/* DESCRIPTION SECTION - Scrollable independent of video */}
                            <div className="flex-1 overflow-y-auto custom-scrollbar p-8 bg-white relative z-10">
                               <div className="flex flex-col md:flex-row justify-between items-start border-b border-slate-100 pb-6 mb-6 gap-4">
                                  <div>
                                    <h3 className="text-sm font-black uppercase text-indigo-600 tracking-widest">Material de Apoio</h3>
                                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-wide mt-1">Recursos da Aula</p>
                                  </div>
                                  {activeTimelineItem.data.materialUrl && (
                                    <a 
