                                      onClick={(e) => !activeTimelineItem.isCompleted && e.preventDefault()}
                                    >
                                       <FileText size={16}/> {activeTimelineItem.isCompleted ? 'Baixar Arquivo' : 'Conclua a aula para liberar'}
