                 </div>

                 {/* HIERARCHICAL SIDEBAR TIMELINE */}
                 <div className="w-full md:w-80 lg:w-96 bg-white rounded-[2rem] border border-slate-200 shadow-lg overflow-hidden flex flex-col h-full shrink-0">
                    <div className="p-6 bg-slate-50 border-b border-slate-100 shrink-0">
                       <h3 className="text-xs font-black uppercase italic text-slate-800 tracking-widest flex items-center gap-2"><BookOpen size={14} className="text-indigo-600"/> Cronograma Completo</h3>
                    </div>
                    <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
                       {timelineModules.map((group, gIdx) => (
                         <div key={group.module.id} className="relative">
                            {/* Module Header */}
                            <div className="sticky top-0 z-10 bg-white pb-2 pt-1 border-b border-slate-50 mb-2">
