                                       ? 'bg-indigo-600 text-white border-indigo-600 shadow-md scale-[1.02]' 
                                       : item.isLocked 
                                         ? 'bg-slate-50/50 text-slate-300 border-transparent cursor-not-allowed grayscale' 
                                         : 'bg-white text-slate-600 border-transparent hover:bg-slate-50 hover:border-slate-100'
                                   }`}
                                 >
                                    <div className={`p-1.5 rounded-lg shrink-0 ${activeTimelineItem.id === item.id ? 'bg-white/20 text-white' : item.isCompleted ? 'bg-emerald-100 text-emerald-600' : item.isLocked ? 'bg-slate-100 text-slate-300' : 'bg-slate-100 text-slate-400'}`}>
