                                       <p className={`text-[8px] font-medium uppercase tracking-widest mt-0.5 ${activeTimelineItem.id === item.id ? 'text-indigo-200' : 'text-slate-400'}`}>{item.type === 'lesson' ? 'Videoaula' : 'Avaliação'}</p>
