          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
             {tickets.filter(t => chatFilter === 'abertos' ? (t.status !== 'Finalizado' && t.status !== 'Arquivado') : (t.status === 'Finalizado' || t.status === 'Arquivado')).map(t => (
