                       {m.text}
                    </div>
                    <span className="text-[8px] font-bold text-slate-300 mt-1 uppercase px-2">{m.sender} • {m.createdAt?.seconds ? new Date(m.createdAt.seconds * 1000).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '...'}</span>
                 </div>
