            ) : activeSubView === 'classroom' && !selectedClassroomCourse ? (
               <div className="h-full flex items-center justify-center"><p>Selecione um curso para começar.</p></div>
            ) : (
              // NON-CLASSROOM VIEWS
              <>
              {(activeSubView === 'dashboard' || activeSubView === 'library') && (
                <div className="max-w-7xl mx-auto space-y-8 animate-in fade-in duration-700">
                   <div className="flex flex-col md:flex-row gap-8">
                      <div className="flex-1 space-y-8">
