                            <input value={editForm.endereco?.rua || ''} readOnly className="w-full p-3 bg-slate-100 border border-slate-100 rounded-xl text-xs font-bold text-slate-500 cursor-not-allowed" />
                         </div>
                         <div className="grid grid-cols-3 gap-2">
                             <div className="col-span-1 space-y-2">
                                <label className="text-[8px] font-black uppercase text-slate-400 tracking-widest">Número</label>
                                <input value={editForm.endereco?.numero || ''} onChange={e => setEditForm({...editForm, endereco: {...editForm.endereco, numero: e.target.value}})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold" />
                             </div>
                             <div className="col-span-2 space-y-2">
                                <label className="text-[8px] font-black uppercase text-slate-400 tracking-widest">Bairro</label>
                                <input value={editForm.endereco?.bairro || ''} readOnly className="w-full p-3 bg-slate-100 border border-slate-100 rounded-xl text-xs font-bold text-slate-500 cursor-not-allowed" />
