              {/* Certificates View (Filtered) */}
              {activeSubView === 'certificates' && (
                 <div className="space-y-6 animate-in fade-in">
                    <h2 className="text-2xl font-black uppercase italic text-slate-900 tracking-tighter">Galeria de Diplomas</h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                       {enrolledCourses.map(course => {
                          // Calculate real progress
                          const totalItems = 20; // This should ideally be calculated from timeline length
                          const completedItems = Object.keys(studentProgress[course.id] || {}).filter(k => studentProgress[course.id][k].completed).length;
                          // For demo, if mock total isn't reached, show locked.
                          // In real app, calculate true total from modules/lessons query.
                          // Assuming if we have data it's in progress.
                          const isComplete = completedItems >= totalItems; 

                          if (!isComplete) return null; // Only show completed diplomas

                          return (
                             <div key={course.id} className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm flex flex-col items-center text-center space-y-4 cursor-pointer hover:shadow-xl transition-all border-emerald-100 bg-emerald-50/10">
                                <Award size={40} className="text-emerald-500"/>
                                <div>
                                   <h4 className="font-black text-slate-900 uppercase italic">{course.nome}</h4>
                                   <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Concluído</p>
                                </div>
                                <span className="px-3 py-1 bg-emerald-100 rounded-lg text-[8px] font-black uppercase text-emerald-600">Certificado Disponível</span>
                             </div>
                          );
                       })}
                       {/* Placeholder if empty */}
                       {enrolledCourses.length > 0 && <div className="col-span-full text-center py-10 text-slate-300 text-xs italic">Complete seus cursos para desbloquear os diplomas.</div>}
                    </div>
                 </div>
              )}

              {/* Support View */}
              {activeSubView === 'support' && (
                <div className="h-full animate-in fade-in">
                   <SupportSystem user={user} />
                </div>
              )}
              </>
            )}
         </main>
      </div>
    </div>
  );
};

export default StudentView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, addDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, Clock, MessageSquare, Search, X, FileText, UserCheck, ShieldAlert, UserX, Check, ArrowRightLeft, Fingerprint, Send, Archive, ChevronRight, Eye, Phone, CreditCard, Printer, RefreshCw, BookOpen, ShieldCheck, MessageCircle, AlertTriangle, AlertCircle, Timer, User as UserIcon
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'assinatura';
type ChatFilter = 'aguardando' | 'andamento' | 'historico'; 

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('aguardando');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  // Modals
  const [viewingStudent, setViewingStudent] = useState<any | null>(null);
  const [viewingTicketDetails, setViewingTicketDetails] = useState<any | null>(null);
  const [transferenciaData, setTransferenciaData] = useState({ alunoUid: '', novoCursoId: '' });

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Removed orderBy to prevent index errors in dev, sorting client side
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        // Sort by creation date descending
        t.sort((a:any, b:any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0));
        setTickets(t);
    });
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => {
      setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() })));
    });
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  // Sync chat messages with Firestore
  useEffect(() => {
    if (!selectedTicketId) {
      setChatHistory([]);
      return;
    }
    const q = query(collection(db, 'tickets', selectedTicketId, 'messages'), orderBy('createdAt', 'asc'));
    const unsubMessages = onSnapshot(q, (snap) => {
      setChatHistory(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsubMessages();
  }, [selectedTicketId]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory]);

  const getMissingFields = (s: any) => {
    const missing = [];
    if (!s.cpf) missing.push("CPF");
    if (!s.photoURL) missing.push("Foto");
    if (!s.endereco?.cep) missing.push("Endereço");
    if (!s.nascimento) missing.push("Nascimento");
    if (!s.telefone) missing.push("WhatsApp");
    if (!s.termsAccepted) missing.push("Contrato");
    return missing;
  };

  const getTicketStatus = (ticket: any) => {
    if (ticket.status === 'Arquivado') return { label: 'Arquivado', color: 'bg-slate-100 text-slate-500' };
    if (ticket.status === 'Finalizado') return { label: 'Finalizado', color: 'bg-slate-100 text-slate-500' };

    // Time Logic
    const created = ticket.createdAt?.seconds ? new Date(ticket.createdAt.seconds * 1000) : new Date();
    const diffMins = (new Date().getTime() - created.getTime()) / 60000;

    if (ticket.status === 'Em Atendimento') return { label: 'Em Andamento', color: 'bg-indigo-50 text-indigo-600' };
    if (ticket.status === 'Resolvido') return { label: 'Pesquisa Pendente', color: 'bg-emerald-50 text-emerald-600' };
    if (diffMins > 5 && ticket.status === 'Pendente') return { label: 'Atrasado (Prioridade)', color: 'bg-rose-50 text-rose-600 animate-pulse' };

    return { label: 'Pendente', color: 'bg-amber-50 text-amber-600' };
  };

  const stats = useMemo(() => {
    const pendingVal = students.filter(s => 
      s.status === 'aguardando_validacao' || 
      s.status === 'pendente' || 
      getMissingFields(s).length > 0
    ).length;

    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado' || t.status === 'Resolvido').length,
      arquivados: tickets.filter(t => t.status === 'Arquivado').length,
      pendentesVal: pendingVal,
      totalGed: files.length
    };
  }, [tickets, students, files]);

  const handleNotifyWhatsApp = (s: any) => {
    const missing = getMissingFields(s);
    const phone = s.telefone?.replace(/\D/g, '');
    const message = `Olá ${s.displayName}, aqui é da Secretaria Master EB-AD. Para liberar seu acesso completo e emissão de diplomas, precisamos regularizar: ${missing.join(', ')}. Por favor, acesse o portal e atualize seu perfil.`;
    window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`, '_blank');
  };

  const handleSendMessage = async () => {
    if (!chatMessage.trim() || !selectedTicketId) return;
    const messageData = { text: chatMessage, sender: 'Secretaria', senderId: user.uid, createdAt: serverTimestamp() };
    try {
      await addDoc(collection(db, 'tickets', selectedTicketId, 'messages'), messageData);
      await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, updatedAt: serverTimestamp() });
      setChatMessage('');
    } catch (error) { console.error("Erro msg", error); }
  };

  const assumirAtendimento = async (ticketId: string) => {
    await updateDoc(doc(db, 'tickets', ticketId), {
      status: 'Em Atendimento',
      attendantId: user.uid,
      startedAt: serverTimestamp()
    });
    // System message
    await addDoc(collection(db, 'tickets', ticketId, 'messages'), {
      text: `Olá, sou ${user.displayName}. Assumi seu atendimento e darei continuidade.`,
      sender: 'Sistema',
      createdAt: serverTimestamp()
    });
  };

  const finalizarAtendimento = async (ticketId: string) => {
    if(!confirm("Finalizar atendimento? O aluno receberá a pesquisa de satisfação.")) return;
    await updateDoc(doc(db, 'tickets', ticketId), {
      status: 'Resolvido',
      endedAt: serverTimestamp()
    });
    // System message
    await addDoc(collection(db, 'tickets', ticketId, 'messages'), {
      text: `Atendimento finalizado pelo operador. Por favor, responda a pesquisa de satisfação.`,
      sender: 'Sistema',
      createdAt: serverTimestamp()
    });
    setSelectedTicketId(null);
  };

  // Filter Logic for Chat Tabs
  const getFilteredTickets = () => {
    if (chatFilter === 'aguardando') return tickets.filter(t => t.status === 'Pendente');
    if (chatFilter === 'andamento') return tickets.filter(t => t.status === 'Em Atendimento' || t.status === 'Resolvido'); // Resolved stays here until survey done
    if (chatFilter === 'historico') return tickets.filter(t => t.status === 'Finalizado' || t.status === 'Arquivado');
    return [];
  };

  const renderOperational = () => {
    switch(opSubView) {
      case 'validacao':
        const pending = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente' || getMissingFields(s).length > 0);
        return (
          <div className="bg-white border border-slate-300 animate-in zoom-in-98 h-full flex flex-col rounded-xl overflow-hidden shadow-xl">
             <div className="p-4 bg-slate-900 text-white flex justify-between items-center shrink-0">
                <div className="flex items-center gap-3">
                   <div className="p-1.5 bg-indigo-600 rounded-lg shadow-lg"><UserCheck size={16}/></div>
                   <h3 className="text-xs font-black uppercase italic tracking-widest">Auditoria Digital</h3>
                </div>
                <button onClick={() => setOpSubView('main')} className="p-1.5 hover:bg-white/10 rounded-lg transition-all"><X size={16}/></button>
             </div>
             <div className="flex-1 overflow-auto custom-scrollbar">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-50 border-b border-slate-200 text-[9px] font-black uppercase italic tracking-widest sticky top-0 z-10 text-slate-400">
                       <tr><th className="px-6 py-3">ID</th><th className="px-6 py-3">Discente</th><th className="px-6 py-3">Status</th><th className="px-6 py-3 text-center">Ação</th></tr>
                    </thead>
                    <tbody className="text-xs">
                       {pending.length === 0 ? (
                         <tr><td colSpan={4} className="p-20 text-center text-slate-300 uppercase italic font-black text-xs tracking-widest">Nenhuma pendência encontrada.</td></tr>
                       ) : pending.map(s => {
                         const missing = getMissingFields(s);
                         return (
                         <tr key={s.uid} className="border-b border-slate-100 hover:bg-indigo-50/20 transition-all group">
                            <td className="px-6 py-3 font-mono font-black text-indigo-600 text-xs">{s.academicId}</td>
                            <td className="px-6 py-3">
                               <div className="flex items-center gap-3">
                                  <div className="w-8 h-8 rounded-lg bg-slate-100 overflow-hidden shadow-sm shrink-0 border border-slate-200">
                                     {s.photoURL ? <img src={s.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center font-black italic text-slate-300 text-xs">{(s.displayName||'U').charAt(0)}</div>}
                                  </div>
                                  <div>
                                     <p className="font-black uppercase text-slate-900 leading-none italic text-xs">{s.displayName}</p>
                                     <p className="text-[9px] text-slate-400 font-bold mt-0.5 uppercase italic">Pendências: {missing.length > 0 ? <span className="text-rose-500">{missing.join(', ')}</span> : 'Aguardando Validação'}</p>
                                  </div>
                               </div>
                            </td>
                            <td className="px-6 py-3 font-bold text-slate-500 uppercase italic text-[10px]">{s.status}</td>
                            <td className="px-6 py-3 flex items-center justify-center gap-2">
                               <button onClick={() => setViewingStudent(s)} className="p-2 bg-slate-100 text-slate-400 hover:text-indigo-600 rounded-lg transition-all border border-slate-200 shadow-sm"><Eye size={14}/></button>
                               <button onClick={async () => { if(missing.length > 0) { if(!confirm(`ATENÇÃO: Existem ${missing.length} campos pendentes. Validar mesmo assim?`)) return; } await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'}); alert(`${s.displayName} ativado!`); }} className="px-4 py-2 bg-emerald-600 text-white text-[9px] font-black uppercase italic tracking-widest shadow-sm rounded-lg transition-all hover:bg-emerald-700 active:scale-95">Validar</button>
                               <button onClick={() => handleNotifyWhatsApp(s)} className="p-2 bg-emerald-50 text-emerald-600 hover:bg-emerald-600 hover:text-white rounded-lg transition-all border border-emerald-100 shadow-sm"><MessageCircle size={14}/></button>
                            </td>
                         </tr>
                       )})}
                    </tbody>
                </table>
             </div>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
             <button onClick={() => setOpSubView('declaracao')} className="bg-white p-6 border border-slate-200 rounded-xl flex flex-col items-center gap-3 hover:bg-indigo-600 group transition-all shadow-lg hover:shadow-indigo-200"><div className="text-slate-400 group-hover:text-white transition-colors p-3 bg-slate-50 group-hover:bg-white/20 rounded-lg"><FileText size={24}/></div><span className="text-[9px] font-black uppercase text-slate-900 group-hover:text-white italic tracking-widest">Declarações</span></button>
             <button onClick={() => setOpSubView('validacao')} className="bg-white p-6 border border-slate-200 rounded-xl flex flex-col items-center gap-3 hover:bg-indigo-600 group transition-all shadow-lg hover:shadow-indigo-200 relative"><div className="text-slate-400 group-hover:text-white transition-colors p-3 bg-slate-50 group-hover:bg-white/20 rounded-lg"><UserCheck size={24}/></div><span className="text-[9px] font-black uppercase text-slate-900 group-hover:text-white italic tracking-widest text-center">Auditoria</span>{stats.pendentesVal > 0 && <span className="absolute top-3 right-3 bg-rose-600 text-white text-[9px] px-2 py-0.5 font-black rounded-full border border-white animate-bounce">{stats.pendentesVal}</span>}</button>
             <button onClick={() => setOpSubView('transferencia')} className="bg-white p-6 border border-slate-200 rounded-xl flex flex-col items-center gap-3 hover:bg-indigo-600 group transition-all shadow-lg hover:shadow-indigo-200"><div className="text-slate-400 group-hover:text-white transition-colors p-3 bg-slate-50 group-hover:bg-white/20 rounded-lg"><ArrowRightLeft size={24}/></div><span className="text-[9px] font-black uppercase text-slate-900 group-hover:text-white italic tracking-widest text-center">Transferência</span></button>
             <button onClick={() => setOpSubView('assinatura')} className="bg-white p-6 border border-slate-200 rounded-xl flex flex-col items-center gap-3 hover:bg-indigo-600 group transition-all shadow-lg hover:shadow-indigo-200"><div className="text-slate-400 group-hover:text-white transition-colors p-3 bg-slate-50 group-hover:bg-white/20 rounded-lg"><Fingerprint size={24}/></div><span className="text-[9px] font-black uppercase text-slate-900 group-hover:text-white italic tracking-widest">Assinatura</span></button>
          </div>
        );
    }
  };

  const filteredTickets = tickets.filter(t => 
    t.user?.toLowerCase().includes(searchTerm.toLowerCase()) || 
    t.protocolo?.includes(searchTerm) ||
    t.id.includes(searchTerm)
  );

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6 print:bg-white print:p-0">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><MessageSquare size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); setSelectedTicketId(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
