  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  const handleSaveToFiles = async (fileData: any, fileName: string) => {
    // Save a file (e.g. from chat) to "Chat Uploads" folder. Create folder if missing.
    let targetFolder = fileSystem.find(f => f.name === 'Chat Uploads' && f.parentId === 'root');
    if (!targetFolder) {
      const ref = await addDoc(collection(db, 'secretaria_arquivos'), { name: 'Chat Uploads', type: 'folder', parentId: 'root', createdAt: serverTimestamp() });
      targetFolder = { id: ref.id };
    }
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: fileName, type: 'file', url: fileData, parentId: targetFolder.id || targetFolder.id, createdAt: serverTimestamp(), source: 'chat'
    });
    alert("Arquivo salvo em 'Chat Uploads'!");
  };

  // --- DOCUMENT GENERATION LOGIC ---
  const saveGeneratedDocument = async (docTitle: string, docType: string, contentHTML: string) => {
