    let targetFolder = fileSystem.find(f => f.name === 'Documentos Oficiais' && f.parentId === 'root');
    if (!targetFolder) {
      const ref = await addDoc(collection(db, 'secretaria_arquivos'), { name: 'Documentos Oficiais', type: 'folder', parentId: 'root', createdAt: serverTimestamp() });
      targetFolder = { id: ref.id };
    }

    const docCode = generateVerificationCode();

    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: `${docTitle} - ${opStudent?.displayName}.pdf`,
      type: 'file',
      mimeType: 'application/pdf', // Mock
      docData: { contentHTML, docCode, studentId: opStudent?.uid, type: docType }, // Store raw data to reconstruct
      parentId: targetFolder.id,
      createdAt: serverTimestamp(),
      createdBy: user.uid
    });

