  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('aguardando');

  // Data States
  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [fileSystem, setFileSystem] = useState<any[]>([]);

  // UI States
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  // File Explorer State
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [attachMode, setAttachMode] = useState(false); // If picking file for chat

  // Operational State
  const [opStudent, setOpStudent] = useState<any>(null);
  const [generatedDoc, setGeneratedDoc] = useState<any>(null);
  const [viewingStudent, setViewingStudent] = useState<any | null>(null); // Reuse for Validation

  // Modals
  const [viewingTicketDetails, setViewingTicketDetails] = useState<any | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Ticket Listener
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        t.sort((a:any, b:any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0));
        setTickets(t);
    });

    // File System Listener
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    // Students Listener
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => {
      setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() })));
    });

    // Get Signature
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid]);

  // Sync Chat
  useEffect(() => {
    if (!selectedTicketId) { setChatHistory([]); return; }
    const q = query(collection(db, 'tickets', selectedTicketId, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setChatHistory(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [selectedTicketId]);

  // --- FILE EXPLORER LOGIC ---
  const currentItems = useMemo(() => {
    return fileSystem.filter(f => f.parentId === currentFolderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  }, [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      if (ev.target?.result) {
        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name,
          type: 'file',
          mimeType: file.type,
          url: ev.target.result, // Storing base64 for prototype
          parentId: currentFolderId,
          size: file.size,
          createdAt: serverTimestamp(),
          createdBy: user.uid
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id);
    setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  // --- SAVE CHAT UPLOAD TO FILES ---
  const handleSaveToFiles = async (fileData: any, fileName: string) => {
    // 1. Check if 'Uploads do Chat' folder exists
    let targetFolder = fileSystem.find(f => f.name === 'Uploads do Chat' && f.parentId === 'root');
    let targetId = targetFolder?.id;

    if (!targetId) {
      const ref = await addDoc(collection(db, 'secretaria_arquivos'), { 
        name: 'Uploads do Chat', type: 'folder', parentId: 'root', createdAt: serverTimestamp() 
      });
      targetId = ref.id;
    }

    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: fileName, 
      type: 'file', 
      url: fileData, 
      parentId: targetId, 
      createdAt: serverTimestamp(), 
      source: 'chat'
    });
    alert("Arquivo salvo na pasta 'Uploads do Chat'!");
  };

  // --- DOCUMENT GENERATION LOGIC ---
  const saveGeneratedDocument = async (docTitle: string, docType: string) => {
    let targetFolder = fileSystem.find(f => f.name === 'Documentos Oficiais' && f.parentId === 'root');
    let targetId = targetFolder?.id;

    if (!targetId) {
      const ref = await addDoc(collection(db, 'secretaria_arquivos'), { 
        name: 'Documentos Oficiais', type: 'folder', parentId: 'root', createdAt: serverTimestamp() 
      });
      targetId = ref.id;
    }

    const docCode = generatedDoc.code;

    // In a real app, we would generate a PDF blob here.
    // For this prototype, we'll save a file record representing the document
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: `${docTitle} - ${opStudent?.displayName}.pdf`,
      type: 'file',
      mimeType: 'application/pdf',
      // We store the data to recreate it or link to a generated PDF
      docData: { 
          title: generatedDoc.title,
          studentName: opStudent?.displayName,
          code: docCode, 
          type: docType,
          date: new Date().toISOString()
      },
      parentId: targetId,
      createdAt: serverTimestamp(),
      createdBy: user.uid
    });
  };

  const generateDeclaration = async (type: 'matricula'|'conclusao'|'transferencia') => {
    if (!opStudent) return;
    let title = '';
    let content = null;
    const code = generateVerificationCode();

    if (type === 'matricula') {
        title = 'Declaração de Matrícula';
        content = (
            <>
              <p>Declaramos para os devidos fins que, a pedido do(a) interessado(a), <strong>{opStudent.displayName}</strong>, portador(a) do CPF nº {opStudent.cpf}, está regularmente matriculado(a) nesta instituição de ensino, no curso de Teologia Sistemática, sob o RA <strong>{opStudent.academicId}</strong>.</p>
              <p>O referido curso é ministrado na modalidade à distância (EAD), estando o aluno com situação acadêmica: <strong>ATIVO</strong>.</p>
              <p>Por ser verdade, firmamos o presente documento.</p>
            </>
        );
    } else if (type === 'transferencia') {
        title = 'Guia de Transferência';
        content = (
            <>
              <p>Pelo presente instrumento, concedemos transferência ao aluno(a) <strong>{opStudent.displayName}</strong>, matrícula nº <strong>{opStudent.academicId}</strong>, para prosseguimento de seus estudos em outra congênere.</p>
              <p>Informamos que o histórico escolar oficial será expedido e enviado num prazo de até 30 (trinta) dias.</p>
              <p>A partir desta data, não há pendências acadêmicas ou financeiras impeditivas.</p>
            </>
        );
    } else {
        title = 'Certificado de Conclusão';
        content = (
            <>
                <p>Certificamos que <strong>{opStudent.displayName}</strong> concluiu com êxito o curso de Teologia Avançada.</p>
            </>
        );
    }

    const docObj = { title, content, code, student: opStudent };
    setGeneratedDoc(docObj);
    // Auto-save triggers after render or via effect, but let's call save manually in the button for simplicity
  };

  const generateTranscript = async () => {
    if (!opStudent) return;
    const code = generateVerificationCode();

    // Mock grades - in real app, fetch from `student.progress`
    const content = (
      <div className="space-y-6">
        <p>Certificamos que <strong>{opStudent.displayName}</strong>, RA <strong>{opStudent.academicId}</strong>, obteve o seguinte aproveitamento acadêmico:</p>
        <table className="w-full border-collapse border border-slate-900 text-xs">
          <thead>
            <tr className="bg-slate-200">
              <th className="border border-slate-900 p-2 text-left">Disciplina / Módulo</th>
              <th className="border border-slate-900 p-2 text-center">Carga Horária</th>
              <th className="border border-slate-900 p-2 text-center">Média Final</th>
              <th className="border border-slate-900 p-2 text-center">Resultado</th>
            </tr>
          </thead>
          <tbody>
            <tr><td className="border border-slate-900 p-2">Teologia Sistemática I</td><td className="border border-slate-900 p-2 text-center">60h</td><td className="border border-slate-900 p-2 text-center">9.5</td><td className="border border-slate-900 p-2 text-center">APROVADO</td></tr>
            <tr><td className="border border-slate-900 p-2">Hermenêutica Bíblica</td><td className="border border-slate-900 p-2 text-center">40h</td><td className="border border-slate-900 p-2 text-center">8.0</td><td className="border border-slate-900 p-2 text-center">APROVADO</td></tr>
            <tr><td className="border border-slate-900 p-2">Homilética</td><td className="border border-slate-900 p-2 text-center">50h</td><td className="border border-slate-900 p-2 text-center">10.0</td><td className="border border-slate-900 p-2 text-center">APROVADO</td></tr>
            <tr><td className="border border-slate-900 p-2">História da Igreja</td><td className="border border-slate-900 p-2 text-center">60h</td><td className="border border-slate-900 p-2 text-center">9.0</td><td className="border border-slate-900 p-2 text-center">APROVADO</td></tr>
          </tbody>
        </table>
        <div className="mt-4 p-4 border border-slate-900">
            <p><strong>Média Global:</strong> 9.1</p>
            <p><strong>Carga Horária Total:</strong> 210 Horas</p>
            <p><strong>Situação:</strong> EM CURSO</p>
        </div>
      </div>
    );

    setGeneratedDoc({ title: 'Histórico Escolar Oficial', content, code, student: opStudent });
  };

  // --- CHAT LOGIC ---
  const handleSendFileFromExplorer = async (file: any) => {
    if (!selectedTicketId) return;
    await addDoc(collection(db, 'tickets', selectedTicketId, 'messages'), {
      text: `[Arquivo Anexado: ${file.name}]`,
      attachmentUrl: file.url, // Assuming base64 or URL
      sender: 'Secretaria',
      createdAt: serverTimestamp()
    });
    setAttachMode(false);
  };

  const handleSendMessage = async () => {
    if (!chatMessage.trim() || !selectedTicketId) return;
    await addDoc(collection(db, 'tickets', selectedTicketId, 'messages'), {
      text: chatMessage,
      sender: 'Secretaria',
      createdAt: serverTimestamp()
    });
    setChatMessage('');
  };

  const getMissingFields = (s: any) => {
    const missing = [];
    if (!s.cpf) missing.push("CPF");
    if (!s.photoURL) missing.push("Foto");
    if (!s.endereco?.cep) missing.push("Endereço");
    return missing;
  };

  const stats = useMemo(() => {
    const pendingVal = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').length;
    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado' || t.status === 'Resolvido').length,
      totalGed: fileSystem.length,
      pendentesVal: pendingVal
    };
  }, [tickets, students, fileSystem]);

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      {/* HEADER */}
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); setSelectedTicketId(null); setGeneratedDoc(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      {/* STATS (Visible on all tabs roughly, or hidden if needed) */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 print:hidden">
         <div className="bg-white border-l-4 border-l-amber-500 p-4 rounded-xl border border-slate-200 shadow-sm"><p className="text-[8px] font-black text-slate-400 uppercase italic tracking-widest">Pendentes</p><p className="text-2xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.abertos}</p></div>
         <div className="bg-white border-l-4 border-l-indigo-500 p-4 rounded-xl border border-slate-200 shadow-sm"><p className="text-[8px] font-black text-slate-400 uppercase italic tracking-widest">Ativos</p><p className="text-2xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.finalizados}</p></div>
         <div className="bg-white border-l-4 border-l-rose-500 p-4 rounded-xl border border-slate-200 shadow-sm cursor-pointer hover:bg-rose-50 transition-colors" onClick={() => { setActiveTab('operacional'); setOpSubView('validacao'); }}><p className="text-[8px] font-black text-slate-400 uppercase italic tracking-widest">Auditoria</p><p className="text-2xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.pendentesVal}</p></div>
         <div className="bg-white border-l-4 border-l-emerald-500 p-4 rounded-xl border border-slate-200 shadow-sm"><p className="text-[8px] font-black text-slate-400 uppercase italic tracking-widest">GED</p><p className="text-2xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.totalGed}</p></div>
      </div>

      <main className="flex-1 overflow-hidden flex flex-col">

         {/* --- TAB: ARQUIVOS (FILE EXPLORER) --- */}
         {(activeTab === 'arquivos' || attachMode) && (
           <div className={`bg-white border border-slate-200 rounded-xl overflow-hidden h-full flex flex-col shadow-lg ${attachMode ? 'fixed inset-10 z-[3000] border-indigo-600 border-4' : ''}`}>
              <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                 <div className="flex items-center gap-2 overflow-x-auto">
                    <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-200 rounded-lg"><Home size={16}/></button>
                    {folderPath.map((f, i) => (
                      <React.Fragment key={f.id}>
                        {i > 0 && <ChevronRight size={14} className="text-slate-400"/>}
                        <button onClick={() => handleBreadcrumb(i)} className={`text-xs font-bold px-2 py-1 rounded-lg hover:bg-slate-200 ${i === folderPath.length -1 ? 'text-slate-900' : 'text-slate-500'}`}>{f.name}</button>
                      </React.Fragment>
                    ))}
                 </div>
                 <div className="flex gap-2">
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} />
                    <button onClick={() => fileInputRef.current?.click()} className="px-3 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-indigo-600"><UploadCloud size={14}/> Upload</button>
                    <button onClick={handleCreateFolder} className="px-3 py-2 bg-slate-200 text-slate-700 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-slate-300"><FolderPlus size={14}/> Pasta</button>
                    {attachMode && <button onClick={() => setAttachMode(false)} className="px-3 py-2 bg-rose-600 text-white rounded-lg text-[9px] font-black uppercase">Fechar</button>}
                 </div>
              </div>
              <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50/50">
                 {currentItems.length === 0 ? (
                   <div className="h-full flex flex-col items-center justify-center opacity-30 gap-4"><Folder size={48} /><p className="text-xs font-black uppercase">Pasta Vazia</p></div>
                 ) : (
                   <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                      {currentItems.map(item => (
                        <div key={item.id} 
                             onDoubleClick={() => item.type === 'folder' ? handleNavigate(item) : null}
                             onClick={() => attachMode && item.type === 'file' ? handleSendFileFromExplorer(item) : null}
                             className={`bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all group flex flex-col items-center text-center cursor-pointer relative ${attachMode && item.type === 'file' ? 'hover:border-indigo-600 hover:bg-indigo-50' : ''}`}
                        >
                           <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-3 text-white shadow-inner ${item.type === 'folder' ? 'bg-amber-400' : 'bg-indigo-500'}`}>
                              {item.type === 'folder' ? <Folder size={32} className="fill-white/50"/> : <FileText size={32} className="fill-white/50"/>}
                           </div>
                           <p className="text-[10px] font-bold text-slate-700 line-clamp-2 leading-tight w-full break-words">{item.name}</p>
                           {item.type === 'file' && !attachMode && (
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 flex gap-1">
                               <button onClick={async (e) => { e.stopPropagation(); if(confirm('Apagar?')) await deleteDoc(doc(db, 'secretaria_arquivos', item.id)); }} className="p-1.5 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100"><X size={12}/></button>
                               {item.url && <a href={item.url} download={item.name} onClick={e => e.stopPropagation()} className="p-1.5 bg-slate-50 text-slate-600 rounded-lg hover:bg-slate-100"><Download size={12}/></a>}
                             </div>
                           )}
                        </div>
                      ))}
                   </div>
                 )}
              </div>
           </div>
         )}

         {/* --- TAB: OPERACIONAL --- */}
         {activeTab === 'operacional' && (
           <div className="h-full flex flex-col md:flex-row gap-6">
              {/* OPERATIONAL SIDEBAR */}
              <div className="w-full md:w-64 flex flex-col gap-3">
                 <button onClick={() => { setOpSubView('declaracao'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'declaracao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><FileText size={18}/><span className="text-xs font-black uppercase">Declarações</span></button>
                 <button onClick={() => { setOpSubView('historico'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'historico' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><Archive size={18}/><span className="text-xs font-black uppercase">Histórico Escolar</span></button>
                 <button onClick={() => { setOpSubView('transferencia'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'transferencia' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><ArrowRightLeft size={18}/><span className="text-xs font-black uppercase">Transferência</span></button>
                 <button onClick={() => { setOpSubView('validacao'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'validacao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><UserCheck size={18}/><span className="text-xs font-black uppercase">Auditoria</span></button>
                 <button onClick={() => setIsSignModalOpen(true)} className="p-4 rounded-xl border bg-white border-slate-200 hover:bg-slate-50 flex items-center gap-3 transition-all"><Fingerprint size={18}/><span className="text-xs font-black uppercase">Minha Assinatura</span></button>
              </div>

              {/* OPERATIONAL CONTENT */}
              <div className="flex-1 bg-white rounded-2xl border border-slate-200 p-1 shadow-sm overflow-hidden relative">
                 {/* VALIDATION (AUDITORIA) - PRESERVED LOGIC */}
                 {opSubView === 'validacao' && (
                    <div className="h-full flex flex-col">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                           <h3 className="text-xs font-black uppercase italic tracking-widest text-slate-800">Auditoria Digital</h3>
                        </div>
                        <div className="flex-1 overflow-auto custom-scrollbar">
                            <table className="w-full text-left border-collapse">
                                <thead className="bg-white border-b border-slate-200 text-[9px] font-black uppercase italic tracking-widest sticky top-0 z-10 text-slate-400">
                                   <tr><th className="px-6 py-3">ID</th><th className="px-6 py-3">Discente</th><th className="px-6 py-3">Status</th><th className="px-6 py-3 text-center">Ação</th></tr>
                                </thead>
                                <tbody className="text-xs">
                                   {students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').map(s => (
                                     <tr key={s.uid} className="border-b border-slate-100 hover:bg-indigo-50/20 transition-all">
                                        <td className="px-6 py-3 font-mono font-black text-indigo-600 text-xs">{s.academicId}</td>
                                        <td className="px-6 py-3"><p className="font-black uppercase text-slate-900 leading-none italic text-xs">{s.displayName}</p></td>
                                        <td className="px-6 py-3 font-bold text-slate-500 uppercase italic text-[10px]">{s.status}</td>
                                        <td className="px-6 py-3 flex items-center justify-center gap-2">
                                           <button onClick={() => setViewingStudent(s)} className="p-2 bg-slate-100 text-slate-400 hover:text-indigo-600 rounded-lg"><Eye size={14}/></button>
                                           <button onClick={async () => { await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'}); alert('Validado!'); }} className="px-4 py-2 bg-emerald-600 text-white text-[9px] font-black uppercase rounded-lg">Validar</button>
                                        </td>
                                     </tr>
                                   ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                 )}

                 {/* DOC GENERATORS */}
                 {(opSubView === 'declaracao' || opSubView === 'historico' || opSubView === 'transferencia') && !generatedDoc && (
                   <div className="max-w-lg mx-auto space-y-6 py-10 px-6">
                      <h3 className="text-xl font-black uppercase italic text-slate-900 border-b pb-4">Gerar {opSubView}</h3>
                      <div className="space-y-2">
                         <label className="text-[10px] font-black uppercase text-slate-400">Selecione o Aluno</label>
                         <select onChange={e => setOpStudent(students.find(s => s.uid === e.target.value))} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold">
                            <option value="">Selecione...</option>
