                            <button onClick={() => window.print()} className="px-4 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2"><Printer size={14}/> Imprimir</button>
                         </div>
                      </div>
                      <OfficialDocTemplate 
                        title={generatedDoc.title} 
                        content={generatedDoc.content} 
                        student={generatedDoc.student} 
                        code={generatedDoc.code}
                        signatures={{ director: null, secretary: secSignature }} 
                      />
                   </div>
                 )}
              </div>
           </div>
         )}

         {/* --- TAB: ATENDIMENTO (PRESERVED) / CHAT (ENHANCED) --- */}
         {(activeTab === 'atendimento' || activeTab === 'chat') && (
           <div className="h-full flex flex-col bg-white border border-slate-200 rounded-xl overflow-hidden shadow-lg">
              {activeTab === 'atendimento' ? (
                 // TICKET LIST (PRESERVED LOGIC)
                 <div className="h-full flex flex-col">
                    <div className="p-4 bg-slate-50 border-b border-slate-100 flex justify-between items-center">
                        <h3 className="font-black text-xs uppercase italic tracking-widest text-slate-800">Todos os Protocolos</h3>
                        <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Filtrar..." className="bg-white border rounded-lg px-3 py-1 text-xs" />
                    </div>
                    <div className="flex-1 overflow-auto custom-scrollbar">
                        {tickets.filter(t => t.user?.toLowerCase().includes(searchTerm.toLowerCase())).map(t => (
                            <div key={t.id} className="p-4 border-b hover:bg-slate-50 flex justify-between items-center cursor-pointer" onClick={() => { setSelectedTicketId(t.id); setActiveTab('chat'); }}>
                                <div><p className="font-bold text-xs">{t.user}</p><p className="text-[10px] text-slate-500">{t.lastMessage}</p></div>
                                <span className="text-[9px] font-black bg-slate-100 px-2 py-1 rounded">{t.status}</span>
                            </div>
                        ))}
                    </div>
                 </div>
              ) : (
                 // CHAT VIEW (WITH ATTACHMENT LOGIC)
                 <div className="flex-1 flex flex-col h-full relative">
                    {selectedTicketId ? (
                      <>
                        <div className="p-4 border-b bg-slate-50 flex justify-between items-center">
                           <h4 className="font-bold text-sm uppercase">{tickets.find(t=>t.id===selectedTicketId)?.user}</h4>
                           <button onClick={() => setActiveTab('atendimento')} className="p-2"><X size={16}/></button>
                        </div>
                        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-100 custom-scrollbar">
                           {chatHistory.map((m, i) => (
                             <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                                <div className={`max-w-[80%] p-3 rounded-xl text-xs font-medium ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white' : 'bg-white border text-slate-800'}`}>
                                   {m.text}
                                   {/* ATTACHMENT DISPLAY */}
                                   {m.attachmentUrl && (
                                     <div className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20" onClick={() => window.open(m.attachmentUrl, '_blank')}>
                                        <FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Ver Anexo</span>
                                        {/* SAVE TO FILES BUTTON FOR INCOMING */}
                                        {m.sender !== 'Secretaria' && (
                                          <button onClick={(e) => { e.stopPropagation(); handleSaveToFiles(m.attachmentUrl, `Anexo de ${tickets.find(t=>t.id===selectedTicketId)?.user} - ${Date.now()}`); }} className="ml-2 p-1 bg-white text-slate-900 rounded shadow-sm hover:text-indigo-600" title="Salvar nos Arquivos"><Save size={12}/></button>
                                        )}
                                     </div>
                                   )}
                                </div>
                             </div>
                           ))}
                           <div ref={chatEndRef}/>
                        </div>
                        <div className="p-4 bg-white border-t flex gap-2">
                           <button onClick={() => setAttachMode(true)} className="p-3 bg-slate-100 rounded-xl hover:bg-indigo-100 text-indigo-600"><Paperclip size={18}/></button>
                           <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} className="flex-1 bg-slate-50 rounded-xl px-4 text-xs font-bold outline-none" placeholder="Digite..." />
                           <button onClick={handleSendMessage} className="p-3 bg-indigo-600 text-white rounded-xl"><Send size={18}/></button>
                        </div>
                      </>
                    ) : <div className="flex-1 flex items-center justify-center opacity-30 font-black uppercase">Selecione um Ticket</div>}
                 </div>
              )}
           </div>
         )}
      </main>

      {/* Signature Modal */}
      {isSignModalOpen && <SignaturePad title="Assinatura Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert("Assinatura Salva!"); }} />}
    </div>
  );
};

export default SecretariatView;

