  const [chatMessage, setChatMessage] = useState('');

  // UI States - General
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  // File Explorer State
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [attachMode, setAttachMode] = useState(false); // If picking file for chat

  // Operational State
  const [opStudent, setOpStudent] = useState<any>(null);
  const [generatedDoc, setGeneratedDoc] = useState<any>(null);

  // Audit Modal State
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Ticket Listener
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        // Sort by update time desc
        t.sort((a:any, b:any) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
        setTickets(t);
    });

    // File System Listener
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    // Students Listener (All students for search/validation)
    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    // Get Signature
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid]);

  // Sync Chat
  useEffect(() => {
    if (!selectedTicketId) { setChatHistory([]); return; }
    const q = query(collection(db, 'tickets', selectedTicketId, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setChatHistory(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [selectedTicketId]);

  // --- FILE EXPLORER LOGIC ---
  const currentItems = useMemo(() => {
    return fileSystem.filter(f => f.parentId === currentFolderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  }, [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      if (ev.target?.result) {
        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name,
          type: 'file',
          mimeType: file.type,
          url: ev.target.result, 
          parentId: currentFolderId,
          size: file.size,
          createdAt: serverTimestamp(),
          createdBy: user.uid
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id);
    setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  // --- CHAT & TICKET LOGIC ---
  const handleSaveToFiles = async (fileData: any, fileName: string) => {
    let targetFolder = fileSystem.find(f => f.name === 'Uploads do Chat' && f.parentId === 'root');
    let targetId = targetFolder?.id;

    if (!targetId) {
      const ref = await addDoc(collection(db, 'secretaria_arquivos'), { 
        name: 'Uploads do Chat', type: 'folder', parentId: 'root', createdAt: serverTimestamp() 
      });
      targetId = ref.id;
    }

    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: fileName, type: 'file', url: fileData, parentId: targetId, createdAt: serverTimestamp(), source: 'chat'
    });
    alert("Arquivo salvo na pasta 'Uploads do Chat'!");
  };

  const handleSendFileFromExplorer = async (file: any) => {
    if (!selectedTicketId) return;
    await addDoc(collection(db, 'tickets', selectedTicketId, 'messages'), {
      text: `[Arquivo Anexado: ${file.name}]`,
      attachmentUrl: file.url,
      sender: 'Secretaria',
      createdAt: serverTimestamp()
    });
    setAttachMode(false);
    setActiveTab('chat');
  };

  const handleSendMessage = async () => {
    if (!chatMessage.trim() || !selectedTicketId) return;
    await addDoc(collection(db, 'tickets', selectedTicketId, 'messages'), {
      text: chatMessage,
      sender: 'Secretaria',
      createdAt: serverTimestamp()
    });
    await updateDoc(doc(db, 'tickets', selectedTicketId), {
        lastMessage: chatMessage,
        updatedAt: serverTimestamp()
    });
    setChatMessage('');
  };

  const handleAssumeTicket = async (ticketId: string) => {
      await updateDoc(doc(db, 'tickets', ticketId), {
          status: 'Em Atendimento',
          attendant: user.displayName
      });
      alert('Você assumiu este atendimento.');
  };

  const handleCloseTicket = async (ticketId: string) => {
      if(!confirm("Deseja finalizar este atendimento?")) return;
      await updateDoc(doc(db, 'tickets', ticketId), {
          status: 'Finalizado'
      });
      setSelectedTicketId(null);
      setActiveTab('atendimento');
  };

  // --- AUDIT LOGIC ---
  const openAuditModal = (student: any) => {
      // Create a copy to edit without affecting list immediately
      setEditingStudent({ ...student }); 
      setAuditModalOpen(true);
  };

  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      await updateDoc(doc(db, 'users', editingStudent.uid), {
          ...editingStudent,
          updatedAt: serverTimestamp()
      });
      alert("Dados do aluno atualizados com sucesso.");
  };

  const validateStudent = async () => {
      if (!editingStudent) return;
      await updateDoc(doc(db, 'users', editingStudent.uid), {
          status: 'ativo',
          validatedAt: serverTimestamp(),
          validatedBy: user.uid
      });
      setAuditModalOpen(false);
      setEditingStudent(null);
      alert("Matrícula VALIDADA com sucesso!");
  };

  const rejectStudent = async () => {
      if (!editingStudent) return;
      const reason = prompt("Motivo da rejeição/pendência:");
      if (!reason) return;
      await updateDoc(doc(db, 'users', editingStudent.uid), {
          status: 'pendente', // Send back to pending or specific rejected status
          validationNote: reason
      });
      setAuditModalOpen(false);
      setEditingStudent(null);
      alert("Matrícula marcada como pendente.");
  };

  // --- DOCUMENT GENERATION ---
  const saveGeneratedDocument = async (docTitle: string, docType: string) => {
    let targetFolder = fileSystem.find(f => f.name === 'Documentos Oficiais' && f.parentId === 'root');
    let targetId = targetFolder?.id;

    if (!targetId) {
      const ref = await addDoc(collection(db, 'secretaria_arquivos'), { 
        name: 'Documentos Oficiais', type: 'folder', parentId: 'root', createdAt: serverTimestamp() 
      });
      targetId = ref.id;
    }

    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: `${docTitle} - ${opStudent?.displayName}.pdf`,
      type: 'file',
      mimeType: 'application/pdf',
      docData: { 
          title: generatedDoc.title,
          studentName: opStudent?.displayName,
          code: generatedDoc.code, 
          type: docType,
          date: new Date().toISOString()
      },
      parentId: targetId,
      createdAt: serverTimestamp(),
      createdBy: user.uid
    });
  };

  const generateDeclaration = async (type: 'matricula'|'conclusao'|'transferencia') => {
    if (!opStudent) return;
    let title = '';
    let content = null;
    const code = generateVerificationCode();

    if (type === 'matricula') {
        title = 'Declaração de Matrícula';
        content = (
            <>
              <p>Declaramos para os devidos fins que, a pedido do(a) interessado(a), <strong>{opStudent.displayName}</strong>, portador(a) do CPF nº {opStudent.cpf}, está regularmente matriculado(a) nesta instituição de ensino, no curso de Teologia Sistemática, sob o RA <strong>{opStudent.academicId}</strong>.</p>
              <p>O referido curso é ministrado na modalidade à distância (EAD), estando o aluno com situação acadêmica: <strong>ATIVO</strong>.</p>
              <p>Por ser verdade, firmamos o presente documento.</p>
            </>
        );
    } else if (type === 'transferencia') {
        title = 'Guia de Transferência';
        content = (
            <>
              <p>Pelo presente instrumento, concedemos transferência ao aluno(a) <strong>{opStudent.displayName}</strong>, matrícula nº <strong>{opStudent.academicId}</strong>, para prosseguimento de seus estudos em outra congênere.</p>
              <p>Informamos que o histórico escolar oficial será expedido e enviado num prazo de até 30 (trinta) dias.</p>
              <p>A partir desta data, não há pendências acadêmicas ou financeiras impeditivas.</p>
            </>
        );
    } else {
        title = 'Certificado de Conclusão';
        content = (
            <>
                <p>Certificamos que <strong>{opStudent.displayName}</strong> concluiu com êxito o curso de Teologia Avançada.</p>
            </>
        );
    }

    const docObj = { title, content, code, student: opStudent };
    setGeneratedDoc(docObj);
  };

  const generateTranscript = async () => {
    if (!opStudent) return;
    const code = generateVerificationCode();

    // Mock grades - in real app, fetch from `student.progress`
    const content = (
      <div className="space-y-6">
        <p>Certificamos que <strong>{opStudent.displayName}</strong>, RA <strong>{opStudent.academicId}</strong>, obteve o seguinte aproveitamento acadêmico:</p>
        <table className="w-full border-collapse border border-slate-900 text-xs">
          <thead>
            <tr className="bg-slate-200">
              <th className="border border-slate-900 p-2 text-left">Disciplina / Módulo</th>
              <th className="border border-slate-900 p-2 text-center">Carga Horária</th>
              <th className="border border-slate-900 p-2 text-center">Média Final</th>
              <th className="border border-slate-900 p-2 text-center">Resultado</th>
            </tr>
          </thead>
          <tbody>
            <tr><td className="border border-slate-900 p-2">Teologia Sistemática I</td><td className="border border-slate-900 p-2 text-center">60h</td><td className="border border-slate-900 p-2 text-center">9.5</td><td className="border border-slate-900 p-2 text-center">APROVADO</td></tr>
            <tr><td className="border border-slate-900 p-2">Hermenêutica Bíblica</td><td className="border border-slate-900 p-2 text-center">40h</td><td className="border border-slate-900 p-2 text-center">8.0</td><td className="border border-slate-900 p-2 text-center">APROVADO</td></tr>
            <tr><td className="border border-slate-900 p-2">Homilética</td><td className="border border-slate-900 p-2 text-center">50h</td><td className="border border-slate-900 p-2 text-center">10.0</td><td className="border border-slate-900 p-2 text-center">APROVADO</td></tr>
            <tr><td className="border border-slate-900 p-2">História da Igreja</td><td className="border border-slate-900 p-2 text-center">60h</td><td className="border border-slate-900 p-2 text-center">9.0</td><td className="border border-slate-900 p-2 text-center">APROVADO</td></tr>
          </tbody>
        </table>
        <div className="mt-4 p-4 border border-slate-900">
            <p><strong>Média Global:</strong> 9.1</p>
            <p><strong>Carga Horária Total:</strong> 210 Horas</p>
            <p><strong>Situação:</strong> EM CURSO</p>
        </div>
      </div>
    );
    setGeneratedDoc({ title: 'Histórico Escolar Oficial', content, code, student: opStudent });
  };

  const filteredTickets = tickets.filter(t => {
      const matchSearch = ticketSearchTerm === '' || 
                          (t.protocolo && t.protocolo.toLowerCase().includes(ticketSearchTerm.toLowerCase())) ||
                          (t.user && t.user.toLowerCase().includes(ticketSearchTerm.toLowerCase()));

      if (!matchSearch) return false;

      if (ticketFilter === 'todos') return t.status !== 'Arquivado';
      if (ticketFilter === 'pendente') return t.status === 'Pendente';
      if (ticketFilter === 'ativo') return t.status === 'Em Atendimento';
      if (ticketFilter === 'finalizado') return t.status === 'Finalizado' || t.status === 'Resolvido';
      return true;
  });

  const stats = useMemo(() => {
    return {
      pendentes: tickets.filter(t => t.status === 'Pendente').length,
      ativos: tickets.filter(t => t.status === 'Em Atendimento').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado' || t.status === 'Resolvido').length,
      ged: fileSystem.length
    };
  }, [tickets, fileSystem]);

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      {/* HEADER */}
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); if(t !== 'chat') setSelectedTicketId(null); setGeneratedDoc(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      {/* MAIN CONTENT */}
      <main className="flex-1 overflow-hidden flex flex-col">

         {/* --- TAB: ATENDIMENTO (RESTORED DASHBOARD) --- */}
         {activeTab === 'atendimento' && (
             <div className="space-y-6 h-full flex flex-col overflow-hidden">
                 {/* Stats Cards */}
                 <div className="grid grid-cols-1 md:grid-cols-4 gap-4 shrink-0">
                    <div className="bg-white border-l-4 border-l-amber-500 p-4 rounded-xl border border-slate-200 shadow-sm"><p className="text-[8px] font-black text-slate-400 uppercase italic tracking-widest">Fila de Espera</p><p className="text-3xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.pendentes}</p></div>
                    <div className="bg-white border-l-4 border-l-indigo-600 p-4 rounded-xl border border-slate-200 shadow-sm"><p className="text-[8px] font-black text-slate-400 uppercase italic tracking-widest">Em Atendimento</p><p className="text-3xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.ativos}</p></div>
                    <div className="bg-white border-l-4 border-l-emerald-500 p-4 rounded-xl border border-slate-200 shadow-sm"><p className="text-[8px] font-black text-slate-400 uppercase italic tracking-widest">Resolvidos</p><p className="text-3xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.finalizados}</p></div>
                    <div className="bg-white border-l-4 border-l-slate-500 p-4 rounded-xl border border-slate-200 shadow-sm"><p className="text-[8px] font-black text-slate-400 uppercase italic tracking-widest">Arquivos GED</p><p className="text-3xl font-black text-slate-900 tabular-nums tracking-tighter">{stats.ged}</p></div>
                 </div>

                 {/* Filters & Search */}
                 <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm shrink-0 flex flex-col md:flex-row gap-4 items-center justify-between">
                    <div className="flex gap-2 p-1 bg-slate-50 rounded-lg border border-slate-100">
                        {['todos', 'pendente', 'ativo', 'finalizado'].map((f:any) => (
                            <button key={f} onClick={() => setTicketFilter(f)} className={`px-4 py-2 text-[9px] font-black uppercase rounded-md transition-all ${ticketFilter === f ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>{f}</button>
                        ))}
                    </div>
                    <div className="relative w-full md:w-80">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                        <input value={ticketSearchTerm} onChange={e => setTicketSearchTerm(e.target.value)} placeholder="Pesquisar Protocolo ou Aluno..." className="w-full pl-9 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600" />
                    </div>
                 </div>

                 {/* Ticket Table */}
                 <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                    <div className="overflow-y-auto custom-scrollbar flex-1">
                        <table className="w-full text-left border-collapse">
                            <thead className="bg-slate-50 text-[9px] font-black uppercase text-slate-400 border-b border-slate-100 tracking-widest sticky top-0 z-10">
                                <tr>
                                    <th className="px-6 py-4">Protocolo</th>
                                    <th className="px-6 py-4">Aluno / Solicitante</th>
                                    <th className="px-6 py-4">Status Atual</th>
                                    <th className="px-6 py-4">Última Interação</th>
                                    <th className="px-6 py-4 text-center">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="text-xs">
                                {filteredTickets.length === 0 ? (
                                    <tr><td colSpan={5} className="p-10 text-center text-slate-400 italic">Nenhum atendimento encontrado com os filtros atuais.</td></tr>
                                ) : filteredTickets.map(t => (
                                    <tr key={t.id} className="border-b border-slate-50 hover:bg-slate-50/50 transition-all">
                                        <td className="px-6 py-4 font-mono font-bold text-indigo-600">#{t.protocolo || t.id.substr(0,6).toUpperCase()}</td>
                                        <td className="px-6 py-4 font-bold text-slate-800 uppercase">{t.user}</td>
                                        <td className="px-6 py-4">
                                            <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase border ${
                                                t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-100' :
                                                t.status === 'Em Atendimento' ? 'bg-indigo-50 text-indigo-600 border-indigo-100' :
                                                'bg-emerald-50 text-emerald-600 border-emerald-100'
                                            }`}>{t.status}</span>
                                        </td>
                                        <td className="px-6 py-4 text-slate-500 italic text-[10px]">{t.updatedAt?.seconds ? new Date(t.updatedAt.seconds * 1000).toLocaleString() : '---'}</td>
                                        <td className="px-6 py-4">
                                            <div className="flex justify-center gap-2">
                                                {t.status === 'Pendente' && (
                                                    <button onClick={() => handleAssumeTicket(t.id)} className="px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-lg text-[8px] font-black uppercase border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all">Assumir</button>
                                                )}
                                                <button onClick={() => { setSelectedTicketId(t.id); setActiveTab('chat'); }} className="p-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-indigo-600 hover:text-white transition-all"><MessageSquare size={14}/></button>
                                                {(t.status === 'Em Atendimento' || t.status === 'Pendente') && (
                                                    <button onClick={() => handleCloseTicket(t.id)} className="p-2 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-600 hover:text-white transition-all"><CheckCircle2 size={14}/></button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                 </div>
             </div>
         )}

         {/* --- TAB: CHAT (INTEGRATED) --- */}
         {(activeTab === 'chat' || selectedTicketId) && activeTab !== 'atendimento' && activeTab !== 'arquivos' && activeTab !== 'operacional' && (
            <div className="h-full flex flex-col bg-white border border-slate-200 rounded-xl overflow-hidden shadow-lg">
                {selectedTicketId ? (
                    <>
                        <div className="p-4 border-b bg-slate-50 flex justify-between items-center shadow-sm z-10">
                           <div className="flex items-center gap-3">
                               <button onClick={() => { setSelectedTicketId(null); setActiveTab('atendimento'); }} className="p-2 bg-white border border-slate-200 rounded-lg hover:bg-slate-100"><CornerUpLeft size={16}/></button>
                               <div>
                                   <h4 className="font-bold text-sm uppercase text-slate-800">{tickets.find(t=>t.id===selectedTicketId)?.user}</h4>
                                   <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Protocolo: {tickets.find(t=>t.id===selectedTicketId)?.protocolo}</p>
                               </div>
                           </div>
                           <div className="flex gap-2">
                               <button onClick={() => setAttachMode(true)} className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 border border-indigo-100 hover:bg-indigo-100"><Paperclip size={14}/> Anexar Arquivo</button>
                               <button onClick={() => handleCloseTicket(selectedTicketId)} className="px-4 py-2 bg-rose-600 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-rose-700 shadow-lg"><CheckCircle2 size={14}/> Finalizar</button>
                           </div>
                        </div>
                        <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50 custom-scrollbar">
                           {chatHistory.map((m, i) => (
                             <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                                <div className={`max-w-[80%] p-3 rounded-2xl text-xs font-medium shadow-sm ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none'}`}>
                                   {m.text}
                                   {/* ATTACHMENT DISPLAY */}
                                   {m.attachmentUrl && (
                                     <div className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20" onClick={() => window.open(m.attachmentUrl, '_blank')}>
                                        <FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Ver Anexo</span>
                                        {/* SAVE TO FILES BUTTON FOR INCOMING */}
                                        {m.sender !== 'Secretaria' && (
                                          <button onClick={(e) => { e.stopPropagation(); handleSaveToFiles(m.attachmentUrl, `Anexo de ${tickets.find(t=>t.id===selectedTicketId)?.user} - ${Date.now()}`); }} className="ml-2 p-1.5 bg-white text-slate-900 rounded-md shadow-sm hover:text-indigo-600" title="Salvar nos Arquivos"><Save size={12}/></button>
                                        )}
                                     </div>
                                   )}
                                </div>
                                <span className="text-[8px] text-slate-400 mt-1 font-bold uppercase px-1">{m.sender}</span>
                             </div>
                           ))}
                           <div ref={chatEndRef}/>
