                 <button onClick={() => { setOpSubView('transferencia'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'transferencia' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><ArrowRightLeft size={18}/><span className="text-xs font-black uppercase">Transferência</span></button>
                 <button onClick={() => { setOpSubView('validacao'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'validacao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><UserCheck size={18}/><span className="text-xs font-black uppercase">Auditoria</span></button>
