                                  <input type="date" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={editingStudent.nascimento || ''} onChange={e => setEditingStudent({...editingStudent, nascimento: e.target.value})} />
                              </div>
                          </div>

                          <div className="space-y-4">
                              <h3 className="text-xs font-black uppercase italic text-indigo-600 border-b pb-2">Contato & Endereço</h3>
                              <div className="space-y-2">
                                  <label className="text-[9px] font-bold uppercase text-slate-400">Email</label>
                                  <input className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={editingStudent.email || ''} onChange={e => setEditingStudent({...editingStudent, email: e.target.value})} />
                              </div>
                              <div className="space-y-2">
                                  <label className="text-[9px] font-bold uppercase text-slate-400">Telefone / WhatsApp</label>
                                  <div className="flex gap-2">
                                      <input className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={editingStudent.telefone || ''} onChange={e => setEditingStudent({...editingStudent, telefone: e.target.value})} />
                                      <a href={`https://wa.me/55${editingStudent.telefone?.replace(/\D/g, '')}?text=Olá ${editingStudent.displayName}, estamos validando sua matrícula e precisamos confirmar alguns dados.`} target="_blank" className="p-3 bg-emerald-500 text-white rounded-xl shadow-lg hover:bg-emerald-600 flex items-center gap-2 text-[9px] font-black uppercase whitespace-nowrap"><Phone size={14}/> Solicitar Dados</a>
                                  </div>
                              </div>
                              <div className="space-y-2">
                                  <label className="text-[9px] font-bold uppercase text-slate-400">Endereço Completo</label>
