                              </div>
                          </div>
                      </div>

                      {/* Document Preview (Mock) */}
                      <div className="bg-slate-50 p-6 rounded-2xl border-2 border-dashed border-slate-200">
                          <h4 className="text-xs font-black uppercase italic text-slate-400 mb-4 text-center">Documentos Anexados (Identidade/Comp. Residência)</h4>
                          <div className="flex justify-center gap-4">
                              {editingStudent.photoURL ? (
                                  <img src={editingStudent.photoURL} className="h-32 rounded-lg shadow-md border border-white" alt="Doc" />
                              ) : (
                                  <div className="h-32 w-32 bg-slate-200 rounded-lg flex items-center justify-center text-slate-400 text-[10px] font-bold uppercase">Sem Foto</div>
                              )}
                          </div>
                      </div>
                  </div>

                  <footer className="bg-white p-6 border-t border-slate-100 flex justify-between items-center shrink-0 shadow-[0_-10px_40px_rgba(0,0,0,0.05)]">
                      <button onClick={saveEditedStudent} className="px-6 py-3 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase hover:bg-slate-200 flex items-center gap-2"><Edit3 size={14}/> Salvar Edições</button>
