                          <button onClick={rejectStudent} className="px-6 py-3 bg-rose-50 text-rose-600 border border-rose-100 rounded-xl text-[10px] font-black uppercase hover:bg-rose-600 hover:text-white transition-all flex items-center gap-2 shadow-sm"><Ban size={14}/> Rejeitar / Pendenciar</button>
                          <button onClick={validateStudent} className="px-8 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-emerald-700 transition-all flex items-center gap-2 shadow-xl shadow-emerald-200"><Check size={16}/> Validar Matrícula</button>
                      </div>
                  </footer>
              </div>
          </div>
