                         </div>
                       )}
                    </div>
                    {/* Render Interactive Buttons if present */}
                    {m.sender === 'Sistema' && m.options && (activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado') && (
                        <div className="mt-3 flex flex-wrap gap-2 max-w-[80%]">
                            {m.options.map((opt: string) => (
                                <button key={opt} onClick={() => handleBotOption(opt)} className="px-4 py-2 bg-indigo-50 text-indigo-600 border border-indigo-100 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-600 hover:text-white transition-all shadow-sm">
                                    {opt}
                                </button>
                            ))}
                        </div>
                    )}
                    <span className="text-[8px] font-bold text-slate-300 mt-1 uppercase px-2">{m.sender} • {m.createdAt?.seconds ? new Date(m.createdAt.seconds * 1000).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '...'}</span>
                 </div>
               ))}
               <div ref={chatEndRef} />

               {/* SATISFACTION SURVEY OVERLAY */}
               {(activeTicket.status === 'Resolvido' || activeTicket.status === 'Finalizado') && (
                 <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-sm z-50 flex items-center justify-center p-8">
                    <div className="bg-white w-full max-w-md rounded-3xl p-8 shadow-2xl animate-in zoom-in-95">
                       <h3 className="text-xl font-black text-slate-900 uppercase italic text-center mb-6">Pesquisa de Satisfação</h3>
                       <div className="space-y-6">
                          <div>
                             <p className="text-[10px] font-bold uppercase text-slate-500 mb-2">1. Sua demanda foi atendida?</p>
                             <div className="flex gap-2">
                                <button onClick={() => setSurvey({...survey, demandMet: true})} className={`flex-1 py-2 rounded-lg border text-xs font-black uppercase ${survey.demandMet === true ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white border-slate-200'}`}>Sim</button>
                                <button onClick={() => setSurvey({...survey, demandMet: false})} className={`flex-1 py-2 rounded-lg border text-xs font-black uppercase ${survey.demandMet === false ? 'bg-rose-600 text-white border-rose-600' : 'bg-white border-slate-200'}`}>Não</button>
                             </div>
                          </div>
                          <div>
                             <p className="text-[10px] font-bold uppercase text-slate-500 mb-2">2. Seu problema foi resolvido?</p>
                             <div className="flex gap-2">
                                <button onClick={() => setSurvey({...survey, problemSolved: true})} className={`flex-1 py-2 rounded-lg border text-xs font-black uppercase ${survey.problemSolved === true ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white border-slate-200'}`}>Sim</button>
                                <button onClick={() => setSurvey({...survey, problemSolved: false})} className={`flex-1 py-2 rounded-lg border text-xs font-black uppercase ${survey.problemSolved === false ? 'bg-rose-600 text-white border-rose-600' : 'bg-white border-slate-200'}`}>Não</button>
                             </div>
                          </div>
                          <div>
                             <p className="text-[10px] font-bold uppercase text-slate-500 mb-2">3. Gostou do atendimento?</p>
                             <div className="flex gap-2">
                                <button onClick={() => setSurvey({...survey, likedChat: true})} className={`flex-1 py-2 rounded-lg border text-xs font-black uppercase ${survey.likedChat === true ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-white border-slate-200'}`}><ThumbsUp size={16} className="mx-auto"/></button>
                                <button onClick={() => setSurvey({...survey, likedChat: false})} className={`flex-1 py-2 rounded-lg border text-xs font-black uppercase ${survey.likedChat === false ? 'bg-rose-600 text-white border-rose-600' : 'bg-white border-slate-200'}`}><ThumbsDown size={16} className="mx-auto"/></button>
                             </div>
                          </div>
                          <div>
                             <p className="text-[10px] font-bold uppercase text-slate-500 mb-2">Recomendação (Estrelas)</p>
                             <div className="flex justify-center gap-2">
                                {[1,2,3,4,5].map(s => (
                                  <button key={s} onClick={() => setSurvey({...survey, rating: s})} className={`text-2xl transition-all hover:scale-125 ${s <= survey.rating ? 'text-amber-400' : 'text-slate-200'}`}>★</button>
                                ))}
                             </div>
                          </div>
                          <button onClick={submitSurvey} disabled={survey.rating === 0 || survey.demandMet === null} className="w-full py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase shadow-lg hover:bg-indigo-600 disabled:opacity-50 disabled:cursor-not-allowed transition-all">Enviar e Finalizar</button>
                       </div>
                    </div>
                 </div>
               )}
            </div>

            {activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado' ? (
              <div className="p-4 border-t border-slate-100 bg-white">
                 <div className="flex gap-3">
                    <button onClick={() => fileInputRef.current?.click()} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-indigo-100 hover:text-indigo-600 transition-all"><Paperclip size={18}/></button>
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload}/>
                    <input value={newMessage} onChange={e => setNewMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendMessage()} className="flex-1 bg-slate-50 border-none rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600" placeholder="Digite sua mensagem..." />
                    <button onClick={sendMessage} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all"><Send size={18}/></button>
                 </div>
              </div>
            ) : (
              <div className="p-4 bg-slate-100 text-center text-[10px] font-black uppercase text-slate-400">Atendimento Encerrado.</div>
            )}
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-4">
             <LifeBuoy size={64} className="opacity-20"/>
             <p className="text-xs font-black uppercase tracking-widest opacity-50">Selecione um chamado ou inicie um novo.</p>

             {/* FAQ SECTION */}
             <div className="max-w-md w-full mt-8 space-y-3 px-8">
                <h4 className="text-[10px] font-black uppercase text-indigo-400 text-center mb-4 tracking-widest">Perguntas Frequentes</h4>
                {[{q: 'Como baixo meu certificado?', a: 'Após concluir todas as aulas e exames com média 70%, o certificado aparecerá na aba "Galeria de Diplomas".'}, {q: 'Como alterar minha senha?', a: 'Vá em "Meu Perfil" e use a seção de segurança para redefinir sua senha.'}].map((faq, i) => (
                  <details key={i} className="group bg-slate-50 rounded-xl border border-slate-100 open:bg-white open:shadow-lg transition-all cursor-pointer">
                     <summary className="p-4 text-[10px] font-black uppercase text-slate-600 flex justify-between items-center list-none">{faq.q} <ChevronDown size={14} className="group-open:rotate-180 transition-transform"/></summary>
                     <div className="px-4 pb-4 text-[10px] text-slate-500 leading-relaxed">{faq.a}</div>
                  </details>
                ))}
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

// --- MAIN VIEW ---
const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [enrolledCourses, setEnrolledCourses] = useState<Course[]>([]);
  const [selectedClassroomCourse, setSelectedClassroomCourse] = useState<Course | null>(null);
  const [timelineModules, setTimelineModules] = useState<{module: Module, items: TimelineItem[]}[]>([]);
  const [activeTimelineItem, setActiveTimelineItem] = useState<TimelineItem | null>(null);
  const [studentProgress, setStudentProgress] = useState<Record<string, any>>({});
  const [loading, setLoading] = useState(true);

  // Profile & System
  const [userData, setUserData] = useState<any>(null);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [scheduledClasses, setScheduledClasses] = useState<ScheduledClass[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showTermsModal, setShowTermsModal] = useState(false);
  const [editForm, setEditForm] = useState<any>({});
  const [confirmPassword, setConfirmPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [showNotificationsDropdown, setShowNotificationsDropdown] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const enterClassroom = (course: Course) => {
    setSelectedClassroomCourse(course);
    setActiveSubView('classroom');
  };

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      try {
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          const data = userDoc.data();
          setUserData(data);
          setEditForm(data);
          setStudentProgress(data.progress || {});

          if (data.status === 'ativo' && !data.termsAccepted) setShowTermsModal(true);

          let courseIds = data.matriculas || [];
          if (courseIds.length === 0 && (data.cursoInicial || data.cursoId)) courseIds = [data.cursoInicial || data.cursoId];

          if (courseIds.length > 0) {
             const q = query(collection(db, 'cursos'), where('__name__', 'in', courseIds.slice(0, 10)));
             const querySnapshot = await getDocs(q);
             const loadedCourses = querySnapshot.docs.map(d => ({ id: d.id, ...d.data() } as Course));

             // Sort by creation or ID to try and guess "latest". Ideally would use matriculation date.
             // Here we assume the last in the array is the latest for simplicity, or sort by name.
             // Better: if we had enrollment date in `matriculas`, we'd use that.
             // For now, reverse to show latest added first if they were pushed sequentially.
             setEnrolledCourses(loadedCourses.reverse());

             const agendaQuery = query(collection(db, 'scheduledClasses'), where('courseId', 'in', courseIds.slice(0, 10)), where('date', '>=', new Date()));
             onSnapshot(agendaQuery, (snap) => {
                const classes = snap.docs.map(d => ({ id: d.id, ...d.data() } as ScheduledClass));
                setScheduledClasses(classes.sort((a,b) => {
                   const dateA = a.date?.seconds ? new Date(a.date.seconds * 1000) : new Date(a.date);
                   const dateB = b.date?.seconds ? new Date(b.date.seconds * 1000) : new Date(b.date);
                   return dateA.getTime() - dateB.getTime();
                }));
             });
          }
        }
      } catch (error) { console.error("Sync Error", error); }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  // HIERARCHICAL TIMELINE BUILDER
  useEffect(() => {
    if (!selectedClassroomCourse || !userData) return;

    const buildTimeline = async () => {
      // 1. Get Modules sorted by Order
      const modQ = query(collection(db, 'modulos'), where('courseId', '==', selectedClassroomCourse.id));
      const modSnap = await getDocs(modQ);
      const modules = modSnap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));

      // 2. Get Exams
      const examQ = query(collection(db, 'exams'), where('courseId', '==', selectedClassroomCourse.id));
      const examSnap = await getDocs(examQ);
      const exams = examSnap.docs.map(d => ({ id: d.id, ...d.data() } as Exam));

      const structuredTimeline: {module: Module, items: TimelineItem[]}[] = [];
      let globalIndex = 0;
      let previousCompleted = true; // First item is always unlocked

      modules.forEach(mod => {
        const moduleItems: TimelineItem[] = [];

        const lessons = (mod.lessons || []).sort((a,b) => (a.order||0)-(b.order||0));

        lessons.forEach(lesson => {
          const itemProgress = studentProgress[selectedClassroomCourse.id]?.[lesson.id] || {};
          const isCompleted = itemProgress.completed === true;
          const isLocked = !previousCompleted;

          moduleItems.push({
            id: lesson.id,
            type: 'lesson',
            title: lesson.title,
            moduleId: mod.id,
            moduleTitle: mod.title,
            data: lesson,
            isLocked,
            isCompleted,
            index: globalIndex++
          });
          previousCompleted = isCompleted;
        });

        exams.filter(e => e.moduleId === mod.id).forEach(exam => {
          const itemProgress = studentProgress[selectedClassroomCourse.id]?.[exam.id] || {};
          const isCompleted = itemProgress.completed === true;
          const isLocked = !previousCompleted;

          moduleItems.push({
            id: exam.id,
            type: 'exam',
            title: exam.title,
            moduleId: mod.id,
            moduleTitle: mod.title,
            data: exam,
            isLocked,
            isCompleted,
            index: globalIndex++
          });
          previousCompleted = isCompleted;
        });

        if (moduleItems.length > 0) {
          structuredTimeline.push({ module: mod, items: moduleItems });
        }
      });

      setTimelineModules(structuredTimeline);

      if (!activeTimelineItem) {
        let firstActive: TimelineItem | null = null;
        for (const group of structuredTimeline) {
          for (const item of group.items) {
            if (!item.isLocked && !item.isCompleted) {
              firstActive = item;
              break;
            }
          }
          if (firstActive) break;
        }
        if (firstActive) setActiveTimelineItem(firstActive);
        else if (structuredTimeline.length > 0 && structuredTimeline[0].items.length > 0) setActiveTimelineItem(structuredTimeline[0].items[0]);
      }
    };

    buildTimeline();
  }, [selectedClassroomCourse, studentProgress]);

  const markItemComplete = async (itemId: string, score?: number) => {
    if (!selectedClassroomCourse) return;
    const newProgress = {
      ...studentProgress,
      [selectedClassroomCourse.id]: {
        ...(studentProgress[selectedClassroomCourse.id] || {}),
        [itemId]: { completed: true, score }
      }
    };
    setStudentProgress(newProgress);
    await updateDoc(doc(db, 'users', user.uid), {
      [`progress.${selectedClassroomCourse.id}.${itemId}`]: { completed: true, score }
    });
  };

  const handleUpdateProfile = async () => {
    try {
      if (newPassword) {
          if (newPassword !== confirmPassword) {
              alert("As senhas não conferem!");
              return;
          }
          if (newPassword.length < 6) {
              alert("A senha deve ter pelo menos 6 caracteres.");
              return;
          }
          await updatePassword(auth.currentUser!, newPassword);
          setNewPassword('');
          setConfirmPassword('');
      }

      await updateDoc(doc(db, 'users', user.uid), { ...editForm, updatedAt: serverTimestamp() });
      setUserData(editForm);
      alert("Perfil atualizado com sucesso!");
    } catch (e: any) { alert("Erro: " + e.message); }
  };

  const handleCepSearch = async (cep: string) => {
    const cleanCep = cep.replace(/\D/g, '');
    setEditForm((prev: any) => ({ ...prev, endereco: { ...prev.endereco, cep: cleanCep } }));
    if (cleanCep.length === 8) {
      try {
        const res = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`);
        const data = await res.json();
        if (!data.erro) {
          setEditForm((prev: any) => ({
            ...prev,
            endereco: { 
              ...prev.endereco, 
              rua: data.logradouro, 
              bairro: data.bairro, 
              cidade: data.localidade, 
              uf: data.uf 
            }
          }));
        }
      } catch (e) { console.error("CEP error", e); }
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const img = new Image();
        img.src = reader.result as string;
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const scale = 800 / img.width;
          canvas.width = 800;
          canvas.height = img.height * scale;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
          setEditForm({ ...editForm, photoURL: canvas.toDataURL('image/jpeg', 0.7) });
        };
      };
      reader.readAsDataURL(file);
    }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-slate-50"><RefreshCw className="animate-spin text-indigo-600"/></div>;

  return (
    <div className="min-h-screen bg-slate-50 flex overflow-hidden font-sans relative">
      {/* SIDEBAR NAVIGATION */}
      {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="fixed inset-0 bg-slate-900/60 z-[60] lg:hidden backdrop-blur-sm"></div>}
      <aside className={`fixed lg:static inset-y-0 left-0 bg-slate-900 w-72 flex flex-col transition-transform duration-300 z-[70] ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
         <div className="p-6 border-b border-white/5 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-indigo-600 text-white rounded-lg shadow-lg"><GraduationCap size={20}/></div>
              <div><p className="font-black text-white uppercase italic text-base leading-none">EB-EAD</p><p className="text-[8px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Portal do Aluno</p></div>
            </div>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden p-2 text-white/50 hover:text-white"><X size={20}/></button>
         </div>
         <nav className="flex-1 p-4 space-y-1 mt-2 overflow-y-auto">
            {[
              { id: 'dashboard', label: 'Home Page', icon: <Home size={16}/> },
              { id: 'library', label: 'Meus Cursos', icon: <BookOpen size={16}/> },
              { id: 'certificates', label: 'Galeria de Diplomas', icon: <Award size={16}/> },
              { id: 'support', label: 'Suporte & Ajuda', icon: <LifeBuoy size={16}/> },
              { id: 'profile', label: 'Meu Perfil', icon: <UserCircle size={16}/> }
            ].map(item => (
              <button 
                key={item.id} 
                onClick={() => { setActiveSubView(item.id as any); setIsSidebarOpen(false); setSelectedClassroomCourse(null); }} 
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeSubView === item.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}
              >
                {item.icon} {item.label}
              </button>
            ))}
         </nav>
         <div className="p-6 border-t border-white/5 bg-black/20">
            <div className="flex items-center gap-3 p-3 bg-white/5 rounded-xl border border-white/5 shadow-inner">
               <div className="w-10 h-10 rounded-lg overflow-hidden bg-indigo-600 flex items-center justify-center text-white font-black italic shadow-lg border border-white/10 shrink-0">
                  {userData?.photoURL ? <img src={userData.photoURL} className="w-full h-full object-cover" /> : (userData?.displayName||'U').charAt(0)}
               </div>
               <div className="flex-1 overflow-hidden">
                  <p className="text-[10px] font-black text-white uppercase italic truncate">{userData?.displayName || 'Aluno'}</p>
                  <p className="text-[7px] font-bold text-indigo-400 uppercase mt-0.5 tracking-widest leading-none">Matriculado</p>
               </div>
               <button onClick={() => auth.signOut()} className="text-rose-500 p-2 hover:bg-rose-500/10 rounded-lg transition-all"><LogOut size={16}/></button>
            </div>
         </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
         {/* HEADER */}
         <header className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-6 shadow-sm shrink-0 z-50 relative">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 bg-slate-50 text-slate-400 rounded-lg lg:hidden"><Menu size={18}/></button>
            <div className="flex items-center gap-4 ml-auto">
               <div className="relative">
                 <button onClick={() => setShowNotificationsDropdown(!showNotificationsDropdown)} className={`relative p-2 transition-all rounded-lg ${notifications.length > 0 ? 'text-indigo-600 bg-indigo-50' : 'text-slate-300 hover:text-indigo-600'}`}>
                    <Bell size={18}/>
                    {notifications.length > 0 && <div className="absolute top-2 right-2 w-1.5 h-1.5 bg-rose-500 rounded-full border-2 border-white animate-pulse"></div>}
                 </button>
               </div>
            </div>
         </header>

         {/* MAIN CONTENT AREA */}
         <main className="flex-1 overflow-y-auto p-6 md:p-8 bg-slate-50 custom-scrollbar">
            {activeSubView === 'classroom' && selectedClassroomCourse && activeTimelineItem ? (
              <div className="h-full flex flex-col md:flex-row gap-6 animate-in zoom-in-95">
                 {/* LEFT CONTENT: SPLIT VIDEO AND INFO */}
                 <div className="flex-1 flex flex-col h-full gap-6 overflow-y-auto custom-scrollbar">
                    {/* Header */}
                    <div className="flex items-center justify-between shrink-0">
                       <div>
                          <h2 className="text-lg md:text-xl font-black uppercase italic text-slate-900 tracking-tighter leading-none">{activeTimelineItem.title}</h2>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Módulo: {activeTimelineItem.moduleTitle}</p>
                       </div>
                       <button onClick={() => { setActiveSubView('dashboard'); setSelectedClassroomCourse(null); }} className="px-4 py-2 bg-slate-200 text-slate-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-rose-500 hover:text-white transition-all shadow-sm">Sair</button>
                    </div>

                    {/* VIDEO SECTION - SEPARATE CONTAINER */}
                    <div className="w-full bg-black aspect-video rounded-xl overflow-hidden shadow-xl shrink-0 border border-slate-900">
                       {activeTimelineItem.type === 'lesson' ? (
                         <SecureVideoPlayer 
                           videoUrl={activeTimelineItem.data.videoUrl} 
                           title={activeTimelineItem.title}
                           onComplete={() => markItemComplete(activeTimelineItem.id)}
                         />
                       ) : (
                         <div className="h-full flex items-center justify-center text-white/50 text-xs font-black uppercase tracking-widest italic">Área de Avaliação</div>
                       )}
                    </div>

                    {/* CONTENT CONTAINER - Scroll happens INSIDE here */}
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-8 mb-10">
                       {activeTimelineItem.type === 'lesson' ? (
                          <>
                             <div className="flex flex-col md:flex-row justify-between items-start border-b border-slate-100 pb-6 mb-6 gap-4">
                                <div>
                                  <h3 className="text-sm font-black uppercase text-indigo-600 tracking-widest">Material de Apoio</h3>
                                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-wide mt-1">Recursos da Aula</p>
                                </div>
                                {activeTimelineItem.data.materialUrl && (
                                  <a 
                                    href={activeTimelineItem.isCompleted ? activeTimelineItem.data.materialUrl : undefined} 
                                    target="_blank"
                                    className={`inline-flex items-center gap-3 px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all ${activeTimelineItem.isCompleted ? 'bg-indigo-50 border-indigo-200 text-indigo-700 hover:bg-indigo-600 hover:text-white cursor-pointer shadow-sm' : 'bg-slate-50 border-slate-100 text-slate-400 cursor-not-allowed grayscale'}`}
                                    onClick={(e) => !activeTimelineItem.isCompleted && e.preventDefault()}
                                  >
                                     <FileText size={16}/> {activeTimelineItem.isCompleted ? 'Baixar Arquivo' : 'Conclua a aula para liberar'}
                                  </a>
                                )}
                             </div>

                             <div className="prose prose-sm max-w-none text-slate-600 font-medium leading-relaxed">
                                <h4 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Descrição da Aula</h4>
                                <p className="whitespace-pre-wrap">{activeTimelineItem.data.description || 'Nenhuma descrição fornecida pelo docente para esta aula específica.'}</p>
                             </div>
                          </>
                       ) : activeTimelineItem.type === 'exam' ? (
                         <div className="h-full overflow-y-auto custom-scrollbar p-0">
                            <QuizPlayer 
                              exam={activeTimelineItem.data}
                              onPass={(score) => markItemComplete(activeTimelineItem.id, score)}
                            />
                         </div>
                       ) : null}
                    </div>
