// --- HELPER TO VIEW ATTACHMENTS SAFELY ---
const viewAttachment = (url: string) => {
  if (!url) return;

  // Se for URL HTTP normal
  if (url.startsWith('http')) {
      window.open(url, '_blank');
      return;
  }

  // Se for Data URI (Base64)
  if (url.startsWith('data:')) {
      fetch(url)
          .then(res => res.blob())
          .then(blob => {
              const blobUrl = URL.createObjectURL(blob);
              window.open(blobUrl, '_blank');
              // Revoke URL após um tempo para liberar memória, mas tempo suficiente para o usuário ver
              setTimeout(() => URL.revokeObjectURL(blobUrl), 60000); 
          })
          .catch(err => {
              console.error("Erro ao abrir blob:", err);
              // Fallback para iframe se o fetch falhar
              const win = window.open();
              if(win) win.document.write(`<iframe src="${url}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`);
          });
      return;
  }
};

