// --- HELPER TO VIEW ATTACHMENTS SAFELY ---
const viewAttachment = (url: string) => {
  if (!url) return;

  // Se for URL HTTP normal
  if (url.startsWith('http')) {
      window.open(url, '_blank');
      return;
  }

  // Se for Data URI (Base64)
  // Utiliza iframe para contornar bloqueio de navegação de top-frame para data URLs em navegadores modernos
  if (url.startsWith('data:')) {
      const win = window.open();
      if (win) {
          win.document.write(
              `<iframe src="${url}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`
          );
          win.document.title = "Visualizar Anexo";
          win.document.body.style.margin = "0";
      } else {
          alert("Pop-up bloqueado. Por favor, permita pop-ups para visualizar o anexo.");
      }
      return;
  }
};

