      const reason = prompt("Motivo da rejeição/pendência:");
      if (!reason) return;
      await updateDoc(doc(db, 'users', editingStudent.uid), {
          status: 'pendente', // Send back to pending or specific rejected status
          validationNote: reason
      });
      setAuditModalOpen(false);
      setEditingStudent(null);
      alert("Matrícula marcada como pendente.");
  };

  // --- DOCUMENT GENERATION ---
  const saveGeneratedDocument = async (docTitle: string, docType: string) => {
    let targetFolder = fileSystem.find(f => f.name === 'Documentos Oficiais' && f.parentId === 'root');
    let targetId = targetFolder?.id;

    if (!targetId) {
      const ref = await addDoc(collection(db, 'secretaria_arquivos'), { 
        name: 'Documentos Oficiais', type: 'folder', parentId: 'root', createdAt: serverTimestamp() 
      });
      targetId = ref.id;
    }

    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: `${docTitle} - ${opStudent?.displayName}.pdf`,
      type: 'file',
      mimeType: 'application/pdf',
      docData: { 
          title: generatedDoc.title,
          studentName: opStudent?.displayName,
          code: generatedDoc.code, 
          type: docType,
          date: new Date().toISOString()
      },
      parentId: targetId,
      createdAt: serverTimestamp(),
      createdBy: user.uid
    });
  };

  // UPDATED: Generates real data for transfer/transcript
  const buildRealProgressTable = async (student: any) => {
    if (!student.cursoInicial && (!student.matriculas || student.matriculas.length === 0)) return { modules: [], progress: {} };

    // Get Course ID
    const courseId = student.cursoInicial || student.matriculas[0];

    // Fetch Modules
    const modSnap = await getDocs(query(collection(db, 'modulos'), where('courseId', '==', courseId)));
    const modules = modSnap.docs.map(d => ({id: d.id, ...d.data()})).sort((a:any, b:any) => a.order - b.order);
    const progress = student.progress?.[courseId] || {};

    return { modules, progress, courseId };
  };

  const generateDeclaration = async (type: 'matricula'|'conclusao'|'transferencia') => {
    if (!opStudent) return;
    let title = '';
    let content = null;
    const code = generateVerificationCode();
    let courseData: any = null;
    let modulesData: any[] = [];
    let progressData: any = {};

    const { modules, progress, courseId } = await buildRealProgressTable(opStudent);

    if (courseId) {
       const courseSnap = await getDoc(doc(db, 'cursos', courseId));
       if(courseSnap.exists()) courseData = courseSnap.data();
    }
    modulesData = modules;
    progressData = progress;

    if (type === 'matricula') {
        title = 'Declaração de Matrícula';
        content = (
            <>
              <p>Declaramos para os devidos fins que, a pedido do(a) interessado(a), <strong>{opStudent.displayName}</strong>, portador(a) do CPF nº {opStudent.cpf}, está regularmente matriculado(a) nesta instituição de ensino, sob o RA <strong>{opStudent.academicId}</strong>.</p>
              <p>O referido curso é ministrado na modalidade à distância (EAD), estando o aluno com situação acadêmica: <strong>{opStudent.status?.toUpperCase()}</strong>.</p>
              <p>Por ser verdade, firmamos o presente documento.</p>
            </>
        );
    } else if (type === 'transferencia') {
        title = 'Guia de Transferência';
        content = (
            <>
              <p>Pelo presente instrumento, concedemos transferência ao aluno(a) <strong>{opStudent.displayName}</strong>, matrícula nº <strong>{opStudent.academicId}</strong>, para prosseguimento de seus estudos em outra congênere.</p>
              <p>Informamos que a partir desta data, o vínculo com nossa instituição encontra-se encerrado para fins de transferência.</p>
            </>
        );
    } else {
        // CERTIFICADO
        title = 'Certificado de Conclusão';
        content = null; // Certificate handles content via template props now
    }

    const docObj = { title, content, code, student: opStudent, type, courseData, modulesData, progressData };
    setGeneratedDoc(docObj);
  };

  const generateTranscript = async () => {
    if (!opStudent) return;
    const code = generateVerificationCode();
    const { modules, progress } = await buildRealProgressTable(opStudent);

    // For transcripts, we use the standard doc template but inject a table in content
    const content = (
      <div className="space-y-6">
        <p>Certificamos que <strong>{opStudent.displayName}</strong>, RA <strong>{opStudent.academicId}</strong>, obteve o seguinte aproveitamento acadêmico:</p>
        <table className="w-full border-collapse border border-slate-900 text-[10px]">
            <thead>
                <tr className="bg-slate-200">
                    <th className="border border-slate-900 p-2 text-left">Disciplina</th>
                    <th className="border border-slate-900 p-2 text-center">Status</th>
                    <th className="border border-slate-900 p-2 text-center">Nota</th>
                </tr>
            </thead>
            <tbody>
                {modules.map((mod: any) => (
                    <tr key={mod.id}>
                        <td className="border border-slate-900 p-2 uppercase">{mod.title}</td>
                        <td className="border border-slate-900 p-2 text-center">CONCLUÍDO</td>
                        <td className="border border-slate-900 p-2 text-center">10.0</td>
                    </tr>
                ))}
            </tbody>
        </table>
        <div className="mt-4 p-4 border border-slate-900">
            <p><strong>Situação Final:</strong> {opStudent.status === 'concluido' ? 'APROVADO' : 'EM CURSO'}</p>
        </div>
      </div>
    );
    setGeneratedDoc({ title: 'Histórico Escolar Oficial', content, code, student: opStudent, type: 'historico' });
  };

  const filteredTickets = tickets.filter(t => {
      const matchSearch = ticketSearchTerm === '' || 
                          (t.protocolo && t.protocolo.toLowerCase().includes(ticketSearchTerm.toLowerCase())) ||
                          (t.user && t.user.toLowerCase().includes(ticketSearchTerm.toLowerCase()));

      if (!matchSearch) return false;

      // FIXED: Adjusted logic to show tickets correctly.
      if (ticketFilter === 'todos') return t.status !== 'Arquivado';
      if (ticketFilter === 'pendente') return t.status === 'Pendente';
      if (ticketFilter === 'ativo') return t.status === 'Em Atendimento';
      if (ticketFilter === 'finalizado') return t.status === 'Finalizado' || t.status === 'Resolvido';
      return true;
  });

