    return {
      pendentes: tickets.filter(t => t.status === 'Pendente').length,
      ativos: tickets.filter(t => t.status === 'Em Atendimento').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado' || t.status === 'Resolvido').length,
