                                        <td className="px-6 py-4 text-slate-500 italic text-[10px]">{t.updatedAt?.seconds ? new Date(t.updatedAt.seconds * 1000).toLocaleString() : '---'}</td>
                                        <td className="px-6 py-4">
                                            <div className="flex justify-center gap-2">
                                                {t.status === 'Pendente' && (
                                                    <button onClick={() => handleAssumeTicket(t.id)} className="px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-lg text-[8px] font-black uppercase border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all">Assumir</button>
