         {/* --- TAB: CHAT (INTEGRATED) --- */}
         {(activeTab === 'chat' || selectedTicketId) && activeTab !== 'atendimento' && activeTab !== 'arquivos' && activeTab !== 'operacional' && (
            <div className="h-full flex flex-col bg-white border border-slate-200 rounded-xl overflow-hidden shadow-lg">
                {selectedTicketId ? (
                    <>
                        <div className="p-4 border-b bg-slate-50 flex justify-between items-center shadow-sm z-10">
                           <div className="flex items-center gap-3">
                               <button onClick={() => { setSelectedTicketId(null); setActiveTab('atendimento'); }} className="p-2 bg-white border border-slate-200 rounded-lg hover:bg-slate-100"><CornerUpLeft size={16}/></button>
                               <div>
                                   <h4 className="font-bold text-sm uppercase text-slate-800">{tickets.find(t=>t.id===selectedTicketId)?.user}</h4>
                                   <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Protocolo: {tickets.find(t=>t.id===selectedTicketId)?.protocolo}</p>
                               </div>
                           </div>
                           <div className="flex gap-2">
                               <button onClick={() => setAttachMode(true)} className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 border border-indigo-100 hover:bg-indigo-100"><Paperclip size={14}/> Anexar Arquivo</button>
                               <button onClick={() => handleCloseTicket(selectedTicketId)} className="px-4 py-2 bg-rose-600 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-rose-700 shadow-lg"><CheckCircle2 size={14}/> Finalizar</button>
                           </div>
