// --- HELPER TO VIEW ATTACHMENTS SAFELY ---
const viewAttachment = (url: string) => {
  if (!url) return;

  if (url.startsWith('http')) {
      window.open(url, '_blank');
      return;
  }

  if (url.startsWith('data:')) {
      try {
          // Convert Base64 to Blob for reliable opening in modern browsers
          const byteString = atob(url.split(',')[1]);
          const mimeString = url.split(',')[0].split(':')[1].split(';')[0];
          const ab = new ArrayBuffer(byteString.length);
          const ia = new Uint8Array(ab);
          for (let i = 0; i < byteString.length; i++) {
              ia[i] = byteString.charCodeAt(i);
          }
          const blob = new Blob([ab], {type: mimeString});
          const blobUrl = URL.createObjectURL(blob);

          const win = window.open(blobUrl, '_blank');
          if (!win) {
             alert("Pop-up bloqueado. Por favor, permita pop-ups para visualizar o anexo.");
          }
      } catch (e) {
          console.error("Erro ao abrir anexo:", e);
          alert("Erro ao processar o arquivo. Tente novamente.");
      }
      return;
  }
};

