                                <td className="border border-slate-900 p-2 text-center font-bold">APROVADO</td>
                             </tr>
                          );
                       })}
                       {(!modulesData || modulesData.length === 0) && (
                          <tr><td colSpan={5} className="border border-slate-900 p-4 text-center italic">Dados curriculares não disponíveis.</td></tr>
