                    <p>Escola Bíblica EAD - CNPJ 00.000.000/0001-00</p>
                 </div>
                 <div className="text-center">
                    <div className="border-b border-slate-900 w-64 mb-1"></div>
                    <p>Secretaria Acadêmica</p>
                 </div>
              </div>
           </div>
        </div>
      </div>
    );
  }

  // STANDARD DOCUMENT TEMPLATE (DECLARATIONS, TRANSFERS) - Portrait
  return (
    <div id="official-cert-container" className="bg-white p-12 text-slate-900 font-serif max-w-[210mm] mx-auto border shadow-lg relative min-h-[297mm]">
      <style>{printStyles}</style>
