        <div className="grid grid-cols-2 gap-12 text-center">
          <div className="flex flex-col items-center">
             <div className="h-12 w-48 border-b border-slate-300 mb-2 flex items-end justify-center">
               <span className="text-[8px] text-slate-300 italic mb-1">Assinatura Digital</span>
             </div>
            <p className="text-xs font-bold uppercase">Diretor Executivo</p>
            <p className="text-[10px] text-slate-500">Reg. 12345-AB</p>
          </div>
          <div className="flex flex-col items-center">
            {signatures.secretary ? <img src={signatures.secretary} className="h-12 mb-2 object-contain" /> : <div className="h-12 w-48 border-b border-slate-300 mb-2"></div>}
            <p className="text-xs font-bold uppercase">Secretário(a) Geral</p>
            <p className="text-[10px] text-slate-500">Reg. 98765-CD</p>
          </div>
        </div>
        <div className="mt-12 text-center">
          <div className="inline-block p-2 border border-slate-900 rounded">
             <p className="text-[8px] font-mono font-bold uppercase">Autenticação Digital</p>
             <p className="text-[10px] font-mono">{code}</p>
          </div>
          <p className="text-[8px] text-slate-400 mt-2 uppercase">Este documento possui validade nacional conforme lei 9.394/96.</p>
          <p className="text-[7px] text-slate-300 mt-1">Gerado eletronicamente via Sistema EB-EAD.</p>
        </div>
      </div>
    </div>
  );
};

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');

  // Data States
  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [fileSystem, setFileSystem] = useState<any[]>([]);

  // UI States - Atendimento
  const [ticketSearchTerm, setTicketSearchTerm] = useState('');
  const [ticketFilter, setTicketFilter] = useState<'todos' | 'pendente' | 'ativo' | 'finalizado'>('todos');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  // UI States - General
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  // File Explorer State
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [attachMode, setAttachMode] = useState(false); // If picking file for chat

  // Operational State
  const [opStudent, setOpStudent] = useState<any>(null);
  const [generatedDoc, setGeneratedDoc] = useState<any>(null);

  // Audit Modal State
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Ticket Listener - Fixed to show all relevant tickets
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        // Sort by update time desc
        t.sort((a:any, b:any) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
        setTickets(t);
    });

    // File System Listener
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    // Students Listener (All students for search/validation)
    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    // Get Signature
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid]);

  // Sync Chat
  useEffect(() => {
    if (!selectedTicketId) { setChatHistory([]); return; }
    const q = query(collection(db, 'tickets', selectedTicketId, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setChatHistory(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [selectedTicketId]);

  // --- FILE EXPLORER LOGIC ---
  const currentItems = useMemo(() => {
    return fileSystem.filter(f => f.parentId === currentFolderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  }, [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      if (ev.target?.result) {
        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name,
          type: 'file',
          mimeType: file.type,
          url: ev.target.result, 
          parentId: currentFolderId,
          size: file.size,
          createdAt: serverTimestamp(),
          createdBy: user.uid
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id);
    setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  // --- CHAT & TICKET LOGIC ---
  const handleSaveToFiles = async (fileData: any, fileName: string) => {
    let targetFolder = fileSystem.find(f => f.name === 'Uploads do Chat' && f.parentId === 'root');
    let targetId = targetFolder?.id;

    if (!targetId) {
      const ref = await addDoc(collection(db, 'secretaria_arquivos'), { 
        name: 'Uploads do Chat', type: 'folder', parentId: 'root', createdAt: serverTimestamp() 
      });
      targetId = ref.id;
    }

    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: fileName, type: 'file', url: fileData, parentId: targetId, createdAt: serverTimestamp(), source: 'chat'
    });
    alert("Arquivo salvo na pasta 'Uploads do Chat'!");
  };

  // UPDATED: Sends a file from the Explorer to the active chat
  const handleSendFileFromExplorer = async (file: any) => {
    if (!selectedTicketId) return;
    await addDoc(collection(db, 'tickets', selectedTicketId, 'messages'), {
      text: `Arquivo enviado pela Secretaria: ${file.name}`,
      attachmentUrl: file.url, // Ensure this URL is accessible
      sender: 'Secretaria',
      createdAt: serverTimestamp()
    });
    setAttachMode(false);
    setActiveTab('chat');
  };

  const handleSendMessage = async () => {
    if (!chatMessage.trim() || !selectedTicketId) return;
    await addDoc(collection(db, 'tickets', selectedTicketId, 'messages'), {
      text: chatMessage,
      sender: 'Secretaria',
      createdAt: serverTimestamp()
    });
    await updateDoc(doc(db, 'tickets', selectedTicketId), {
        lastMessage: chatMessage,
        updatedAt: serverTimestamp()
    });
    setChatMessage('');
  };

  const handleAssumeTicket = async (ticketId: string) => {
      await updateDoc(doc(db, 'tickets', ticketId), {
          status: 'Em Atendimento',
          attendant: user.displayName
      });
      alert('Você assumiu este atendimento.');
  };

  const handleCloseTicket = async (ticketId: string) => {
      if(!confirm("Deseja finalizar este atendimento?")) return;
      await updateDoc(doc(db, 'tickets', ticketId), {
          status: 'Finalizado'
      });
      setSelectedTicketId(null);
      setActiveTab('atendimento');
  };

  // --- AUDIT LOGIC ---
  const openAuditModal = (student: any) => {
      setEditingStudent({ ...student }); 
      setAuditModalOpen(true);
  };

  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      await updateDoc(doc(db, 'users', editingStudent.uid), {
          ...editingStudent,
          updatedAt: serverTimestamp()
      });
      alert("Dados do aluno atualizados com sucesso.");
  };

  const validateStudent = async () => {
      if (!editingStudent) return;
      await updateDoc(doc(db, 'users', editingStudent.uid), {
          status: 'ativo',
          validatedAt: serverTimestamp(),
          validatedBy: user.uid
      });
      setAuditModalOpen(false);
      setEditingStudent(null);
      alert("Matrícula VALIDADA com sucesso!");
  };

  const rejectStudent = async () => {
      if (!editingStudent) return;
      const reason = prompt("Motivo da rejeição/pendência:");
      if (!reason) return;
      await updateDoc(doc(db, 'users', editingStudent.uid), {
          status: 'pendente', // Send back to pending or specific rejected status
          validationNote: reason
      });
      setAuditModalOpen(false);
      setEditingStudent(null);
      alert("Matrícula marcada como pendente.");
  };

  // --- DOCUMENT GENERATION ---
  const saveGeneratedDocument = async (docTitle: string, docType: string) => {
    let targetFolder = fileSystem.find(f => f.name === 'Documentos Oficiais' && f.parentId === 'root');
    let targetId = targetFolder?.id;

    if (!targetId) {
      const ref = await addDoc(collection(db, 'secretaria_arquivos'), { 
        name: 'Documentos Oficiais', type: 'folder', parentId: 'root', createdAt: serverTimestamp() 
      });
      targetId = ref.id;
    }

    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: `${docTitle} - ${opStudent?.displayName}.pdf`,
      type: 'file',
      mimeType: 'application/pdf',
      docData: { 
          title: generatedDoc.title,
          student: generatedDoc.student, 
          code: generatedDoc.code, 
          type: docType,
          date: new Date().toISOString(),
          // Persist extra data needed for rebuilding the view
          courseData: generatedDoc.courseData,
          modulesData: generatedDoc.modulesData,
          progressData: generatedDoc.progressData
      },
      parentId: targetId,
      createdAt: serverTimestamp(),
      createdBy: user.uid
    });
  };

  // UPDATED: Generates real data for transfer/transcript
  const buildRealProgressTable = async (student: any) => {
    if (!student.cursoInicial && (!student.matriculas || student.matriculas.length === 0)) return { modules: [], progress: {} };

    // Get Course ID
    const courseId = student.cursoInicial || student.matriculas[0];

    // Fetch Modules
    const modSnap = await getDocs(query(collection(db, 'modulos'), where('courseId', '==', courseId)));
    const modules = modSnap.docs.map(d => ({id: d.id, ...d.data()})).sort((a:any, b:any) => a.order - b.order);
    const progress = student.progress?.[courseId] || {};

    return { modules, progress, courseId };
  };

  const generateDeclaration = async (type: 'matricula'|'conclusao'|'transferencia') => {
    if (!opStudent) return;
    let title = '';
    let content = null;
    const code = generateVerificationCode();
    let courseData: any = null;
    let modulesData: any[] = [];
    let progressData: any = {};

    const { modules, progress, courseId } = await buildRealProgressTable(opStudent);

    if (courseId) {
       const courseSnap = await getDoc(doc(db, 'cursos', courseId));
       if(courseSnap.exists()) courseData = courseSnap.data();
    }
    modulesData = modules;
    progressData = progress;

    if (type === 'matricula') {
        title = 'Declaração de Matrícula';
        // Content generated in template via renderContent
    } else if (type === 'transferencia') {
        title = 'Guia de Transferência';
        // Content generated in template via renderContent
    } else {
        // CERTIFICADO
        title = 'Certificado de Conclusão';
        content = null; 
    }

    const docObj = { title, content, code, student: opStudent, type, courseData, modulesData, progressData };
    setGeneratedDoc(docObj);
  };

  const generateTranscript = async () => {
    if (!opStudent) return;
    const code = generateVerificationCode();
    const { modules, progress } = await buildRealProgressTable(opStudent);

    // For transcripts, we use the standard doc template but inject a table in content
    const content = (
      <div className="space-y-6">
        <p>Certificamos que <strong>{opStudent.displayName}</strong>, RA <strong>{opStudent.academicId}</strong>, obteve o seguinte aproveitamento acadêmico:</p>
        <table className="w-full border-collapse border border-slate-900 text-[10px]">
            <thead>
                <tr className="bg-slate-200">
                    <th className="border border-slate-900 p-2 text-left">Disciplina</th>
                    <th className="border border-slate-900 p-2 text-center">Status</th>
                    <th className="border border-slate-900 p-2 text-center">Nota</th>
                </tr>
            </thead>
            <tbody>
                {modules.map((mod: any) => (
                    <tr key={mod.id}>
                        <td className="border border-slate-900 p-2 uppercase">{mod.title}</td>
                        <td className="border border-slate-900 p-2 text-center">CONCLUÍDO</td>
                        <td className="border border-slate-900 p-2 text-center">10.0</td>
                    </tr>
                ))}
            </tbody>
        </table>
        <div className="mt-4 p-4 border border-slate-900">
            <p><strong>Situação Final:</strong> {opStudent.status === 'concluido' ? 'APROVADO' : 'EM CURSO'}</p>
        </div>
      </div>
    );
    setGeneratedDoc({ title: 'Histórico Escolar Oficial', content, code, student: opStudent, type: 'historico' });
  };

  const filteredTickets = tickets.filter(t => {
      const matchSearch = ticketSearchTerm === '' || 
                          (t.protocolo && t.protocolo.toLowerCase().includes(ticketSearchTerm.toLowerCase())) ||
                          (t.user && t.user.toLowerCase().includes(ticketSearchTerm.toLowerCase()));

      if (!matchSearch) return false;

      if (ticketFilter === 'todos') return t.status !== 'Arquivado';
      if (ticketFilter === 'pendente') return t.status === 'Pendente';
      if (ticketFilter === 'ativo') return t.status === 'Em Atendimento';
      if (ticketFilter === 'finalizado') return t.status === 'Finalizado' || t.status === 'Resolvido';
      return true;
  });

  const stats = useMemo(() => {
    return {
      pendentes: tickets.filter(t => t.status === 'Pendente').length,
      ativos: tickets.filter(t => t.status === 'Em Atendimento').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado' || t.status === 'Resolvido').length,
      ged: fileSystem.length
    };
  }, [tickets, fileSystem]);

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
