                            <thead className="bg-slate-50 text-[9px] font-black uppercase text-slate-400 border-b border-slate-100 tracking-widest sticky top-0 z-10">
                                <tr><th className="px-6 py-4">Protocolo</th><th className="px-6 py-4">Aluno / Solicitante</th><th className="px-6 py-4">Status Atual</th><th className="px-6 py-4">Última Interação</th><th className="px-6 py-4 text-center">Ações</th></tr>
                            </thead>
                            <tbody className="text-xs">
                                {filteredTickets.length === 0 ? (
                                    <tr><td colSpan={5} className="p-10 text-center text-slate-400 italic">Nenhum atendimento encontrado com os filtros atuais.</td></tr>
                                ) : filteredTickets.map(t => (
                                    <tr key={t.id} className="border-b border-slate-50 hover:bg-slate-50/50 transition-all">
                                        <td className="px-6 py-4 font-mono font-bold text-indigo-600">#{t.protocolo || t.id.substr(0,6).toUpperCase()}</td>
                                        <td className="px-6 py-4 font-bold text-slate-800 uppercase">{t.user}</td>
                                        <td className="px-6 py-4"><span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase border ${t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-100' : t.status === 'Em Atendimento' ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>{t.status}</span></td>
                                        <td className="px-6 py-4 text-slate-500 italic text-[10px]">{t.updatedAt?.seconds ? new Date(t.updatedAt.seconds * 1000).toLocaleString() : '---'}</td>
                                        <td className="px-6 py-4"><div className="flex justify-center gap-2">{t.status === 'Pendente' && <button onClick={() => handleAssumeTicket(t.id)} className="px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-lg text-[8px] font-black uppercase border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all">Assumir</button>}<button onClick={() => { setSelectedTicketId(t.id); setActiveTab('chat'); }} className="p-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-indigo-600 hover:text-white transition-all"><MessageSquare size={14}/></button>{(t.status === 'Em Atendimento' || t.status === 'Pendente') && <button onClick={() => handleCloseTicket(t.id)} className="p-2 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-600 hover:text-white transition-all"><CheckCircle2 size={14}/></button>}</div></td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                 </div>
             </div>
         )}

         {(activeTab === 'chat' || selectedTicketId) && activeTab !== 'atendimento' && activeTab !== 'arquivos' && activeTab !== 'operacional' && (
            <div className="h-full flex flex-col bg-white border border-slate-200 rounded-xl overflow-hidden shadow-lg">
                {selectedTicketId ? (
                    <>
                        <div className="p-4 border-b bg-slate-50 flex justify-between items-center shadow-sm z-10">
                           <div className="flex items-center gap-3"><button onClick={() => { setSelectedTicketId(null); setActiveTab('atendimento'); }} className="p-2 bg-white border border-slate-200 rounded-lg hover:bg-slate-100"><CornerUpLeft size={16}/></button><div><h4 className="font-bold text-sm uppercase text-slate-800">{tickets.find(t=>t.id===selectedTicketId)?.user}</h4><p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Protocolo: {tickets.find(t=>t.id===selectedTicketId)?.protocolo}</p></div></div>
                           <div className="flex gap-2"><button onClick={() => setAttachMode(true)} className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 border border-indigo-100 hover:bg-indigo-100"><Paperclip size={14}/> Anexar Arquivo</button><button onClick={() => handleCloseTicket(selectedTicketId)} className="px-4 py-2 bg-rose-600 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-rose-700 shadow-lg"><CheckCircle2 size={14}/> Finalizar</button></div>
                        </div>
                        <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50 custom-scrollbar">
                           {chatHistory.map((m, i) => (
                             <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                                <div className={`max-w-[80%] p-3 rounded-2xl text-xs font-medium shadow-sm ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none'}`}>
                                   {m.text}
                                   {m.attachmentUrl && (
                                     <div className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20" onClick={() => viewAttachment(m.attachmentUrl)}>
                                        <FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Ver Anexo</span>
                                        {m.sender !== 'Secretaria' && <button onClick={(e) => { e.stopPropagation(); handleSaveToFiles(m.attachmentUrl, `Anexo de ${tickets.find(t=>t.id===selectedTicketId)?.user} - ${Date.now()}`); }} className="ml-2 p-1.5 bg-white text-slate-900 rounded-md shadow-sm hover:text-indigo-600" title="Salvar nos Arquivos"><Save size={12}/></button>}
                                     </div>
                                   )}
                                </div>
                                <span className="text-[8px] text-slate-400 mt-1 font-bold uppercase px-1">{m.sender}</span>
                             </div>
                           ))}
                           <div ref={chatEndRef}/>
                        </div>
                        <div className="p-4 bg-white border-t flex gap-2"><input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} className="flex-1 bg-slate-50 rounded-xl px-4 py-3 text-xs font-bold outline-none border border-transparent focus:border-indigo-200 focus:bg-white transition-all" placeholder="Digite sua mensagem..." /><button onClick={handleSendMessage} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all"><Send size={18}/></button></div>
                    </>
                ) : (
                    <div className="flex-1 flex flex-col items-center justify-center opacity-30 gap-4"><MessageSquare size={48} /><p className="font-black uppercase tracking-widest text-xs">Selecione um Ticket na aba Atendimento</p></div>
                )}
            </div>
         )}

         {/* --- TAB: ARQUIVOS (FILE EXPLORER) --- */}
         {(activeTab === 'arquivos' || attachMode) && (
           <div className={`bg-white border border-slate-200 rounded-xl overflow-hidden h-full flex flex-col shadow-lg ${attachMode ? 'fixed inset-10 z-[3000] border-indigo-600 border-4' : ''}`}>
              <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                 <div className="flex items-center gap-2 overflow-x-auto">
                    <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-200 rounded-lg"><Home size={16}/></button>
                    {folderPath.map((f, i) => (
                      <React.Fragment key={f.id}>
                        {i > 0 && <ChevronRight size={14} className="text-slate-400"/>}
                        <button onClick={() => handleBreadcrumb(i)} className={`text-xs font-bold px-2 py-1 rounded-lg hover:bg-slate-200 ${i === folderPath.length -1 ? 'text-slate-900' : 'text-slate-500'}`}>{f.name}</button>
                      </React.Fragment>
                    ))}
                 </div>
                 <div className="flex gap-2">
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} />
                    <button onClick={() => fileInputRef.current?.click()} className="px-3 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-indigo-600"><UploadCloud size={14}/> Upload</button>
                    <button onClick={handleCreateFolder} className="px-3 py-2 bg-slate-200 text-slate-700 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-slate-300"><FolderPlus size={14}/> Pasta</button>
                    {attachMode && <button onClick={() => setAttachMode(false)} className="px-3 py-2 bg-rose-600 text-white rounded-lg text-[9px] font-black uppercase">Fechar</button>}
                 </div>
              </div>
              <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50/50">
                 {currentItems.length === 0 ? (
                   <div className="h-full flex flex-col items-center justify-center opacity-30 gap-4"><Folder size={48} /><p className="text-xs font-black uppercase">Pasta Vazia</p></div>
                 ) : (
                   <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                      {currentItems.map(item => (
                        <div key={item.id} 
                             onDoubleClick={() => item.type === 'folder' ? handleNavigate(item) : null}
                             onClick={() => attachMode && item.type === 'file' ? handleSendFileFromExplorer(item) : null}
                             className={`bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all group flex flex-col items-center text-center cursor-pointer relative ${attachMode && item.type === 'file' ? 'hover:border-indigo-600 hover:bg-indigo-50' : ''}`}
                        >
                           <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-3 text-white shadow-inner ${item.type === 'folder' ? 'bg-amber-400' : 'bg-indigo-500'}`}>
                              {item.type === 'folder' ? <Folder size={32} className="fill-white/50"/> : <FileText size={32} className="fill-white/50"/>}
                           </div>
                           <p className="text-[10px] font-bold text-slate-700 line-clamp-2 leading-tight w-full break-words">{item.name}</p>
                           {/* Improved logic for file actions: View URL or Open Generated Doc */}
                           {(item.url || item.docData) && !attachMode && (
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 flex gap-1">
                               <button onClick={async (e) => { e.stopPropagation(); if(confirm('Apagar?')) await deleteDoc(doc(db, 'secretaria_arquivos', item.id)); }} className="p-1.5 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100"><X size={12}/></button>
                               {item.url && <a href="#" onClick={(e) => { e.preventDefault(); viewAttachment(item.url); }} className="p-1.5 bg-slate-50 text-slate-600 rounded-lg hover:bg-slate-100"><Eye size={12}/></a>}
                               {item.docData && <button onClick={(e) => { e.preventDefault(); setGeneratedDoc(item.docData); setOpSubView('declaracao'); setActiveTab('operacional'); }} className="p-1.5 bg-slate-50 text-slate-600 rounded-lg hover:bg-slate-100"><Eye size={12}/></button>}
                             </div>
                           )}
                        </div>
                      ))}
                   </div>
                 )}
              </div>
           </div>
         )}

         {/* --- TAB: OPERACIONAL --- */}
         {activeTab === 'operacional' && (
           <div className="h-full flex flex-col md:flex-row gap-6">
              {/* OPERATIONAL SIDEBAR */}
              <div className="w-full md:w-64 flex flex-col gap-3">
                 <button onClick={() => { setOpSubView('declaracao'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'declaracao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><FileText size={18}/><span className="text-xs font-black uppercase">Declarações</span></button>
                 <button onClick={() => { setOpSubView('historico'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'historico' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><Archive size={18}/><span className="text-xs font-black uppercase">Histórico Escolar</span></button>
                 <button onClick={() => { setOpSubView('transferencia'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'transferencia' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><ArrowRightLeft size={18}/><span className="text-xs font-black uppercase">Transferência</span></button>
                 <button onClick={() => { setOpSubView('validacao'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'validacao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><UserCheck size={18}/><span className="text-xs font-black uppercase">Auditoria</span></button>
                 <button onClick={() => setIsSignModalOpen(true)} className="p-4 rounded-xl border bg-white border-slate-200 hover:bg-slate-50 flex items-center gap-3 transition-all"><Fingerprint size={18}/><span className="text-xs font-black uppercase">Minha Assinatura</span></button>
              </div>

              {/* OPERATIONAL CONTENT */}
              <div className="flex-1 bg-white rounded-2xl border border-slate-200 p-1 shadow-sm overflow-hidden relative">
                 {/* VALIDATION (AUDITORIA) */}
                 {opSubView === 'validacao' && (
                    <div className="h-full flex flex-col">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                           <h3 className="text-xs font-black uppercase italic tracking-widest text-slate-800">Auditoria Digital</h3>
                        </div>
                        <div className="flex-1 overflow-auto custom-scrollbar">
                            <table className="w-full text-left border-collapse">
                                <thead className="bg-white border-b border-slate-200 text-[9px] font-black uppercase italic tracking-widest sticky top-0 z-10 text-slate-400">
                                   <tr><th className="px-6 py-3">ID</th><th className="px-6 py-3">Discente</th><th className="px-6 py-3">Status</th><th className="px-6 py-3 text-center">Ação</th></tr>
                                </thead>
                                <tbody className="text-xs">
                                   {students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').map(s => (
                                     <tr key={s.uid} className="border-b border-slate-100 hover:bg-indigo-50/20 transition-all">
                                        <td className="px-6 py-3 font-mono font-black text-indigo-600 text-xs">{s.academicId}</td>
                                        <td className="px-6 py-3"><p className="font-black uppercase text-slate-900 leading-none italic text-xs">{s.displayName}</p></td>
                                        <td className="px-6 py-3 font-bold text-slate-500 uppercase italic text-[10px]">{s.status}</td>
                                        <td className="px-6 py-3 flex items-center justify-center gap-2">
                                           <button onClick={() => openAuditModal(s)} className="p-2 bg-slate-100 text-slate-400 hover:text-indigo-600 rounded-lg"><Eye size={14}/></button>
                                        </td>
                                     </tr>
                                   ))}
                                   {students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').length === 0 && (
                                       <tr><td colSpan={4} className="p-10 text-center text-slate-300 font-bold uppercase italic text-xs">Nenhuma pendência de validação.</td></tr>
                                   )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                 )}

                 {/* DOC GENERATORS */}
                 {(opSubView === 'declaracao' || opSubView === 'historico' || opSubView === 'transferencia') && !generatedDoc && (
                   <div className="max-w-lg mx-auto space-y-6 py-10 px-6">
                      <h3 className="text-xl font-black uppercase italic text-slate-900 border-b pb-4">Gerar {opSubView}</h3>
                      <div className="space-y-2">
                         <label className="text-[10px] font-black uppercase text-slate-400">Selecione o Aluno</label>
                         <select onChange={e => setOpStudent(students.find(s => s.uid === e.target.value))} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold">
                            <option value="">Selecione...</option>
                            {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName} (RA: {s.academicId})</option>)}
                         </select>
                      </div>
                      <div className="pt-4 flex gap-4">
                         {opSubView === 'declaracao' && (
                           <>
                             <button disabled={!opStudent} onClick={() => generateDeclaration('matricula')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50">Dec. Matrícula</button>
                             <button disabled={!opStudent} onClick={() => generateDeclaration('conclusao')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50">Cert. Conclusão</button>
                           </>
                         )}
                         {opSubView === 'transferencia' && (
                           <button disabled={!opStudent} onClick={() => generateDeclaration('transferencia')} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50">Emitir Guia de Transferência</button>
                         )}
                         {opSubView === 'historico' && (
                           <button disabled={!opStudent} onClick={generateTranscript} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50">Gerar Histórico Completo</button>
                         )}
                      </div>
                   </div>
                 )}

                 {/* DOCUMENT PREVIEW */}
                 {generatedDoc && (
                   <div className="h-full overflow-y-auto custom-scrollbar p-6 bg-slate-100">
                      <div className="flex justify-between items-center mb-6 no-print max-w-[800px] mx-auto">
                         <button onClick={() => setGeneratedDoc(null)} className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-slate-900"><CornerUpLeft size={14}/> Voltar</button>
                         <div className="flex gap-2">
                            <button onClick={() => { saveGeneratedDocument(generatedDoc.title, opSubView); alert('Salvo em Arquivos > Documentos Oficiais'); }} className="px-4 py-2 bg-emerald-600 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2"><CheckCircle2 size={14}/> Salvar no Arquivo</button>
                            <button onClick={() => window.print()} className="px-4 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2"><Printer size={14}/> Imprimir</button>
                         </div>
                      </div>
                      <OfficialDocTemplate 
                        title={generatedDoc.title} 
                        content={generatedDoc.content} 
                        student={generatedDoc.student} 
                        code={generatedDoc.code}
                        type={generatedDoc.type}
                        signatures={{ director: null, secretary: secSignature }} 
                        courseData={generatedDoc.courseData}
                        modulesData={generatedDoc.modulesData}
                        progressData={generatedDoc.progressData}
                      />
                   </div>
                 )}
              </div>
           </div>
         )}
      </main>

      {/* --- AUDIT MODAL --- */}
      {auditModalOpen && editingStudent && (
          <div className="fixed inset-0 z-[3000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-white w-full max-w-4xl h-[90vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
                  <header className="bg-slate-50 px-8 py-5 border-b border-slate-100 flex justify-between items-center shrink-0">
                      <div className="flex items-center gap-3">
                          <div className="p-2 bg-indigo-600 text-white rounded-lg shadow-md"><ShieldCheck size={20}/></div>
                          <div>
                              <h2 className="text-lg font-black uppercase italic text-slate-900 leading-none">Auditoria de Prontuário</h2>
                              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Validação Cadastral</p>
                          </div>
                      </div>
                      <button onClick={() => setAuditModalOpen(false)} className="p-2 hover:bg-rose-50 text-slate-400 rounded-full transition-all"><X size={20}/></button>
                  </header>

                  <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-8">
                      {/* Personal Info Edit Section */}
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div className="space-y-4">
                              <h3 className="text-xs font-black uppercase italic text-indigo-600 border-b pb-2">Dados Pessoais</h3>
                              <div className="space-y-2">
                                  <label className="text-[9px] font-bold uppercase text-slate-400">Nome Completo</label>
                                  <input className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={editingStudent.displayName || ''} onChange={e => setEditingStudent({...editingStudent, displayName: e.target.value})} />
                              </div>
                              <div className="space-y-2">
                                  <label className="text-[9px] font-bold uppercase text-slate-400">CPF</label>
                                  <input className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={editingStudent.cpf || ''} onChange={e => setEditingStudent({...editingStudent, cpf: e.target.value})} />
                              </div>
                              <div className="space-y-2">
                                  <label className="text-[9px] font-bold uppercase text-slate-400">Data de Nascimento</label>
                                  <input type="date" className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={editingStudent.nascimento || ''} onChange={e => setEditingStudent({...editingStudent, nascimento: e.target.value})} />
                              </div>
                          </div>

                          <div className="space-y-4">
                              <h3 className="text-xs font-black uppercase italic text-indigo-600 border-b pb-2">Contato & Endereço</h3>
                              <div className="space-y-2">
                                  <label className="text-[9px] font-bold uppercase text-slate-400">Email</label>
                                  <input className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={editingStudent.email || ''} onChange={e => setEditingStudent({...editingStudent, email: e.target.value})} />
                              </div>
                              <div className="space-y-2">
                                  <label className="text-[9px] font-bold uppercase text-slate-400">Telefone / WhatsApp</label>
                                  <div className="flex gap-2">
                                      <input className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" value={editingStudent.telefone || ''} onChange={e => setEditingStudent({...editingStudent, telefone: e.target.value})} />
                                      <a href={`https://wa.me/55${editingStudent.telefone?.replace(/\D/g, '')}?text=Olá ${editingStudent.displayName}, estamos validando sua matrícula e precisamos confirmar alguns dados.`} target="_blank" className="p-3 bg-emerald-500 text-white rounded-xl shadow-lg hover:bg-emerald-600 flex items-center gap-2 text-[9px] font-black uppercase whitespace-nowrap"><Phone size={14}/> Solicitar Dados</a>
                                  </div>
                              </div>
                              <div className="space-y-2">
                                  <label className="text-[9px] font-bold uppercase text-slate-400">Endereço Completo</label>
                                  <input className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold" placeholder="Rua, Nº, Bairro, Cidade-UF" value={editingStudent.endereco ? `${editingStudent.endereco.rua}, ${editingStudent.endereco.numero} - ${editingStudent.endereco.bairro}` : ''} onChange={e => { /* Simple mock edit for address string */ }} />
                              </div>
                          </div>
                      </div>

                      {/* Document Preview (Mock) */}
                      <div className="bg-slate-50 p-6 rounded-2xl border-2 border-dashed border-slate-200">
                          <h4 className="text-xs font-black uppercase italic text-slate-400 mb-4 text-center">Documentos Anexados (Identidade/Comp. Residência)</h4>
                          <div className="flex justify-center gap-4">
                              {editingStudent.photoURL ? (
                                  <img src={editingStudent.photoURL} className="h-32 rounded-lg shadow-md border border-white" alt="Doc" />
                              ) : (
                                  <div className="h-32 w-32 bg-slate-200 rounded-lg flex items-center justify-center text-slate-400 text-[10px] font-bold uppercase">Sem Foto</div>
                              )}
                          </div>
                      </div>
                  </div>

                  <footer className="bg-white p-6 border-t border-slate-100 flex justify-between items-center shrink-0 shadow-[0_-10px_40px_rgba(0,0,0,0.05)]">
                      <button onClick={saveEditedStudent} className="px-6 py-3 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase hover:bg-slate-200 flex items-center gap-2"><Edit3 size={14}/> Salvar Edições</button>
                      <div className="flex gap-3">
                          <button onClick={rejectStudent} className="px-6 py-3 bg-rose-50 text-rose-600 border border-rose-100 rounded-xl text-[10px] font-black uppercase hover:bg-rose-600 hover:text-white transition-all flex items-center gap-2 shadow-sm"><Ban size={14}/> Rejeitar / Pendenciar</button>
                          <button onClick={validateStudent} className="px-8 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-emerald-700 transition-all flex items-center gap-2 shadow-xl shadow-emerald-200"><Check size={16}/> Validar Matrícula</button>
                      </div>
                  </footer>
              </div>
          </div>
      )}

      {/* Signature Modal */}
      {isSignModalOpen && <SignaturePad title="Assinatura Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert("Assinatura Salva!"); }} />}
    </div>
  );
};

