                            moduleId: m.id, moduleTitle: m.title, data: e,
                            isLocked: idx > 0,
                            isCompleted: false,
                            index: idx++
                        });
                    });
                });
                setTimeline(items);
                if (items.length > 0) setCurrentLesson(items[0]);
            }
        }
    };
    loadData();
