                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                 </div>
             </div>
         )}

         {/* --- TAB: CHAT --- */}
         {(activeTab === 'chat' || selectedTicketId) && (
