                           </div>
                        </div>
                        {/* Chat Messages */}
                        <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50 custom-scrollbar">
                           {chatHistory.map((m, i) => (
                             <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                                <div className={`max-w-[80%] p-3 rounded-2xl text-xs font-medium shadow-sm ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none'}`}>
                                   {m.text}
                                   {(m.attachmentUrl || m.docData) && (
                                     <div className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20" onClick={() => viewAttachment(m.attachmentUrl)}>
                                        <FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Ver Documento</span>
                                     </div>
                                   )}
                                </div>
                                <span className="text-[8px] text-slate-400 mt-1 font-bold uppercase px-1">{m.sender}</span>
                             </div>
                           ))}
                           <div ref={chatEndRef}/>
                        </div>
                        <div className="p-4 bg-white border-t flex gap-2"><input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} className="flex-1 bg-slate-50 rounded-xl px-4 py-3 text-xs font-bold outline-none border border-transparent focus:border-indigo-200 focus:bg-white transition-all" placeholder="Digite sua mensagem..." /><button onClick={handleSendMessage} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all"><Send size={18}/></button></div>
                    </>
                ) : (
                    <div className="flex-1 flex flex-col items-center justify-center opacity-30 gap-4"><MessageSquare size={48} /><p className="font-black uppercase tracking-widest text-xs">Selecione um Ticket na aba Atendimento</p></div>
                )}
            </div>
         )}

         {/* --- INTERNAL FILE PICKER MODAL FOR CHAT --- */}
         {internalFilePickerOpen && (
            <div className="fixed inset-0 z-[3000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-6">
                <div className="bg-white w-full max-w-2xl h-[80vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden">
                    <header className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                        <h3 className="font-black text-slate-900 uppercase italic tracking-widest">Selecionar Documento</h3>
                        <button onClick={() => setInternalFilePickerOpen(false)} className="p-2 bg-white rounded-full hover:bg-rose-50 hover:text-rose-600 shadow-sm"><X size={18}/></button>
                    </header>
                    <div className="flex-1 flex flex-col overflow-hidden">
                        <div className="p-4 bg-white border-b border-slate-50 flex gap-2 overflow-x-auto">
                            <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-100 rounded-lg"><Home size={16}/></button>
                            {folderPath.map((f, i) => (
                                <React.Fragment key={f.id}>
                                    {i > 0 && <ChevronRight size={14} className="text-slate-400"/>}
                                    <button onClick={() => handleBreadcrumb(i)} className="text-xs font-bold text-slate-600 hover:text-indigo-600">{f.name}</button>
                                </React.Fragment>
                            ))}
                        </div>
                        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50/50">
                            <div className="grid grid-cols-4 gap-4">
                                {currentItems.map(item => (
                                    <div key={item.id} 
                                         onClick={() => item.type === 'folder' ? handleNavigate(item) : handleSendFileFromExplorer(item)}
                                         className={`p-4 rounded-xl border border-slate-200 bg-white hover:border-indigo-400 hover:shadow-md cursor-pointer flex flex-col items-center text-center transition-all ${item.type === 'file' ? 'hover:bg-indigo-50' : ''}`}
                                    >
                                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center mb-2 ${item.type === 'folder' ? 'bg-amber-100 text-amber-600' : 'bg-indigo-100 text-indigo-600'}`}>
                                            {item.type === 'folder' ? <Folder size={24}/> : <FileText size={24}/>}
                                        </div>
                                        <p className="text-[9px] font-bold text-slate-700 line-clamp-2">{item.name}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
         )}

         {/* --- SAVE LOCATION MODAL (FOR GENERATED DOCS) --- */}
         {isSaveLocationModalOpen && (
            <div className="fixed inset-0 z-[3000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-6">
                <div className="bg-white w-full max-w-xl h-[70vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden">
                    <header className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                        <div>
                            <h3 className="font-black text-slate-900 uppercase italic tracking-widest">Salvar Documento</h3>
                            <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Selecione a pasta de destino</p>
                        </div>
                        <button onClick={() => setIsSaveLocationModalOpen(false)} className="p-2 bg-white rounded-full hover:bg-rose-50 hover:text-rose-600 shadow-sm"><X size={18}/></button>
                    </header>

                    <div className="flex-1 flex flex-col overflow-hidden">
                        {/* Navigation Bar */}
                        <div className="p-3 bg-white border-b border-slate-50 flex gap-2 overflow-x-auto items-center">
                            <button onClick={() => { setCurrentSaveLocationId('root'); setSaveLocationPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-100 rounded-lg"><Home size={16}/></button>
                            {saveLocationPath.map((f, i) => (
                                <React.Fragment key={f.id}>
                                    <ChevronRight size={14} className="text-slate-300"/>
                                    <button 
                                        onClick={() => {
                                            const newPath = saveLocationPath.slice(0, i + 1);
                                            setSaveLocationPath(newPath);
                                            setCurrentSaveLocationId(f.id);
                                        }} 
                                        className={`text-xs font-bold px-2 py-1 rounded hover:bg-slate-100 ${i === saveLocationPath.length-1 ? 'text-indigo-600' : 'text-slate-500'}`}
                                    >
                                        {f.name}
                                    </button>
                                </React.Fragment>
                            ))}
                        </div>

                        {/* Folder Grid */}
                        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50">
                            <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                {saveLocationItems.map(folder => (
                                    <div 
                                        key={folder.id}
                                        onClick={() => {
                                            setCurrentSaveLocationId(folder.id);
                                            setSaveLocationPath([...saveLocationPath, {id: folder.id, name: folder.name}]);
                                        }}
                                        className="p-4 bg-white border border-slate-200 rounded-xl hover:border-indigo-400 hover:shadow-md cursor-pointer flex flex-col items-center text-center transition-all group"
                                    >
                                        <div className="w-10 h-10 bg-amber-100 text-amber-600 rounded-lg flex items-center justify-center mb-2 group-hover:scale-110 transition-transform">
                                            <Folder size={20}/>
                                        </div>
                                        <p className="text-[9px] font-bold text-slate-700 line-clamp-2 w-full">{folder.name}</p>
                                    </div>
                                ))}
                                {saveLocationItems.length === 0 && <p className="col-span-full text-center text-slate-400 text-xs italic py-10">Nenhuma subpasta aqui.</p>}
                            </div>
                        </div>
                    </div>

                    <footer className="p-4 border-t border-slate-100 bg-white flex justify-end gap-3">
                        <button onClick={() => setIsSaveLocationModalOpen(false)} className="px-6 py-3 rounded-xl text-xs font-bold text-slate-500 hover:bg-slate-100">Cancelar</button>
                        <button onClick={handleSaveToSelectedFolder} className="px-8 py-3 bg-indigo-600 text-white rounded-xl text-xs font-black uppercase shadow-lg hover:bg-indigo-700 flex items-center gap-2"><Check size={16}/> Salvar Aqui</button>
                    </footer>
                </div>
            </div>
         )}

         {/* --- TAB: OPERACIONAL (DOC PREVIEW) --- */}
         {generatedDoc && (
            <div className="fixed inset-0 z-[2000] bg-slate-100 flex flex-col">
               <header className="bg-slate-900 text-white p-4 flex justify-between items-center shadow-lg print:hidden">
                  <div className="flex items-center gap-4">
                     <button onClick={() => setGeneratedDoc(null)} className="p-2 hover:bg-white/10 rounded-full"><ArrowRightLeft className="rotate-180" size={20}/></button>
                     <h2 className="text-sm font-black uppercase italic tracking-widest">{generatedDoc.title}</h2>
                  </div>
                  <div className="flex gap-3">
                     <button onClick={openSaveLocationModal} className="px-5 py-2 bg-emerald-600 hover:bg-emerald-700 rounded-lg text-[10px] font-black uppercase flex items-center gap-2 transition-all"><Save size={14}/> Salvar no Arquivo</button>
                     <button onClick={() => window.print()} className="px-5 py-2 bg-white text-slate-900 hover:bg-indigo-50 rounded-lg text-[10px] font-black uppercase flex items-center gap-2 transition-all"><Printer size={14}/> Imprimir</button>
                  </div>
               </header>
               <div className="flex-1 overflow-auto p-8 custom-scrollbar flex justify-center">
                  <OfficialDocTemplate 
                    title={generatedDoc.title} 
                    content={generatedDoc.content} 
                    student={generatedDoc.student} 
                    code={generatedDoc.code}
                    type={generatedDoc.type}
                    signatures={{ director: null, secretary: secSignature }} 
                    courseData={generatedDoc.courseData}
                    modulesData={generatedDoc.modulesData}
                    progressData={generatedDoc.progressData}
                  />
               </div>
            </div>
         )}

         {/* --- FILE EXPLORER TAB (For consistency with attach mode) --- */}
         {(activeTab === 'arquivos' || attachMode) && !selectedTicketId && (
           <div className={`bg-white border border-slate-200 rounded-xl overflow-hidden h-full flex flex-col shadow-lg ${attachMode ? 'fixed inset-10 z-[3000] border-indigo-600 border-4' : ''}`}>
              {/* Reuse existing explorer logic here or keep simplified version if needed */}
              <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                 <div className="flex items-center gap-2 overflow-x-auto">
                    <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-200 rounded-lg"><Home size={16}/></button>
                    {folderPath.map((f, i) => (
                      <React.Fragment key={f.id}>
                        {i > 0 && <ChevronRight size={14} className="text-slate-400"/>}
                        <button onClick={() => handleBreadcrumb(i)} className={`text-xs font-bold px-2 py-1 rounded-lg hover:bg-slate-200 ${i === folderPath.length -1 ? 'text-slate-900' : 'text-slate-500'}`}>{f.name}</button>
                      </React.Fragment>
                    ))}
                 </div>
                 <div className="flex gap-2">
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} />
                    <button onClick={() => fileInputRef.current?.click()} className="px-3 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-indigo-600"><UploadCloud size={14}/> Upload</button>
                    <button onClick={handleCreateFolder} className="px-3 py-2 bg-slate-200 text-slate-700 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-slate-300"><FolderPlus size={14}/> Pasta</button>
                    {attachMode && <button onClick={() => setAttachMode(false)} className="px-3 py-2 bg-rose-600 text-white rounded-lg text-[9px] font-black uppercase">Fechar</button>}
                 </div>
              </div>
              <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50/50">
                 {currentItems.length === 0 ? (
                   <div className="h-full flex flex-col items-center justify-center opacity-30 gap-4"><Folder size={48} /><p className="text-xs font-black uppercase">Pasta Vazia</p></div>
                 ) : (
                   <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                      {currentItems.map(item => (
                        <div key={item.id} 
                             onDoubleClick={() => item.type === 'folder' ? handleNavigate(item) : null}
                             className={`bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all group flex flex-col items-center text-center cursor-pointer relative`}
                        >
                           <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-3 text-white shadow-inner ${item.type === 'folder' ? 'bg-amber-400' : 'bg-indigo-500'}`}>
                              {item.type === 'folder' ? <Folder size={32} className="fill-white/50"/> : <FileText size={32} className="fill-white/50"/>}
                           </div>
                           <p className="text-[10px] font-bold text-slate-700 line-clamp-2 leading-tight w-full break-words">{item.name}</p>
                           {/* Actions for Files in Explorer */}
                           {item.type === 'file' && (
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 flex gap-1">
                               <button onClick={async (e) => { e.stopPropagation(); if(confirm('Apagar?')) await deleteDoc(doc(db, 'secretaria_arquivos', item.id)); }} className="p-1.5 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100"><X size={12}/></button>
                               {item.url && <a href="#" onClick={(e) => { e.preventDefault(); viewAttachment(item.url); }} className="p-1.5 bg-slate-50 text-slate-600 rounded-lg hover:bg-slate-100"><Eye size={12}/></a>}
                             </div>
                           )}
                        </div>
                      ))}
                   </div>
                 )}
              </div>
           </div>
         )}

         {/* --- TAB: OPERACIONAL (LANDING) --- */}
         {activeTab === 'operacional' && !generatedDoc && (
           <div className="h-full flex flex-col md:flex-row gap-6">
              {/* OPERATIONAL SIDEBAR */}
              <div className="w-full md:w-64 flex flex-col gap-3">
                 <button onClick={() => { setOpSubView('declaracao'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'declaracao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><FileText size={18}/><span className="text-xs font-black uppercase">Declarações</span></button>
                 <button onClick={() => { setOpSubView('historico'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'historico' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><Archive size={18}/><span className="text-xs font-black uppercase">Histórico Escolar</span></button>
                 <button onClick={() => { setOpSubView('transferencia'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'transferencia' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><ArrowRightLeft size={18}/><span className="text-xs font-black uppercase">Transferência</span></button>
                 <button onClick={() => { setOpSubView('validacao'); setGeneratedDoc(null); }} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'validacao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><UserCheck size={18}/><span className="text-xs font-black uppercase">Auditoria</span></button>
                 <button onClick={() => setIsSignModalOpen(true)} className="p-4 rounded-xl border bg-white border-slate-200 hover:bg-slate-50 flex items-center gap-3 transition-all"><Fingerprint size={18}/><span className="text-xs font-black uppercase">Minha Assinatura</span></button>
              </div>

              {/* OPERATIONAL CONTENT */}
              <div className="flex-1 bg-white rounded-2xl border border-slate-200 p-1 shadow-sm overflow-hidden relative">
                 {/* ... (Validation & Generators remain mostly same, just ensuring correct state handling) ... */}
                 {(opSubView === 'declaracao' || opSubView === 'historico' || opSubView === 'transferencia') && (
                   <div className="max-w-lg mx-auto space-y-6 py-10 px-6">
                      <h3 className="text-xl font-black uppercase italic text-slate-900 border-b pb-4">Gerar {opSubView}</h3>
                      <div className="space-y-2">
                         <label className="text-[10px] font-black uppercase text-slate-400">Selecione o Aluno</label>
                         <select onChange={e => setOpStudent(students.find(s => s.uid === e.target.value))} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold">
                            <option value="">Selecione...</option>
                            {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName} (RA: {s.academicId})</option>)}
                         </select>
                      </div>
                      <div className="pt-4 flex gap-4">
                         {opSubView === 'declaracao' && (
                           <>
                             <button disabled={!opStudent} onClick={() => generateDeclaration('matricula')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50">Dec. Matrícula</button>
                             <button disabled={!opStudent} onClick={() => generateDeclaration('conclusao')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50">Cert. Conclusão</button>
                           </>
                         )}
                         {opSubView === 'transferencia' && (
                           <button disabled={!opStudent} onClick={() => generateDeclaration('transferencia')} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50">Emitir Guia de Transferência</button>
                         )}
                         {opSubView === 'historico' && (
                           <button disabled={!opStudent} onClick={generateTranscript} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50">Gerar Histórico Completo</button>
                         )}
                      </div>
                   </div>
                 )}
                 {opSubView === 'validacao' && (
                    <div className="p-8 h-full flex flex-col">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-lg font-black uppercase italic text-slate-900">Auditoria de Cadastros</h3>
                            <div className="text-[10px] font-bold text-slate-400 uppercase bg-slate-50 px-3 py-1 rounded-lg border border-slate-100">Filtro: Pendentes</div>
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3">
                            {students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').length === 0 ? (
                                <p className="text-center text-slate-300 italic py-10 text-xs uppercase font-black">Nenhum aluno pendente de validação.</p>
                            ) : students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').map(s => (
                                <div key={s.uid} className="flex justify-between items-center p-4 border border-rose-100 bg-rose-50/50 rounded-xl hover:bg-rose-50 transition-all">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-full bg-rose-100 flex items-center justify-center text-rose-600 font-bold">{s.displayName?.charAt(0)}</div>
                                        <div>
                                            <p className="text-xs font-black uppercase text-slate-800">{s.displayName}</p>
                                            <p className="text-[9px] text-slate-500 font-mono">{s.cpf} • {s.email}</p>
                                        </div>
                                    </div>
                                    <button onClick={() => { setEditingStudent(s); setAuditModalOpen(true); }} className="px-4 py-2 bg-white text-rose-600 border border-rose-200 rounded-lg text-[9px] font-black uppercase hover:bg-rose-600 hover:text-white transition-all shadow-sm">Auditar</button>
                                </div>
                            ))}
                        </div>
                    </div>
                 )}
              </div>
           </div>
         )}
      </main>

      {/* Audit & Signature Modals (Same as before) */}
      {auditModalOpen && editingStudent && (
          <div className="fixed inset-0 z-[3000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-white w-full max-w-4xl h-[90vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
                  <header className="bg-slate-50 px-8 py-5 border-b border-slate-100 flex justify-between items-center shrink-0">
                      <div className="flex items-center gap-3">
                          <div className="p-2 bg-indigo-600 text-white rounded-lg shadow-md"><ShieldCheck size={20}/></div>
                          <div>
                              <h2 className="text-lg font-black uppercase italic text-slate-900 leading-none">Auditoria de Prontuário</h2>
                              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Validação Cadastral</p>
                          </div>
                      </div>
                      <button onClick={() => setAuditModalOpen(false)} className="p-2 hover:bg-rose-50 text-slate-400 rounded-full transition-all"><X size={20}/></button>
                  </header>
                  <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-8">
                       <div className="grid grid-cols-2 gap-6">
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Nome</label><input value={editingStudent.displayName} onChange={e => setEditingStudent({...editingStudent, displayName: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">CPF</label><input value={editingStudent.cpf} onChange={e => setEditingStudent({...editingStudent, cpf: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Email</label><input value={editingStudent.email} disabled className="w-full p-3 bg-slate-100 rounded-xl text-xs font-bold text-slate-500 border border-slate-200 cursor-not-allowed"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Telefone</label><input value={editingStudent.telefone} onChange={e => setEditingStudent({...editingStudent, telefone: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                       </div>

                       <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
                           <h4 className="text-[10px] font-black uppercase text-slate-400 mb-4 tracking-widest">Documentos Anexados</h4>
                           <div className="flex items-center gap-4">
                               <div className="w-24 h-24 bg-white rounded-xl border border-slate-200 flex items-center justify-center overflow-hidden">
                                   {editingStudent.photoURL ? <img src={editingStudent.photoURL} className="w-full h-full object-cover"/> : <span className="text-[8px] font-black uppercase text-slate-300">Sem Foto</span>}
                               </div>
                               <div>
                                   <p className="text-xs font-bold text-slate-800">Foto de Identificação</p>
                                   <p className="text-[9px] text-slate-400">Status: {editingStudent.photoURL ? 'Enviado' : 'Pendente'}</p>
                               </div>
                           </div>
                       </div>

                       <div className="flex gap-4 pt-4 border-t border-slate-100">
                          <button onClick={saveEditedStudent} className="px-6 py-3 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase hover:bg-slate-200 flex items-center gap-2"><Edit3 size={14}/> Salvar Edições</button>
                          <button onClick={validateStudent} className="px-8 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-emerald-700 transition-all flex items-center gap-2 shadow-xl shadow-emerald-200"><Check size={16}/> Validar Matrícula</button>
                       </div>
                  </div>
              </div>
          </div>
      )}
      {isSignModalOpen && <SignaturePad title="Assinatura Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert("Assinatura Salva!"); }} />}
    </div>
  );
};

