  const [chatMessage, setChatMessage] = useState('');

  // UI States - General
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  // File Explorer & Save States
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [isSaveLocationModalOpen, setIsSaveLocationModalOpen] = useState(false);
  const [saveLocationPath, setSaveLocationPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [currentSaveLocationId, setCurrentSaveLocationId] = useState('root');
  const [internalFilePickerOpen, setInternalFilePickerOpen] = useState(false); // New state for chat file picker

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [attachMode, setAttachMode] = useState(false);

  // Operational State
  const [opStudent, setOpStudent] = useState<any>(null);
  const [generatedDoc, setGeneratedDoc] = useState<any>(null);

  // Audit Modal State
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Ticket Listener
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        t.sort((a:any, b:any) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
        setTickets(t);
    });

    // File System Listener
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    // Students Listener
    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid]);

  // Sync Chat
  useEffect(() => {
    if (!selectedTicketId) { setChatHistory([]); return; }
    const q = query(collection(db, 'tickets', selectedTicketId, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setChatHistory(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [selectedTicketId]);

  // --- FILE EXPLORER HELPERS ---
  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  };

  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);
  const saveLocationItems = useMemo(() => getFilesForFolder(currentSaveLocationId).filter(f => f.type === 'folder'), [fileSystem, currentSaveLocationId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      if (ev.target?.result) {
        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name,
          type: 'file',
          mimeType: file.type,
          url: ev.target.result, 
          parentId: currentFolderId,
          size: file.size,
          createdAt: serverTimestamp(),
          createdBy: user.uid
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id);
    setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  // --- CHAT & TICKET LOGIC ---
  const handleSendFileFromExplorer = async (file: any) => {
    if (!selectedTicketId) return;
    await addDoc(collection(db, 'tickets', selectedTicketId, 'messages'), {
      text: `Arquivo enviado pela Secretaria: ${file.name}`,
      attachmentUrl: file.url || (file.docData ? 'doc_internal' : ''), // Fallback if needed
      docData: file.docData, // Store internal doc data
      sender: 'Secretaria',
      createdAt: serverTimestamp()
    });
    setInternalFilePickerOpen(false);
    setAttachMode(false);
    setActiveTab('chat');
  };

  const handleSendMessage = async () => {
    if (!chatMessage.trim() || !selectedTicketId) return;
    await addDoc(collection(db, 'tickets', selectedTicketId, 'messages'), {
      text: chatMessage,
      sender: 'Secretaria',
      createdAt: serverTimestamp()
    });
    await updateDoc(doc(db, 'tickets', selectedTicketId), {
        lastMessage: chatMessage,
        updatedAt: serverTimestamp()
    });
    setChatMessage('');
  };

  const handleAssumeTicket = async (ticketId: string) => {
      await updateDoc(doc(db, 'tickets', ticketId), {
          status: 'Em Atendimento',
          attendant: user.displayName,
          specialistJoined: true // Marks that a human joined
      });
      alert('Você assumiu este atendimento.');
  };

  const handleCloseTicket = async (ticketId: string) => {
      if(!confirm("Deseja finalizar este atendimento?")) return;
      await updateDoc(doc(db, 'tickets', ticketId), {
          status: 'Finalizado'
      });
      setSelectedTicketId(null);
      setActiveTab('atendimento');
  };

  const handleDeleteTicket = async (ticketId: string) => {
      if(!confirm("Deseja EXCLUIR este atendimento? Esta ação não pode ser desfeita.")) return;
      await deleteDoc(doc(db, 'tickets', ticketId));
  };

  const handleArchiveTicket = async (ticketId: string) => {
      await updateDoc(doc(db, 'tickets', ticketId), { status: 'Arquivado' });
  };

  // --- DOCUMENT GENERATION & SAVING ---
  const openSaveLocationModal = () => {
    setSaveLocationPath([{id: 'root', name: 'Arquivos'}]);
    setCurrentSaveLocationId('root');
    setIsSaveLocationModalOpen(true);
  };

  const handleSaveToSelectedFolder = async () => {
    if (!generatedDoc) return;

    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: `${generatedDoc.title} - ${generatedDoc.student?.displayName || 'Aluno'}.pdf`,
      type: 'file',
      mimeType: 'application/pdf',
      docData: { 
          title: generatedDoc.title,
          student: generatedDoc.student, 
          code: generatedDoc.code, 
          type: generatedDoc.type,
          date: new Date().toISOString(),
          courseData: generatedDoc.courseData || null, // Sanitize undefined
          modulesData: generatedDoc.modulesData || null, // Sanitize undefined
          progressData: generatedDoc.progressData || null // Sanitize undefined
      },
      parentId: currentSaveLocationId,
      createdAt: serverTimestamp(),
      createdBy: user.uid
    });
    setIsSaveLocationModalOpen(false);
    alert(`Documento salvo com sucesso na pasta selecionada!`);
  };

  const generateDeclaration = async (type: 'matricula'|'conclusao'|'transferencia') => {
    if (!opStudent) return;
    const code = generateVerificationCode();
    const docObj = { title: type === 'matricula' ? 'Declaração de Matrícula' : type === 'transferencia' ? 'Guia de Transferência' : 'Certificado de Conclusão', code, student: opStudent, type };
    setGeneratedDoc(docObj);
  };

  const generateTranscript = async () => {
    if (!opStudent) return;
    const code = generateVerificationCode();

    let courseData: any = {};
    if (opStudent.cursoInicial) {
        try {
            const cRef = doc(db, 'cursos', opStudent.cursoInicial);
            const cSnap = await getDoc(cRef);
            if (cSnap.exists()) courseData = cSnap.data();
        } catch (e) { console.error(e); }
    }

    let modulesData: any[] = [];
    if (opStudent.cursoInicial) {
        try {
            const mRef = collection(db, 'modulos');
            const q = query(mRef, where('courseId', '==', opStudent.cursoInicial), orderBy('order'));
            const mSnap = await getDocs(q);
            modulesData = mSnap.docs.map(d => ({id: d.id, ...d.data()}));
        } catch (e) { console.error(e); }
    }

    const docObj = { 
        title: 'Histórico Escolar', 
        code, 
        student: opStudent, 
        type: 'historico',
        courseData,
        modulesData,
        progressData: opStudent.progress 
    };
    setGeneratedDoc(docObj);
  };

  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              ...editingStudent,
              updatedAt: serverTimestamp()
          });
          alert('Dados do aluno atualizados.');
          setAuditModalOpen(false);
          setEditingStudent(null);
      } catch (e: any) {
          alert('Erro ao salvar: ' + e.message);
      }
  };

  const validateStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              status: 'ativo',
              updatedAt: serverTimestamp()
          });
          alert('Matrícula validada com sucesso.');
          setAuditModalOpen(false);
          setEditingStudent(null);
      } catch (e: any) {
          alert('Erro ao validar: ' + e.message);
      }
  };

  // TIME CALCULATION HELPER
  const calculateWaitTime = (timestamp: any) => {
    if (!timestamp) return '0min';
    const diff = Date.now() - (timestamp.seconds * 1000);
    const minutes = Math.floor(diff / 60000);
    if (minutes < 60) return `${minutes}min`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours}h ${minutes % 60}min`;
    return `${Math.floor(hours / 24)}d`;
  };

  const filteredTickets = tickets.filter(t => {
      const matchSearch = ticketSearchTerm === '' || 
                          (t.protocolo && t.protocolo.toLowerCase().includes(ticketSearchTerm.toLowerCase())) ||
                          (t.user && t.user.toLowerCase().includes(ticketSearchTerm.toLowerCase()));
      if (!matchSearch) return false;
      if (ticketFilter === 'todos') return true; // Now showing ALL if filtered to all
      if (ticketFilter === 'pendente') return t.status === 'Pendente';
      if (ticketFilter === 'ativo') return t.status === 'Em Atendimento';
      if (ticketFilter === 'finalizado') return t.status === 'Finalizado' || t.status === 'Resolvido' || t.status === 'Arquivado';
      return true;
  });

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      {/* HEADER */}
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); if(t !== 'chat') setSelectedTicketId(null); setGeneratedDoc(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      {/* MAIN CONTENT */}
      <main className="flex-1 overflow-hidden flex flex-col">

         {/* --- TAB: ATENDIMENTO (RESTORED TABLE) --- */}
         {activeTab === 'atendimento' && (
             <div className="space-y-6 h-full flex flex-col overflow-hidden">
                 {/* Filters */}
                 <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm shrink-0 flex flex-col md:flex-row gap-4 items-center justify-between">
                    <div className="flex gap-2 p-1 bg-slate-50 rounded-lg border border-slate-100">
                        {['todos', 'pendente', 'ativo', 'finalizado'].map((f:any) => (
                            <button key={f} onClick={() => setTicketFilter(f)} className={`px-4 py-2 text-[9px] font-black uppercase rounded-md transition-all ${ticketFilter === f ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>{f}</button>
                        ))}
                    </div>
                    <div className="relative w-full md:w-80">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                        <input value={ticketSearchTerm} onChange={e => setTicketSearchTerm(e.target.value)} placeholder="Pesquisar Protocolo, Nome ou Matrícula..." className="w-full pl-9 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600" />
                    </div>
                 </div>

                 {/* Restored Ticket Table */}
                 <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                    <div className="overflow-y-auto custom-scrollbar flex-1">
                        <table className="w-full text-left border-collapse">
                            <thead className="bg-slate-50 text-[9px] font-black uppercase text-slate-400 border-b border-slate-100 tracking-widest sticky top-0 z-10">
                                <tr>
                                    <th className="px-6 py-4">Protocolo</th>
                                    <th className="px-6 py-4">Aluno / Matrícula</th>
                                    <th className="px-6 py-4">Descrição do Problema</th>
                                    <th className="px-6 py-4 text-center">Tempo de Espera</th>
                                    <th className="px-6 py-4 text-center">Status</th>
                                    <th className="px-6 py-4 text-center">Gestão</th>
                                </tr>
                            </thead>
                            <tbody className="text-xs">
                                {filteredTickets.map(t => (
                                    <tr key={t.id} className="border-b border-slate-50 hover:bg-slate-50/50 transition-all">
                                        <td className="px-6 py-4 font-mono font-bold text-indigo-600">#{t.protocolo || t.id.substr(0,6).toUpperCase()}</td>
                                        <td className="px-6 py-4">
                                            <p className="font-bold text-slate-800 uppercase">{t.user}</p>
                                            <p className="text-[9px] text-slate-400 font-mono mt-0.5">ID: {t.senderId?.substr(0,8).toUpperCase()}</p>
                                        </td>
                                        <td className="px-6 py-4 max-w-xs">
                                            <p className="line-clamp-2 text-slate-600 font-medium italic">{t.lastMessage}</p>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <span className={`px-2 py-1 rounded text-[9px] font-black ${t.status === 'Pendente' ? 'bg-rose-50 text-rose-600' : 'bg-slate-100 text-slate-400'}`}>
                                                {calculateWaitTime(t.createdAt)}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase border ${
                                                t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-100' :
                                                t.status === 'Em Atendimento' ? 'bg-indigo-50 text-indigo-600 border-indigo-100' :
                                                'bg-emerald-50 text-emerald-600 border-emerald-100'
                                            }`}>{t.status}</span>
                                        </td>
                                        <td className="px-6 py-4">
                                            <div className="flex justify-center gap-2">
                                                <button onClick={() => { setSelectedTicketId(t.id); setActiveTab('chat'); }} className="p-2 bg-slate-100 text-slate-500 rounded-lg hover:bg-indigo-600 hover:text-white transition-all border border-slate-200" title="Ver / Chat"><MessageSquare size={14}/></button>
                                                <button onClick={() => handleArchiveTicket(t.id)} className="p-2 bg-slate-100 text-slate-500 rounded-lg hover:bg-amber-500 hover:text-white transition-all border border-slate-200" title="Arquivar"><Archive size={14}/></button>
                                                <button onClick={() => handleDeleteTicket(t.id)} className="p-2 bg-slate-100 text-slate-500 rounded-lg hover:bg-rose-600 hover:text-white transition-all border border-slate-200" title="Excluir"><Trash2 size={14}/></button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                 </div>
             </div>
         )}

         {/* --- TAB: CHAT --- */}
         {(activeTab === 'chat' || selectedTicketId) && (
            <div className="h-full flex flex-col bg-white border border-slate-200 rounded-xl overflow-hidden shadow-lg">
                {selectedTicketId ? (
                    <>
                        {/* Chat Header */}
                        <div className="p-4 border-b bg-slate-50 flex justify-between items-center shadow-sm z-10">
                           <div className="flex items-center gap-3">
                               <button onClick={() => { setSelectedTicketId(null); setActiveTab('atendimento'); }} className="p-2 bg-white border border-slate-200 rounded-lg hover:bg-slate-100"><CornerUpLeft size={16}/></button>
                               <div><h4 className="font-bold text-sm uppercase text-slate-800">{tickets.find(t=>t.id===selectedTicketId)?.user}</h4><p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Protocolo: {tickets.find(t=>t.id===selectedTicketId)?.protocolo}</p></div>
                           </div>
                           <div className="flex gap-2">
                               <button onClick={() => setInternalFilePickerOpen(true)} className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 border border-indigo-100 hover:bg-indigo-100"><FolderInput size={14}/> Selecionar dos Arquivos</button>
                               <button onClick={() => setAttachMode(true)} className="px-4 py-2 bg-white text-slate-600 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 border border-slate-200 hover:bg-slate-50"><Paperclip size={14}/> Upload</button>
                               <button onClick={() => handleCloseTicket(selectedTicketId)} className="px-4 py-2 bg-rose-600 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-rose-700 shadow-lg"><CheckCircle2 size={14}/> Finalizar</button>
                           </div>
                        </div>
                        {/* Chat Messages */}
                        <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50 custom-scrollbar">
                           {chatHistory.map((m, i) => (
                             <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                                <div className={`max-w-[80%] p-3 rounded-2xl text-xs font-medium shadow-sm ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none'}`}>
                                   {m.text}
                                   {(m.attachmentUrl || m.docData) && (
                                     <div className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20" onClick={() => viewAttachment(m.attachmentUrl)}>
                                        <FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Ver Documento</span>
                                     </div>
                                   )}
                                </div>
                                <span className="text-[8px] text-slate-400 mt-1 font-bold uppercase px-1">{m.sender}</span>
                             </div>
                           ))}
                           <div ref={chatEndRef}/>
                        </div>
                        <div className="p-4 bg-white border-t flex gap-2"><input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} className="flex-1 bg-slate-50 rounded-xl px-4 py-3 text-xs font-bold outline-none border border-transparent focus:border-indigo-200 focus:bg-white transition-all" placeholder="Digite sua mensagem..." /><button onClick={handleSendMessage} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all"><Send size={18}/></button></div>
                    </>
                ) : (
                    <div className="flex-1 flex flex-col items-center justify-center opacity-30 gap-4"><MessageSquare size={48} /><p className="font-black uppercase tracking-widest text-xs">Selecione um Ticket na aba Atendimento</p></div>
                )}
            </div>
         )}

         {/* --- INTERNAL FILE PICKER MODAL FOR CHAT --- */}
         {internalFilePickerOpen && (
            <div className="fixed inset-0 z-[3000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-6">
                <div className="bg-white w-full max-w-2xl h-[80vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden">
                    <header className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                        <h3 className="font-black text-slate-900 uppercase italic tracking-widest">Selecionar Documento</h3>
                        <button onClick={() => setInternalFilePickerOpen(false)} className="p-2 bg-white rounded-full hover:bg-rose-50 hover:text-rose-600 shadow-sm"><X size={18}/></button>
                    </header>
                    <div className="flex-1 flex flex-col overflow-hidden">
                        <div className="p-4 bg-white border-b border-slate-50 flex gap-2 overflow-x-auto">
                            <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-100 rounded-lg"><Home size={16}/></button>
                            {folderPath.map((f, i) => (
                                <React.Fragment key={f.id}>
                                    {i > 0 && <ChevronRight size={14} className="text-slate-400"/>}
                                    <button onClick={() => handleBreadcrumb(i)} className="text-xs font-bold text-slate-600 hover:text-indigo-600">{f.name}</button>
                                </React.Fragment>
                            ))}
                        </div>
                        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50/50">
                            <div className="grid grid-cols-4 gap-4">
                                {currentItems.map(item => (
                                    <div key={item.id} 
                                         onClick={() => item.type === 'folder' ? handleNavigate(item) : handleSendFileFromExplorer(item)}
                                         className={`p-4 rounded-xl border border-slate-200 bg-white hover:border-indigo-400 hover:shadow-md cursor-pointer flex flex-col items-center text-center transition-all ${item.type === 'file' ? 'hover:bg-indigo-50' : ''}`}
                                    >
                                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center mb-2 ${item.type === 'folder' ? 'bg-amber-100 text-amber-600' : 'bg-indigo-100 text-indigo-600'}`}>
                                            {item.type === 'folder' ? <Folder size={24}/> : <FileText size={24}/>}
                                        </div>
                                        <p className="text-[9px] font-bold text-slate-700 line-clamp-2">{item.name}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
         )}

         {/* --- SAVE LOCATION MODAL (FOR GENERATED DOCS) --- */}
         {isSaveLocationModalOpen && (
            <div className="fixed inset-0 z-[3000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-6">
                <div className="bg-white w-full max-w-xl h-[70vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden">
                    <header className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                        <div>
                            <h3 className="font-black text-slate-900 uppercase italic tracking-widest">Salvar Documento</h3>
                            <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Selecione a pasta de destino</p>
                        </div>
                        <button onClick={() => setIsSaveLocationModalOpen(false)} className="p-2 bg-white rounded-full hover:bg-rose-50 hover:text-rose-600 shadow-sm"><X size={18}/></button>
                    </header>

                    <div className="flex-1 flex flex-col overflow-hidden">
                        {/* Navigation Bar */}
                        <div className="p-3 bg-white border-b border-slate-50 flex gap-2 overflow-x-auto items-center">
                            <button onClick={() => { setCurrentSaveLocationId('root'); setSaveLocationPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-100 rounded-lg"><Home size={16}/></button>
                            {saveLocationPath.map((f, i) => (
                                <React.Fragment key={f.id}>
                                    <ChevronRight size={14} className="text-slate-300"/>
                                    <button 
                                        onClick={() => {
                                            const newPath = saveLocationPath.slice(0, i + 1);
                                            setSaveLocationPath(newPath);
                                            setCurrentSaveLocationId(f.id);
                                        }} 
                                        className={`text-xs font-bold px-2 py-1 rounded hover:bg-slate-100 ${i === saveLocationPath.length-1 ? 'text-indigo-600' : 'text-slate-500'}`}
                                    >
                                        {f.name}
                                    </button>
                                </React.Fragment>
                            ))}
                        </div>

                        {/* Folder Grid */}
                        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50">
                            <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                {saveLocationItems.map(folder => (
                                    <div 
                                        key={folder.id}
                                        onClick={() => {
                                            setCurrentSaveLocationId(folder.id);
                                            setSaveLocationPath([...saveLocationPath, {id: folder.id, name: folder.name}]);
                                        }}
                                        className="p-4 bg-white border border-slate-200 rounded-xl hover:border-indigo-400 hover:shadow-md cursor-pointer flex flex-col items-center text-center transition-all group"
                                    >
                                        <div className="w-10 h-10 bg-amber-100 text-amber-600 rounded-lg flex items-center justify-center mb-2 group-hover:scale-110 transition-transform">
                                            <Folder size={20}/>
                                        </div>
                                        <p className="text-[9px] font-bold text-slate-700 line-clamp-2 w-full">{folder.name}</p>
                                    </div>
                                ))}
                                {saveLocationItems.length === 0 && <p className="col-span-full text-center text-slate-400 text-xs italic py-10">Nenhuma subpasta aqui.</p>}
                            </div>
                        </div>
                    </div>

                    <footer className="p-4 border-t border-slate-100 bg-white flex justify-end gap-3">
                        <button onClick={() => setIsSaveLocationModalOpen(false)} className="px-6 py-3 rounded-xl text-xs font-bold text-slate-500 hover:bg-slate-100">Cancelar</button>
                        <button onClick={handleSaveToSelectedFolder} className="px-8 py-3 bg-indigo-600 text-white rounded-xl text-xs font-black uppercase shadow-lg hover:bg-indigo-700 flex items-center gap-2"><Check size={16}/> Salvar Aqui</button>
                    </footer>
                </div>
            </div>
         )}

         {/* --- TAB: OPERACIONAL (DOC PREVIEW) --- */}
         {generatedDoc && (
            <div className="fixed inset-0 z-[2000] bg-slate-100 flex flex-col">
               <header className="bg-slate-900 text-white p-4 flex justify-between items-center shadow-lg print:hidden">
                  <div className="flex items-center gap-4">
                     <button onClick={() => setGeneratedDoc(null)} className="p-2 hover:bg-white/10 rounded-full"><ArrowRightLeft className="rotate-180" size={20}/></button>
                     <h2 className="text-sm font-black uppercase italic tracking-widest">{generatedDoc.title}</h2>
                  </div>
                  <div className="flex gap-3">
                     <button onClick={openSaveLocationModal} className="px-5 py-2 bg-emerald-600 hover:bg-emerald-700 rounded-lg text-[10px] font-black uppercase flex items-center gap-2 transition-all"><Save size={14}/> Salvar no Arquivo</button>
                     <button onClick={() => window.print()} className="px-5 py-2 bg-white text-slate-900 hover:bg-indigo-50 rounded-lg text-[10px] font-black uppercase flex items-center gap-2 transition-all"><Printer size={14}/> Imprimir</button>
                  </div>
               </header>
               <div className="flex-1 overflow-auto p-8 custom-scrollbar flex justify-center">
                  <OfficialDocTemplate 
                    title={generatedDoc.title} 
                    content={generatedDoc.content} 
                    student={generatedDoc.student} 
                    code={generatedDoc.code}
                    type={generatedDoc.type}
                    signatures={{ director: null, secretary: secSignature }} 
                    courseData={generatedDoc.courseData}
                    modulesData={generatedDoc.modulesData}
                    progressData={generatedDoc.progressData}
                  />
               </div>
            </div>
         )}

