  }

  // STANDARD DOCUMENT TEMPLATE (PORTRAIT)
  return (
    <div id="official-cert-container" className="bg-white p-12 text-slate-900 font-serif max-w-[210mm] mx-auto border shadow-lg relative min-h-[297mm]">
      <style>{printStyles}</style>
      <div className="border-b-2 border-slate-900 pb-6 mb-8 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="w-16 h-16 bg-slate-900 text-white flex items-center justify-center font-bold text-2xl rounded-full">EB</div>
          <div>
            <h1 className="text-xl font-bold uppercase tracking-wider">Escola Bíblica EAD</h1>
            <p className="text-xs font-bold text-slate-500 uppercase">Credenciamento MEC/CNE nº 999.999</p>
          </div>
        </div>
        <div className="text-right">
          <p className="text-xs font-bold uppercase">Secretaria Geral</p>
          <p className="text-[10px] text-slate-500">{new Date().toLocaleDateString('pt-BR')}</p>
        </div>
