      <div className="mb-8 text-center">
        <h2 className="text-2xl font-bold uppercase underline decoration-2 underline-offset-4">{title}</h2>
        <p className="text-xs font-bold text-slate-400 mt-2 uppercase tracking-[0.2em]">Ref: {code}</p>
