    if (!generatedDoc) return;

    await addDoc(collection(db, 'secretaria_arquivos'), {
      name: `${generatedDoc.title} - ${generatedDoc.student?.displayName || 'Aluno'}.pdf`,
      type: 'file',
      mimeType: 'application/pdf',
      docData: { 
          title: generatedDoc.title,
          student: generatedDoc.student, 
          code: generatedDoc.code, 
          type: generatedDoc.type,
          date: new Date().toISOString(),
          courseData: generatedDoc.courseData || null, // Sanitize undefined
          modulesData: generatedDoc.modulesData || null, // Sanitize undefined
          progressData: generatedDoc.progressData || null // Sanitize undefined
      },
      parentId: currentSaveLocationId,
      createdAt: serverTimestamp(),
      createdBy: user.uid
    });
    setIsSaveLocationModalOpen(false);
    alert(`Documento salvo com sucesso na pasta selecionada!`);
  };

  const generateDeclaration = async (type: 'matricula'|'conclusao'|'transferencia') => {
    if (!opStudent) return;
    const code = generateVerificationCode();
    const docObj = { title: type === 'matricula' ? 'Declaração de Matrícula' : type === 'transferencia' ? 'Guia de Transferência' : 'Certificado de Conclusão', code, student: opStudent, type };
    setGeneratedDoc(docObj);
  };

  const generateTranscript = async () => {
    if (!opStudent) return;
    const code = generateVerificationCode();

    let courseData: any = {};
    if (opStudent.cursoInicial) {
        try {
            const cRef = doc(db, 'cursos', opStudent.cursoInicial);
            const cSnap = await getDoc(cRef);
            if (cSnap.exists()) courseData = cSnap.data();
        } catch (e) { console.error(e); }
    }

    let modulesData: any[] = [];
    if (opStudent.cursoInicial) {
        try {
            const mRef = collection(db, 'modulos');
            const q = query(mRef, where('courseId', '==', opStudent.cursoInicial), orderBy('order'));
            const mSnap = await getDocs(q);
            modulesData = mSnap.docs.map(d => ({id: d.id, ...d.data()}));
        } catch (e) { console.error(e); }
    }

    const docObj = { 
        title: 'Histórico Escolar', 
        code, 
        student: opStudent, 
        type: 'historico',
        courseData,
        modulesData,
        progressData: opStudent.progress 
    };
    setGeneratedDoc(docObj);
  };

  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
