const OfficialDocTemplate = ({ title, content, student, code, signatures, type, courseData, modulesData, progressData, examsData }: any) => {
  const isCertificate = type === 'conclusao';
  const pageOrientation = isCertificate ? 'landscape' : 'portrait';

  // CSS Fix for Printing - Using visibility instead of display to ensure layout works
  const printStyles = `
    @media print {
      @page { size: ${pageOrientation} !important; margin: 0 !important; }
      body { 
        visibility: hidden !important; 
        height: auto !important; 
        overflow: visible !important;
        background: white !important;
      }
      #official-cert-container { 
        visibility: visible !important;
        position: fixed !important; 
        left: 0 !important; 
        top: 0 !important; 
        width: 100% !important; 
        height: 100% !important;
        margin: 0 !important; 
        padding: 0 !important; 
        background: white !important;
        z-index: 999999 !important;
        display: block !important;
      }
      #official-cert-container * { visibility: visible !important; }
      .no-print { display: none !important; }
      .page-break { page-break-before: always !important; }
      .break-after-page { page-break-after: always !important; }
    }
  `;

  // Helper to calculate module grade based on REAL data
  const calculateModuleStats = (moduleId: string) => {
    // 1. Find all exams for this module
    const moduleExams = examsData ? examsData.filter((e: any) => e.moduleId === moduleId && e.type === 'evaluation') : [];

    // 2. If no exams, check lesson completion
    if (moduleExams.length === 0) {
       // Logic: Check if all lessons are marked as completed in progressData
       // For now, simpler logic: if progress exists for course, assume generic completion
       return { grade: '---', status: 'APROVADO (Freq.)', score: 100 };
    }

    // 3. Calculate average from student.progress
    let totalScore = 0;
    let examsTaken = 0;

    // progressData structure: { [courseId]: { [itemId]: { completed: boolean, score: number } } }
    const courseProgress = progressData && courseData ? progressData[courseData.id] : null;

    if (!courseProgress) return { grade: '0.0', status: 'PENDENTE', score: 0 };

    moduleExams.forEach((exam: any) => {
        const p = courseProgress[exam.id];
        if (p && p.score !== undefined) {
            totalScore += p.score;
            examsTaken++;
        }
    });

    if (examsTaken === 0) return { grade: '0.0', status: 'CURSANDO', score: 0 };

    const average = totalScore / examsTaken; // Score is usually 0-100
    const finalGrade = (average / 10).toFixed(1); // Convert to 0-10 scale
    const status = average >= 70 ? 'APROVADO' : 'REPROVADO';

    return { grade: finalGrade, status, score: average };
