    return <p>Conteúdo não disponível.</p>;
  };

  // Calculate Total Hours & Final Grade for Certificate
  const totalHours = modulesData ? modulesData.length * 20 : 100; // Est. 20h per module
  let globalSum = 0;
  let globalCount = 0;

  if (modulesData) {
