    let modulesData: any[] = [];
    let examsData: any[] = [];

    if (opStudent.cursoInicial) {
        try {
            // 1. Fetch Course Data
            const cRef = doc(db, 'cursos', opStudent.cursoInicial);
            const cSnap = await getDoc(cRef);
            if (cSnap.exists()) courseData = { id: cSnap.id, ...cSnap.data() };

            // 2. Fetch Modules
            const mRef = collection(db, 'modulos');
            const qMod = query(mRef, where('courseId', '==', opStudent.cursoInicial), orderBy('order'));
            const mSnap = await getDocs(qMod);
            modulesData = mSnap.docs.map(d => ({id: d.id, ...d.data()}));

            // 3. Fetch Exams (to calculate REAL grades)
            const eRef = collection(db, 'exams');
            const qExam = query(eRef, where('courseId', '==', opStudent.cursoInicial));
            const eSnap = await getDocs(qExam);
            examsData = eSnap.docs.map(d => ({id: d.id, ...d.data()}));

