import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, addDoc, setDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, MessageSquare, Search, X, FileText, UserCheck, 
  ArrowRightLeft, Fingerprint, Send, Archive, Eye, 
  Printer, Folder, File, Download, Plus, ChevronRight,
  UploadCloud, FolderPlus, MoreVertical, CheckCircle2, ShieldCheck,
  AlertTriangle, Home, CornerUpLeft, Paperclip, Save, Timer, MessageCircle,
  Phone, UserX, Edit3, Ban, Check, RefreshCw, Award, Clock, Trash2, FolderInput,
  Move
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';
import { jsPDF } from "https://esm.sh/jspdf@2.5.1";
import autoTable from "https://esm.sh/jspdf-autotable@3.8.1";
import QRCode from "https://esm.sh/qrcode@1.5.3";

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'historico' | 'transferencia' | 'assinatura' | 'validacao';

// --- HELPERS ---
const generateVerificationCode = () => {
  return `${new Date().getFullYear()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}`;
};

const viewFile = (file: any) => {
  if (!file || !file.url) return;

  // Se for PDF (base64 ou URL), abrir em nova aba para impressão nativa do browser
  if (file.mimeType === 'application/pdf' || file.name?.endsWith('.pdf')) {
      const newWindow = window.open();
      if (newWindow) {
          if (file.url.startsWith('data:')) {
             // Se for base64, criar um iframe ou embed para garantir visualização correta
             newWindow.document.write(
                 `<iframe width='100%' height='100%' src='${file.url}'></iframe>`
             );
             newWindow.document.title = file.name;
          } else {
             newWindow.location.href = file.url;
          }
      } else {
          alert("Pop-up bloqueado. Permita pop-ups para visualizar o PDF.");
      }
      return;
  }

  // Outros arquivos
  window.open(file.url, '_blank');
};

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');

  // Data States
  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [fileSystem, setFileSystem] = useState<any[]>([]);

  // UI States - Atendimento
  const [ticketSearchTerm, setTicketSearchTerm] = useState('');
  const [ticketFilter, setTicketFilter] = useState<'todos' | 'pendente' | 'ativo' | 'finalizado'>('todos');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  // UI States - General
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null); // Minha assinatura (Secretário)
  const [directorSignature, setDirectorSignature] = useState<string | null>(null); // Assinatura do Diretor (Simulada ou do banco)

  // File Explorer & Save States
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [internalFilePickerOpen, setInternalFilePickerOpen] = useState(false);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<any>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState('root');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [attachMode, setAttachMode] = useState(false);

  // Operational State
  const [opStudent, setOpStudent] = useState<any>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Audit Modal State
  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Ticket Listener
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        t.sort((a:any, b:any) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
        setTickets(t);
    });

    // File System Listener
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    // Students Listener
    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    // Fetch Signatures
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    // Tenta buscar assinatura do diretor (simulado: busca primeiro usuário com role 'diretor')
    const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
    getDocs(qDir).then(s => {
        if (!s.empty) setDirectorSignature(s.docs[0].data().signatureUrl);
    });

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid]);

  // Sync Chat
  useEffect(() => {
    if (!selectedTicketId) { setChatHistory([]); return; }
    const q = query(collection(db, 'tickets', selectedTicketId, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setChatHistory(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [selectedTicketId]);

  // --- FILE EXPLORER HELPERS ---
  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  };

  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);
  const moveTargetItems = useMemo(() => getFilesForFolder(moveTargetFolderId).filter(f => f.type === 'folder'), [fileSystem, moveTargetFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      if (ev.target?.result) {
        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name,
          type: 'file',
          mimeType: file.type,
          url: ev.target.result, 
          parentId: currentFolderId,
          size: file.size,
          createdAt: serverTimestamp(),
          createdBy: user.uid
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleMoveFile = async () => {
      if (!fileToMove) return;
      await updateDoc(doc(db, 'secretaria_arquivos', fileToMove.id), {
          parentId: moveTargetFolderId,
          updatedAt: serverTimestamp()
      });
      setMoveModalOpen(false);
      setFileToMove(null);
      alert("Arquivo movido com sucesso.");
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id);
    setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  // --- PDF GENERATOR (REAL PDF) ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
      setIsGeneratingPdf(true);

      try {
          // 1. Prepare Data
          const code = generateVerificationCode();
          const docTitle = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 
                           docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' : 
                           docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';

          let courseData: any = {};
          let modulesData: any[] = [];

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();

              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial), orderBy('order'));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data());
          }

          // 2. Generate QR Code Data URL
          const validationUrl = `https://escola-biblica-ead.web.app/verify?code=${code}`; // Exemplo de URL
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 100 });

          // 3. Initialize jsPDF
          const docPdf = new jsPDF({
              orientation: docType === 'conclusao' ? 'landscape' : 'portrait',
              unit: 'mm',
              format: 'a4'
          });

          const width = docPdf.internal.pageSize.getWidth();
          const height = docPdf.internal.pageSize.getHeight();

          // --- LAYOUT DRAWING ---

          // Borda Decorativa
          docPdf.setDrawColor(0);
          docPdf.setLineWidth(1);
          docPdf.rect(5, 5, width - 10, height - 10);
          docPdf.setLineWidth(0.5);
          docPdf.rect(7, 7, width - 14, height - 14);

          // Header (Logo & Escola)
          docPdf.setFont("times", "bold");
          docPdf.setFontSize(22);
          docPdf.text("ESCOLA BÍBLICA EAD", width / 2, 25, { align: "center" });

          docPdf.setFontSize(10);
          docPdf.setFont("helvetica", "normal");
          docPdf.text("Credenciamento MEC/CNE nº 999.999 | Portaria Nº 1004 de 17/08/2017", width / 2, 32, { align: "center" });
          docPdf.line(20, 35, width - 20, 35);

          // Título do Documento
          docPdf.setFont("times", "bold");
          docPdf.setFontSize(24);
          docPdf.text(docTitle, width / 2, 50, { align: "center" });

          // Corpo do Texto
          docPdf.setFont("times", "normal");
          docPdf.setFontSize(12);
          const margin = 25;
          let currentY = 70;

          const textData = `Certificamos para os devidos fins que o(a) aluno(a) ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF nº ${opStudent.cpf || '---'}, matrícula nº ${opStudent.academicId || '---'}.`;

          const splitText = docPdf.splitTextToSize(textData, width - (margin * 2));
          docPdf.text(splitText, margin, currentY);
          currentY += 20;

          // Conteúdo Específico
          if (docType === 'matricula') {
              docPdf.text(`Encontra-se regularmente MATRICULADO(A) no curso de ${courseData.nome || 'Teologia Livre'}, modalidade EAD.`, margin, currentY);
              currentY += 10;
              docPdf.text(`Situação Acadêmica: ${opStudent.status?.toUpperCase()}.`, margin, currentY);
          } else if (docType === 'conclusao') {
              docPdf.text(`Concluiu com êxito o curso de ${courseData.nome || 'Teologia'}, cumprindo a carga horária total exigida e obtendo a aprovação necessária.`, margin, currentY);
              currentY += 10;
              docPdf.text(`Data de Conclusão: ${new Date().toLocaleDateString('pt-BR')}`, margin, currentY);
          } else if (docType === 'historico') {
              currentY += 10;
              docPdf.setFont("helvetica", "bold");
              docPdf.text(`Curso: ${courseData.nome || '---'}`, margin, currentY);
              currentY += 10;

              const tableBody = modulesData.map((m: any) => [
                  m.title || "Módulo",
                  "20h", // Carga horária simulada ou real
                  "100%",
                  "10.0",
                  "APROVADO"
              ]);

              autoTable(docPdf, {
                  startY: currentY,
                  head: [['Disciplina / Módulo', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                  body: tableBody,
                  theme: 'grid',
                  headStyles: { fillColor: [40, 40, 40] },
                  styles: { fontSize: 9, font: "helvetica" },
                  margin: { left: margin, right: margin }
              });

              currentY = (docPdf as any).lastAutoTable.finalY + 20;
          }

          // Data e Local
          currentY = Math.max(currentY, height - 90);
          const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
          docPdf.text(dateStr, width - margin, currentY, { align: "right" });

          // Assinaturas
          const sigY = height - 60;

          // Assinatura Diretor
          if (directorSignature) {
              docPdf.addImage(directorSignature, 'PNG', margin + 10, sigY - 20, 40, 20);
          }
          docPdf.line(margin + 10, sigY, margin + 70, sigY);
          docPdf.setFontSize(8);
          docPdf.text("Diretor Executivo", margin + 40, sigY + 5, { align: "center" });

          // Assinatura Secretário
          if (secSignature) {
              docPdf.addImage(secSignature, 'PNG', width - margin - 70, sigY - 20, 40, 20);
          }
          docPdf.line(width - margin - 70, sigY, width - margin - 10, sigY);
          docPdf.text("Secretaria Geral", width - margin - 40, sigY + 5, { align: "center" });

          // Rodapé de Validação (QR Code e Hash)
          const footerY = height - 25;
          docPdf.setDrawColor(200);
          docPdf.line(margin, footerY, width - margin, footerY);

          // QR Code Image
          docPdf.addImage(qrCodeDataUrl, 'PNG', margin, footerY + 2, 20, 20);

          // Texto de Validação
          docPdf.setFontSize(7);
          docPdf.setTextColor(100);
          docPdf.text("DOCUMENTO COM VALIDADE JURÍDICA", margin + 25, footerY + 8);
          docPdf.text(`Código de Autenticidade: ${code}`, margin + 25, footerY + 12);
          docPdf.text("Verifique a autenticidade deste documento lendo o QR Code ao lado.", margin + 25, footerY + 16);

          // 4. Output as Blob/Data URL
          const pdfBlob = docPdf.output('blob');
          const pdfBase64 = docPdf.output('datauristring'); // Para salvar no firestore se precisar

          // 5. Save to Firestore (Simulated File System)
          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: `${docTitle} - ${opStudent.displayName}.pdf`,
              type: 'file',
              mimeType: 'application/pdf',
              url: pdfBase64, // Na produção ideal, upload para Storage e salvar URL. Aqui salvamos base64.
              parentId: 'root', // Salva na raiz por padrão
              createdAt: serverTimestamp(),
              createdBy: user.uid,
              studentId: opStudent.uid,
              docType: docType
          });

          // 6. Open in New Tab for Printing
          const blobUrl = URL.createObjectURL(pdfBlob);
          window.open(blobUrl, '_blank');

          alert("Documento gerado com sucesso! Verifique a nova aba e a pasta 'Arquivos'.");

      } catch (e: any) {
          console.error("Erro ao gerar PDF:", e);
          alert("Erro ao gerar documento: " + e.message);
      } finally {
          setIsGeneratingPdf(false);
      }
  };

  // ... (Rest of chat logic remains same)

