                              key={f.id}
                              onClick={() => setMoveTargetFolderId(f.id)}
                              className={`p-3 rounded-lg cursor-pointer flex items-center gap-2 ml-4 ${moveTargetFolderId === f.id ? 'bg-indigo-100 text-indigo-700 font-bold' : 'hover:bg-white text-slate-600'}`}
                          >
                              <Folder size={16}/> {f.name}
                          </div>
