                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Printer size={14}/>} Matrícula
                             </button>
                             <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateAndSavePDF('conclusao')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Award size={14}/>} Diploma
                             </button>
