                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <ArrowRightLeft size={14}/>} Gerar Guia
                           </button>
                         )}
                         {opSubView === 'historico' && (
                           <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateAndSavePDF('historico')} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
