    const docRef = await addDoc(collection(db, 'tickets'), {
      user: user.displayName, senderId: user.uid, protocolo: Math.random().toString(36).substr(2, 9).toUpperCase(),
      lastMessage: 'Atendimento Iniciado', status: 'Pendente', createdAt: serverTimestamp(), updatedAt: serverTimestamp()
    });
    await addDoc(collection(db, 'tickets', docRef.id, 'messages'), {
      text: `Olá ${user.displayName?.split(' ')[0]}. Sou o assistente virtual. Selecione um tema abaixo para que eu possa te ajudar:`,
      sender: 'Sistema', isBot: true, options: ['Problemas de Acesso', 'Material Didático', 'Aplicativo / Perfil', 'Elogio / Sugestão', 'Reclamação'], createdAt: serverTimestamp()
    });
    const newTicketSnap = await getDoc(docRef);
    if (newTicketSnap.exists()) { setActiveTicket({ id: newTicketSnap.id, ...newTicketSnap.data() }); }
  };

  const handleBotOption = async (option: string) => {
    if(!activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: option, sender: 'Aluno', createdAt: serverTimestamp() });
    let botResponse = ''; let nextOptions: string[] = []; let escalate = false;
    switch(option) {
        case 'Problemas de Acesso': botResponse = 'Para problemas de acesso: 1. Verifique se sua senha está correta. 2. Tente redefinir a senha no perfil. 3. Limpe o cache do navegador. Isso resolveu?'; nextOptions = ['Sim, resolvido', 'Não, preciso de ajuda']; break;
        case 'Material Didático': botResponse = 'Para materiais: O download é liberado após a conclusão da aula anterior. Verifique se há aulas pendentes no módulo. Conseguiu baixar?'; nextOptions = ['Sim, resolvido', 'Não, material com erro']; break;
        case 'Aplicativo / Perfil': botResponse = 'Você pode editar seus dados (Foto, WhatsApp, Senha) na aba "Meu Perfil". O sistema atualiza imediatamente. Conseguiu editar?'; nextOptions = ['Sim, resolvido', 'Não, erro ao salvar']; break;
        case 'Elogio / Sugestão': botResponse = 'Que ótimo! Por favor, digite seu elogio ou sugestão abaixo. Nós leremos com carinho!'; break;
        case 'Reclamação': botResponse = 'Sinto muito por isso. Por favor, descreva o problema detalhadamente abaixo. Um atendente humano irá analisar seu caso com prioridade.'; escalate = true; break;
        case 'Sim, resolvido': botResponse = 'Fico feliz em ajudar! Vou encerrar este atendimento. Por favor, avalie nosso suporte.'; await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Resolvido' }); break;
        case 'Não, preciso de ajuda': case 'Não, material com erro': case 'Não, erro ao salvar': botResponse = 'Aguarde enquanto chamo um especialista. Um atendente entrará no chat em instantes.'; escalate = true; break;
        default: botResponse = 'Certo. Por favor, descreva sua solicitação para o atendente.';
    }
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: botResponse, sender: 'Sistema', isBot: true, options: nextOptions.length > 0 ? nextOptions : undefined, createdAt: serverTimestamp() });
    const updatePayload: any = { lastMessage: `Bot: ${option}`, updatedAt: serverTimestamp() };
    if (escalate) { updatePayload.status = 'Pendente'; updatePayload.createdAt = serverTimestamp(); }
    await updateDoc(doc(db, 'tickets', activeTicket.id), updatePayload);
  };

  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: chatMessage, sender: 'Aluno', createdAt: serverTimestamp() });
    await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: chatMessage, updatedAt: serverTimestamp() });
    setChatMessage('');
  };

  const handleChatFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file || !activeTicket) return;
    const reader = new FileReader();
    reader.onload = async (ev) => { if(ev.target?.result) { const base64 = ev.target.result as string; await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: `Arquivo enviado: ${file.name}`, attachmentUrl: base64, sender: 'Aluno', createdAt: serverTimestamp() }); await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: `[Arquivo]: ${file.name}`, updatedAt: serverTimestamp() }); } };
    reader.readAsDataURL(file);
  };

  const handleStudentFinalize = async () => {
    if(!activeTicket) return;
    if(!confirm("Deseja encerrar este atendimento?")) return;
    await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Finalizado', updatedAt: serverTimestamp() });
    setActiveTicket((prev: any) => prev ? {...prev, status: 'Finalizado'} : null);
  };

  const submitSurvey = async () => {
    if (!activeTicket) return;
    await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Arquivado', survey: survey, archivedAt: serverTimestamp() });
    setSurvey({ demandMet: null, problemSolved: null, likedChat: null, rating: 0 });
    setActiveTicket(null);
  };

  // --- PDF GENERATOR (REAL PDF) ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
      setIsGeneratingPdf(true);

      try {
          // 1. Prepare Data
          const code = generateVerificationCode();
          const docTitle = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 
                           docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' : 
                           docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';

          let courseData: any = {};
          let modulesData: any[] = [];

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();

              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial), orderBy('order'));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data());
          }

          // Use current origin for validation URL
          const validationUrl = `${window.location.origin}?code=${code}`;
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 100 });

          const docPdf = new jsPDF({
              orientation: docType === 'conclusao' ? 'landscape' : 'portrait',
              unit: 'mm',
              format: 'a4'
          });

          const width = docPdf.internal.pageSize.getWidth();
          const height = docPdf.internal.pageSize.getHeight();

          docPdf.setDrawColor(0);
          docPdf.setLineWidth(1);
          docPdf.rect(5, 5, width - 10, height - 10);
          docPdf.setLineWidth(0.5);
          docPdf.rect(7, 7, width - 14, height - 14);

          docPdf.setFont("times", "bold");
          docPdf.setFontSize(22);
          docPdf.text("ESCOLA BÍBLICA EAD", width / 2, 25, { align: "center" });

          docPdf.setFontSize(10);
          docPdf.setFont("helvetica", "normal");
          docPdf.text("Credenciamento MEC/CNE nº 999.999 | Portaria Nº 1004 de 17/08/2017", width / 2, 32, { align: "center" });
          docPdf.line(20, 35, width - 20, 35);

          docPdf.setFont("times", "bold");
          docPdf.setFontSize(24);
          docPdf.text(docTitle, width / 2, 50, { align: "center" });

          docPdf.setFont("times", "normal");
          docPdf.setFontSize(12);
          const margin = 25;
          let currentY = 70;

          const textData = `Certificamos para os devidos fins que o(a) aluno(a) ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF nº ${opStudent.cpf || '---'}, matrícula nº ${opStudent.academicId || '---'}.`;

          const splitText = docPdf.splitTextToSize(textData, width - (margin * 2));
          docPdf.text(splitText, margin, currentY);
          currentY += 20;

          if (docType === 'matricula') {
              docPdf.text(`Encontra-se regularmente MATRICULADO(A) no curso de ${courseData.nome || 'Teologia Livre'}, modalidade EAD.`, margin, currentY);
              currentY += 10;
              docPdf.text(`Situação Acadêmica: ${opStudent.status?.toUpperCase()}.`, margin, currentY);
          } else if (docType === 'conclusao') {
              docPdf.text(`Concluiu com êxito o curso de ${courseData.nome || 'Teologia'}, cumprindo a carga horária total exigida e obtendo a aprovação necessária.`, margin, currentY);
              currentY += 10;
              docPdf.text(`Data de Conclusão: ${new Date().toLocaleDateString('pt-BR')}`, margin, currentY);
          } else if (docType === 'historico') {
              currentY += 10;
              docPdf.setFont("helvetica", "bold");
              docPdf.text(`Curso: ${courseData.nome || '---'}`, margin, currentY);
              currentY += 10;

              const tableBody = modulesData.map((m: any) => [
                  m.title || "Módulo",
                  "20h",
                  "100%",
                  "10.0",
                  "APROVADO"
              ]);

              autoTable(docPdf, {
                  startY: currentY,
                  head: [['Disciplina / Módulo', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                  body: tableBody,
                  theme: 'grid',
                  headStyles: { fillColor: [40, 40, 40] },
                  styles: { fontSize: 9, font: "helvetica" },
                  margin: { left: margin, right: margin }
              });

              currentY = (docPdf as any).lastAutoTable.finalY + 20;
          }

          currentY = Math.max(currentY, height - 90);
          const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
          docPdf.text(dateStr, width - margin, currentY, { align: "right" });

          const sigY = height - 60;

          if (directorSignature) {
              docPdf.addImage(directorSignature, 'PNG', margin + 10, sigY - 20, 40, 20);
          }
          docPdf.line(margin + 10, sigY, margin + 70, sigY);
          docPdf.setFontSize(8);
          docPdf.text("Diretor Executivo", margin + 40, sigY + 5, { align: "center" });

          if (secSignature) {
              docPdf.addImage(secSignature, 'PNG', width - margin - 70, sigY - 20, 40, 20);
          }
          docPdf.line(width - margin - 70, sigY, width - margin - 10, sigY);
          docPdf.text("Secretaria Geral", width - margin - 40, sigY + 5, { align: "center" });

          const footerY = height - 25;
          docPdf.setDrawColor(200);
          docPdf.line(margin, footerY, width - margin, footerY);

          docPdf.addImage(qrCodeDataUrl, 'PNG', margin, footerY + 2, 20, 20);

          docPdf.setFontSize(7);
          docPdf.setTextColor(100);
          docPdf.text("DOCUMENTO COM VALIDADE JURÍDICA", margin + 25, footerY + 8);
          docPdf.text(`Código de Autenticidade: ${code}`, margin + 25, footerY + 12);
          docPdf.text("Verifique a autenticidade deste documento lendo o QR Code ao lado.", margin + 25, footerY + 16);

          const pdfBase64 = docPdf.output('datauristring');
          const pdfBlob = docPdf.output('blob');

          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: `${docTitle} - ${opStudent.displayName}.pdf`,
              type: 'file',
              mimeType: 'application/pdf',
              url: pdfBase64,
              parentId: 'root',
              createdAt: serverTimestamp(),
              createdBy: user.uid,
              studentId: opStudent.uid,
              docType: docType,
              // Save critical data for verification view
              docData: {
                  code,
                  title: docTitle,
                  date: new Date().toISOString(),
                  student: {
                      displayName: opStudent.displayName,
                      cpf: opStudent.cpf,
                      academicId: opStudent.academicId
                  },
                  courseData: courseData,
                  modulesData: modulesData
              }
          });

          const blobUrl = URL.createObjectURL(pdfBlob);
          window.open(blobUrl, '_blank');

          alert("Documento gerado com sucesso! Verifique a nova aba e a pasta 'Arquivos'.");

      } catch (e: any) {
          console.error("Erro ao gerar PDF:", e);
          alert("Erro ao gerar documento: " + e.message);
      } finally {
          setIsGeneratingPdf(false);
      }
  };

  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              ...editingStudent,
              updatedAt: serverTimestamp()
          });
          alert('Dados do aluno atualizados.');
          setAuditModalOpen(false);
          setEditingStudent(null);
      } catch (e: any) {
          alert('Erro ao salvar: ' + e.message);
      }
  };

  const validateStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              status: 'ativo',
              updatedAt: serverTimestamp()
          });
          alert('Matrícula validada com sucesso.');
          setAuditModalOpen(false);
          setEditingStudent(null);
      } catch (e: any) {
          alert('Erro ao validar: ' + e.message);
      }
  };

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); if(t !== 'chat') setActiveTicket(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="flex-1 overflow-hidden flex flex-col">
         {activeTab === 'atendimento' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                <div className="p-4 bg-slate-50 border-b flex gap-2">
                    {['todos', 'pendente', 'ativo', 'finalizado'].map((f:any) => (
                        <button key={f} onClick={() => setTicketFilter(f)} className={`px-3 py-1 rounded text-[10px] font-black uppercase ${ticketFilter === f ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}>{f}</button>
                    ))}
                </div>
                <div className="flex-1 overflow-y-auto p-4">
                    {tickets.filter(t => ticketFilter === 'todos' || t.status.toLowerCase() === ticketFilter).map(t => (
                        <div key={t.id} className="flex justify-between p-3 border-b hover:bg-slate-50">
                            <div><span className="font-bold text-xs">#{t.protocolo}</span> - {t.user}</div>
                            <button onClick={() => {setActiveTicket(t); setActiveTab('chat');}} className="text-indigo-600 text-[10px] font-bold uppercase">Abrir</button>
                        </div>
                    ))}
                </div>
             </div>
         )}

         {activeTab === 'chat' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col relative">
                {activeTicket ? (
                  <>
                    <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
                       <div><h3 className="font-black text-slate-900 text-sm uppercase italic">Protocolo #{activeTicket.protocolo}</h3><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Status: {activeTicket.status}</p></div>
                       {timerDisplay && <div className="flex items-center gap-2 px-3 py-1 bg-amber-50 text-amber-600 rounded-lg border border-amber-100 animate-pulse"><Timer size={12} /><span className="text-[10px] font-black uppercase">Espera: {timerDisplay}</span></div>}
                       <div className="flex gap-2">
                           {activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado' && <button onClick={handleStudentFinalize} className="px-4 py-2 bg-rose-50 text-rose-600 rounded-xl text-[9px] font-black uppercase hover:bg-rose-600 hover:text-white transition-all">Encerrar Atendimento</button>}
                           {(activeTicket.status === 'Resolvido' || activeTicket.status === 'Finalizado') && <div className="px-3 py-1 bg-emerald-100 text-emerald-700 rounded-lg text-[9px] font-black uppercase animate-pulse">Pesquisa Pendente</div>}
                       </div>
                    </div>
                    <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/50 custom-scrollbar relative">
                       {messages.map((m, i) => (
                         <div key={i} className={`flex flex-col ${m.sender === 'Aluno' ? 'items-end' : 'items-start'}`}>
                            <div className={`max-w-[70%] p-4 rounded-2xl text-xs font-medium leading-relaxed shadow-sm ${m.sender === 'Aluno' ? 'bg-indigo-600 text-white rounded-tr-sm' : m.sender === 'Sistema' ? 'bg-white border border-slate-200 text-slate-700' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-sm'}`}>
                               {m.text}
                               {m.attachmentUrl && <div onClick={() => viewAttachment(m.attachmentUrl)} className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20 text-white"><FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Visualizar Anexo</span> <ExternalLink size={10}/></div>}
                            </div>
                            {m.sender === 'Sistema' && m.options && (activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado') && (
                                <div className="mt-3 flex flex-wrap gap-2 max-w-[80%]">{m.options.map((opt: string) => <button key={opt} onClick={() => handleBotOption(opt)} className="px-4 py-2 bg-indigo-50 text-indigo-600 border border-indigo-100 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-600 hover:text-white transition-all shadow-sm">{opt}</button>)}</div>
                            )}
                            <span className="text-[8px] font-bold text-slate-300 mt-1 uppercase px-2">{m.sender}</span>
                         </div>
                       ))}
                       <div ref={chatEndRef} />
                    </div>
                    {activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado' ? (
                      <div className="p-4 border-t border-slate-100 bg-white"><div className="flex gap-3"><button onClick={() => chatFileInputRef.current?.click()} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-indigo-100 hover:text-indigo-600 transition-all"><Paperclip size={18}/></button><input type="file" ref={chatFileInputRef} className="hidden" onChange={handleChatFileUpload}/><input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendMessage()} className="flex-1 bg-slate-50 border-none rounded-xl px-4 py-3 text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600" placeholder="Digite sua mensagem..." /><button onClick={sendMessage} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all"><Send size={18}/></button></div></div>
                    ) : <div className="p-4 bg-slate-100 text-center text-[10px] font-black uppercase text-slate-400">Atendimento Encerrado.</div>}
                  </>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-4"><LifeBuoy size={64} className="opacity-20"/><p className="text-xs font-black uppercase tracking-widest opacity-50">Selecione um chamado.</p></div>
                )}
             </div>
         )}

         {(activeTab === 'arquivos' || attachMode) && !activeTicket && (
           <div className={`bg-white border border-slate-200 rounded-xl overflow-hidden h-full flex flex-col shadow-lg ${attachMode ? 'fixed inset-10 z-[3000] border-indigo-600 border-4' : ''}`}>
              <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                 <div className="flex items-center gap-2 overflow-x-auto">
                    <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-200 rounded-lg"><Home size={16}/></button>
                    {folderPath.map((f, i) => (
                      <React.Fragment key={f.id}>
                        {i > 0 && <ChevronRight size={14} className="text-slate-400"/>}
                        <button onClick={() => handleBreadcrumb(i)} className={`text-xs font-bold px-2 py-1 rounded-lg hover:bg-slate-200 ${i === folderPath.length -1 ? 'text-slate-900' : 'text-slate-500'}`}>{f.name}</button>
                      </React.Fragment>
                    ))}
                 </div>
                 <div className="flex gap-2">
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} />
                    <button onClick={() => fileInputRef.current?.click()} className="px-3 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-indigo-600"><UploadCloud size={14}/> Upload</button>
                    <button onClick={handleCreateFolder} className="px-3 py-2 bg-slate-200 text-slate-700 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-slate-300"><FolderPlus size={14}/> Pasta</button>
                    {attachMode && <button onClick={() => setAttachMode(false)} className="px-3 py-2 bg-rose-600 text-white rounded-lg text-[9px] font-black uppercase">Fechar</button>}
                 </div>
              </div>
              <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50/50">
                 {currentItems.length === 0 ? (
                   <div className="h-full flex flex-col items-center justify-center opacity-30 gap-4"><Folder size={48} /><p className="text-xs font-black uppercase">Pasta Vazia</p></div>
                 ) : (
                   <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                      {currentItems.map(item => (
                        <div key={item.id} 
                             onDoubleClick={() => item.type === 'folder' ? handleNavigate(item) : null}
                             className={`bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all group flex flex-col items-center text-center cursor-pointer relative`}
                        >
                           <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-3 text-white shadow-inner ${item.type === 'folder' ? 'bg-amber-400' : 'bg-indigo-500'}`}>
                              {item.type === 'folder' ? <Folder size={32} className="fill-white/50"/> : <FileText size={32} className="fill-white/50"/>}
                           </div>
                           <p className="text-[10px] font-bold text-slate-700 line-clamp-2 leading-tight w-full break-words">{item.name}</p>
                           {item.type === 'file' && (
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 flex gap-1 bg-white/90 rounded-lg p-1 shadow-sm">
                               <button onClick={async (e) => { e.stopPropagation(); if(confirm('Apagar?')) await deleteDoc(doc(db, 'secretaria_arquivos', item.id)); }} className="p-1.5 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100"><Trash2 size={12}/></button>
                               <button onClick={(e) => { e.stopPropagation(); setFileToMove(item); setMoveModalOpen(true); }} className="p-1.5 bg-slate-50 text-slate-600 rounded-lg hover:bg-slate-100"><Move size={12}/></button>
                               <button onClick={(e) => { e.stopPropagation(); viewFile(item); }} className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100"><Eye size={12}/></button>
                             </div>
                           )}
                        </div>
                      ))}
                   </div>
                 )}
              </div>
           </div>
         )}

         {activeTab === 'operacional' && (
