    getDocs(qDir).then(s => {
        if (!s.empty) setDirectorSignature(s.docs[0].data().signatureUrl);
    });

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid, activeTicket?.id]);

  useEffect(() => {
    if (!activeTicket) { setMessages([]); return; }
    const q = query(collection(db, 'tickets', activeTicket.id, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [activeTicket]);

  useEffect(() => {
    let interval: any;
    if (activeTicket && activeTicket.status === 'Pendente' && !activeTicket.specialistJoined) {
        interval = setInterval(async () => {
            const now = Date.now();
            const created = activeTicket.createdAt?.seconds ? activeTicket.createdAt.seconds * 1000 : Date.now();
            const diff = now - created;
            const limit = 5 * 60 * 1000;
            if (diff >= limit) {
                const hasTimeoutMsg = messages.some((m: any) => m.text.includes("todos os atendentes e especialistas estão ocupados"));
                if (!hasTimeoutMsg) {
                    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
                        text: "Infelizmente, todos os atendentes e especialistas estão ocupados no momento. Sua solicitação foi registrada e entraremos em contato através do seu WhatsApp cadastrado em breve.",
                        sender: 'Sistema', isBot: true, createdAt: serverTimestamp()
                    });
                    await updateDoc(doc(db, 'tickets', activeTicket.id), {
                        status: 'Encaminhado', lastMessage: "Encaminhado para WhatsApp (Timeout)", updatedAt: serverTimestamp()
                    });
                }
                setTimerDisplay("Tempo esgotado");
            } else {
                const remaining = Math.ceil((limit - diff) / 1000);
                const mins = Math.floor(remaining / 60);
                const secs = remaining % 60;
                setTimerDisplay(`${mins}:${secs.toString().padStart(2, '0')}`);
            }
        }, 1000);
    } else { setTimerDisplay(''); }
    return () => clearInterval(interval);
  }, [activeTicket, messages]);

  // --- FILE EXPLORER ---
  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  };
  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      if (ev.target?.result) {
        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name, type: 'file', mimeType: file.type, url: ev.target.result, 
          parentId: currentFolderId, size: file.size, createdAt: serverTimestamp(), createdBy: user.uid
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleMoveFile = async () => {
      if (!fileToMove) return;
      await updateDoc(doc(db, 'secretaria_arquivos', fileToMove.id), {
          parentId: moveTargetFolderId, updatedAt: serverTimestamp()
      });
      setMoveModalOpen(false); setFileToMove(null); alert("Arquivo movido.");
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id); setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1); setFolderPath(newPath); setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  // --- CHAT ---
  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: chatMessage, sender: 'Aluno', createdAt: serverTimestamp() });
    await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: chatMessage, updatedAt: serverTimestamp() });
    setChatMessage('');
  };

  const handleChatFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file || !activeTicket) return;
    const reader = new FileReader();
    reader.onload = async (ev) => { if(ev.target?.result) { const base64 = ev.target.result as string; await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: `Arquivo enviado: ${file.name}`, attachmentUrl: base64, sender: 'Aluno', createdAt: serverTimestamp() }); await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: `[Arquivo]: ${file.name}`, updatedAt: serverTimestamp() }); } };
    reader.readAsDataURL(file);
  };

  const handleStudentFinalize = async () => {
    if(!activeTicket) return;
    if(!confirm("Deseja encerrar este atendimento?")) return;
    await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Finalizado', updatedAt: serverTimestamp() });
    setActiveTicket((prev: any) => prev ? {...prev, status: 'Finalizado'} : null);
  };

  // --- PDF GENERATOR (PREMIUM DESIGN) ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
      setIsGeneratingPdf(true);

      try {
          const code = generateVerificationCode();
          const docTitle = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 
                           docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' : 
                           docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';

          let courseData: any = {};
          let modulesData: any[] = [];

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();
              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data()).sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
          }

          const validationUrl = `${window.location.origin}?code=${code}`;
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 100 });

          const docPdf = new jsPDF({
              orientation: docType === 'conclusao' ? 'landscape' : 'portrait',
              unit: 'mm',
              format: 'a4'
          });

          const width = docPdf.internal.pageSize.getWidth();
          const height = docPdf.internal.pageSize.getHeight();
          const centerX = width / 2;

          // --- 1. MOLDURA DOURADA (Elegância) ---
          const goldColor = [197, 160, 89];
          const marginBox = 10;

          // Borda Externa Grossa
          docPdf.setDrawColor(goldColor[0], goldColor[1], goldColor[2]);
          docPdf.setLineWidth(2);
          docPdf.rect(marginBox, marginBox, width - (marginBox * 2), height - (marginBox * 2));

          // Borda Interna Fina
          docPdf.setLineWidth(0.5);
          docPdf.rect(marginBox + 2, marginBox + 2, width - (marginBox * 2) - 4, height - (marginBox * 2) - 4);

          // --- 2. CABEÇALHO (Centralizado) ---
          let currentY = 35;

          // Logo Vetorial Simples (Escudo)
          docPdf.setFillColor(30, 41, 59); // Slate 900
          docPdf.circle(centerX, currentY - 10, 8, 'F');
          docPdf.setTextColor(255, 255, 255);
          docPdf.setFontSize(8);
          docPdf.setFont("times", "bold");
          docPdf.text("EB", centerX, currentY - 8, { align: "center" });

          currentY += 10;
          docPdf.setTextColor(0, 0, 0);
          docPdf.setFont("times", "bold");
          docPdf.setFontSize(26);
          docPdf.text("ESCOLA BÍBLICA EAD", centerX, currentY, { align: "center" });

          currentY += 8;
          docPdf.setFontSize(10);
          docPdf.setFont("helvetica", "normal");
          docPdf.setTextColor(100);
          docPdf.text("Credenciamento MEC/CNE nº 999.999 | Portaria Nº 1004 de 17/08/2017", centerX, currentY, { align: "center" });

          currentY += 20;
          docPdf.setDrawColor(200);
          docPdf.setLineWidth(0.5);
          docPdf.line(40, currentY, width - 40, currentY);

          // --- 3. TÍTULO DO DOCUMENTO ---
          currentY += 20;
          docPdf.setFont("times", "bold");
          docPdf.setFontSize(24);
          docPdf.setTextColor(30, 41, 59);
          docPdf.text(docTitle, centerX, currentY, { align: "center" });

          // --- 4. CONTEÚDO DINÂMICO (Quebra de Linha Automática) ---
          currentY += 25;
          docPdf.setFont("times", "normal");
          docPdf.setFontSize(14);
          docPdf.setTextColor(0);

          const textMargin = 30;
          const maxLineWidth = width - (textMargin * 2);
          const lineHeight = 8;

          // Parágrafo Principal
          const p1 = `Certificamos para os devidos fins que o(a) aluno(a) ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF nº ${opStudent.cpf || '---'}, matrícula institucional nº ${opStudent.academicId || '---'}.`;
          const p1Lines = docPdf.splitTextToSize(p1, maxLineWidth);
          docPdf.text(p1Lines, centerX, currentY, { align: "center" });
          currentY += (p1Lines.length * lineHeight) + 5;

          // Parágrafo Secundário (Específico por tipo)
          let p2 = "";
          if (docType === 'matricula') {
              p2 = `Encontra-se regularmente MATRICULADO(A) no curso de ${courseData.nome || 'Teologia Livre'}, modalidade Ensino a Distância (EAD), usufruindo de todos os direitos e deveres acadêmicos previstos no regimento interno desta instituição. Situação Acadêmica atual: ${opStudent.status?.toUpperCase()}.`;
          } else if (docType === 'conclusao') {
              p2 = `Concluiu com êxito todos os requisitos acadêmicos do curso de ${courseData.nome || 'Teologia'}, cumprindo a carga horária total exigida, obtendo a aprovação necessária em todas as disciplinas e demonstrando aptidão técnica e teológica. Data oficial de conclusão: ${new Date().toLocaleDateString('pt-BR')}.`;
          }

          if (p2) {
              const p2Lines = docPdf.splitTextToSize(p2, maxLineWidth);
              docPdf.text(p2Lines, centerX, currentY, { align: "center" });
              currentY += (p2Lines.length * lineHeight) + 10;
          }

          // Tabela para Histórico
          if (docType === 'historico') {
              currentY += 5;
              docPdf.setFont("helvetica", "bold");
              docPdf.setFontSize(12);
              docPdf.text(`Grade Curricular: ${courseData.nome || '---'}`, textMargin, currentY);
              currentY += 5;

              const tableBody = modulesData.map((m: any) => [
                  m.title || "Módulo",
                  "20h",
                  "100%",
                  "10.0",
                  "APROVADO"
              ]);

              autoTable(docPdf, {
                  startY: currentY,
                  head: [['Disciplina / Módulo', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                  body: tableBody,
                  theme: 'grid',
                  headStyles: { fillColor: [30, 41, 59], halign: 'center' },
                  bodyStyles: { halign: 'center' },
                  styles: { fontSize: 10, font: "helvetica" },
                  margin: { left: textMargin, right: textMargin }
              });

              currentY = (docPdf as any).lastAutoTable.finalY + 20;
          }

          // --- 5. DATA E LOCAL ---
          currentY = Math.max(currentY, height - 90); // Garante que fique na parte inferior mas acima das assinaturas
          const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
          docPdf.setFont("times", "normal");
          docPdf.setFontSize(12);
          docPdf.text(dateStr, width - textMargin, currentY, { align: "right" });

          // --- 6. ASSINATURAS (Centralizadas e Lado a Lado) ---
          const sigY = height - 60;
          const sigGap = 80; // Distância entre os centros das assinaturas

          // Diretor (Esquerda)
          const dirX = centerX - 50;
          if (directorSignature) {
              docPdf.addImage(directorSignature, 'PNG', dirX - 25, sigY - 20, 50, 20);
          }
          docPdf.setDrawColor(0);
          docPdf.line(dirX - 35, sigY, dirX + 35, sigY);
          docPdf.setFontSize(10);
          docPdf.setFont("helvetica", "bold");
          docPdf.text("DIRETOR EXECUTIVO", dirX, sigY + 5, { align: "center" });
          docPdf.setFontSize(8);
          docPdf.setFont("helvetica", "normal");
          docPdf.setTextColor(100);
          docPdf.text("Registro nº 001/MEC", dirX, sigY + 9, { align: "center" });

          // Secretário (Direita)
          const secX = centerX + 50;
          if (secSignature) {
              docPdf.addImage(secSignature, 'PNG', secX - 25, sigY - 20, 50, 20);
          }
          docPdf.setTextColor(0);
          docPdf.line(secX - 35, sigY, secX + 35, sigY);
          docPdf.setFontSize(10);
          docPdf.setFont("helvetica", "bold");
          docPdf.text("SECRETARIA GERAL", secX, sigY + 5, { align: "center" });
          docPdf.setFontSize(8);
          docPdf.setFont("helvetica", "normal");
          docPdf.setTextColor(100);
          docPdf.text("Registro nº 042/SEC", secX, sigY + 9, { align: "center" });

          // --- 7. RODAPÉ DE VALIDAÇÃO (QR Code + Hash) ---
          const footerY = height - 28;
          docPdf.setDrawColor(goldColor[0], goldColor[1], goldColor[2]);
          docPdf.setLineWidth(0.5);
          docPdf.line(marginBox + 10, footerY, width - marginBox - 10, footerY);

          // QR Code
          docPdf.addImage(qrCodeDataUrl, 'PNG', marginBox + 10, footerY + 2, 22, 22);

          // Texto Legal
          docPdf.setFontSize(8);
          docPdf.setTextColor(80);
          docPdf.text("DOCUMENTO COM VALIDADE JURÍDICA NACIONAL", marginBox + 36, footerY + 8);
          docPdf.text(`Código de Autenticidade Digital: ${code}`, marginBox + 36, footerY + 13);
          docPdf.setFontSize(7);
          docPdf.setTextColor(150);
          docPdf.text("Para verificar a veracidade deste documento, escaneie o QR Code ou acesse o portal de validação.", marginBox + 36, footerY + 18);

          // Salvar e Output
          const pdfBase64 = docPdf.output('datauristring');
          const pdfBlob = docPdf.output('blob');

          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: `${docTitle} - ${opStudent.displayName}.pdf`,
              type: 'file', mimeType: 'application/pdf', url: pdfBase64,
              parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid,
              studentId: opStudent.uid, docType: docType,
              docData: {
                  code, title: docTitle, date: new Date().toISOString(),
                  student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId },
                  courseData: courseData, modulesData: modulesData
              }
          });

          const blobUrl = URL.createObjectURL(pdfBlob);
          window.open(blobUrl, '_blank');
          alert("Documento oficial gerado e registrado com sucesso.");

      } catch (e: any) {
          console.error("Erro PDF:", e);
          alert("Erro: " + e.message);
      } finally {
          setIsGeneratingPdf(false);
      }
  };

  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), { ...editingStudent, updatedAt: serverTimestamp() });
          alert('Dados do aluno atualizados.'); setAuditModalOpen(false); setEditingStudent(null);
      } catch (e: any) { alert('Erro ao salvar: ' + e.message); }
  };

  const validateStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), { status: 'ativo', updatedAt: serverTimestamp() });
          alert('Matrícula validada com sucesso.'); setAuditModalOpen(false); setEditingStudent(null);
      } catch (e: any) { alert('Erro ao validar: ' + e.message); }
  };

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); if(t !== 'chat') setActiveTicket(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="flex-1 overflow-hidden flex flex-col">

         {/* --- ÁREA DE ATENDIMENTO RESTAURADA COM TABELA --- */}
         {activeTab === 'atendimento' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                {/* Header e Filtros */}
                <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row justify-between gap-4 items-center bg-slate-50/50">
                    <div className="relative w-full md:w-96">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                        <input value={ticketSearchTerm} onChange={e => setTicketSearchTerm(e.target.value)} placeholder="Buscar protocolo ou aluno..." className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" />
                    </div>
                    <div className="flex gap-2 p-1 bg-slate-100 rounded-xl">
                        {['todos', 'pendente', 'ativo', 'finalizado'].map((f:any) => (
                            <button key={f} onClick={() => setTicketFilter(f)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${ticketFilter === f ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>{f}</button>
                        ))}
                    </div>
                </div>

                {/* Tabela de Tickets */}
                <div className="flex-1 overflow-y-auto">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest sticky top-0 z-10 shadow-sm">
                            <tr>
                                <th className="px-6 py-4 border-b border-slate-100">Protocolo</th>
                                <th className="px-6 py-4 border-b border-slate-100">Aluno Solicitante</th>
                                <th className="px-6 py-4 border-b border-slate-100">Assunto / Última Msg</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-center">Status</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-center">Data</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-right">Ação</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {tickets.filter(t => 
                                (ticketFilter === 'todos' || t.status.toLowerCase() === ticketFilter) &&
                                (t.user?.toLowerCase().includes(ticketSearchTerm.toLowerCase()) || t.protocolo?.toLowerCase().includes(ticketSearchTerm.toLowerCase()))
                            ).map(t => (
                                <tr key={t.id} className="hover:bg-indigo-50/10 transition-colors group">
                                    <td className="px-6 py-4 font-mono text-xs font-bold text-indigo-600">#{t.protocolo}</td>
                                    <td className="px-6 py-4 font-black text-xs text-slate-800 uppercase italic">{t.user}</td>
                                    <td className="px-6 py-4">
                                        <p className="text-[10px] text-slate-500 line-clamp-1 italic font-medium max-w-[250px]">{t.lastMessage}</p>
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${
                                            t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-100' :
                                            t.status === 'Resolvido' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                                            t.status === 'Finalizado' ? 'bg-slate-100 text-slate-500 border-slate-200' :
                                            'bg-indigo-50 text-indigo-600 border-indigo-100'
                                        }`}>
                                            {t.status}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-center text-[10px] font-bold text-slate-400">
                                        {t.createdAt?.seconds ? new Date(t.createdAt.seconds * 1000).toLocaleDateString('pt-BR') : '-'}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button onClick={() => { setActiveTicket(t); setActiveTab('chat'); }} className="px-4 py-2 bg-indigo-600 text-white rounded-lg text-[9px] font-black uppercase hover:bg-indigo-700 shadow-sm transition-all">Abrir Painel</button>
                                    </td>
                                </tr>
                            ))}
                            {tickets.length === 0 && (
                                <tr><td colSpan={6} className="p-12 text-center text-slate-300 italic uppercase font-black text-xs">Nenhum atendimento encontrado.</td></tr>
                            )}
                        </tbody>
                    </table>
                </div>
             </div>
         )}

         {/* --- CHAT RESTAURADO --- */}
         {activeTab === 'chat' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col relative h-full">
                {activeTicket ? (
                  <>
                    {/* Chat Header */}
                    <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center shadow-sm z-10">
                       <div className="flex items-center gap-4">
                           <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center font-black italic">{activeTicket.user.charAt(0)}</div>
                           <div>
                               <h3 className="font-black text-slate-900 text-sm uppercase italic">Protocolo #{activeTicket.protocolo}</h3>
                               <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">{activeTicket.user} • Status: {activeTicket.status}</p>
                           </div>
                       </div>
                       {timerDisplay && <div className="flex items-center gap-2 px-4 py-2 bg-amber-50 text-amber-600 rounded-xl border border-amber-100 animate-pulse"><Timer size={14} /><span className="text-[10px] font-black uppercase">Espera: {timerDisplay}</span></div>}
                       <div className="flex gap-2">
                           <button onClick={() => { setActiveTicket(null); setActiveTab('atendimento'); }} className="px-4 py-2 bg-white border border-slate-200 rounded-xl text-[9px] font-black uppercase hover:bg-slate-50 text-slate-500">Voltar</button>
                           {activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado' && <button onClick={handleStudentFinalize} className="px-4 py-2 bg-rose-50 text-rose-600 rounded-xl text-[9px] font-black uppercase hover:bg-rose-600 hover:text-white transition-all border border-rose-100">Encerrar</button>}
                       </div>
                    </div>

                    {/* Chat Messages Area */}
                    <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/50 custom-scrollbar relative">
                       {messages.map((m, i) => (
                         <div key={i} className={`flex flex-col ${m.sender === 'Aluno' ? 'items-start' : 'items-end'}`}>
                            <div className={`max-w-[70%] p-4 rounded-2xl text-xs font-medium leading-relaxed shadow-sm relative group ${m.sender === 'Aluno' ? 'bg-white border border-slate-200 text-slate-700 rounded-tl-none' : m.isBot ? 'bg-slate-200 text-slate-700 rounded-tr-none' : 'bg-indigo-600 text-white rounded-tr-none'}`}>
                               {m.text}
                               {m.attachmentUrl && <div onClick={() => viewAttachment(m.attachmentUrl)} className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20 text-white"><FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Anexo</span> <ExternalLink size={10}/></div>}
                               <span className="text-[8px] font-bold opacity-50 absolute -bottom-5 block w-full">{m.sender} • {m.createdAt?.seconds ? new Date(m.createdAt.seconds*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) : '...'}</span>
                            </div>
                            {/* Bot Options */}
                            {m.sender === 'Sistema' && m.options && (activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado') && (
                                <div className="mt-6 flex flex-wrap gap-2 justify-end max-w-[80%] opacity-50 pointer-events-none">
                                    {m.options.map((opt: string) => <span key={opt} className="px-3 py-1 bg-slate-100 rounded-lg text-[9px] font-black uppercase border border-slate-200">{opt}</span>)}
                                </div>
                            )}
                         </div>
                       ))}
                       <div ref={chatEndRef} className="h-4" />
                    </div>

                    {/* Chat Input Area */}
                    {activeTicket.status !== 'Arquivado' && activeTicket.status !== 'Resolvido' && activeTicket.status !== 'Finalizado' ? (
