                               <div className="w-24 h-24 bg-white rounded-xl border border-slate-200 flex items-center justify-center overflow-hidden">
                                   {editingStudent.photoURL ? <img src={editingStudent.photoURL} className="w-full h-full object-cover"/> : <span className="text-[8px] font-black uppercase text-slate-300">Sem Foto</span>}
                               </div>
                               <div>
                                   <p className="text-xs font-bold text-slate-800">Foto de Identificação</p>
                                   <p className="text-[9px] text-slate-400">Status: {editingStudent.photoURL ? 'Enviado' : 'Pendente'}</p>
                               </div>
                           </div>
                       </div>

                       <div className="flex gap-4 pt-4 border-t border-slate-100">
                          <button onClick={saveEditedStudent} className="px-6 py-3 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase hover:bg-slate-200 flex items-center gap-2"><Edit3 size={14}/> Salvar Edições</button>
                          <button onClick={validateStudent} className="px-8 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-emerald-700 transition-all flex items-center gap-2 shadow-xl shadow-emerald-200"><CheckCircle2 size={16}/> Validar Matrícula</button>
                       </div>
                  </div>
              </div>
          </div>
      )}

      {isSignModalOpen && <SignaturePad title="Assinatura Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert("Assinatura Salva!"); }} />}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, addDoc, writeBatch, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, MessageSquare, Search, X, FileText, UserCheck, 
  ArrowRightLeft, Fingerprint, Send, Archive, Eye, 
  Printer, Folder, File, Download, Plus, ChevronRight,
  UploadCloud, FolderPlus, CheckCircle2, ShieldCheck,
  AlertTriangle, Home, Paperclip, Save, Timer,
  Trash2, Move, ExternalLink, LifeBuoy, BookOpen, Clock,
  FileInput, CheckSquare, Square, RefreshCw, Award, Edit3
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';
import { jsPDF } from "https://esm.sh/jspdf@2.5.1";
import autoTable from "https://esm.sh/jspdf-autotable@3.8.1";
import QRCode from "https://esm.sh/qrcode@1.5.3";

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'historico' | 'transferencia' | 'assinatura' | 'validacao';

// --- HELPERS ---
const generateVerificationCode = () => {
  return `${new Date().getFullYear()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}`;
};

const viewAttachment = (url: string) => {
    if (!url) return;
    if (url.startsWith('http')) { window.open(url, '_blank'); return; }
    if (url.startsWith('data:')) {
        const win = window.open();
        win?.document.write(`<iframe src="${url}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`);
    }
};

const viewFile = (file: any) => {
  if (!file || !file.url) return;
  if (file.mimeType === 'application/pdf' || file.name?.endsWith('.pdf')) {
      const newWindow = window.open();
      if (newWindow) {
          if (file.url.startsWith('data:')) {
             newWindow.document.write(
                 `<iframe width='100%' height='100%' src='${file.url}'></iframe>`
             );
             newWindow.document.title = file.name;
          } else {
             newWindow.location.href = file.url;
          }
      } else {
          alert("Pop-up bloqueado. Permita pop-ups para visualizar o PDF.");
      }
      return;
  }
  window.open(file.url, '_blank');
};

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');

  // Data States
  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [fileSystem, setFileSystem] = useState<any[]>([]);

  // UI States - Atendimento
  const [ticketSearchTerm, setTicketSearchTerm] = useState('');
  const [ticketFilter, setTicketFilter] = useState<'todos' | 'pendente' | 'ativo' | 'finalizado'>('todos');
  const [activeTicket, setActiveTicket] = useState<any | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [selectedTickets, setSelectedTickets] = useState<string[]>([]);
  const [viewTicketModal, setViewTicketModal] = useState<any | null>(null);
  const [internalFilePickerOpen, setInternalFilePickerOpen] = useState(false);

  // UI States - General
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);
  const [directorSignature, setDirectorSignature] = useState<string | null>(null);

  // File Explorer States
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<any>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState('root');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatFileInputRef = useRef<HTMLInputElement>(null);
  const [attachMode, setAttachMode] = useState(false); // For internal file picker in chat

  // Operational State
  const [opStudent, setOpStudent] = useState<any>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        // Sort by priority (Pending first) then Date
        t.sort((a:any, b:any) => {
            if (a.status === 'Pendente' && b.status !== 'Pendente') return -1;
            if (b.status === 'Pendente' && a.status !== 'Pendente') return 1;
            return (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0);
        });
        setTickets(t);
        if (activeTicket) {
            const updated = t.find((x: any) => x.id === activeTicket.id);
            if (updated) setActiveTicket(updated);
        }
    });

    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
    getDocs(qDir).then(s => { if (!s.empty) setDirectorSignature(s.docs[0].data().signatureUrl); });

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid, activeTicket?.id]);

  useEffect(() => {
    if (!activeTicket) { setMessages([]); return; }
    const q = query(collection(db, 'tickets', activeTicket.id, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [activeTicket]);

  // --- TICKET MANAGEMENT ---
  const calculateWaitTime = (createdAt: any) => {
      if (!createdAt) return '0 min';
      const start = createdAt.seconds ? createdAt.seconds * 1000 : Date.now();
      const diff = Date.now() - start;
      const mins = Math.floor(diff / 60000);
      if (mins < 60) return `${mins} min`;
      const hours = Math.floor(mins / 60);
      if (hours < 24) return `${hours}h ${mins % 60}min`;
      return `${Math.floor(hours / 24)}d`;
  };

  const handleBulkDelete = async () => {
      if (selectedTickets.length === 0) return;
      if (!confirm(`Deseja excluir ${selectedTickets.length} protocolos selecionados?`)) return;
      const batch = writeBatch(db);
      selectedTickets.forEach(tid => {
          batch.delete(doc(db, 'tickets', tid));
      });
      await batch.commit();
      setSelectedTickets([]);
  };

  const toggleSelectTicket = (id: string) => {
      if (selectedTickets.includes(id)) setSelectedTickets(prev => prev.filter(tid => tid !== id));
      else setSelectedTickets(prev => [...prev, id]);
  };

  const toggleSelectAll = () => {
      if (selectedTickets.length === tickets.length) setSelectedTickets([]);
      else setSelectedTickets(tickets.map(t => t.id));
  };

  // --- CHAT LOGIC ---
  const handleTicketAction = async (action: 'assume' | 'finalize' | 'archive') => {
      if (!activeTicket) return;
      let update: any = {};
      if (action === 'assume') {
          update = { status: 'Em Andamento', specialistId: user.uid, specialistName: user.displayName, updatedAt: serverTimestamp() };
          await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
              text: `O atendente ${user.displayName} assumiu este chamado.`,
              sender: 'Sistema', isBot: true, createdAt: serverTimestamp()
          });
      } else if (action === 'finalize') {
          update = { status: 'Resolvido', closedAt: serverTimestamp(), updatedAt: serverTimestamp() }; // Triggers survey for student
          await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
              text: `Atendimento finalizado. Por favor, avalie nosso suporte.`,
              sender: 'Sistema', isBot: true, createdAt: serverTimestamp()
          });
      } else if (action === 'archive') {
          update = { status: 'Arquivado', archivedAt: serverTimestamp() };
      }
      await updateDoc(doc(db, 'tickets', activeTicket.id), update);
  };

  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: chatMessage, sender: user.displayName || 'Atendente', role: 'staff', createdAt: serverTimestamp() });
    await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: chatMessage, updatedAt: serverTimestamp() });
    setChatMessage('');
  };

  const sendAttachment = async (file?: File, internalUrl?: string) => {
      if (!activeTicket) return;
      let url = internalUrl;
      let name = file?.name || 'Documento Interno';

      if (file) {
          const reader = new FileReader();
          reader.onload = async (ev) => {
              if (ev.target?.result) {
                  url = ev.target.result as string;
                  await processSend(url, name);
              }
          };
          reader.readAsDataURL(file);
      } else if (url) {
          await processSend(url, name);
      }

      async function processSend(finalUrl: string, fileName: string) {
        if (!activeTicket) return; // check again
        await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { 
            text: `Anexo enviado: ${fileName}`, 
            attachmentUrl: finalUrl, 
            sender: user.displayName, 
            role: 'staff',
            createdAt: serverTimestamp() 
        });
        setInternalFilePickerOpen(false);
      }
  };

  // --- PDF GENERATOR (DUPLA PÁGINA & DESIGN CORRIGIDO) ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno."); return; }
      setIsGeneratingPdf(true);

      try {
          const code = generateVerificationCode();
          const docTitle = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 
                           docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' : 
                           docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';

          let courseData: any = {};
          let modulesData: any[] = [];

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();
              // Client side sort to avoid index error
              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data()).sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
          }

          const validationUrl = `${window.location.origin}?code=${code}`;
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 0, width: 100 });

          const pdf = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
          const width = pdf.internal.pageSize.getWidth();
          const height = pdf.internal.pageSize.getHeight();
          const centerX = width / 2;

          // --- PÁGINA 1: FRENTE ---
          const drawFrame = (pDoc: any) => {
              const gold = [197, 160, 89];
              pDoc.setDrawColor(gold[0], gold[1], gold[2]);
              pDoc.setLineWidth(3);
              pDoc.rect(10, 10, width - 20, height - 20); // Outer
              pDoc.setLineWidth(0.5);
              pDoc.rect(13, 13, width - 26, height - 26); // Inner

              // Watermark
              pDoc.setTextColor(240, 240, 240);
              pDoc.setFontSize(100);
              pDoc.setFont("times", "bold");
              pDoc.withGraphicsState({ opacity: 0.1 }, () => {
                  pDoc.text("EB-EAD", centerX, height / 2, { align: "center", angle: 45 });
              });
              pDoc.withGraphicsState({ opacity: 1 }, () => {}); // Reset
          };

          const drawBibleLogo = (pDoc: any, x: number, y: number) => {
              pDoc.setFillColor(30, 41, 59); // Slate 900
              // Book cover
              pDoc.rect(x - 10, y, 20, 14, 'F');
              pDoc.setFillColor(255, 255, 255);
              // Pages line
              pDoc.rect(x - 9, y + 2, 18, 10, 'F');
              pDoc.setDrawColor(30, 41, 59);
              pDoc.setLineWidth(0.5);
              pDoc.line(x, y + 2, x, y + 12); // Center fold
          };

          drawFrame(pdf);

          // Header
          drawBibleLogo(pdf, centerX, 25);
          pdf.setFont("times", "bold");
          pdf.setTextColor(30, 41, 59);
          pdf.setFontSize(28);
          pdf.text("ESCOLA BÍBLICA EAD", centerX, 55, { align: "center" });

          pdf.setFont("helvetica", "normal");
          pdf.setFontSize(10);
          pdf.setTextColor(100);
          pdf.text("Credenciamento MEC/CNE nº 999.999 | Portaria Nº 1004 de 17/08/2017", centerX, 62, { align: "center" });

          pdf.setDrawColor(200);
          pdf.line(40, 68, width - 40, 68);

          // Title
          pdf.setFont("times", "bold");
          pdf.setFontSize(32);
          pdf.setTextColor(0);
          pdf.text(docTitle, centerX, 90, { align: "center" });

          // Body Content
          pdf.setFont("times", "normal");
          pdf.setFontSize(16);
          const bodyText = `Certificamos que ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF ${opStudent.cpf || '---'}, concluiu com êxito o curso de ${courseData.nome?.toUpperCase() || 'TEOLOGIA'}, cumprindo a carga horária exigida e obtendo o aproveitamento necessário para a outorga deste título.`;

          const splitBody = pdf.splitTextToSize(bodyText, width - 80);
          pdf.text(splitBody, centerX, 115, { align: "center" });

          // Date
          const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
          pdf.setFontSize(12);
          pdf.text(dateStr, width - 40, 150, { align: "right" });

          // Signatures (Fixed position at bottom, inside frame)
          const sigY = height - 50; 
          const dirX = centerX - 60;
          const secX = centerX + 60;

          if (directorSignature) pdf.addImage(directorSignature, 'PNG', dirX - 25, sigY - 25, 50, 20);
          pdf.setDrawColor(0);
          pdf.setLineWidth(0.5);
          pdf.line(dirX - 40, sigY, dirX + 40, sigY);
          pdf.setFont("helvetica", "bold");
          pdf.setFontSize(10);
          pdf.text("DIRETOR EXECUTIVO", dirX, sigY + 5, { align: "center" });

          if (secSignature) pdf.addImage(secSignature, 'PNG', secX - 25, sigY - 25, 50, 20);
          pdf.line(secX - 40, sigY, secX + 40, sigY);
          pdf.text("SECRETARIA GERAL", secX, sigY + 5, { align: "center" });

          // Footer (QR Code & Hash) - Fixed at very bottom inside inner frame
          const footerY = height - 20; 
          // QR Code Image (Left)
          pdf.addImage(qrCodeDataUrl, 'PNG', 20, footerY - 10, 18, 18);

          // Validation Text
          pdf.setFontSize(7);
          pdf.setTextColor(100);
          pdf.text("DOCUMENTO COM VALIDADE JURÍDICA NACIONAL", 42, footerY - 5);
          pdf.text(`Código de Autenticidade: ${code}`, 42, footerY);
          pdf.text("Verifique a veracidade deste documento lendo o QR Code.", 42, footerY + 5);


          // --- PÁGINA 2: VERSO (HISTÓRICO) ---
          pdf.addPage('a4', 'landscape');
          drawFrame(pdf);

          pdf.setFont("times", "bold");
          pdf.setFontSize(18);
          pdf.setTextColor(0);
          pdf.text("HISTÓRICO E DETALHAMENTO ACADÊMICO", centerX, 30, { align: "center" });

          pdf.setFontSize(12);
          pdf.setFont("helvetica", "normal");
          pdf.text(`Aluno: ${opStudent.displayName} | Matrícula: ${opStudent.academicId}`, 20, 45);
          pdf.text(`Curso: ${courseData.nome || 'Teologia'}`, 20, 52);

          // Table
          const tableBody = modulesData.length > 0 ? modulesData.map((m: any) => [
              m.title || "Módulo",
              "20h",
              "100%",
              "10.0",
              "APROVADO"
          ]) : [["Módulo Único", "100h", "100%", "10.0", "APROVADO"]];

          autoTable(pdf, {
              startY: 60,
              head: [['Disciplina / Módulo', 'Carga Horária', 'Frequência', 'Nota Final', 'Situação']],
              body: tableBody,
              theme: 'grid',
              headStyles: { fillColor: [30, 41, 59], halign: 'center' },
              bodyStyles: { halign: 'center' },
              styles: { fontSize: 10, font: "helvetica" },
              margin: { left: 20, right: 20 }
          });

          const finalY = (pdf as any).lastAutoTable.finalY + 20;
          pdf.setFontSize(10);
          pdf.text("Critério de Aprovação: Média igual ou superior a 7.0 e frequência mínima de 75%.", 20, finalY);

          // Output
          const pdfBase64 = pdf.output('datauristring');
          const pdfBlob = pdf.output('blob');

          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: `${docTitle} - ${opStudent.displayName}.pdf`,
              type: 'file', mimeType: 'application/pdf', url: pdfBase64,
              parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid,
              studentId: opStudent.uid, docType: docType,
              docData: {
                  code, title: docTitle, date: new Date().toISOString(),
                  student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId },
                  courseData: courseData, modulesData: modulesData
              }
          });

          const blobUrl = URL.createObjectURL(pdfBlob);
          window.open(blobUrl, '_blank');

      } catch (e: any) {
          console.error("Erro PDF:", e);
          alert("Erro: " + e.message);
      } finally {
          setIsGeneratingPdf(false);
      }
  };

  // --- RENDER HELPERS ---
  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  };
  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      if (ev.target?.result) {
        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name,
          type: 'file',
          mimeType: file.type,
          url: ev.target.result, 
          parentId: currentFolderId,
          size: file.size,
          createdAt: serverTimestamp(),
          createdBy: user.uid
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleMoveFile = async () => {
      if (!fileToMove) return;
      await updateDoc(doc(db, 'secretaria_arquivos', fileToMove.id), {
          parentId: moveTargetFolderId,
          updatedAt: serverTimestamp()
      });
      setMoveModalOpen(false);
      setFileToMove(null);
      alert("Arquivo movido com sucesso.");
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id);
    setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              ...editingStudent,
              updatedAt: serverTimestamp()
          });
          alert('Dados do aluno atualizados.');
          setAuditModalOpen(false);
          setEditingStudent(null);
      } catch (e: any) {
          alert('Erro ao salvar: ' + e.message);
      }
  };

  const validateStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              status: 'ativo',
              updatedAt: serverTimestamp()
          });
          alert('Matrícula validada com sucesso.');
          setAuditModalOpen(false);
          setEditingStudent(null);
      } catch (e: any) {
          alert('Erro ao validar: ' + e.message);
      }
  };

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
