           ))}
        </div>
      </header>

      <main className="flex-1 overflow-hidden flex flex-col">

         {/* --- ÁREA DE ATENDIMENTO RESTAURADA COM TABELA --- */}
         {activeTab === 'atendimento' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                {/* Header e Filtros */}
                <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row justify-between gap-4 items-center bg-slate-50/50">
                    <div className="relative w-full md:w-96">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                        <input value={ticketSearchTerm} onChange={e => setTicketSearchTerm(e.target.value)} placeholder="Buscar protocolo ou aluno..." className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" />
                    </div>
                    <div className="flex gap-2">
                        {selectedTickets.length > 0 && (
                            <button onClick={handleBulkDelete} className="px-4 py-2 bg-rose-600 text-white rounded-lg text-[10px] font-black uppercase flex items-center gap-2 hover:bg-rose-700 transition-all animate-in slide-in-from-right"><Trash2 size={14}/> Excluir ({selectedTickets.length})</button>
                        )}
                        <div className="flex gap-2 p-1 bg-slate-100 rounded-xl">
                            {['todos', 'pendente', 'ativo', 'finalizado'].map((f:any) => (
                                <button key={f} onClick={() => setTicketFilter(f)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${ticketFilter === f ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>{f}</button>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Tabela de Tickets */}
                <div className="flex-1 overflow-y-auto">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest sticky top-0 z-10 shadow-sm">
                            <tr>
                                <th className="px-6 py-4 border-b border-slate-100 w-10 text-center"><button onClick={toggleSelectAll} className="p-1 hover:bg-slate-200 rounded"><CheckSquare size={14}/></button></th>
                                <th className="px-6 py-4 border-b border-slate-100">Protocolo</th>
                                <th className="px-6 py-4 border-b border-slate-100">Aluno / Matrícula</th>
                                <th className="px-6 py-4 border-b border-slate-100">Problema (Descrição)</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-center">Espera</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-center">Status</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-center">Data</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-right">Gestão</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {tickets.filter(t => 
                                (ticketFilter === 'todos' || t.status.toLowerCase() === ticketFilter) &&
                                (t.user?.toLowerCase().includes(ticketSearchTerm.toLowerCase()) || t.protocolo?.toLowerCase().includes(ticketSearchTerm.toLowerCase()))
                            ).map(t => (
                                <tr key={t.id} className="hover:bg-indigo-50/10 transition-colors group">
                                    <td className="px-6 py-4 text-center"><input type="checkbox" checked={selectedTickets.includes(t.id)} onChange={() => toggleSelectTicket(t.id)} className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer"/></td>
                                    <td className="px-6 py-4 font-mono text-xs font-bold text-indigo-600">#{t.protocolo}</td>
                                    <td className="px-6 py-4">
                                        <p className="font-black text-xs text-slate-800 uppercase italic">{t.user}</p>
                                        <p className="text-[9px] text-slate-400 font-mono">ID: {t.studentId || 'N/A'}</p>
                                    </td>
                                    <td className="px-6 py-4">
                                        <p className="text-[10px] text-slate-500 italic font-medium max-w-[200px] line-clamp-2" title={t.lastMessage}>{t.lastMessage || 'Sem descrição'}</p>
                                    </td>
                                    <td className="px-6 py-4 text-center text-[10px] font-bold text-amber-600 bg-amber-50 rounded-lg tabular-nums">
                                        {t.status === 'Pendente' ? calculateWaitTime(t.createdAt) : '-'}
                                    </td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${
                                            t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-100' :
                                            t.status === 'Resolvido' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                                            t.status === 'Finalizado' ? 'bg-slate-100 text-slate-500 border-slate-200' :
                                            'bg-indigo-50 text-indigo-600 border-indigo-100'
                                        }`}>
                                            {t.status}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-center text-[10px] font-bold text-slate-400">
                                        {t.createdAt?.seconds ? new Date(t.createdAt.seconds * 1000).toLocaleDateString('pt-BR') : '-'}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex justify-end gap-2">
                                            <button onClick={() => setViewTicketModal(t)} className="p-2 bg-slate-50 text-slate-400 hover:text-indigo-600 rounded-lg transition-all border border-transparent hover:border-slate-200" title="Visualizar Detalhes"><Eye size={14}/></button>
                                            <button onClick={() => { setActiveTicket(t); setActiveTab('chat'); }} className="p-2 bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white rounded-lg transition-all border border-indigo-100 shadow-sm" title="Abrir Chat"><MessageSquare size={14}/></button>
                                            <button onClick={async () => { if(confirm('Excluir ticket permanentemente?')) await deleteDoc(doc(db, 'tickets', t.id)); }} className="p-2 bg-rose-50 text-rose-500 hover:bg-rose-600 hover:text-white rounded-lg transition-all border border-rose-100 shadow-sm" title="Excluir"><Trash2 size={14}/></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {tickets.length === 0 && (
                                <tr><td colSpan={8} className="p-12 text-center text-slate-300 italic uppercase font-black text-xs">Nenhum atendimento encontrado.</td></tr>
                            )}
                        </tbody>
                    </table>
                </div>
             </div>
         )}

         {/* --- CHAT COM FLUXO DE GESTÃO --- */}
         {activeTab === 'chat' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col relative h-full">
                {activeTicket ? (
                  <>
                    {/* Chat Header */}
                    <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center shadow-sm z-10">
                       <div className="flex items-center gap-4">
                           <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center font-black italic">{activeTicket.user.charAt(0)}</div>
                           <div>
                               <h3 className="font-black text-slate-900 text-sm uppercase italic">Protocolo #{activeTicket.protocolo}</h3>
                               <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">{activeTicket.user} • Status: <span className={activeTicket.status === 'Pendente' ? 'text-amber-500' : 'text-emerald-500'}>{activeTicket.status}</span></p>
                           </div>
                       </div>

                       <div className="flex gap-2">
                           <button onClick={() => { setActiveTicket(null); setActiveTab('atendimento'); }} className="px-4 py-2 bg-white border border-slate-200 rounded-xl text-[9px] font-black uppercase hover:bg-slate-50 text-slate-500">Voltar</button>

                           {/* LOGICA DE BOTÕES DO FLUXO */}
                           {activeTicket.status === 'Pendente' && (
                               <button onClick={() => handleTicketAction('assume')} className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-indigo-700 transition-all shadow-lg flex items-center gap-2"><UserCheck size={14}/> Assumir Atendimento</button>
                           )}
                           {activeTicket.status === 'Em Andamento' && (
                               <button onClick={() => handleTicketAction('finalize')} className="px-4 py-2 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-emerald-700 transition-all shadow-lg flex items-center gap-2"><CheckCircle2 size={14}/> Finalizar Atendimento</button>
                           )}
                           {(activeTicket.status === 'Resolvido' || activeTicket.status === 'Finalizado') && activeTicket.status !== 'Arquivado' && (
                               <button onClick={() => handleTicketAction('archive')} className="px-4 py-2 bg-slate-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-slate-700 transition-all shadow-lg flex items-center gap-2"><Archive size={14}/> Arquivar</button>
                           )}
                       </div>
                    </div>

                    {/* Chat Messages */}
                    <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/50 custom-scrollbar relative">
                       {messages.map((m, i) => (
                         <div key={i} className={`flex flex-col ${m.sender === 'Aluno' ? 'items-start' : 'items-end'}`}>
                            <div className={`max-w-[70%] p-4 rounded-2xl text-xs font-medium leading-relaxed shadow-sm relative group ${m.sender === 'Aluno' ? 'bg-white border border-slate-200 text-slate-700 rounded-tl-none' : m.isBot ? 'bg-slate-200 text-slate-700 rounded-tr-none' : 'bg-indigo-600 text-white rounded-tr-none'}`}>
                               {m.text}
                               {m.attachmentUrl && <div onClick={() => viewAttachment(m.attachmentUrl)} className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20 text-white"><FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Ver Documento</span> <ExternalLink size={10}/></div>}
                               <span className="text-[8px] font-bold opacity-50 absolute -bottom-5 block w-full">{m.sender} • {m.createdAt?.seconds ? new Date(m.createdAt.seconds*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) : '...'}</span>
                            </div>
                         </div>
                       ))}
                       <div ref={chatEndRef} className="h-4" />
                    </div>

                    {/* Chat Input */}
                    {(activeTicket.status === 'Em Andamento' || activeTicket.status === 'Pendente') ? (
                      <div className="p-4 border-t border-slate-100 bg-white z-20">
                         <div className="flex gap-3 items-center bg-slate-50 p-2 rounded-2xl border border-slate-200 focus-within:border-indigo-400 focus-within:ring-2 focus-within:ring-indigo-100 transition-all">
                            {/* Anexo de Arquivo Local */}
                            <button onClick={() => chatFileInputRef.current?.click()} className="p-3 bg-white text-slate-400 rounded-xl hover:text-indigo-600 shadow-sm transition-all" title="Anexar Arquivo Local"><Paperclip size={18}/></button>
                            <input type="file" ref={chatFileInputRef} className="hidden" onChange={e => { if(e.target.files?.[0]) sendAttachment(e.target.files[0]); }}/>

                            {/* Anexo da Secretaria (Arquivos) */}
                            <button onClick={() => setInternalFilePickerOpen(true)} className="p-3 bg-white text-slate-400 rounded-xl hover:text-indigo-600 shadow-sm transition-all" title="Enviar Documento da Secretaria"><Folder size={18}/></button>

                            <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendMessage()} className="flex-1 bg-transparent border-none text-xs font-bold outline-none text-slate-700 placeholder:text-slate-400" placeholder="Digite sua resposta..." />
                            <button onClick={sendMessage} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all"><Send size={18}/></button>
                         </div>
                      </div>
                    ) : <div className="p-4 bg-slate-100 text-center text-[10px] font-black uppercase text-slate-400 border-t border-slate-200">Este atendimento foi encerrado.</div>}
                  </>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-6">
                      <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center"><LifeBuoy size={48} className="opacity-20"/></div>
                      <div className="text-center">
                          <h3 className="text-lg font-black uppercase italic text-slate-400">Central de Atendimento</h3>
                          <p className="text-xs font-bold uppercase tracking-widest opacity-50 mt-1">Selecione um ticket na aba "Atendimento"</p>
                      </div>
                  </div>
                )}
             </div>
         )}

         {(activeTab === 'arquivos') && !activeTicket && (
           <div className={`bg-white border border-slate-200 rounded-xl overflow-hidden h-full flex flex-col shadow-lg`}>
              <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                 <div className="flex items-center gap-2 overflow-x-auto">
                    <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-200 rounded-lg"><Home size={16}/></button>
