                           <div className="flex items-center gap-4">
                               <div className="w-24 h-24 bg-white rounded-xl border border-slate-200 flex items-center justify-center overflow-hidden">
                                   {editingStudent.photoURL ? <img src={editingStudent.photoURL} className="w-full h-full object-cover"/> : <span className="text-[8px] font-black uppercase text-slate-300">Sem Foto</span>}
                               </div>
                               <div>
                                   <p className="text-xs font-bold text-slate-800">Foto de Identificação</p>
                                   <p className="text-[9px] text-slate-400">Status: {editingStudent.photoURL ? 'Enviado' : 'Pendente'}</p>
                               </div>
                           </div>
                       </div>

                       <div className="flex gap-4 pt-4 border-t border-slate-100">
                          <button onClick={saveEditedStudent} className="px-6 py-3 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase hover:bg-slate-200 flex items-center gap-2"><Edit3 size={14}/> Salvar Edições</button>
                          <button onClick={validateStudent} className="px-8 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-emerald-700 transition-all flex items-center gap-2 shadow-xl shadow-emerald-200"><CheckCircle2 size={16}/> Validar Matrícula</button>
                       </div>
                  </div>
              </div>
          </div>
      )}

      {isSignModalOpen && <SignaturePad title="Assinatura Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert("Assinatura Salva!"); }} />}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, addDoc, writeBatch, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, MessageSquare, Search, X, FileText, UserCheck, 
  ArrowRightLeft, Fingerprint, Send, Archive, Eye, 
  Printer, Folder, File, Download, Plus, ChevronRight,
  UploadCloud, FolderPlus, CheckCircle2, ShieldCheck,
  AlertTriangle, Home, Paperclip, Save, Timer,
  Trash2, Move, ExternalLink, LifeBuoy, BookOpen, Clock,
  FileInput, CheckSquare, Square, RefreshCw, Award, Edit3
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';
import { jsPDF } from "https://esm.sh/jspdf@2.5.1";
import autoTable from "https://esm.sh/jspdf-autotable@3.8.1";
import QRCode from "https://esm.sh/qrcode@1.5.3";

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'historico' | 'transferencia' | 'assinatura' | 'validacao';

// --- HELPERS ---
const generateVerificationCode = () => {
  return `${new Date().getFullYear()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}`;
};

const viewAttachment = (url: string) => {
    if (!url) return;
    if (url.startsWith('http')) { window.open(url, '_blank'); return; }
    if (url.startsWith('data:')) {
        const win = window.open();
        win?.document.write(`<iframe src="${url}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`);
    }
};

const viewFile = (file: any) => {
  if (!file || !file.url) return;
  if (file.mimeType === 'application/pdf' || file.name?.endsWith('.pdf')) {
      const newWindow = window.open();
      if (newWindow) {
          if (file.url.startsWith('data:')) {
             newWindow.document.write(
                 `<iframe width='100%' height='100%' src='${file.url}'></iframe>`
             );
             newWindow.document.title = file.name;
          } else {
             newWindow.location.href = file.url;
          }
      } else {
          alert("Pop-up bloqueado. Permita pop-ups para visualizar o PDF.");
      }
      return;
  }
  window.open(file.url, '_blank');
};

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');

  // Data States
  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [fileSystem, setFileSystem] = useState<any[]>([]);

  // UI States - Atendimento
  const [ticketSearchTerm, setTicketSearchTerm] = useState('');
  const [ticketFilter, setTicketFilter] = useState<'todos' | 'pendente' | 'ativo' | 'finalizado'>('todos');
  const [activeTicket, setActiveTicket] = useState<any | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [selectedTickets, setSelectedTickets] = useState<string[]>([]);
  const [viewTicketModal, setViewTicketModal] = useState<any | null>(null);
  const [internalFilePickerOpen, setInternalFilePickerOpen] = useState(false);

  // UI States - General
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);
  const [directorSignature, setDirectorSignature] = useState<string | null>(null);

  // File Explorer States
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<any>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState('root');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatFileInputRef = useRef<HTMLInputElement>(null);
  const [attachMode, setAttachMode] = useState(false); // For internal file picker in chat

  // Operational State
  const [opStudent, setOpStudent] = useState<any>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        // Sort by priority (Pending first) then Date
        t.sort((a:any, b:any) => {
            if (a.status === 'Pendente' && b.status !== 'Pendente') return -1;
            if (b.status === 'Pendente' && a.status !== 'Pendente') return 1;
            return (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0);
        });
        setTickets(t);
        if (activeTicket) {
            const updated = t.find((x: any) => x.id === activeTicket.id);
            if (updated) setActiveTicket(updated);
        }
    });

    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
    getDocs(qDir).then(s => { if (!s.empty) setDirectorSignature(s.docs[0].data().signatureUrl); });

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid, activeTicket?.id]);

  useEffect(() => {
    if (!activeTicket) { setMessages([]); return; }
    const q = query(collection(db, 'tickets', activeTicket.id, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [activeTicket]);

  // --- FUNCTIONS FOR TICKETS & CHAT ---

  const calculateWaitTime = (createdAt: any) => {
    if (!createdAt) return '-';
    const start = createdAt.seconds ? new Date(createdAt.seconds * 1000) : new Date(createdAt);
    const now = new Date();
    const diffMs = now.getTime() - start.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHrs = Math.floor(diffMins / 60);

    if (diffHrs > 0) return `${diffHrs}h ${diffMins % 60}m`;
    return `${diffMins}m`;
  };

  const toggleSelectAll = () => {
    if (selectedTickets.length === tickets.length) setSelectedTickets([]);
    else setSelectedTickets(tickets.map(t => t.id));
  };

  const toggleSelectTicket = (id: string) => {
    if (selectedTickets.includes(id)) setSelectedTickets(prev => prev.filter(t => t !== id));
    else setSelectedTickets(prev => [...prev, id]);
  };

  const handleBulkDelete = async () => {
    if (!confirm(`Excluir ${selectedTickets.length} tickets?`)) return;
    const batch = writeBatch(db);
    selectedTickets.forEach(id => {
      batch.delete(doc(db, 'tickets', id));
    });
    await batch.commit();
    setSelectedTickets([]);
  };

  const handleTicketAction = async (action: 'assume' | 'finalize' | 'archive') => {
    if (!activeTicket) return;
    let updates: any = {};
    if (action === 'assume') {
        updates = { status: 'Em Andamento', specialistJoined: true, specialistId: user.uid, specialistName: user.displayName };
        await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
            text: `O especialista ${user.displayName} assumiu o atendimento.`,
            sender: 'Sistema',
            isBot: true,
            createdAt: serverTimestamp()
        });
    } else if (action === 'finalize') {
        updates = { status: 'Resolvido' }; // Triggers survey for user
        await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
            text: `Atendimento finalizado pelo especialista. Por favor, avalie nosso suporte.`,
            sender: 'Sistema',
            isBot: true,
            createdAt: serverTimestamp()
        });
    } else if (action === 'archive') {
        updates = { status: 'Arquivado', archivedAt: serverTimestamp() };
    }
    await updateDoc(doc(db, 'tickets', activeTicket.id), { ...updates, updatedAt: serverTimestamp() });
    setActiveTicket(prev => prev ? ({ ...prev, ...updates }) : null);
  };

  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
        text: chatMessage,
        sender: user.displayName || 'Secretaria',
        createdAt: serverTimestamp()
    });
    await updateDoc(doc(db, 'tickets', activeTicket.id), {
        lastMessage: chatMessage,
        updatedAt: serverTimestamp()
    });
    setChatMessage('');
  };

  const sendAttachment = async (file?: File, fileUrl?: string) => {
    if (!activeTicket) return;
    let url = fileUrl;
    let name = file?.name || 'Arquivo';

    if (file) {
       const reader = new FileReader();
       reader.readAsDataURL(file);
       await new Promise<void>(resolve => {
           reader.onload = () => { url = reader.result as string; resolve(); }
       });
    }

    if (url) {
        await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
            text: `Documento anexado: ${name}`,
            attachmentUrl: url,
            sender: user.displayName || 'Secretaria',
            createdAt: serverTimestamp()
        });
        await updateDoc(doc(db, 'tickets', activeTicket.id), {
            lastMessage: `[Anexo] ${name}`,
            updatedAt: serverTimestamp()
        });
        setInternalFilePickerOpen(false);
    }
  };

  // --- PDF GENERATOR ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno."); return; }
      setIsGeneratingPdf(true);

      try {
          const code = generateVerificationCode();
          const isCertificate = docType === 'conclusao';
          const orientation = isCertificate ? 'landscape' : 'portrait';

          const docTitle = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 
                           docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' : 
                           docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';

          let courseData: any = {};
          let modulesData: any[] = [];

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();
              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data()).sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
          }

          const validationUrl = `${window.location.origin}?code=${code}`;
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 0, width: 100 });

          const pdf = new jsPDF({ orientation, unit: 'mm', format: 'a4' });
          const width = pdf.internal.pageSize.getWidth();
          const height = pdf.internal.pageSize.getHeight();
          const centerX = width / 2;

          const drawBibleLogo = (doc: any, x: number, y: number, scale: number = 1) => {
              doc.setLineWidth(0.5 * scale);
              doc.setDrawColor(30, 41, 59); 
              doc.setFillColor(255, 255, 255);
              doc.lines([[ -12 * scale, -4 * scale, -10 * scale, 6 * scale, 0, 8 * scale ]], x, y, [1, 1, 1]);
              doc.lines([[ 12 * scale, -4 * scale, 10 * scale, 6 * scale, 0, 8 * scale ]], x, y, [1, 1, 1]);
              doc.line(x, y, x, y + (8 * scale));
              doc.setLineWidth(1 * scale);
              doc.line(x - (12 * scale), y + (4 * scale), x, y + (10 * scale));
              doc.line(x, y + (10 * scale), x + (12 * scale), y + (4 * scale));
          };

          const drawSignatures = (doc: any, bottomY: number) => {
              const sigY = bottomY - 35; 
              const dirX = isCertificate ? centerX - 60 : centerX - 40;
              const secX = isCertificate ? centerX + 60 : centerX + 40;

              if (directorSignature) doc.addImage(directorSignature, 'PNG', dirX - 25, sigY - 20, 50, 20);
              doc.setDrawColor(0);
              doc.setLineWidth(0.5);
              doc.line(dirX - 35, sigY, dirX + 35, sigY);
              doc.setFont("helvetica", "bold");
              doc.setFontSize(8);
              doc.text("DIRETOR EXECUTIVO", dirX, sigY + 5, { align: "center" });

              if (secSignature) doc.addImage(secSignature, 'PNG', secX - 25, sigY - 20, 50, 20);
              doc.line(secX - 35, sigY, secX + 35, sigY);
              doc.text("SECRETARIA GERAL", secX, sigY + 5, { align: "center" });
          };

          const drawWatermark = (doc: any) => {
              doc.setTextColor(245, 245, 245);
              doc.setFontSize(isCertificate ? 100 : 80);
              doc.setFont("times", "bold");
              doc.text("EB-EAD", width / 2, height / 2, { align: "center", angle: 45 });
              doc.setTextColor(0, 0, 0); 
          };

          if (isCertificate) {
              const drawGoldFrame = (doc: any) => {
                  const gold = [197, 160, 89];
                  doc.setDrawColor(gold[0], gold[1], gold[2]);
                  doc.setLineWidth(3);
                  doc.rect(10, 10, width - 20, height - 20);
                  doc.setLineWidth(0.5);
                  doc.rect(13, 13, width - 26, height - 26);
              };

              drawGoldFrame(pdf);
              drawWatermark(pdf);

              drawBibleLogo(pdf, centerX, 25, 1.5);
              pdf.setFont("times", "bold");
              pdf.setTextColor(30, 41, 59);
              pdf.setFontSize(28);
              pdf.text("ESCOLA BÍBLICA EAD", centerX, 50, { align: "center" });

              pdf.setFont("helvetica", "normal");
              pdf.setFontSize(9);
              pdf.setTextColor(100);
              pdf.text("Credenciamento MEC/CNE nº 999.999 | Portaria Nº 1004 de 17/08/2017", centerX, 56, { align: "center" });

              pdf.setFont("times", "bold");
              pdf.setFontSize(36);
              pdf.setTextColor(0);
              pdf.text("CERTIFICADO DE CONCLUSÃO", centerX, 85, { align: "center" });

              pdf.setFont("times", "normal");
              pdf.setFontSize(16);
              const bodyText = `Certificamos que ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF ${opStudent.cpf || '---'}, concluiu com êxito o curso de ${courseData.nome?.toUpperCase() || 'TEOLOGIA'}, cumprindo a carga horária exigida e obtendo o aproveitamento necessário para a outorga deste título.`;
              const splitBody = pdf.splitTextToSize(bodyText, width - 70);
              pdf.text(splitBody, centerX, 110, { align: "center" });

              const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
              pdf.setFontSize(12);
              pdf.text(dateStr, width - 35, 140, { align: "right" });

              drawSignatures(pdf, height - 20); 

              pdf.addImage(qrCodeDataUrl, 'PNG', 20, height - 35, 20, 20);
              pdf.setFontSize(7);
              pdf.setTextColor(100);
              pdf.text(`Autenticidade: ${code}`, 42, height - 28);
              pdf.text("Documento com validade jurídica nacional.", 42, height - 23);

              pdf.addPage('a4', 'landscape');
              drawGoldFrame(pdf);
              drawWatermark(pdf);

              pdf.setFont("times", "bold");
              pdf.setFontSize(16);
              pdf.setTextColor(0);
              pdf.text("REGISTRO DE DESEMPENHO ACADÊMICO", centerX, 30, { align: "center" });

              const tableBody = modulesData.length > 0 ? modulesData.map((m: any) => [
                  m.title || "Módulo", "20h", "100%", "10.0", "APROVADO"
              ]) : [["Módulo Único", "100h", "100%", "10.0", "APROVADO"]];

              autoTable(pdf, {
                  startY: 45,
                  head: [['Disciplina / Módulo', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                  body: tableBody,
                  theme: 'grid',
                  headStyles: { fillColor: [30, 41, 59], halign: 'center' },
                  bodyStyles: { halign: 'center' },
                  margin: { left: 30, right: 30 },
                  styles: { fontSize: 10, font: "helvetica" }
              });
          } 
          else {
              const drawStandardHeader = (doc: any, title: string) => {
                  drawBibleLogo(doc, 30, 20, 1.2);
                  doc.setFont("times", "bold");
                  doc.setFontSize(18);
                  doc.setTextColor(30, 41, 59);
                  doc.text("ESCOLA BÍBLICA EAD", 50, 20);

                  doc.setFont("helvetica", "normal");
                  doc.setFontSize(8);
                  doc.setTextColor(100);
                  doc.text("Secretaria Geral de Ensino a Distância", 50, 24);

                  doc.setDrawColor(200);
                  doc.line(20, 35, width - 20, 35); 

                  doc.setFont("times", "bold");
                  doc.setFontSize(20);
                  doc.setTextColor(0);
                  doc.text(title, centerX, 55, { align: "center" });
              };

              drawWatermark(pdf);
              drawStandardHeader(pdf, docTitle);

              let currentY = 75;
              const margin = 25;
              const maxW = width - (margin * 2);

              pdf.setFont("times", "normal");
              pdf.setFontSize(12);
              pdf.setTextColor(0);

              let introText = "";
              if (docType === 'matricula') {
                  introText = `DECLARAMOS, para os devidos fins de direito, que o(a) aluno(a) ${opStudent.displayName?.toUpperCase()}, inscrito(a) no CPF sob o nº ${opStudent.cpf || '---'} e portador(a) da matrícula institucional nº ${opStudent.academicId || '---'}, encontra-se devidamente MATRICULADO(A) no curso de ${courseData.nome || 'Teologia'}, modalidade EAD, neste período letivo.`;
                  introText += `\n\nSituação Acadêmica Atual: ${opStudent.status?.toUpperCase()}.`;
              } else if (docType === 'transferencia') {
                  introText = `Atestamos a TRANSFERÊNCIA do(a) aluno(a) ${opStudent.displayName?.toUpperCase()} (Matrícula: ${opStudent.academicId}) para outra instituição de ensino, conforme solicitado. O(a) discente cumpriu as obrigações acadêmicas até a presente data no curso de ${courseData.nome || 'Teologia'}.`;
                  introText += `\n\nSegue em anexo (página seguinte) o histórico escolar detalhado para fins de aproveitamento de estudos.`;
              } else if (docType === 'historico') {
                  introText = `Histórico Escolar Oficial do(a) aluno(a) ${opStudent.displayName?.toUpperCase()}, referente ao curso de ${courseData.nome || 'Teologia'}.`;
              }

              const splitIntro = pdf.splitTextToSize(introText, maxW);
              pdf.text(splitIntro, margin, currentY);
              currentY += (splitIntro.length * 7) + 15;

              if (docType === 'historico') {
                  const tableBody = modulesData.length > 0 ? modulesData.map((m: any) => [
                      m.title || "Módulo", "20h", "100%", "10.0", "APROVADO"
                  ]) : [["Sem registros", "-", "-", "-", "-"]];

                  autoTable(pdf, {
                      startY: currentY,
                      head: [['Componente Curricular', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                      body: tableBody,
                      theme: 'striped',
                      headStyles: { fillColor: [240, 240, 240], textColor: 0, fontStyle: 'bold' },
                      styles: { fontSize: 10, font: "helvetica" },
                      margin: { left: margin, right: margin }
                  });
              }

              if (docType === 'transferencia') {
                  pdf.addPage();
                  drawWatermark(pdf);
                  drawStandardHeader(pdf, "ANEXO: HISTÓRICO ESCOLAR");

                  const tableBody = modulesData.length > 0 ? modulesData.map((m: any) => [
                      m.title || "Módulo", "20h", "100%", "10.0", "APROVADO"
                  ]) : [["Sem registros acadêmicos concluídos até a data da transferência", "-", "-", "-", "-"]];

                  autoTable(pdf, {
                      startY: 70,
                      head: [['Componente Curricular', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                      body: tableBody,
                      theme: 'grid',
                      headStyles: { fillColor: [30, 41, 59] },
                      margin: { left: margin, right: margin }
                  });
              }

              const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
              pdf.setFontSize(11);
              pdf.text(dateStr, width - margin, height - 60, { align: "right" });

              drawSignatures(pdf, height - 30);

              pdf.setDrawColor(200);
              pdf.line(margin, height - 25, width - margin, height - 25);
              pdf.addImage(qrCodeDataUrl, 'PNG', margin, height - 22, 16, 16);
              pdf.setFontSize(7);
              pdf.setTextColor(120);
              pdf.text(`Validação Digital: ${code}`, margin + 20, height - 16);
              pdf.text("Este documento possui assinatura eletrônica.", margin + 20, height - 12);
          }

          const pdfBase64 = pdf.output('datauristring');
          const pdfBlob = pdf.output('blob');

          const nameParts = (opStudent.displayName || 'Aluno').split(' ').filter(Boolean);
          const firstName = nameParts[0] || 'Aluno';
          const lastName = nameParts.length > 1 ? nameParts[nameParts.length - 1] : '';
          const fileName = `${firstName} ${lastName} - ${opStudent.academicId || 'SM'}.pdf`;

          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: fileName,
              type: 'file', mimeType: 'application/pdf', url: pdfBase64,
              parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid,
              studentId: opStudent.uid, docType: docType,
              docData: {
                  code, title: docTitle, date: new Date().toISOString(),
                  student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId },
                  courseData: courseData, modulesData: modulesData
              }
          });

          const blobUrl = URL.createObjectURL(pdfBlob);
          window.open(blobUrl, '_blank');

      } catch (e: any) {
          console.error("Erro PDF:", e);
          alert("Erro: " + e.message);
      } finally {
          setIsGeneratingPdf(false);
      }
  };

  // --- RENDER HELPERS ---
  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  };
  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);

  // --- FILE EXPLORER FUNCTIONS ---
  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      if (ev.target?.result) {
        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name,
          type: 'file',
          mimeType: file.type,
          url: ev.target.result, 
          parentId: currentFolderId,
          size: file.size,
          createdAt: serverTimestamp(),
          createdBy: user.uid
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleMoveFile = async () => {
      if (!fileToMove) return;
      await updateDoc(doc(db, 'secretaria_arquivos', fileToMove.id), {
          parentId: moveTargetFolderId,
          updatedAt: serverTimestamp()
      });
      setMoveModalOpen(false);
      setFileToMove(null);
      alert("Arquivo movido com sucesso.");
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id);
    setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  // --- OPERATIONAL FUNCTIONS ---
  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              ...editingStudent,
              updatedAt: serverTimestamp()
          });
          alert('Dados do aluno atualizados.');
          setAuditModalOpen(false);
          setEditingStudent(null);
      } catch (e: any) {
          alert('Erro ao salvar: ' + e.message);
      }
  };

  const validateStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              status: 'ativo',
              updatedAt: serverTimestamp()
          });
          alert('Matrícula validada com sucesso.');
          setAuditModalOpen(false);
          setEditingStudent(null);
      } catch (e: any) {
          alert('Erro ao validar: ' + e.message);
      }
  };

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); if(t !== 'chat') setActiveTicket(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="flex-1 overflow-hidden flex flex-col">
         {/* ATENDIMENTO TAB */}
         {activeTab === 'atendimento' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row justify-between gap-4 items-center bg-slate-50/50">
                    <div className="relative w-full md:w-96">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
                        <input value={ticketSearchTerm} onChange={e => setTicketSearchTerm(e.target.value)} placeholder="Buscar protocolo ou aluno..." className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" />
                    </div>
                    <div className="flex gap-2">
                        {selectedTickets.length > 0 && (
                            <button onClick={handleBulkDelete} className="px-4 py-2 bg-rose-600 text-white rounded-lg text-[10px] font-black uppercase flex items-center gap-2 hover:bg-rose-700 transition-all animate-in slide-in-from-right"><Trash2 size={14}/> Excluir ({selectedTickets.length})</button>
                        )}
                        <div className="flex gap-2 p-1 bg-slate-100 rounded-xl">
                            {['todos', 'pendente', 'ativo', 'finalizado'].map((f:any) => (
                                <button key={f} onClick={() => setTicketFilter(f)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${ticketFilter === f ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>{f}</button>
                            ))}
                        </div>
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest sticky top-0 z-10 shadow-sm">
                            <tr>
                                <th className="px-6 py-4 border-b border-slate-100 w-10 text-center"><button onClick={toggleSelectAll} className="p-1 hover:bg-slate-200 rounded"><CheckSquare size={14}/></button></th>
                                <th className="px-6 py-4 border-b border-slate-100">Protocolo</th>
                                <th className="px-6 py-4 border-b border-slate-100">Aluno / Matrícula</th>
                                <th className="px-6 py-4 border-b border-slate-100">Problema</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-center">Espera</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-center">Status</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-right">Gestão</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {tickets.filter(t => 
                                (ticketFilter === 'todos' || t.status.toLowerCase() === ticketFilter) &&
                                (t.user?.toLowerCase().includes(ticketSearchTerm.toLowerCase()) || t.protocolo?.toLowerCase().includes(ticketSearchTerm.toLowerCase()))
                            ).map(t => (
                                <tr key={t.id} className="hover:bg-indigo-50/10 transition-colors group">
                                    <td className="px-6 py-4 text-center"><input type="checkbox" checked={selectedTickets.includes(t.id)} onChange={() => toggleSelectTicket(t.id)} className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer"/></td>
                                    <td className="px-6 py-4 font-mono text-xs font-bold text-indigo-600">#{t.protocolo}</td>
                                    <td className="px-6 py-4">
                                        <p className="font-black text-xs text-slate-800 uppercase italic">{t.user}</p>
                                        <p className="text-[9px] text-slate-400 font-mono">ID: {t.studentId || 'N/A'}</p>
                                    </td>
                                    <td className="px-6 py-4"><p className="text-[10px] text-slate-500 italic font-medium max-w-[200px] line-clamp-2">{t.lastMessage || 'Sem descrição'}</p></td>
                                    <td className="px-6 py-4 text-center text-[10px] font-bold text-amber-600 bg-amber-50 rounded-lg tabular-nums">{t.status === 'Pendente' ? calculateWaitTime(t.createdAt) : '-'}</td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${
                                            t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-100' :
                                            t.status === 'Resolvido' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                                            t.status === 'Finalizado' ? 'bg-slate-100 text-slate-500 border-slate-200' :
                                            'bg-indigo-50 text-indigo-600 border-indigo-100'
                                        }`}>{t.status}</span>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex justify-end gap-2">
                                            <button onClick={() => setViewTicketModal(t)} className="p-2 bg-slate-50 text-slate-400 hover:text-indigo-600 rounded-lg transition-all" title="Visualizar Detalhes"><Eye size={14}/></button>
                                            <button onClick={() => { setActiveTicket(t); setActiveTab('chat'); }} className="p-2 bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white rounded-lg transition-all shadow-sm" title="Abrir Chat"><MessageSquare size={14}/></button>
                                            <button onClick={async () => { if(confirm('Excluir ticket?')) await deleteDoc(doc(db, 'tickets', t.id)); }} className="p-2 bg-rose-50 text-rose-500 hover:bg-rose-600 hover:text-white rounded-lg transition-all shadow-sm" title="Excluir"><Trash2 size={14}/></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
             </div>
         )}

         {/* CHAT TAB */}
         {activeTab === 'chat' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col relative h-full">
                {activeTicket ? (
                  <>
                    <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center shadow-sm z-10">
                       <div className="flex items-center gap-4">
                           <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center font-black italic">{activeTicket.user.charAt(0)}</div>
                           <div><h3 className="font-black text-slate-900 text-sm uppercase italic">Protocolo #{activeTicket.protocolo}</h3><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">{activeTicket.user} • Status: <span className={activeTicket.status === 'Pendente' ? 'text-amber-500' : 'text-emerald-500'}>{activeTicket.status}</span></p></div>
                       </div>
                       <div className="flex gap-2">
                           <button onClick={() => { setActiveTicket(null); setActiveTab('atendimento'); }} className="px-4 py-2 bg-white border border-slate-200 rounded-xl text-[9px] font-black uppercase hover:bg-slate-50 text-slate-500">Voltar</button>
                           {activeTicket.status === 'Pendente' && <button onClick={() => handleTicketAction('assume')} className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-indigo-700 transition-all shadow-lg flex items-center gap-2"><UserCheck size={14}/> Assumir Atendimento</button>}
                           {activeTicket.status === 'Em Andamento' && <button onClick={() => handleTicketAction('finalize')} className="px-4 py-2 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-emerald-700 transition-all shadow-lg flex items-center gap-2"><CheckCircle2 size={14}/> Finalizar Atendimento</button>}
                           {(activeTicket.status === 'Resolvido' || activeTicket.status === 'Finalizado') && activeTicket.status !== 'Arquivado' && <button onClick={() => handleTicketAction('archive')} className="px-4 py-2 bg-slate-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-slate-700 transition-all shadow-lg flex items-center gap-2"><Archive size={14}/> Arquivar</button>}
                       </div>
                    </div>
                    <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/50 custom-scrollbar relative">
                       {messages.map((m, i) => (
                         <div key={i} className={`flex flex-col ${m.sender === 'Aluno' ? 'items-start' : 'items-end'}`}>
                            <div className={`max-w-[70%] p-4 rounded-2xl text-xs font-medium leading-relaxed shadow-sm relative group ${m.sender === 'Aluno' ? 'bg-white border border-slate-200 text-slate-700 rounded-tl-none' : m.isBot ? 'bg-slate-200 text-slate-700 rounded-tr-none' : 'bg-indigo-600 text-white rounded-tr-none'}`}>
                               {m.text}
                               {m.attachmentUrl && <div onClick={() => viewAttachment(m.attachmentUrl)} className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20 text-white"><FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Ver Documento</span> <ExternalLink size={10}/></div>}
                               <span className="text-[8px] font-bold opacity-50 absolute -bottom-5 block w-full">{m.sender} • {m.createdAt?.seconds ? new Date(m.createdAt.seconds*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) : '...'}</span>
                            </div>
                         </div>
                       ))}
                       <div ref={chatEndRef} className="h-4" />
                    </div>
                    {(activeTicket.status === 'Em Andamento' || activeTicket.status === 'Pendente') ? (
                      <div className="p-4 border-t border-slate-100 bg-white z-20">
                         <div className="flex gap-3 items-center bg-slate-50 p-2 rounded-2xl border border-slate-200 focus-within:border-indigo-400 focus-within:ring-2 focus-within:ring-indigo-100 transition-all">
                            <button onClick={() => chatFileInputRef.current?.click()} className="p-3 bg-white text-slate-400 rounded-xl hover:text-indigo-600 shadow-sm transition-all" title="Anexar Arquivo Local"><Paperclip size={18}/></button>
                            <input type="file" ref={chatFileInputRef} className="hidden" onChange={e => { if(e.target.files?.[0]) sendAttachment(e.target.files[0]); }}/>
                            <button onClick={() => setInternalFilePickerOpen(true)} className="p-3 bg-white text-slate-400 rounded-xl hover:text-indigo-600 shadow-sm transition-all" title="Enviar Documento da Secretaria"><Folder size={18}/></button>
                            <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendMessage()} className="flex-1 bg-transparent border-none text-xs font-bold outline-none text-slate-700 placeholder:text-slate-400" placeholder="Digite sua resposta..." />
                            <button onClick={sendMessage} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all"><Send size={18}/></button>
                         </div>
                      </div>
                    ) : <div className="p-4 bg-slate-100 text-center text-[10px] font-black uppercase text-slate-400 border-t border-slate-200">Este atendimento foi encerrado.</div>}
                  </>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-6">
                      <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center"><LifeBuoy size={48} className="opacity-20"/></div>
                      <div className="text-center"><h3 className="text-lg font-black uppercase italic text-slate-400">Central de Atendimento</h3><p className="text-xs font-bold uppercase tracking-widest opacity-50 mt-1">Selecione um ticket na aba "Atendimento"</p></div>
                  </div>
                )}
             </div>
         )}

         {/* ARQUIVOS TAB */}
         {(activeTab === 'arquivos') && !activeTicket && (
           <div className={`bg-white border border-slate-200 rounded-xl overflow-hidden h-full flex flex-col shadow-lg`}>
              <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                 <div className="flex items-center gap-2 overflow-x-auto">
                    <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-200 rounded-lg"><Home size={16}/></button>
                    {folderPath.map((f, i) => (
                      <React.Fragment key={f.id}>
                        {i > 0 && <ChevronRight size={14} className="text-slate-400"/>}
                        <button onClick={() => handleBreadcrumb(i)} className={`text-xs font-bold px-2 py-1 rounded-lg hover:bg-slate-200 ${i === folderPath.length -1 ? 'text-slate-900' : 'text-slate-500'}`}>{f.name}</button>
                      </React.Fragment>
                    ))}
                 </div>
                 <div className="flex gap-2">
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} />
                    <button onClick={() => fileInputRef.current?.click()} className="px-3 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-indigo-600"><UploadCloud size={14}/> Upload</button>
                    <button onClick={handleCreateFolder} className="px-3 py-2 bg-slate-200 text-slate-700 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-slate-300"><FolderPlus size={14}/> Pasta</button>
                 </div>
              </div>
              <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50/50">
                 {currentItems.length === 0 ? (
                   <div className="h-full flex flex-col items-center justify-center opacity-30 gap-4"><Folder size={48} /><p className="text-xs font-black uppercase">Pasta Vazia</p></div>
                 ) : (
                   <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                      {currentItems.map(item => (
                        <div key={item.id} 
                             onDoubleClick={() => item.type === 'folder' ? handleNavigate(item) : null}
                             className={`bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all group flex flex-col items-center text-center cursor-pointer relative`}
                        >
                           <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-3 text-white shadow-inner ${item.type === 'folder' ? 'bg-amber-400' : 'bg-indigo-500'}`}>
                              {item.type === 'folder' ? <Folder size={32} className="fill-white/50"/> : <FileText size={32} className="fill-white/50"/>}
                           </div>
                           <p className="text-[10px] font-bold text-slate-700 line-clamp-2 leading-tight w-full break-words">{item.name}</p>
                           {item.type === 'file' && (
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 flex gap-1 bg-white/90 rounded-lg p-1 shadow-sm">
                               <button onClick={async (e) => { e.stopPropagation(); if(confirm('Apagar?')) await deleteDoc(doc(db, 'secretaria_arquivos', item.id)); }} className="p-1.5 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100"><Trash2 size={12}/></button>
                               <button onClick={(e) => { e.stopPropagation(); setFileToMove(item); setMoveModalOpen(true); }} className="p-1.5 bg-slate-50 text-slate-600 rounded-lg hover:bg-slate-100"><Move size={12}/></button>
                               <button onClick={(e) => { e.stopPropagation(); viewFile(item); }} className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100"><Eye size={12}/></button>
                             </div>
                           )}
                        </div>
                      ))}
                   </div>
                 )}
              </div>
           </div>
         )}

         {/* OPERATIONAL TAB */}
         {activeTab === 'operacional' && (
