        t.sort((a:any, b:any) => (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0));
        setTickets(t);
        if (activeTicket) {
            const updated = t.find((x: any) => x.id === activeTicket.id);
            if (updated) setActiveTicket(updated);
        }
    });

    // File System Listener
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    // Students Listener
    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    // Fetch Signatures
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
    getDocs(qDir).then(s => {
        if (!s.empty) setDirectorSignature(s.docs[0].data().signatureUrl);
    });

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid, activeTicket?.id]);

  useEffect(() => {
    if (!activeTicket) { setMessages([]); return; }
    const q = query(collection(db, 'tickets', activeTicket.id, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [activeTicket]);

  useEffect(() => {
    let interval: any;
    if (activeTicket && activeTicket.status === 'Pendente' && !activeTicket.specialistJoined) {
        interval = setInterval(async () => {
            const now = Date.now();
            const created = activeTicket.createdAt?.seconds ? activeTicket.createdAt.seconds * 1000 : Date.now();
            const diff = now - created;
            const limit = 5 * 60 * 1000;
            if (diff >= limit) {
                const hasTimeoutMsg = messages.some((m: any) => m.text.includes("todos os atendentes e especialistas estão ocupados"));
                if (!hasTimeoutMsg) {
                    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
                        text: "Infelizmente, todos os atendentes e especialistas estão ocupados no momento. Sua solicitação foi registrada e entraremos em contato através do seu WhatsApp cadastrado em breve.",
                        sender: 'Sistema', isBot: true, createdAt: serverTimestamp()
                    });
                    await updateDoc(doc(db, 'tickets', activeTicket.id), {
                        status: 'Encaminhado', lastMessage: "Encaminhado para WhatsApp (Timeout)", updatedAt: serverTimestamp()
                    });
                }
                setTimerDisplay("Tempo esgotado");
            } else {
                const remaining = Math.ceil((limit - diff) / 1000);
                const mins = Math.floor(remaining / 60);
                const secs = remaining % 60;
                setTimerDisplay(`${mins}:${secs.toString().padStart(2, '0')}`);
            }
        }, 1000);
    } else { setTimerDisplay(''); }
    return () => clearInterval(interval);
  }, [activeTicket, messages]);

  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a,b) => {
      if(a.type === b.type) return a.name.localeCompare(b.name);
      return a.type === 'folder' ? -1 : 1;
    });
  };

  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome da nova pasta:");
    if (!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), {
      name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid
    });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      if (ev.target?.result) {
        await addDoc(collection(db, 'secretaria_arquivos'), {
          name: file.name, type: 'file', mimeType: file.type, url: ev.target.result, 
          parentId: currentFolderId, size: file.size, createdAt: serverTimestamp(), createdBy: user.uid
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleMoveFile = async () => {
      if (!fileToMove) return;
      await updateDoc(doc(db, 'secretaria_arquivos', fileToMove.id), { parentId: moveTargetFolderId, updatedAt: serverTimestamp() });
      setMoveModalOpen(false); setFileToMove(null); alert("Arquivo movido com sucesso.");
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id); setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1); setFolderPath(newPath); setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  const createTicket = async () => {
    const docRef = await addDoc(collection(db, 'tickets'), {
      user: user.displayName, senderId: user.uid, protocolo: Math.random().toString(36).substr(2, 9).toUpperCase(),
      lastMessage: 'Atendimento Iniciado', status: 'Pendente', createdAt: serverTimestamp(), updatedAt: serverTimestamp()
    });
    await addDoc(collection(db, 'tickets', docRef.id, 'messages'), {
      text: `Olá ${user.displayName?.split(' ')[0]}. Sou o assistente virtual. Selecione um tema abaixo para que eu possa te ajudar:`,
      sender: 'Sistema', isBot: true, options: ['Problemas de Acesso', 'Material Didático', 'Aplicativo / Perfil', 'Elogio / Sugestão', 'Reclamação'], createdAt: serverTimestamp()
    });
    const newTicketSnap = await getDoc(docRef);
    if (newTicketSnap.exists()) { setActiveTicket({ id: newTicketSnap.id, ...newTicketSnap.data() }); }
  };

  const handleBotOption = async (option: string) => {
    if(!activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: option, sender: 'Aluno', createdAt: serverTimestamp() });
    let botResponse = ''; let nextOptions: string[] = []; let escalate = false;
    switch(option) {
        case 'Problemas de Acesso': botResponse = 'Para problemas de acesso: 1. Verifique se sua senha está correta. 2. Tente redefinir a senha no perfil. 3. Limpe o cache do navegador. Isso resolveu?'; nextOptions = ['Sim, resolvido', 'Não, preciso de ajuda']; break;
        case 'Material Didático': botResponse = 'Para materiais: O download é liberado após a conclusão da aula anterior. Verifique se há aulas pendentes no módulo. Conseguiu baixar?'; nextOptions = ['Sim, resolvido', 'Não, material com erro']; break;
        case 'Aplicativo / Perfil': botResponse = 'Você pode editar seus dados (Foto, WhatsApp, Senha) na aba "Meu Perfil". O sistema atualiza imediatamente. Conseguiu editar?'; nextOptions = ['Sim, resolvido', 'Não, erro ao salvar']; break;
        case 'Elogio / Sugestão': botResponse = 'Que ótimo! Por favor, digite seu elogio ou sugestão abaixo. Nós leremos com carinho!'; break;
        case 'Reclamação': botResponse = 'Sinto muito por isso. Por favor, descreva o problema detalhadamente abaixo. Um atendente humano irá analisar seu caso com prioridade.'; escalate = true; break;
        case 'Sim, resolvido': botResponse = 'Fico feliz em ajudar! Vou encerrar este atendimento. Por favor, avalie nosso suporte.'; await updateDoc(doc(db, 'tickets', activeTicket.id), { status: 'Resolvido' }); break;
        case 'Não, preciso de ajuda': case 'Não, material com erro': case 'Não, erro ao salvar': botResponse = 'Aguarde enquanto chamo um especialista. Um atendente entrará no chat em instantes.'; escalate = true; break;
        default: botResponse = 'Certo. Por favor, descreva sua solicitação para o atendente.';
    }
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: botResponse, sender: 'Sistema', isBot: true, options: nextOptions.length > 0 ? nextOptions : undefined, createdAt: serverTimestamp() });
    const updatePayload: any = { lastMessage: `Bot: ${option}`, updatedAt: serverTimestamp() };
    if (escalate) { updatePayload.status = 'Pendente'; updatePayload.createdAt = serverTimestamp(); }
    await updateDoc(doc(db, 'tickets', activeTicket.id), updatePayload);
  };

  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: chatMessage, sender: 'Aluno', createdAt: serverTimestamp() });
    await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: chatMessage, updatedAt: serverTimestamp() });
    setChatMessage('');
