  // --- PDF GENERATOR (REAL PDF) ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno primeiro."); return; }
      setIsGeneratingPdf(true);

      try {
          const code = generateVerificationCode();
          const docTitle = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 
                           docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' : 
                           docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';
          const isLandscape = docType === 'conclusao';

          let courseData: any = {};
          let modulesData: any[] = [];

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();
              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial), orderBy('order'));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data());
          }

          const validationUrl = `${window.location.origin}?code=${code}`;
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 1, width: 100 });

          const docPdf = new jsPDF({
              orientation: isLandscape ? 'landscape' : 'portrait',
              unit: 'mm',
              format: 'a4'
          });

          const width = docPdf.internal.pageSize.getWidth();
          const height = docPdf.internal.pageSize.getHeight();
          const centerX = width / 2;
          const centerY = height / 2;

          // --- HELPERS GRAFICOS ---
          const drawBibleWingsLogo = (doc: any, x: number, y: number, scale: number = 1.0) => {
              doc.setDrawColor(30, 41, 59); // Slate 900
              doc.setFillColor(30, 41, 59);
              doc.setLineWidth(0.5 * scale);

              // Spine (Lombada)
              doc.line(x, y - (5*scale), x, y + (10*scale));

              // Left Pages (Wings Effect) - Curvas Bezier
              // Camada 1 (Mais baixa)
              doc.lines([[-(25*scale), -(8*scale), -(15*scale), (2*scale), -(2*scale), (5*scale)]], x, y + (5*scale));
              // Camada 2 (Meio)
              doc.lines([[-(25*scale), -(10*scale), -(15*scale), (0), -(2*scale), (3*scale)]], x, y + (2*scale));
              // Camada 3 (Topo)
              doc.lines([[-(25*scale), -(12*scale), -(15*scale), -(2*scale), -(2*scale), (1*scale)]], x, y - (1*scale));

              // Right Pages (Wings Effect) - Espelhado
              // Camada 1
              doc.lines([[(25*scale), -(8*scale), (15*scale), (2*scale), (2*scale), (5*scale)]], x, y + (5*scale));
              // Camada 2
              doc.lines([[(25*scale), -(10*scale), (15*scale), (0), (2*scale), (3*scale)]], x, y + (2*scale));
              // Camada 3
              doc.lines([[(25*scale), -(12*scale), (15*scale), -(2*scale), (2*scale), (1*scale)]], x, y - (1*scale));

              // Texto "EB" abaixo
              doc.setFontSize(8 * scale);
              doc.setFont("times", "bold");
              doc.text("EB-EAD", x, y + (18 * scale), { align: "center" });
          };

          const drawCornerOrnament = (doc: any, x: number, y: number, angle: number) => {
              doc.saveGraphicsState();
              doc.translate(x, y);
              doc.rotate(angle);
              doc.setDrawColor(197, 160, 89); // Gold
              doc.setLineWidth(1);
              // Desenho estilizado de canto
              doc.lines([[20, 0], [0, 0], [0, 20]], 0, 0); // L Shape
              doc.setLineWidth(0.5);
              doc.lines([[15, 0], [0, 0], [0, 15]], 3, 3); // Inner L
              doc.circle(5, 5, 1, 'F'); // Dot
              doc.restoreGraphicsState();
          };

          const drawWatermark = (doc: any) => {
              doc.setTextColor(240, 240, 240); // Cinza muito claro
              doc.setFontSize(isLandscape ? 120 : 80);
              doc.setFont("times", "bold");
              // Coordenadas exatas do centro para rotação correta
              doc.text("EB-EAD", centerX, centerY, { align: "center", angle: 45, baseline: 'middle' });
              doc.setTextColor(0, 0, 0); // Reset
          };

          // --- RENDERIZAÇÃO ---

          if (isLandscape) {
              // *** CERTIFICADO (PAISAGEM) ***
              // Borda Dupla
              docPdf.setDrawColor(197, 160, 89); // Gold
              docPdf.setLineWidth(2);
              docPdf.rect(10, 10, width - 20, height - 20);
              docPdf.setLineWidth(0.5);
              docPdf.rect(14, 14, width - 28, height - 28);

              // Ornamentos
              drawCornerOrnament(docPdf, 14, 14, 0);       // Top Left
              drawCornerOrnament(docPdf, width-14, 14, 90);  // Top Right
              drawCornerOrnament(docPdf, width-14, height-14, 180); // Bottom Right
              drawCornerOrnament(docPdf, 14, height-14, 270); // Bottom Left

              drawWatermark(docPdf);

              // Logo & Cabeçalho
              drawBibleWingsLogo(docPdf, centerX, 35, 1.5);

              docPdf.setFont("times", "bold");
              docPdf.setFontSize(32);
              docPdf.setTextColor(30, 41, 59);
              docPdf.text("CERTIFICADO DE CONCLUSÃO", centerX, 70, { align: "center" });

              docPdf.setFontSize(10);
              docPdf.setFont("helvetica", "normal");
              docPdf.setTextColor(100);
              docPdf.text("Credenciamento MEC/CNE nº 999.999 | Portaria Nº 1004 de 17/08/2017", centerX, 80, { align: "center" });

              // Texto Principal
              docPdf.setFont("times", "normal");
              docPdf.setFontSize(18);
              docPdf.setTextColor(0);
              const certText = `Certificamos que ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF ${opStudent.cpf || '---'}, concluiu com êxito o curso de ${courseData.nome?.toUpperCase() || 'TEOLOGIA'}, cumprindo a carga horária exigida e obtendo o aproveitamento necessário para a outorga deste título.`;
              const splitCert = docPdf.splitTextToSize(certText, width - 80);
              docPdf.text(splitCert, centerX, 105, { align: "center" });

              // Data e Local
              const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
              docPdf.setFontSize(12);
              docPdf.text(dateStr, width - 60, 140, { align: "center" });

              // Assinaturas
              const sigY = height - 45;
              if (directorSignature) docPdf.addImage(directorSignature, 'PNG', centerX - 70, sigY - 20, 50, 20);
              if (secSignature) docPdf.addImage(secSignature, 'PNG', centerX + 20, sigY - 20, 50, 20);

              docPdf.setDrawColor(0);
              docPdf.setLineWidth(0.5);
              docPdf.line(centerX - 80, sigY, centerX - 20, sigY);
              docPdf.line(centerX + 20, sigY, centerX + 80, sigY);

              docPdf.setFontSize(9);
              docPdf.setFont("helvetica", "bold");
              docPdf.text("DIRETOR EXECUTIVO", centerX - 50, sigY + 5, { align: "center" });
              docPdf.text("SECRETARIA GERAL", centerX + 50, sigY + 5, { align: "center" });

              // --- PÁGINA 2: HISTÓRICO (Verso do Certificado) ---
              docPdf.addPage('a4', 'landscape');
              // Borda simples para histórico
              docPdf.setDrawColor(30, 41, 59);
              docPdf.setLineWidth(1);
              docPdf.rect(10, 10, width - 20, height - 20);

              docPdf.setFont("times", "bold");
              docPdf.setFontSize(18);
              docPdf.text("HISTÓRICO E DETALHAMENTO ACADÊMICO", centerX, 25, { align: "center" });

              docPdf.setFontSize(12);
              docPdf.setFont("helvetica", "normal");
              docPdf.text(`Aluno: ${opStudent.displayName} | Matrícula: ${opStudent.academicId}`, 20, 40);

              // Nome do Curso e Descrição (PEDIDO DO USUÁRIO)
              docPdf.setFont("helvetica", "bold");
              docPdf.text(`Curso: ${courseData.nome || 'Teologia Livre'}`, 20, 48);

              if (courseData.descricao) {
                  docPdf.setFont("helvetica", "italic");
                  docPdf.setFontSize(10);
                  const descText = docPdf.splitTextToSize(`Ementa: ${courseData.descricao}`, width - 40);
                  docPdf.text(descText, 20, 55);
              }

              // Tabela de Módulos
              const tableStartY = courseData.descricao ? 70 : 60;
              const tableBody = modulesData.length > 0 ? modulesData.map((m: any) => [
                  m.title || "Módulo",
                  "20h",
                  "100%",
                  "10.0",
                  "APROVADO"
              ]) : [["Módulo Único", "100h", "100%", "10.0", "APROVADO"]];

              autoTable(docPdf, {
                  startY: tableStartY,
                  head: [['Disciplina / Módulo', 'Carga Horária', 'Frequência', 'Nota Final', 'Situação']],
                  body: tableBody,
                  theme: 'grid',
                  headStyles: { fillColor: [30, 41, 59], halign: 'center' },
                  bodyStyles: { halign: 'center' },
                  styles: { fontSize: 10, font: "helvetica" },
                  margin: { left: 20, right: 20 }
              });

              // Footer com QR Code (PÁGINA 2)
              const footerY = height - 30;
              docPdf.addImage(qrCodeDataUrl, 'PNG', 20, footerY, 20, 20);
              docPdf.setFontSize(8);
              docPdf.setTextColor(100);
              docPdf.text("DOCUMENTO COM VALIDADE JURÍDICA NACIONAL", 45, footerY + 8);
              docPdf.text(`Código de Autenticidade: ${code}`, 45, footerY + 13);
              docPdf.text("Verifique a veracidade deste documento lendo o QR Code.", 45, footerY + 18);

          } else {
              // *** DOCUMENTO PADRÃO (RETRATO - DECLARAÇÃO/HISTÓRICO) ***
              drawWatermark(docPdf);

              // Cabeçalho Centralizado
              drawBibleWingsLogo(docPdf, 30, 20, 1.2); // Logo à esquerda superior

              docPdf.setFont("times", "bold");
              docPdf.setFontSize(20);
              docPdf.setTextColor(30, 41, 59);
              docPdf.text("ESCOLA BÍBLICA EAD", centerX + 10, 20, { align: "center" }); // Offset logo compensation

              docPdf.setFont("helvetica", "normal");
              docPdf.setFontSize(9);
              docPdf.setTextColor(100);
              docPdf.text("Secretaria Geral de Ensino a Distância", centerX + 10, 26, { align: "center" });

              docPdf.setDrawColor(200);
              docPdf.line(20, 35, width - 20, 35); // Linha separadora

              // Título do Documento
              docPdf.setFont("times", "bold");
              docPdf.setFontSize(22);
              docPdf.setTextColor(0);
              docPdf.text(docTitle, centerX, 60, { align: "center" });

              // Conteúdo do Texto (Centralizado Verticalmente)
              // Calculamos onde começar para que fique balanceado
              docPdf.setFont("times", "normal");
              docPdf.setFontSize(12);

              const margin = 25;
              const maxW = width - (margin * 2);

              let textBody = "";
              if (docType === 'matricula') {
                  textBody = `DECLARAMOS, para os devidos fins de direito, que o(a) aluno(a) ${opStudent.displayName?.toUpperCase()}, inscrito(a) no CPF sob o nº ${opStudent.cpf || '---'} e portador(a) da matrícula institucional nº ${opStudent.academicId || '---'}, encontra-se devidamente MATRICULADO(A) no curso de ${courseData.nome || 'Teologia'}, modalidade EAD, neste período letivo.\n\nSituação Acadêmica Atual: ${opStudent.status?.toUpperCase()}.`;
              } else if (docType === 'transferencia') {
                  textBody = `Atestamos a TRANSFERÊNCIA do(a) aluno(a) ${opStudent.displayName?.toUpperCase()} (Matrícula: ${opStudent.academicId}) para outra instituição de ensino. O(a) discente cumpriu as obrigações acadêmicas até a presente data no curso de ${courseData.nome || 'Teologia'}.\n\nSegue em anexo o histórico escolar.`;
              } else if (docType === 'historico') {
                  textBody = `Histórico Escolar Oficial do(a) aluno(a) ${opStudent.displayName?.toUpperCase()}, referente ao curso de ${courseData.nome || 'Teologia'}.`;
              }

              // Posição inicial calculada para "meio visual" da página (aprox 90mm)
              let currentY = 90; 
              const splitText = docPdf.splitTextToSize(textBody, maxW);
              docPdf.text(splitText, margin, currentY);

              // Avança Y baseado no tamanho do texto
              currentY += (splitText.length * 7) + 10;

              // Data (Logo após o texto)
              const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
              docPdf.text(dateStr, width - margin, currentY, { align: "right" });

              // Se for Histórico (na mesma página se couber)
              if (docType === 'historico') {
                  currentY += 20;
                  const tableBody = modulesData.length > 0 ? modulesData.map((m: any) => [m.title || "Módulo", "20h", "100%", "10.0", "APROVADO"]) : [["Sem registros", "-", "-", "-", "-"]];
                  autoTable(docPdf, {
                      startY: currentY,
                      head: [['Componente', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                      body: tableBody,
                      theme: 'striped',
                      headStyles: { fillColor: [30, 41, 59] },
                      margin: { left: margin, right: margin }
                  });
              }

              // Assinaturas (Espaço Fixo abaixo da data/texto, mas acima do rodapé)
              // Vamos posicionar as assinaturas a 2/3 da página ou logo após o conteúdo se for longo
              let sigY = Math.max(currentY + 40, height - 70); 

              if (directorSignature) docPdf.addImage(directorSignature, 'PNG', centerX - 60, sigY - 20, 40, 20);
              if (secSignature) docPdf.addImage(secSignature, 'PNG', centerX + 20, sigY - 20, 40, 20);

              docPdf.setDrawColor(0);
              docPdf.setLineWidth(0.5);
              docPdf.line(centerX - 70, sigY, centerX - 20, sigY);
              docPdf.line(centerX + 20, sigY, centerX + 70, sigY);

              docPdf.setFontSize(8);
              docPdf.setFont("helvetica", "bold");
              docPdf.text("DIRETOR EXECUTIVO", centerX - 45, sigY + 5, { align: "center" });
              docPdf.text("SECRETARIA GERAL", centerX + 45, sigY + 5, { align: "center" });

              // Rodapé com QR Code (Mais alto, perto das assinaturas)
              const footerY = height - 35;
              docPdf.setDrawColor(200);
              docPdf.line(margin, footerY, width - margin, footerY);

              docPdf.addImage(qrCodeDataUrl, 'PNG', margin, footerY + 2, 18, 18);
              docPdf.setFontSize(7);
              docPdf.setTextColor(100);
              docPdf.text(`Validação Digital: ${code}`, margin + 22, footerY + 8);
              docPdf.text("Este documento possui assinatura eletrônica.", margin + 22, footerY + 12);

              // Se for transferência, gera página 2 com histórico completo
              if (docType === 'transferencia') {
                  docPdf.addPage();
                  drawWatermark(docPdf);
                  // Cabeçalho Simplificado Pag 2
                  docPdf.setFont("times", "bold");
                  docPdf.setFontSize(14);
                  docPdf.setTextColor(0);
                  docPdf.text("ANEXO: HISTÓRICO ESCOLAR", centerX, 20, { align: "center" });

                  docPdf.setFontSize(10);
                  docPdf.setFont("helvetica", "normal");
                  docPdf.text(`Aluno: ${opStudent.displayName}`, margin, 30);
                  docPdf.text(`Curso: ${courseData.nome}`, margin, 35);

                  const tableBody = modulesData.map((m: any) => [m.title || "Módulo", "20h", "100%", "10.0", "APROVADO"]);
                  autoTable(docPdf, {
                      startY: 45,
                      head: [['Componente', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                      body: tableBody,
                      theme: 'grid',
                      headStyles: { fillColor: [30, 41, 59] },
                      margin: { left: margin, right: margin }
                  });
              }
          }

          // Output
          const pdfBase64 = docPdf.output('datauristring');
          const pdfBlob = docPdf.output('blob');

          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: `${docTitle} - ${opStudent.displayName}.pdf`,
              type: 'file', mimeType: 'application/pdf', url: pdfBase64,
              parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid,
              studentId: opStudent.uid, docType: docType,
              docData: {
                  code, title: docTitle, date: new Date().toISOString(),
                  student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId },
                  courseData: courseData, modulesData: modulesData
              }
          });

          const blobUrl = URL.createObjectURL(pdfBlob);
          window.open(blobUrl, '_blank');

      } catch (e: any) {
          console.error("Erro PDF:", e);
          alert("Erro: " + e.message);
      } finally {
          setIsGeneratingPdf(false);
      }
  };

  const saveEditedStudent = async () => {
      if (!editingStudent) return;
      try {
          await updateDoc(doc(db, 'users', editingStudent.uid), {
              ...editingStudent,
              updatedAt: serverTimestamp()
          });
