                            {students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').length === 0 ? (
                                <p className="text-center text-slate-300 italic py-10 text-xs uppercase font-black">Nenhum aluno pendente de validação.</p>
                            ) : students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').map(s => (
                                <div key={s.uid} className="flex justify-between items-center p-4 border border-rose-100 bg-rose-50/50 rounded-xl hover:bg-rose-50 transition-all">
                                    <div className="flex items-center gap-3">
