                               <span className="text-[8px] font-bold opacity-50 absolute -bottom-5 block w-full">{m.sender} • {m.createdAt?.seconds ? new Date(m.createdAt.seconds*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) : '...'}</span>
                            </div>
                         </div>
                       ))}
                       <div ref={chatEndRef} className="h-4" />
                    </div>
                    {(activeTicket.status === 'Em Andamento' || activeTicket.status === 'Pendente') ? (
                      <div className="p-4 border-t border-slate-100 bg-white z-20">
                         <div className="flex gap-3 items-center bg-slate-50 p-2 rounded-2xl border border-slate-200 focus-within:border-indigo-400 focus-within:ring-2 focus-within:ring-indigo-100 transition-all">
                            <button onClick={() => chatFileInputRef.current?.click()} className="p-3 bg-white text-slate-400 rounded-xl hover:text-indigo-600 shadow-sm transition-all"><Paperclip size={18}/></button>
                            <input type="file" ref={chatFileInputRef} className="hidden" onChange={sendAttachment}/>
                            <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendMessage()} className="flex-1 bg-transparent border-none text-xs font-bold outline-none text-slate-700 placeholder:text-slate-400" placeholder="Digite sua resposta..." />
                            <button onClick={sendMessage} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all"><Send size={18}/></button>
                         </div>
                      </div>
                    ) : <div className="p-4 bg-slate-100 text-center text-[10px] font-black uppercase text-slate-400 border-t border-slate-200">Atendimento Encerrado.</div>}
                  </>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-6"><LifeBuoy size={48} className="opacity-20"/><div className="text-center"><h3 className="text-lg font-black uppercase italic text-slate-400">Chat de Suporte</h3><p className="text-xs font-bold uppercase tracking-widest opacity-50 mt-1">Selecione um ticket na aba "Atendimento"</p></div></div>
                )}
             </div>
         )}

         {(activeTab === 'arquivos') && !activeTicket && (
           <div className={`bg-white border border-slate-200 rounded-xl overflow-hidden h-full flex flex-col shadow-lg`}>
              <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                 <div className="flex items-center gap-2 overflow-x-auto">
                    <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-200 rounded-lg"><Home size={16}/></button>
                    {folderPath.map((f, i) => (
                      <React.Fragment key={f.id}>
                        {i > 0 && <ChevronRight size={14} className="text-slate-400"/>}
                        <button onClick={() => handleBreadcrumb(i)} className={`text-xs font-bold px-2 py-1 rounded-lg hover:bg-slate-200 ${i === folderPath.length -1 ? 'text-slate-900' : 'text-slate-500'}`}>{f.name}</button>
                      </React.Fragment>
                    ))}
                 </div>
                 <div className="flex gap-2">
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} />
                    <button onClick={() => fileInputRef.current?.click()} className="px-3 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-indigo-600"><UploadCloud size={14}/> Upload</button>
                    <button onClick={handleCreateFolder} className="px-3 py-2 bg-slate-200 text-slate-700 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-slate-300"><FolderPlus size={14}/> Pasta</button>
                 </div>
              </div>
              <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50/50">
                 {currentItems.length === 0 ? (
                   <div className="h-full flex flex-col items-center justify-center opacity-30 gap-4"><Folder size={48} /><p className="text-xs font-black uppercase">Pasta Vazia</p></div>
                 ) : (
                   <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                      {currentItems.map(item => (
                        <div key={item.id} onDoubleClick={() => item.type === 'folder' ? handleNavigate(item) : null} className={`bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all group flex flex-col items-center text-center cursor-pointer relative`}>
                           <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-3 text-white shadow-inner ${item.type === 'folder' ? 'bg-amber-400' : 'bg-indigo-500'}`}>{item.type === 'folder' ? <Folder size={32} className="fill-white/50"/> : <FileText size={32} className="fill-white/50"/>}</div>
                           <p className="text-[10px] font-bold text-slate-700 line-clamp-2 leading-tight w-full break-words">{item.name}</p>
                           {item.type === 'file' && (
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 flex gap-1 bg-white/90 rounded-lg p-1 shadow-sm">
                               <button onClick={async (e) => { e.stopPropagation(); if(confirm('Apagar?')) await deleteDoc(doc(db, 'secretaria_arquivos', item.id)); }} className="p-1.5 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100"><Trash2 size={12}/></button>
                               <button onClick={(e) => { e.stopPropagation(); setFileToMove(item); setMoveModalOpen(true); }} className="p-1.5 bg-slate-50 text-slate-600 rounded-lg hover:bg-slate-100"><Move size={12}/></button>
                               <button onClick={(e) => { e.stopPropagation(); viewFile(item); }} className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100"><Eye size={12}/></button>
                             </div>
                           )}
                        </div>
                      ))}
                   </div>
                 )}
              </div>
           </div>
         )}

         {activeTab === 'operacional' && (
           <div className="h-full flex flex-col md:flex-row gap-6">
              <div className="w-full md:w-64 flex flex-col gap-3">
                 <button onClick={() => setOpSubView('declaracao')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'declaracao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><FileText size={18}/><span className="text-xs font-black uppercase">Declarações</span></button>
                 <button onClick={() => setOpSubView('historico')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'historico' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><Archive size={18}/><span className="text-xs font-black uppercase">Histórico Escolar</span></button>
                 <button onClick={() => setOpSubView('transferencia')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'transferencia' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><ArrowRightLeft size={18}/><span className="text-xs font-black uppercase">Transferência</span></button>
                 <button onClick={() => setOpSubView('validacao')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'validacao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><UserCheck size={18}/><span className="text-xs font-black uppercase">Auditoria</span></button>
                 <button onClick={() => setIsSignModalOpen(true)} className="p-4 rounded-xl border bg-white border-slate-200 hover:bg-slate-50 flex items-center gap-3 transition-all"><Fingerprint size={18}/><span className="text-xs font-black uppercase">Minha Assinatura</span></button>
              </div>

              <div className="flex-1 bg-white rounded-2xl border border-slate-200 p-1 shadow-sm overflow-hidden relative">
                 {(opSubView === 'declaracao' || opSubView === 'historico' || opSubView === 'transferencia') && (
                   <div className="max-w-lg mx-auto space-y-6 py-10 px-6">
                      <h3 className="text-xl font-black uppercase italic text-slate-900 border-b pb-4">Gerar Documento Oficial</h3>
                      <div className="p-4 bg-amber-50 rounded-xl border border-amber-100 text-[10px] text-amber-700 leading-relaxed italic">
                         <AlertTriangle size={14} className="inline mr-1 mb-0.5"/> 
                         Os documentos gerados possuem <strong>validade jurídica</strong> através de assinatura digital e chave de verificação única (Hash + QR Code).
                      </div>
                      <div className="space-y-2">
                         <label className="text-[10px] font-black uppercase text-slate-400">Selecione o Aluno</label>
                         <select onChange={e => setOpStudent(students.find(s => s.uid === e.target.value))} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold">
                            <option value="">Selecione...</option>
                            {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName} (RA: {s.academicId})</option>)}
                         </select>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div className={`p-3 rounded-lg border text-center ${secSignature ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-rose-50 border-rose-200 text-rose-700'}`}>
                              <p className="text-[9px] font-black uppercase">Assinatura Secretário</p>
                              <p className="text-xs">{secSignature ? "OK" : "Pendente"}</p>
                          </div>
                          <div className={`p-3 rounded-lg border text-center ${directorSignature ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-amber-50 border-amber-200 text-amber-700'}`}>
                              <p className="text-[9px] font-black uppercase">Assinatura Diretor</p>
                              <p className="text-xs">{directorSignature ? "OK" : "Pendente (Simulado)"}</p>
                          </div>
                      </div>

                      <div className="pt-4 flex gap-4">
                         {opSubView === 'declaracao' && (
                           <>
                             <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('matricula')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Printer size={14}/>} Matrícula PDF
                             </button>
                             <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('conclusao')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Award size={14}/>} Diploma PDF
                             </button>
                           </>
                         )}
                         {opSubView === 'transferencia' && (
                           <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('transferencia')} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <ArrowRightLeft size={14}/>} Gerar Guia PDF
                           </button>
                         )}
                         {opSubView === 'historico' && (
                           <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('historico')} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Archive size={14}/>} Gerar Histórico PDF
                           </button>
                         )}
                      </div>
                   </div>
                 )}
                 {opSubView === 'validacao' && (
                    <div className="p-8 h-full flex flex-col">
