      {auditModalOpen && editingStudent && (
          <div className="fixed inset-0 z-[3000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-white w-full max-w-4xl h-[90vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
                  <header className="bg-slate-50 px-8 py-5 border-b border-slate-100 flex justify-between items-center shrink-0">
                      <div className="flex items-center gap-3">
                          <div className="p-2 bg-indigo-600 text-white rounded-lg shadow-md"><ShieldCheck size={20}/></div>
                          <div><h2 className="text-lg font-black uppercase italic text-slate-900 leading-none">Auditoria de Prontuário</h2><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Validação Cadastral</p></div>
                      </div>
                      <button onClick={() => setAuditModalOpen(false)} className="p-2 hover:bg-rose-50 text-slate-400 rounded-full transition-all"><X size={20}/></button>
                  </header>
                  <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-8">
                       <div className="grid grid-cols-2 gap-6">
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Nome</label><input value={editingStudent.displayName} onChange={e => setEditingStudent({...editingStudent, displayName: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">CPF</label><input value={editingStudent.cpf} onChange={e => setEditingStudent({...editingStudent, cpf: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Email</label><input value={editingStudent.email} disabled className="w-full p-3 bg-slate-100 rounded-xl text-xs font-bold text-slate-500 border border-slate-200 cursor-not-allowed"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Telefone</label><input value={editingStudent.telefone} onChange={e => setEditingStudent({...editingStudent, telefone: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                       </div>
                       <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
                           <h4 className="text-[10px] font-black uppercase text-slate-400 mb-4 tracking-widest">Documentos Anexados</h4>
                           <div className="flex items-center gap-4">
                               <div className="w-24 h-24 bg-white rounded-xl border border-slate-200 flex items-center justify-center overflow-hidden">{editingStudent.photoURL ? <img src={editingStudent.photoURL} className="w-full h-full object-cover"/> : <span className="text-[8px] font-black uppercase text-slate-300">Sem Foto</span>}</div>
                               <div><p className="text-xs font-bold text-slate-800">Foto de Identificação</p><p className="text-[9px] text-slate-400">Status: {editingStudent.photoURL ? 'Enviado' : 'Pendente'}</p></div>
                           </div>
                       </div>
                       <div className="flex gap-4 pt-4 border-t border-slate-100">
                          <button onClick={saveEditedStudent} className="px-6 py-3 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase hover:bg-slate-200 flex items-center gap-2"><Edit3 size={14}/> Salvar Edições</button>
                          <button onClick={validateStudent} className="px-8 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-emerald-700 transition-all flex items-center gap-2 shadow-xl shadow-emerald-200"><Check size={16}/> Validar Matrícula</button>
                       </div>
                  </div>
              </div>
          </div>
      )}
      {isSignModalOpen && <SignaturePad title="Assinatura Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert("Assinatura Salva!"); }} />}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, addDoc, setDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, MessageSquare, Search, X, FileText, UserCheck, 
  ArrowRightLeft, Fingerprint, Send, Archive, Eye, 
  Printer, Folder, File, Download, Plus, ChevronRight,
  UploadCloud, FolderPlus, MoreVertical, CheckCircle2, ShieldCheck,
  AlertTriangle, Home, CornerUpLeft, Paperclip, Save, Timer, MessageCircle,
  Phone, UserX, Edit3, Ban, Check, RefreshCw, Award, Clock, Trash2, FolderInput,
  Move, ThumbsUp, ThumbsDown, ExternalLink, LifeBuoy, ChevronDown, CheckSquare
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';
import { jsPDF } from "https://esm.sh/jspdf@2.5.1";
import autoTable from "https://esm.sh/jspdf-autotable@3.8.1";
import QRCode from "https://esm.sh/qrcode@1.5.3";

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'historico' | 'transferencia' | 'assinatura' | 'validacao';

// --- HELPERS ---
const generateVerificationCode = () => {
  return `${new Date().getFullYear()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}.${Math.random().toString(36).substr(2, 4).toUpperCase()}`;
};

const viewFile = (file: any) => {
  if (!file || !file.url) return;
  if (file.mimeType === 'application/pdf' || file.name?.endsWith('.pdf')) {
      const newWindow = window.open();
      if (newWindow) {
          if (file.url.startsWith('data:')) {
             newWindow.document.write(`<iframe width='100%' height='100%' src='${file.url}'></iframe>`);
             newWindow.document.title = file.name;
          } else {
             newWindow.location.href = file.url;
          }
      } else {
          alert("Pop-up bloqueado. Permita pop-ups para visualizar o PDF.");
      }
      return;
  }
  window.open(file.url, '_blank');
};

const viewAttachment = (url: string) => {
    if (!url) return;
    if (url.startsWith('http')) { window.open(url, '_blank'); return; }
    if (url.startsWith('data:')) {
        const win = window.open();
        win?.document.write(`<iframe src="${url}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`);
    }
};

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');

  // Data States
  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [fileSystem, setFileSystem] = useState<any[]>([]);

  // UI States - Atendimento
  const [ticketSearchTerm, setTicketSearchTerm] = useState('');
  const [ticketFilter, setTicketFilter] = useState<'todos' | 'pendente' | 'ativo' | 'finalizado'>('todos');
  const [activeTicket, setActiveTicket] = useState<any | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [selectedTickets, setSelectedTickets] = useState<string[]>([]);

  // UI States - General
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);
  const [directorSignature, setDirectorSignature] = useState<string | null>(null);

  // File Explorer States
  const [currentFolderId, setCurrentFolderId] = useState<string>('root');
  const [folderPath, setFolderPath] = useState<{id: string, name: string}[]>([{id: 'root', name: 'Arquivos'}]);
  const [moveModalOpen, setMoveModalOpen] = useState(false);
  const [fileToMove, setFileToMove] = useState<any>(null);
  const [moveTargetFolderId, setMoveTargetFolderId] = useState('root');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatFileInputRef = useRef<HTMLInputElement>(null);

  // Operational State
  const [opStudent, setOpStudent] = useState<any>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const [auditModalOpen, setAuditModalOpen] = useState(false);
  const [editingStudent, setEditingStudent] = useState<any | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(collection(db, 'tickets'), s => {
        const t = s.docs.map(d => ({ id: d.id, ...d.data() }));
        t.sort((a:any, b:any) => {
            if (a.status === 'Pendente' && b.status !== 'Pendente') return -1;
            if (b.status === 'Pendente' && a.status !== 'Pendente') return 1;
            return (b.updatedAt?.seconds || 0) - (a.updatedAt?.seconds || 0);
        });
        setTickets(t);
        if (activeTicket) {
            const updated = t.find((x: any) => x.id === activeTicket.id);
            if (updated) setActiveTicket(updated);
        }
    });

    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => {
      setFileSystem(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubS = onSnapshot(collection(db, 'users'), s => {
      const allUsers = s.docs.map(d => ({ uid: d.id, ...d.data() }));
      setStudents(allUsers.filter((u: any) => u.role === 'aluno'));
    });

    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
    getDocs(qDir).then(s => { if (!s.empty) setDirectorSignature(s.docs[0].data().signatureUrl); });

    return () => { unsubT(); unsubF(); unsubS(); };
  }, [user.uid, activeTicket?.id]);

  useEffect(() => {
    if (!activeTicket) { setMessages([]); return; }
    const q = query(collection(db, 'tickets', activeTicket.id, 'messages'), orderBy('createdAt', 'asc'));
    return onSnapshot(q, (snap) => {
      setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
  }, [activeTicket]);

  const toggleSelectTicket = (id: string) => {
      if (selectedTickets.includes(id)) setSelectedTickets(prev => prev.filter(tid => tid !== id));
      else setSelectedTickets(prev => [...prev, id]);
  };

  const toggleSelectAll = () => {
      if (selectedTickets.length === tickets.length) setSelectedTickets([]);
      else setSelectedTickets(tickets.map(t => t.id));
  };

  const handleBulkDelete = async () => {
      if (selectedTickets.length === 0) return;
      if (!confirm(`Deseja excluir ${selectedTickets.length} protocolos?`)) return;
      const batch = await import("https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js").then(m => m.writeBatch(db));
      selectedTickets.forEach(tid => {
          batch.delete(doc(db, 'tickets', tid));
      });
      await batch.commit();
      setSelectedTickets([]);
  };

  const handleTicketAction = async (action: 'assume' | 'finalize' | 'archive') => {
      if (!activeTicket) return;
      let update: any = {};
      if (action === 'assume') {
          update = { status: 'Em Andamento', specialistId: user.uid, specialistName: user.displayName, updatedAt: serverTimestamp() };
          await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
              text: `O atendente ${user.displayName} assumiu este chamado.`,
              sender: 'Sistema', isBot: true, createdAt: serverTimestamp()
          });
      } else if (action === 'finalize') {
          update = { status: 'Resolvido', closedAt: serverTimestamp(), updatedAt: serverTimestamp() };
          await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), {
              text: `Atendimento finalizado.`,
              sender: 'Sistema', isBot: true, createdAt: serverTimestamp()
          });
      } else if (action === 'archive') {
          update = { status: 'Arquivado', archivedAt: serverTimestamp() };
      }
      await updateDoc(doc(db, 'tickets', activeTicket.id), update);
  };

  const sendMessage = async () => {
    if (!chatMessage.trim() || !activeTicket) return;
    await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { text: chatMessage, sender: user.displayName || 'Atendente', role: 'staff', createdAt: serverTimestamp() });
    await updateDoc(doc(db, 'tickets', activeTicket.id), { lastMessage: chatMessage, updatedAt: serverTimestamp() });
    setChatMessage('');
  };

  const sendAttachment = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file || !activeTicket) return;
      const reader = new FileReader();
      reader.onload = async (ev) => {
          if (ev.target?.result) {
              await addDoc(collection(db, 'tickets', activeTicket.id, 'messages'), { 
                  text: `Anexo enviado: ${file.name}`, 
                  attachmentUrl: ev.target.result, 
                  sender: user.displayName, 
                  role: 'staff',
                  createdAt: serverTimestamp() 
              });
          }
      };
      reader.readAsDataURL(file);
  };

  // --- PDF GENERATOR V2 (REFINED) ---
  const generateLegalPDF = async (docType: 'matricula' | 'conclusao' | 'transferencia' | 'historico') => {
      if (!opStudent) { alert("Selecione um aluno."); return; }
      setIsGeneratingPdf(true);

      try {
          const code = generateVerificationCode();
          const isCertificate = docType === 'conclusao';

          const docTitle = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 
                           docType === 'conclusao' ? 'CERTIFICADO DE CONCLUSÃO' : 
                           docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';

          let courseData: any = {};
          let modulesData: any[] = [];

          if (opStudent.cursoInicial) {
              const cSnap = await getDoc(doc(db, 'cursos', opStudent.cursoInicial));
              if (cSnap.exists()) courseData = cSnap.data();
              const mQuery = query(collection(db, 'modulos'), where('courseId', '==', opStudent.cursoInicial));
              const mSnap = await getDocs(mQuery);
              modulesData = mSnap.docs.map(d => d.data()).sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
          }

          const validationUrl = `${window.location.origin}?code=${code}`;
          const qrCodeDataUrl = await QRCode.toDataURL(validationUrl, { margin: 0, width: 100 });

          const pdf = new jsPDF({ 
              orientation: isCertificate ? 'landscape' : 'portrait', 
              unit: 'mm', 
              format: 'a4' 
          });

          const width = pdf.internal.pageSize.getWidth();
          const height = pdf.internal.pageSize.getHeight();
          const centerX = width / 2;
          const centerY = height / 2;

          // --- HELPER DE DESENHO DA LOGO (BÍBLIA/ASAS) ---
          const drawLogo = (doc: any, x: number, y: number, scale: number) => {
              doc.setLineWidth(0.5 * scale);
              doc.setDrawColor(30, 41, 59); 
              doc.setFillColor(255, 255, 255);

              // Simula páginas abertas (Esquerda)
              doc.lines([[ -15*scale, -5*scale, -10*scale, 5*scale, -2*scale, 8*scale ]], x, y + (5*scale));
              doc.lines([[ -15*scale, -8*scale, -10*scale, 2*scale, -2*scale, 5*scale ]], x, y + (2*scale));
              // Simula páginas abertas (Direita)
              doc.lines([[ 15*scale, -5*scale, 10*scale, 5*scale, 2*scale, 8*scale ]], x, y + (5*scale));
              doc.lines([[ 15*scale, -8*scale, 10*scale, 2*scale, 2*scale, 5*scale ]], x, y + (2*scale));

              // Centro
              doc.line(x, y - (5*scale), x, y + (10*scale));

              // Base
              doc.text("EB-EAD", x, y + (15*scale), { align: "center" });
          };

          const drawSignatures = (doc: any, yPos: number) => {
              const dirX = centerX - 50;
              const secX = centerX + 50;

              if (directorSignature) doc.addImage(directorSignature, 'PNG', dirX - 25, yPos - 20, 50, 20);
              doc.setDrawColor(0);
              doc.setLineWidth(0.5);
              doc.line(dirX - 35, yPos, dirX + 35, yPos);
              doc.setFont("helvetica", "bold");
              doc.setFontSize(8);
              doc.text("DIRETOR EXECUTIVO", dirX, yPos + 5, { align: "center" });

              if (secSignature) doc.addImage(secSignature, 'PNG', secX - 25, yPos - 20, 50, 20);
              doc.line(secX - 35, yPos, secX + 35, yPos);
              doc.text("SECRETARIA GERAL", secX, yPos + 5, { align: "center" });
          };

          // --- 1. CERTIFICADO (PAISAGEM) ---
          if (isCertificate) {
              // Moldura Ornamental
              const gold = [197, 160, 89];
              pdf.setDrawColor(gold[0], gold[1], gold[2]);
              pdf.setLineWidth(2);
              pdf.rect(10, 10, width - 20, height - 20);
              pdf.rect(13, 13, width - 26, height - 26);

              // Cantoneiras (Simples)
              pdf.setLineWidth(1);
              pdf.circle(13, 13, 2); pdf.circle(width-13, 13, 2);
              pdf.circle(13, height-13, 2); pdf.circle(width-13, height-13, 2);

              // Marca D'água Centralizada
              pdf.setTextColor(245, 245, 245);
              pdf.setFontSize(100);
              pdf.setFont("times", "bold");
              pdf.text("EB-EAD", centerX, centerY, { align: "center", angle: 45, baseline: 'middle' });
              pdf.setTextColor(0, 0, 0); // Reset

              // Cabeçalho
              drawLogo(pdf, centerX, 35, 1.5);
              pdf.setFont("times", "bold");
              pdf.setFontSize(32);
              pdf.setTextColor(30, 41, 59);
              pdf.text("CERTIFICADO DE CONCLUSÃO", centerX, 70, { align: "center" });

              // Corpo
              pdf.setFont("times", "normal");
              pdf.setFontSize(16);
              pdf.setTextColor(0);
              const text = `Certificamos que ${opStudent.displayName?.toUpperCase()}, portador(a) do CPF ${opStudent.cpf || '---'}, concluiu com êxito o curso de ${courseData.nome?.toUpperCase() || 'TEOLOGIA'}, cumprindo a carga horária exigida e obtendo o aproveitamento necessário para a outorga deste título.`;
              const splitText = pdf.splitTextToSize(text, width - 80);
              pdf.text(splitText, centerX, 100, { align: "center" });

              // Data
              const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
              pdf.setFontSize(12);
              pdf.text(dateStr, width - 40, 130, { align: "right" });

              // Assinaturas
              drawSignatures(pdf, height - 40);

              // PÁGINA 2: HISTÓRICO
              pdf.addPage('a4', 'landscape');
              pdf.setDrawColor(0); pdf.setLineWidth(0.5);
              pdf.rect(10, 10, width - 20, height - 20); // Borda simples

              pdf.setFont("times", "bold");
              pdf.setFontSize(18);
              pdf.text("HISTÓRICO E DETALHAMENTO ACADÊMICO", centerX, 25, { align: "center" });

              // Info do Curso
              pdf.setFontSize(12);
              pdf.setFont("helvetica", "normal");
              pdf.text(`Aluno: ${opStudent.displayName}`, 20, 40);
              pdf.text(`Matrícula: ${opStudent.academicId || '---'}`, 120, 40);
              pdf.setFont("helvetica", "bold");
              pdf.text(`Curso: ${courseData.nome || 'Teologia'}`, 20, 50);

              if(courseData.descricao) {
                  pdf.setFont("helvetica", "italic");
                  pdf.setFontSize(10);
                  const desc = pdf.splitTextToSize(`Ementa: ${courseData.descricao}`, width - 40);
                  pdf.text(desc, 20, 58);
              }

              // Tabela
              const tableBody = modulesData.length > 0 ? modulesData.map((m: any) => [
                  m.title || "Módulo", "20h", "100%", "10.0", "APROVADO"
              ]) : [["Módulo Único", "100h", "100%", "10.0", "APROVADO"]];

              autoTable(pdf, {
                  startY: courseData.descricao ? 75 : 60,
                  head: [['Disciplina / Módulo', 'Carga Horária', 'Frequência', 'Nota Final', 'Situação']],
                  body: tableBody,
                  theme: 'grid',
                  headStyles: { fillColor: [30, 41, 59] },
                  margin: { left: 20, right: 20 }
              });

              // Footer com QR Code (Página 2)
              const footerY = height - 30;
              pdf.addImage(qrCodeDataUrl, 'PNG', 20, footerY, 20, 20);
              pdf.setFontSize(8);
              pdf.text("DOCUMENTO COM VALIDADE JURÍDICA NACIONAL", 45, footerY + 8);
              pdf.text(`Autenticidade: ${code}`, 45, footerY + 13);

          } else {
              // --- 2. OUTROS (RETRATO) ---
              // Marca D'água
              pdf.setTextColor(245, 245, 245);
              pdf.setFontSize(80);
              pdf.setFont("times", "bold");
              pdf.text("EB-EAD", centerX, centerY, { align: "center", angle: 45, baseline: 'middle' });
              pdf.setTextColor(0, 0, 0);

              // Cabeçalho
              drawLogo(pdf, 30, 25, 1.2);
              pdf.setFont("times", "bold");
              pdf.setFontSize(18);
              pdf.text("ESCOLA BÍBLICA EAD", centerX + 10, 25, { align: "center" });
              pdf.setFontSize(10);
              pdf.setFont("helvetica", "normal");
              pdf.setTextColor(100);
              pdf.text("Secretaria Geral de Ensino a Distância", centerX + 10, 32, { align: "center" });
              pdf.setDrawColor(200);
              pdf.line(20, 40, width - 20, 40);

              // Título
              const docName = docType === 'matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : docType === 'historico' ? 'HISTÓRICO ESCOLAR' : 'GUIA DE TRANSFERÊNCIA';
              pdf.setFont("times", "bold");
              pdf.setFontSize(20);
              pdf.setTextColor(0);
              pdf.text(docName, centerX, 60, { align: "center" });

              // Texto (Centralizado Verticalmente)
              pdf.setFont("times", "normal");
              pdf.setFontSize(12);

              let body = "";
              if (docType === 'matricula') {
                  body = `DECLARAMOS, para os devidos fins, que o(a) aluno(a) ${opStudent.displayName?.toUpperCase()}, CPF ${opStudent.cpf || '---'}, encontra-se devidamente MATRICULADO(A) no curso de ${courseData.nome || 'Teologia'}, modalidade EAD.\n\nSituação: ${opStudent.status?.toUpperCase()}.`;
              } else {
                  body = `Documento oficial referente ao aluno(a) ${opStudent.displayName?.toUpperCase()}, CPF ${opStudent.cpf || '---'}, do curso de ${courseData.nome || 'Teologia'}.`;
              }

              const margin = 25;
              const splitBody = pdf.splitTextToSize(body, width - (margin * 2));
              let textY = centerY - 20; // Start slightly above center
              pdf.text(splitBody, margin, textY);
              textY += (splitBody.length * 7) + 10;

              // Data
              const dateStr = `São Paulo, ${new Date().toLocaleDateString('pt-BR', {day:'numeric', month:'long', year:'numeric'})}.`;
              pdf.text(dateStr, width - margin, textY, { align: "right" });

              // Assinaturas (Fixo embaixo)
              drawSignatures(pdf, height - 50);

              // QR Code (Fixo rodapé)
              const fY = height - 30;
              pdf.line(margin, fY, width - margin, fY);
              pdf.addImage(qrCodeDataUrl, 'PNG', margin, fY + 2, 18, 18);
              pdf.setFontSize(7);
              pdf.text(`Validação: ${code}`, margin + 22, fY + 10);

              // Se for histórico, tabela na mesma página se couber ou nova página
              if (docType === 'historico' || docType === 'transferencia') {
                  if (docType === 'transferencia') {
                      pdf.addPage();
                      drawLogo(pdf, 30, 25, 1.2);
                      pdf.text("ANEXO: HISTÓRICO", centerX, 25, { align: "center" });
                  } else {
                      // Se histórico simples, tenta desenhar abaixo se der espaço, senão nova pag
                      if (textY > height - 120) pdf.addPage();
                      else textY += 30;
                  }

                  const startTable = docType === 'transferencia' ? 50 : textY;

                  const tableBody = modulesData.length > 0 ? modulesData.map((m: any) => [
                      m.title || "Módulo", "20h", "100%", "10.0", "APROVADO"
                  ]) : [["Sem registros", "-", "-", "-", "-"]];

                  autoTable(pdf, {
                      startY: startTable,
                      head: [['Disciplina', 'C.H.', 'Freq.', 'Nota', 'Situação']],
                      body: tableBody,
                      theme: 'striped',
                      headStyles: { fillColor: [30, 41, 59] },
                      margin: { left: margin, right: margin }
                  });
              }
          }

          // Output
          const pdfBase64 = pdf.output('datauristring');
          const pdfBlob = pdf.output('blob');

          await addDoc(collection(db, 'secretaria_arquivos'), {
              name: `${docType.toUpperCase()} - ${opStudent.displayName}.pdf`,
              type: 'file', mimeType: 'application/pdf', url: pdfBase64,
              parentId: 'root', createdAt: serverTimestamp(), createdBy: user.uid,
              studentId: opStudent.uid, docType: docType,
              docData: { code, title: docTitle, date: new Date().toISOString(), student: { displayName: opStudent.displayName, cpf: opStudent.cpf, academicId: opStudent.academicId }, courseData }
          });

          const blobUrl = URL.createObjectURL(pdfBlob);
          window.open(blobUrl, '_blank');

      } catch (e: any) {
          console.error("PDF Error:", e);
          alert("Erro: " + e.message);
      } finally {
          setIsGeneratingPdf(false);
      }
  };

  const getFilesForFolder = (folderId: string) => {
    return fileSystem.filter(f => f.parentId === folderId).sort((a,b) => (a.type === b.type ? a.name.localeCompare(b.name) : a.type === 'folder' ? -1 : 1));
  };
  const currentItems = useMemo(() => getFilesForFolder(currentFolderId), [fileSystem, currentFolderId]);

  const handleCreateFolder = async () => {
    const name = prompt("Nome:"); if(!name) return;
    await addDoc(collection(db, 'secretaria_arquivos'), { name, type: 'folder', parentId: currentFolderId, createdAt: serverTimestamp(), createdBy: user.uid });
  };

  const handleUploadFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if(!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => { if(ev.target?.result) await addDoc(collection(db, 'secretaria_arquivos'), { name: file.name, type: 'file', mimeType: file.type, url: ev.target.result, parentId: currentFolderId, size: file.size, createdAt: serverTimestamp(), createdBy: user.uid }); };
    reader.readAsDataURL(file);
  };

  const handleMoveFile = async () => {
      if (!fileToMove) return;
      await updateDoc(doc(db, 'secretaria_arquivos', fileToMove.id), { parentId: moveTargetFolderId, updatedAt: serverTimestamp() });
      setMoveModalOpen(false); setFileToMove(null);
  };

  const handleNavigate = (folder: any) => {
    setCurrentFolderId(folder.id);
    setFolderPath([...folderPath, { id: folder.id, name: folder.name }]);
  };

  const handleBreadcrumb = (index: number) => {
    const newPath = folderPath.slice(0, index + 1);
    setFolderPath(newPath);
    setCurrentFolderId(newPath[newPath.length - 1].id);
  };

  const saveEditedStudent = async () => { if(editingStudent) await updateDoc(doc(db, 'users', editingStudent.uid), {...editingStudent, updatedAt: serverTimestamp()}); setAuditModalOpen(false); setEditingStudent(null); };
  const validateStudent = async () => { if(editingStudent) await updateDoc(doc(db, 'users', editingStudent.uid), {status: 'ativo', updatedAt: serverTimestamp()}); setAuditModalOpen(false); setEditingStudent(null); };

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden flex flex-col pb-6">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4 rounded-xl shadow-lg print:hidden">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-indigo-600 rounded-lg shadow-lg"><Archive size={20}/></div>
           <div><h1 className="text-lg font-black uppercase italic tracking-tighter leading-none">Gabinete Operacional</h1><p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-0.5 italic">Secretaria EB-AD</p></div>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg shadow-inner border border-white/5 overflow-x-auto max-w-full">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); if(t !== 'chat') setActiveTicket(null); }} className={`px-4 py-2 text-[9px] font-black uppercase italic transition-all rounded-lg whitespace-nowrap ${activeTab === t ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="flex-1 overflow-hidden flex flex-col">
         {activeTab === 'atendimento' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row justify-between gap-4 items-center bg-slate-50/50">
                    <div className="relative w-full md:w-96"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16}/><input value={ticketSearchTerm} onChange={e => setTicketSearchTerm(e.target.value)} placeholder="Buscar protocolo..." className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" /></div>
                    <div className="flex gap-2">
                        {selectedTickets.length > 0 && <button onClick={handleBulkDelete} className="px-4 py-2 bg-rose-600 text-white rounded-lg text-[10px] font-black uppercase flex items-center gap-2 hover:bg-rose-700 transition-all"><Trash2 size={14}/> Excluir ({selectedTickets.length})</button>}
                        <div className="flex gap-2 p-1 bg-slate-100 rounded-xl">
                            {['todos', 'pendente', 'ativo', 'finalizado'].map((f:any) => <button key={f} onClick={() => setTicketFilter(f)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${ticketFilter === f ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>{f}</button>)}
                        </div>
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest sticky top-0 z-10 shadow-sm">
                            <tr>
                                <th className="px-6 py-4 border-b border-slate-100 w-10 text-center"><button onClick={toggleSelectAll}><CheckSquare size={14}/></button></th>
                                <th className="px-6 py-4 border-b border-slate-100">Protocolo</th>
                                <th className="px-6 py-4 border-b border-slate-100">Aluno / Matrícula</th>
                                <th className="px-6 py-4 border-b border-slate-100">Assunto</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-center">Status</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-center">Data</th>
                                <th className="px-6 py-4 border-b border-slate-100 text-right">Ação</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {tickets.filter(t => (ticketFilter === 'todos' || t.status.toLowerCase() === ticketFilter) && (t.user?.toLowerCase().includes(ticketSearchTerm.toLowerCase()) || t.protocolo?.toLowerCase().includes(ticketSearchTerm.toLowerCase()))).map(t => (
                                <tr key={t.id} className="hover:bg-indigo-50/10 transition-colors group">
                                    <td className="px-6 py-4 text-center"><input type="checkbox" checked={selectedTickets.includes(t.id)} onChange={() => toggleSelectTicket(t.id)} className="rounded border-slate-300 text-indigo-600 cursor-pointer"/></td>
                                    <td className="px-6 py-4 font-mono text-xs font-bold text-indigo-600">#{t.protocolo}</td>
                                    <td className="px-6 py-4"><p className="font-black text-xs text-slate-800 uppercase italic">{t.user}</p></td>
                                    <td className="px-6 py-4"><p className="text-[10px] text-slate-500 italic font-medium max-w-[200px] line-clamp-1">{t.lastMessage}</p></td>
                                    <td className="px-6 py-4 text-center"><span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-100' : t.status === 'Resolvido' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-slate-100 text-slate-500 border-slate-200'}`}>{t.status}</span></td>
                                    <td className="px-6 py-4 text-center text-[10px] font-bold text-slate-400">{t.createdAt?.seconds ? new Date(t.createdAt.seconds * 1000).toLocaleDateString('pt-BR') : '-'}</td>
                                    <td className="px-6 py-4 text-right"><button onClick={() => { setActiveTicket(t); setActiveTab('chat'); }} className="p-2 bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white rounded-lg transition-all border border-indigo-100 shadow-sm" title="Abrir Chat"><MessageSquare size={14}/></button></td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
             </div>
         )}

         {activeTab === 'chat' && (
             <div className="flex-1 bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col relative h-full">
                {activeTicket ? (
                  <>
                    <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center shadow-sm z-10">
                       <div className="flex items-center gap-4">
                           <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center font-black italic">{activeTicket.user.charAt(0)}</div>
                           <div><h3 className="font-black text-slate-900 text-sm uppercase italic">Protocolo #{activeTicket.protocolo}</h3><p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">{activeTicket.user}</p></div>
                       </div>
                       <div className="flex gap-2">
                           <button onClick={() => { setActiveTicket(null); setActiveTab('atendimento'); }} className="px-4 py-2 bg-white border border-slate-200 rounded-xl text-[9px] font-black uppercase hover:bg-slate-50 text-slate-500">Voltar</button>
                           {activeTicket.status === 'Pendente' && <button onClick={() => handleTicketAction('assume')} className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-indigo-700 transition-all shadow-lg flex items-center gap-2"><UserCheck size={14}/> Assumir</button>}
                           {activeTicket.status !== 'Finalizado' && <button onClick={() => handleTicketAction('finalize')} className="px-4 py-2 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase hover:bg-emerald-700 transition-all shadow-lg flex items-center gap-2"><CheckCircle2 size={14}/> Finalizar</button>}
                       </div>
                    </div>
                    <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/50 custom-scrollbar relative">
                       {messages.map((m, i) => (
                         <div key={i} className={`flex flex-col ${m.sender === 'Aluno' ? 'items-start' : 'items-end'}`}>
                            <div className={`max-w-[70%] p-4 rounded-2xl text-xs font-medium leading-relaxed shadow-sm relative group ${m.sender === 'Aluno' ? 'bg-white border border-slate-200 text-slate-700 rounded-tl-none' : m.isBot ? 'bg-slate-200 text-slate-700 rounded-tr-none' : 'bg-indigo-600 text-white rounded-tr-none'}`}>
                               {m.text}
                               {m.attachmentUrl && <div onClick={() => viewAttachment(m.attachmentUrl)} className="mt-2 p-2 bg-black/10 rounded flex items-center gap-2 cursor-pointer hover:bg-black/20 text-white"><FileText size={14}/> <span className="text-[9px] font-bold uppercase underline">Ver Anexo</span> <ExternalLink size={10}/></div>}
                               <span className="text-[8px] font-bold opacity-50 absolute -bottom-5 block w-full">{m.sender} • {m.createdAt?.seconds ? new Date(m.createdAt.seconds*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) : '...'}</span>
                            </div>
                         </div>
                       ))}
                       <div ref={chatEndRef} className="h-4" />
                    </div>
                    {(activeTicket.status === 'Em Andamento' || activeTicket.status === 'Pendente') ? (
                      <div className="p-4 border-t border-slate-100 bg-white z-20">
                         <div className="flex gap-3 items-center bg-slate-50 p-2 rounded-2xl border border-slate-200 focus-within:border-indigo-400 focus-within:ring-2 focus-within:ring-indigo-100 transition-all">
                            <button onClick={() => chatFileInputRef.current?.click()} className="p-3 bg-white text-slate-400 rounded-xl hover:text-indigo-600 shadow-sm transition-all"><Paperclip size={18}/></button>
                            <input type="file" ref={chatFileInputRef} className="hidden" onChange={sendAttachment}/>
                            <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendMessage()} className="flex-1 bg-transparent border-none text-xs font-bold outline-none text-slate-700 placeholder:text-slate-400" placeholder="Digite sua resposta..." />
                            <button onClick={sendMessage} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all"><Send size={18}/></button>
                         </div>
                      </div>
                    ) : <div className="p-4 bg-slate-100 text-center text-[10px] font-black uppercase text-slate-400 border-t border-slate-200">Atendimento Encerrado.</div>}
                  </>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-6"><LifeBuoy size={48} className="opacity-20"/><div className="text-center"><h3 className="text-lg font-black uppercase italic text-slate-400">Chat de Suporte</h3><p className="text-xs font-bold uppercase tracking-widest opacity-50 mt-1">Selecione um ticket na aba "Atendimento"</p></div></div>
                )}
             </div>
         )}

         {(activeTab === 'arquivos') && !activeTicket && (
           <div className={`bg-white border border-slate-200 rounded-xl overflow-hidden h-full flex flex-col shadow-lg`}>
              <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                 <div className="flex items-center gap-2 overflow-x-auto">
                    <button onClick={() => { setCurrentFolderId('root'); setFolderPath([{id:'root', name:'Arquivos'}])}} className="p-2 hover:bg-slate-200 rounded-lg"><Home size={16}/></button>
                    {folderPath.map((f, i) => (
                      <React.Fragment key={f.id}>
                        {i > 0 && <ChevronRight size={14} className="text-slate-400"/>}
                        <button onClick={() => handleBreadcrumb(i)} className={`text-xs font-bold px-2 py-1 rounded-lg hover:bg-slate-200 ${i === folderPath.length -1 ? 'text-slate-900' : 'text-slate-500'}`}>{f.name}</button>
                      </React.Fragment>
                    ))}
                 </div>
                 <div className="flex gap-2">
                    <input type="file" ref={fileInputRef} className="hidden" onChange={handleUploadFile} />
                    <button onClick={() => fileInputRef.current?.click()} className="px-3 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-indigo-600"><UploadCloud size={14}/> Upload</button>
                    <button onClick={handleCreateFolder} className="px-3 py-2 bg-slate-200 text-slate-700 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 hover:bg-slate-300"><FolderPlus size={14}/> Pasta</button>
                 </div>
              </div>
              <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-slate-50/50">
                 {currentItems.length === 0 ? (
                   <div className="h-full flex flex-col items-center justify-center opacity-30 gap-4"><Folder size={48} /><p className="text-xs font-black uppercase">Pasta Vazia</p></div>
                 ) : (
                   <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                      {currentItems.map(item => (
                        <div key={item.id} onDoubleClick={() => item.type === 'folder' ? handleNavigate(item) : null} className={`bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all group flex flex-col items-center text-center cursor-pointer relative`}>
                           <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mb-3 text-white shadow-inner ${item.type === 'folder' ? 'bg-amber-400' : 'bg-indigo-500'}`}>{item.type === 'folder' ? <Folder size={32} className="fill-white/50"/> : <FileText size={32} className="fill-white/50"/>}</div>
                           <p className="text-[10px] font-bold text-slate-700 line-clamp-2 leading-tight w-full break-words">{item.name}</p>
                           {item.type === 'file' && (
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 flex gap-1 bg-white/90 rounded-lg p-1 shadow-sm">
                               <button onClick={async (e) => { e.stopPropagation(); if(confirm('Apagar?')) await deleteDoc(doc(db, 'secretaria_arquivos', item.id)); }} className="p-1.5 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100"><Trash2 size={12}/></button>
                               <button onClick={(e) => { e.stopPropagation(); setFileToMove(item); setMoveModalOpen(true); }} className="p-1.5 bg-slate-50 text-slate-600 rounded-lg hover:bg-slate-100"><Move size={12}/></button>
                               <button onClick={(e) => { e.stopPropagation(); viewFile(item); }} className="p-1.5 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100"><Eye size={12}/></button>
                             </div>
                           )}
                        </div>
                      ))}
                   </div>
                 )}
              </div>
           </div>
         )}

         {activeTab === 'operacional' && (
           <div className="h-full flex flex-col md:flex-row gap-6">
              <div className="w-full md:w-64 flex flex-col gap-3">
                 <button onClick={() => setOpSubView('declaracao')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'declaracao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><FileText size={18}/><span className="text-xs font-black uppercase">Declarações</span></button>
                 <button onClick={() => setOpSubView('historico')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'historico' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><Archive size={18}/><span className="text-xs font-black uppercase">Histórico Escolar</span></button>
                 <button onClick={() => setOpSubView('transferencia')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'transferencia' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><ArrowRightLeft size={18}/><span className="text-xs font-black uppercase">Transferência</span></button>
                 <button onClick={() => setOpSubView('validacao')} className={`p-4 rounded-xl border flex items-center gap-3 transition-all ${opSubView === 'validacao' ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg' : 'bg-white border-slate-200 hover:bg-slate-50'}`}><UserCheck size={18}/><span className="text-xs font-black uppercase">Auditoria</span></button>
                 <button onClick={() => setIsSignModalOpen(true)} className="p-4 rounded-xl border bg-white border-slate-200 hover:bg-slate-50 flex items-center gap-3 transition-all"><Fingerprint size={18}/><span className="text-xs font-black uppercase">Minha Assinatura</span></button>
              </div>

              <div className="flex-1 bg-white rounded-2xl border border-slate-200 p-1 shadow-sm overflow-hidden relative">
                 {(opSubView === 'declaracao' || opSubView === 'historico' || opSubView === 'transferencia') && (
                   <div className="max-w-lg mx-auto space-y-6 py-10 px-6">
                      <h3 className="text-xl font-black uppercase italic text-slate-900 border-b pb-4">Gerar Documento Oficial</h3>
                      <div className="p-4 bg-amber-50 rounded-xl border border-amber-100 text-[10px] text-amber-700 leading-relaxed italic">
                         <AlertTriangle size={14} className="inline mr-1 mb-0.5"/> 
                         Os documentos gerados possuem <strong>validade jurídica</strong> através de assinatura digital e chave de verificação única (Hash + QR Code).
                      </div>
                      <div className="space-y-2">
                         <label className="text-[10px] font-black uppercase text-slate-400">Selecione o Aluno</label>
                         <select onChange={e => setOpStudent(students.find(s => s.uid === e.target.value))} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold">
                            <option value="">Selecione...</option>
                            {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName} (RA: {s.academicId})</option>)}
                         </select>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div className={`p-3 rounded-lg border text-center ${secSignature ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-rose-50 border-rose-200 text-rose-700'}`}>
                              <p className="text-[9px] font-black uppercase">Assinatura Secretário</p>
                              <p className="text-xs">{secSignature ? "OK" : "Pendente"}</p>
                          </div>
                          <div className={`p-3 rounded-lg border text-center ${directorSignature ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-amber-50 border-amber-200 text-amber-700'}`}>
                              <p className="text-[9px] font-black uppercase">Assinatura Diretor</p>
                              <p className="text-xs">{directorSignature ? "OK" : "Pendente (Simulado)"}</p>
                          </div>
                      </div>

                      <div className="pt-4 flex gap-4">
                         {opSubView === 'declaracao' && (
                           <>
                             <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('matricula')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Printer size={14}/>} Matrícula PDF
                             </button>
                             <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('conclusao')} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Award size={14}/>} Diploma PDF
                             </button>
                           </>
                         )}
                         {opSubView === 'transferencia' && (
                           <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('transferencia')} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <ArrowRightLeft size={14}/>} Gerar Guia PDF
                           </button>
                         )}
                         {opSubView === 'historico' && (
                           <button disabled={!opStudent || isGeneratingPdf} onClick={() => generateLegalPDF('historico')} className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg disabled:opacity-50 hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">
                                {isGeneratingPdf ? <RefreshCw className="animate-spin" size={14}/> : <Archive size={14}/>} Gerar Histórico PDF
                           </button>
                         )}
                      </div>
                   </div>
                 )}
                 {opSubView === 'validacao' && (
                    <div className="p-8 h-full flex flex-col">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-lg font-black uppercase italic text-slate-900">Auditoria de Cadastros</h3>
                            <div className="text-[10px] font-bold text-slate-400 uppercase bg-slate-50 px-3 py-1 rounded-lg border border-slate-100">Filtro: Pendentes</div>
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3">
                            {students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').length === 0 ? (
                                <p className="text-center text-slate-300 italic py-10 text-xs uppercase font-black">Nenhum aluno pendente de validação.</p>
                            ) : students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').map(s => (
                                <div key={s.uid} className="flex justify-between items-center p-4 border border-rose-100 bg-rose-50/50 rounded-xl hover:bg-rose-50 transition-all">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-full bg-rose-100 flex items-center justify-center text-rose-600 font-bold">{s.displayName?.charAt(0)}</div>
                                        <div>
                                            <p className="text-xs font-black uppercase text-slate-800">{s.displayName}</p>
                                            <p className="text-[9px] text-slate-500 font-mono">{s.cpf} • {s.email}</p>
                                        </div>
                                    </div>
                                    <button onClick={() => { setEditingStudent(s); setAuditModalOpen(true); }} className="px-4 py-2 bg-white text-rose-600 border border-rose-200 rounded-lg text-[9px] font-black uppercase hover:bg-rose-600 hover:text-white transition-all shadow-sm">Auditar</button>
                                </div>
                            ))}
                        </div>
                    </div>
                 )}
              </div>
           </div>
         )}
      </main>

      {/* ... (Modals: moveModalOpen, auditModalOpen, isSignModalOpen) ... */}
      {moveModalOpen && fileToMove && (
          <div className="fixed inset-0 z-[4000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-6">
              <div className="bg-white w-full max-w-md rounded-[2rem] p-6 shadow-2xl animate-in zoom-in-95">
                  <h3 className="font-black text-slate-900 uppercase italic mb-4">Mover "{fileToMove.name}" para...</h3>
                  <div className="bg-slate-50 rounded-xl border border-slate-200 p-4 h-60 overflow-y-auto custom-scrollbar mb-4">
                      <div onClick={() => setMoveTargetFolderId('root')} className={`p-3 rounded-lg cursor-pointer flex items-center gap-2 ${moveTargetFolderId === 'root' ? 'bg-indigo-100 text-indigo-700 font-bold' : 'hover:bg-white text-slate-600'}`}><Home size={16}/> Raiz (Arquivos)</div>
                      {fileSystem.filter(f => f.type === 'folder' && f.id !== fileToMove.id).map(f => (
                          <div key={f.id} onClick={() => setMoveTargetFolderId(f.id)} className={`p-3 rounded-lg cursor-pointer flex items-center gap-2 ml-4 ${moveTargetFolderId === f.id ? 'bg-indigo-100 text-indigo-700 font-bold' : 'hover:bg-white text-slate-600'}`}><Folder size={16}/> {f.name}</div>
                      ))}
                  </div>
                  <div className="flex gap-2"><button onClick={() => setMoveModalOpen(false)} className="flex-1 py-3 bg-slate-100 rounded-xl text-[10px] font-black uppercase text-slate-500">Cancelar</button><button onClick={handleMoveFile} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg hover:bg-indigo-700">Confirmar</button></div>
              </div>
          </div>
      )}

      {auditModalOpen && editingStudent && (
          <div className="fixed inset-0 z-[3000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-white w-full max-w-4xl h-[90vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
                  <header className="bg-slate-50 px-8 py-5 border-b border-slate-100 flex justify-between items-center shrink-0">
                      <div className="flex items-center gap-3">
                          <div className="p-2 bg-indigo-600 text-white rounded-lg shadow-md"><ShieldCheck size={20}/></div>
                          <div><h2 className="text-lg font-black uppercase italic text-slate-900 leading-none">Auditoria de Prontuário</h2><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Validação Cadastral</p></div>
                      </div>
                      <button onClick={() => setAuditModalOpen(false)} className="p-2 hover:bg-rose-50 text-slate-400 rounded-full transition-all"><X size={20}/></button>
                  </header>
                  <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-8">
                       <div className="grid grid-cols-2 gap-6">
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Nome</label><input value={editingStudent.displayName} onChange={e => setEditingStudent({...editingStudent, displayName: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">CPF</label><input value={editingStudent.cpf} onChange={e => setEditingStudent({...editingStudent, cpf: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Email</label><input value={editingStudent.email} disabled className="w-full p-3 bg-slate-100 rounded-xl text-xs font-bold text-slate-500 border border-slate-200 cursor-not-allowed"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Telefone</label><input value={editingStudent.telefone} onChange={e => setEditingStudent({...editingStudent, telefone: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                       </div>
                       <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
                           <h4 className="text-[10px] font-black uppercase text-slate-400 mb-4 tracking-widest">Documentos Anexados</h4>
                           <div className="flex items-center gap-4">
                               <div className="w-24 h-24 bg-white rounded-xl border border-slate-200 flex items-center justify-center overflow-hidden">{editingStudent.photoURL ? <img src={editingStudent.photoURL} className="w-full h-full object-cover"/> : <span className="text-[8px] font-black uppercase text-slate-300">Sem Foto</span>}</div>
                               <div><p className="text-xs font-bold text-slate-800">Foto de Identificação</p><p className="text-[9px] text-slate-400">Status: {editingStudent.photoURL ? 'Enviado' : 'Pendente'}</p></div>
                           </div>
                       </div>
                       <div className="flex gap-4 pt-4 border-t border-slate-100">
                          <button onClick={saveEditedStudent} className="px-6 py-3 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase hover:bg-slate-200 flex items-center gap-2"><Edit3 size={14}/> Salvar Edições</button>
                          <button onClick={validateStudent} className="px-8 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-emerald-700 transition-all flex items-center gap-2 shadow-xl shadow-emerald-200"><Check size={16}/> Validar Matrícula</button>
                       </div>
                  </div>
              </div>
          </div>
      )}
      {isSignModalOpen && <SignaturePad title="Assinatura Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert("Assinatura Salva!"); }} />}
    </div>
  );
};

export default SecretariatView;
